ROBUSTNESS_ARMS = ('M0', 'M-observation', 'M-prior', 'M-combined')


def robustness_config(path):
    cfg = yaml.safe_load(Path(path).read_text())
    refed=cfg.get('schema')=='shared_driver_teacher_robustness_refed_v2'
    if (cfg.get('schema') not in ('shared_driver_teacher_robustness_v1','shared_driver_teacher_robustness_refed_v2')
            or cfg['source_run'] != 'experiments/runs/physiology_semantic_tokenizer/shared_driver_reconstruction/'+('20261013_refed_physiology_semantics_v3' if refed else '20260928_physiology_semantics_v1')
            or cfg['source_config'] != 'experiments/configs/physiology_semantic_tokenizer/shared_driver_physiology_semantics_'+('refed_v2' if refed else 'v1')+'.yaml'
            or cfg['data_boundary'] != 'exact_public_parent_prepared_arrays_and_coordinates_only'
            or cfg['protected_data'] != 'forbidden' or cfg['parameter_policy'] != 'H0_fixed'
            or cfg['arms'] != list(ROBUSTNESS_ARMS)
            or cfg['tensor'] != dict(steps=120, components=3, dt_s=.25, state_order=['r','s','f','v','p','q'])):
        raise ValueError('teacher robustness identity, tensor or data boundary violated')
    if (cfg['observation']['modes'] != 4 or cfg['observation']['rho'] != .35
            or cfg['prior']['amplitude_weights'] != [.01,.1,1.]
            or cfg['observation']['coefficient_scale_multipliers'] != [.5,1.,2.]
            or cfg['prior']['mean'] != 0 or not cfg['calibration']['subject_disjoint']):
        raise ValueError('unregistered observation/prior calibration contract')
    return cfg


def robustness_basis(cfg, parameters=None, rho=None):
    from src.inference.shared_driver_reconstruction import waveform_component_basis
    return waveform_component_basis(parameters or BalloonParameters(), 120, .25,
        semantics_model_operator(), 'volume', modes=cfg['observation']['modes'],
        volume_deoxy_fraction=cfg['observation']['rho'] if rho is None else rho)


def robustness_fit(cfg, base, target, sd, calibration, arm, visible=None, *,
                   prior_weight=None, coefficient_multiplier=None, rho=None, parameters=None):
    from src.inference.shared_driver_reconstruction import fit_nonlinear_shared_driver
    if arm not in ROBUSTNESS_ARMS:raise ValueError('unknown robustness arm')
    options = semantics_solver_options(base)
    if arm in ('M-prior', 'M-combined'):
        options.update(driver_amplitude_weight=calibration['prior_weight'] if prior_weight is None else prior_weight,
                       driver_prior_sd=calibration['driver_sd'])
    if arm in ('M-observation', 'M-combined'):
        multiplier = calibration['coefficient_multiplier'] if coefficient_multiplier is None else coefficient_multiplier
        options.update(observation_basis=robustness_basis(cfg, rho=rho),
            observation_coefficient_sd=np.asarray(calibration['coefficient_sd'])*multiplier)
    mask = np.ones_like(target, dtype=bool) if visible is None else visible
    data = np.array(target, copy=True);data[~mask] = np.nan
    return fit_nonlinear_shared_driver(data, parameters or semantics_parameters(base), .25,
        visible=mask, sd=sd, mean_operator=semantics_model_operator(),
        max_evaluations=base['solver']['max_evaluations_per_trial'], **options)


def robustness_metrics(fit, target, sd, mask, *, driver=None, driver_sd=None, native_factors=None):
    result = dict(converged=fit['converged'], status=fit['status'],
        evaluations=fit.get('evaluations'), objective=fit.get('objective'))
    if 'prediction' not in fit:return result
    endpoint = ~mask if (~mask).any() else mask
    factors = np.ones(3) if native_factors is None else np.asarray(native_factors)
    local = np.maximum(target.std(axis=0), np.asarray(sd)*1e-8)
    for name,pred in [('total',fit['prediction']),('physical',fit['physical_prediction'])]:
        error = pred-target
        result[name+'_nrmse'] = float(np.sqrt(np.mean((error/np.asarray(sd))[endpoint]**2)))
        result[name+'_local_nrmse'] = float(np.sqrt(np.mean((error/local)[endpoint]**2)))
        result[name+'_component_nrmse'] = [float(np.sqrt(np.mean((error[endpoint[:,j],j]/sd[j])**2)))
            if endpoint[:,j].any() else None for j in range(3)]
        result[name+'_native_rmse'] = [float(np.sqrt(np.mean((error[endpoint[:,j],j]/factors[j])**2)))
            if endpoint[:,j].any() else None for j in range(3)]
        result[name+'_correlation'] = [float(np.corrcoef(pred[endpoint[:,j],j],target[endpoint[:,j],j])[0,1])
            if endpoint[:,j].sum()>2 and np.std(pred[endpoint[:,j],j])>1e-12 and np.std(target[endpoint[:,j],j])>1e-12
            else None for j in range(3)]
    result['component_rms_training_SD'] = float(np.sqrt(np.mean((fit['observation_component'][:,1:]/sd[1:])**2)))
    result['driver_rms'] = float(np.sqrt(np.mean(fit['driver']**2)))
    if driver is not None:
        error = fit['driver']-driver
        result['driver_nrmse'] = float(np.sqrt(np.mean(error**2))/driver_sd)
        result['centered_driver_nrmse'] = float(np.sqrt(np.mean((error-error[:20].mean())**2))/driver_sd)
        result['driver_correlation'] = float(np.corrcoef(fit['driver'],driver)[0,1])
    return result


def robustness_teacher(fit, alternatives, scale, threshold):
    """Deterministic sensitivity, never a probability or unique source label."""
    n = len(fit['driver'])
    complete = bool(fit['converged'] and alternatives and all(x.get('converged') for x in alternatives))
    available = [x['driver'] for x in alternatives if 'driver' in x]
    candidates = np.array([fit['driver']]+available)
    spread = np.max(abs(candidates-fit['driver']),axis=0)/scale
    centered = candidates-candidates[:,:20].mean(axis=1,keepdims=True)
    centered_spread = np.max(abs(centered-centered[0]),axis=0)/scale
    return dict(driver=fit['driver'], reference_centered_driver=centered[0],
        sensitivity_SD=spread, centered_sensitivity_SD=centered_spread,
        robustness_mask=(spread<=threshold)&complete,
        centered_robustness_mask=(centered_spread<=threshold)&complete,
        sensitivity_complete=complete, alternatives_expected=len(alternatives),
        alternatives_converged=sum(bool(x.get('converged')) for x in alternatives),
        physical_prediction=fit['physical_prediction'], observation_component=fit['observation_component'],
        full_prediction=fit['prediction'], parameter_policy='H0_fixed',
        interpretation='conditional_candidate_sensitivity_not_calibrated_probability_or_coupling_qualification')


def robustness_synthetic_case(cfg, base, repeat, spectrum, initial, scenario, *, calibration=False):
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    seed = np.random.SeedSequence([cfg['seed'], 101 if calibration else 201, repeat, int(spectrum=='mixed'),int(initial=='nonrest')])
    rng = np.random.default_rng(seed);n = 132
    r = gaussian_filter1d(rng.normal(size=n), 5.)
    if spectrum=='mixed':r += .18*gaussian_filter1d(rng.normal(size=n), .7)
    r *= .025/r.std()
    initial_state = np.r_[0.,np.ones(4)]+(rng.normal(size=5)*.015 if initial=='nonrest' else 0.)
    parameters = semantics_parameters(base)
    if scenario=='driver_amplitude':r = r*1.5
    if scenario=='driver_shape':r = r+.025*np.sin(np.arange(n)*.21+.7)
    if scenario=='physiology_tau':parameters = semantics_parameters(base,tau=4.)
    if scenario=='weak_coupling':parameters = semantics_parameters(base,neurovascular_gain=1e-6)
    forward = nonlinear_driver_forward(r, initial_state, parameters,.25,substeps=8,
        derivative=False,numerical_backend='numba', hemodynamics='inlet_balance', viscoelastic_s=0.)
    raw = forward['canonical_prediction']
    # Fixed noise distribution across all interventions; never rescale on a test condition.
    noise = rng.normal(size=(132,3))*np.array(cfg['synthetic']['canonical_white_noise_SD'])
    observed = raw.copy()+noise
    component = np.zeros((120,3));canonical_basis = robustness_basis(cfg)
    # All common components are added in processed coordinates, under the same
    # frozen temporal operator as the model. No statistical independence is imposed.
    coef = rng.normal(size=4)*np.array(cfg['synthetic']['common_coefficient_SD'])
    if scenario=='EEG_gain':observed[:,0] = 1.3*raw[:,0]+noise[:,0]
    if scenario=='Hb_gain':observed[:,1:] = 1.3*raw[:,1:]+noise[:,1:]
    if scenario=='noise':observed = raw+3*noise
    if scenario in ('lag_1s','lag_3s'):
        shift = 4 if scenario=='lag_1s' else 12
        observed[:120,1:] = observed[shift:120+shift,1:]
    op = semantics_model_operator()
    y = (op@observed[:120].ravel()).reshape(120,3)
    clean = (op@raw[:120].ravel()).reshape(120,3)
    if scenario=='common_basis':component = (canonical_basis@coef).reshape(120,3)
    if scenario in ('common_correlated','common_colored'):
        c = gaussian_filter1d(r[:120] if scenario=='common_correlated' else rng.normal(size=120),8.)
        c = cfg['synthetic']['colored_common_canonical_SD']*c/np.std(c)
        component = (op@(c[:,None]*np.array([0.,.65,.35])).ravel()).reshape(120,3)
    y += component
    return dict(target=y, physical_truth=clean, observation_truth=component, driver=r[:120],
        states=forward['states'][:120], seed=seed.entropy)


def robustness_select(candidates, key):
    scores = {}
    for value,rows in candidates:
        scores[str(value)] = float(np.mean([r.get(key,100.) if r.get('converged') else 100. for r in rows]))
    selected = min(scores,key=lambda v:(scores[v],float(v)))
    return float(selected),scores


def robustness_synthetic_selection_worker(payload):
    cfg,base,calibration,arm,value,i=payload;sd=np.array(calibration['sd']);rows=[]
    for scenario in ('control','common_basis','common_colored','driver_amplitude','driver_shape'):
        case=robustness_synthetic_case(cfg,base,i,'slow','rest',scenario,calibration=True)
        for mode in ('full','EEG_hidden'):
            mask=np.ones((120,3),bool) if mode=='full' else semantics_missing_mask(mode)
            fit=robustness_fit(cfg,base,case['target'],sd,calibration,arm,mask,
                prior_weight=value if arm=='M-prior' else None,
                coefficient_multiplier=value if arm=='M-observation' else None)
            row=robustness_metrics(fit,case['target'],sd,mask,driver=case['driver'],driver_sd=calibration['driver_sd'])
            rows.append(dict(arm=arm,value=value,repeat=i,scenario=scenario,mode=mode,**row))
    return rows


def robustness_synthetic_calibration(cfg,base,out,workers):
    path = out/'synthetic_calibration.json'
    if path.exists():return json.loads(path.read_text())
    cases = [robustness_synthetic_case(cfg,base,i,'slow','rest','control',calibration=True)
             for i in range(cfg['calibration']['synthetic_repeats'])]
    sd = np.std(np.array([c['target'] for c in cases]),axis=(0,1))
    calibration = dict(driver_sd=float(np.sqrt(np.mean(np.array([c['driver'] for c in cases])**2))),
        coefficient_sd=cfg['synthetic']['common_coefficient_SD'], prior_weight=.1,coefficient_multiplier=1.,sd=sd,
        scale_source='known_training_generator_latent_distribution_and_common_component_coefficients',
        training_seed_stream=101,test_seed_stream=201)
    rows=[];payloads=[]
    for arm,values in [('M-prior',cfg['prior']['amplitude_weights']),
                        ('M-observation',cfg['observation']['coefficient_scale_multipliers'])]:
        for value in values:
            for i in range(cfg['calibration']['synthetic_repeats']):
                payloads.append((cfg,base,calibration,arm,value,i))
    for payload,result,error in bounded_nonlinear_work(robustness_synthetic_selection_worker,payloads,workers,2*workers):
        if error:raise RuntimeError(error)
        rows.extend(result)
    for arm,values in [('M-prior',cfg['prior']['amplitude_weights']),
                        ('M-observation',cfg['observation']['coefficient_scale_multipliers'])]:
        candidates=[(value,[r for r in rows if r['arm']==arm and r['value']==value]) for value in values]
        selected,ranking=robustness_select(candidates,'driver_nrmse')
        calibration['prior_weight' if arm=='M-prior' else 'coefficient_multiplier']=selected
        calibration[arm+'_selection_scores']=ranking
    write_json(path,calibration);pd.DataFrame(rows).to_csv(out/'synthetic_calibration_scores.csv',index=False)
    return calibration


def robustness_synthetic_worker(payload):
    cfg,base,root,spec=payload;out=Path(root);path=out/'synthetic'/spec['key']/'result.json'
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();cal=json.loads((out/'synthetic_calibration.json').read_text());sd=np.array(cal['sd'])
    rows=[];saved={};fits={};cases={}
    for scenario in cfg['synthetic']['scenarios']:
        case=robustness_synthetic_case(cfg,base,spec['repeat'],spec['spectrum'],spec['initial'],scenario)
        cases[scenario]=case
        for mode in cfg['synthetic']['modes']:
            mask=np.ones((120,3),bool) if mode=='full' else semantics_missing_mask(mode)
            for arm in ROBUSTNESS_ARMS:
                fit=robustness_fit(cfg,base,case['target'],sd,cal,arm,mask)
                fits[scenario,mode,arm]=fit
                row=robustness_metrics(fit,case['target'],sd,mask,driver=case['driver'],driver_sd=cal['driver_sd'])
                if 'prediction' in fit:
                    row['physical_truth_nrmse']=float(np.sqrt(np.mean(((fit['physical_prediction']-case['physical_truth'])/sd)**2)))
                    row['component_truth_nrmse']=float(np.sqrt(np.mean(((fit['observation_component']-case['observation_truth'])/sd)**2)))
                row.update(scenario=scenario,mode=mode,arm=arm,**spec);rows.append(row)
                if 'driver' in fit:
                    prefix=f'{scenario}__{mode}__{arm}__'
                    for key in ('driver','prediction','physical_prediction','observation_component'):saved[prefix+key]=fit[key]
        saved[scenario+'__truth_driver']=case['driver'];saved[scenario+'__target']=case['target']
    contrasts=[]
    for mode in cfg['synthetic']['modes']:
        for arm in ROBUSTNESS_ARMS:
            control=fits['control',mode,arm]
            for scenario in cfg['synthetic']['scenarios']:
                fit=fits[scenario,mode,arm]
                row=dict(**spec,mode=mode,arm=arm,scenario=scenario,
                    converged=bool(control['converged'] and fit['converged']))
                if 'driver' in control and 'driver' in fit:
                    estimated=fit['driver']-control['driver'];truth=cases[scenario]['driver']-cases['control']['driver']
                    row.update(change_error_SD=float(np.sqrt(np.mean((estimated-truth)**2))/cal['driver_sd']),
                        estimated_change_SD=float(np.sqrt(np.mean(estimated**2)))/cal['driver_sd'],
                        truth_change_SD=float(np.sqrt(np.mean(truth**2)))/cal['driver_sd'])
                contrasts.append(row)
    # Sensitivity to the registered observation counterfactuals tests invariance.
    # True-driver interventions are intentionally excluded from this ensemble.
    reliability=[]
    invariants=['common_basis','common_correlated','common_colored','EEG_gain','Hb_gain','noise','lag_1s','lag_3s']
    for arm in ROBUSTNESS_ARMS:
        control=fits['control','full',arm]
        if 'driver' not in control:continue
        teacher=robustness_teacher(control,[fits[s,'full',arm] for s in invariants],cal['driver_sd'],cfg['teacher']['sensitivity_threshold_SD'])
        errors=np.array([abs(fits[s,'full',arm]['driver']-cases[s]['driver'])/cal['driver_sd']
            for s in ['control']+invariants if 'driver' in fits[s,'full',arm]])
        mask=teacher['robustness_mask'];bad=errors.max(axis=0)>.5
        reliability.append(dict(**spec,arm=arm,robust_fraction=float(mask.mean()),
            high_error_fraction=float(bad.mean()),false_reassurance_fraction=float((mask&bad).mean()),
            sensitivity_complete=teacher['sensitivity_complete']))
        saved[arm+'__robustness_mask']=mask
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',spec=spec,rows=rows,contrasts=contrasts,reliability=reliability,
        seconds=time.monotonic()-start,peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024)
    write_json(path,result);return result


def robustness_parent_inputs(cfg,project_root,out):
    from src.data.ssm_prepared import public_prepared_datasets
    parent=(Path(project_root)/cfg['source_run']).resolve()
    summary=json.loads((parent/'summary.json').read_text())
    if summary['execution']!='completed':raise ValueError('parent evidence is not terminal')
    refs=json.loads((parent/'cohort.json').read_text())['refs']
    panel=json.loads((parent/'diagnostic_plan.json').read_text())['windows']
    datasets=public_prepared_datasets(str(parent))
    for ref in refs:
        if ref['dataset'] not in datasets:
            raise ValueError('unsupported/protected dataset before array read')
        path=Path(ref['array_path']).resolve()
        if not path.is_relative_to(parent/'prepared'):raise ValueError('array path outside exact public parent')
        if ref['dataset']=='visual_cognitive_motivation' and ref['subject']=='S06' and 'Part1' in ref['record']:
            raise ValueError('excluded Visual record')
    ids={r['id'] for r in refs}
    if len(panel)!=24*len(datasets) or any(r['id'] not in ids for r in panel):raise ValueError('parent panel identity mismatch')
    coordinates={}
    for ref in panel:
        key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
        coord=json.loads((parent/'coordinates'/(key+'.json')).read_text())
        if ref['subject'] in coord['training_subjects']:raise ValueError('held-out subject entered coordinate fit')
        coordinates[key]=coord
    plan=dict(parent=str(parent),windows=panel,coordinate_keys=sorted(coordinates),
        selection='unchanged_parent_preselected_QC_tercile_panel_no_result_selection')
    write_json(out/'measured_plan.json',plan)
    for key,coord in coordinates.items():write_json(out/'coordinates'/(key+'.json'),coord)
    op=semantics_model_operator();impulse=np.zeros(360);impulse[60*3+1]=1.
    response=(op@impulse).reshape(120,3)
    audit=dict(status='completed',window_steps=120,dt_s=.25,first_reference_steps=20,
        processing='same_parent_window_local_offline_operators_all_arms',
        Hb_impulse_support=np.flatnonzero(abs(response[:,1])>1e-10),
        constant_mode_max_abs=float(abs(op@np.ones(360)).max()),
        exact_clock_anchors=[{k:r.get(k) for k in ('id','eeg_start_s','hb_start_s','event_id','native_session','independent_block')} for r in panel],
        interpretation='different_native_clock_origins_are_not_fitted_lags; offline_feature_completion_not_raw_prediction',
        extra_lag_correction='none_no_independent_calibration_evidence',
        parent_native_qc=str(parent/'native_qc_summary.json'),
        limitations=['No renewed hardware-clock measurement',
            ('REFED uses coarse planar paper registration, not individual 3D' if datasets==('refed',) else 'REFED excluded from cross-modal fitting: geometry unavailable'),
            'PCA coordinate is statistical EEG log-power, not calibrated neural activity'])
    write_json(out/'processing_timing_audit.json',audit)
    return parent,refs,panel,coordinates


def robustness_calibration_worker(payload):
    cfg,base,root,refs,key=payload;out=Path(root);path=out/'calibration'/(key+'.json')
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();coord=json.loads((out/'coordinates'/(key+'.json')).read_text());sd=np.array(coord['sd'])
    available=[r for r in refs if r['id'] in set(coord['training_ids'])]
    subjects=sorted({r['subject'] for r in available})
    rng=np.random.default_rng(np.random.SeedSequence([cfg['seed'],301,sum(key.encode())]));rng.shuffle(subjects)
    cut=max(2,len(subjects)//3);selection_subjects=set(subjects[:cut])
    training=semantics_balanced_select([r for r in available if r['subject'] not in selection_subjects],
        cfg['calibration']['training_windows'],cfg['seed']+302)
    selection=semantics_balanced_select([r for r in available if r['subject'] in selection_subjects],
        cfg['calibration']['selection_windows'],cfg['seed']+303)
    if len(training)<6 or len(selection)<3:raise ValueError('insufficient subject-disjoint calibration support')
    basis=robustness_basis(cfg);wb=basis/np.tile(sd,120)[:,None]
    full=[];coefficients=[];training_results=[]
    for ref in training:
        y=semantics_target(ref,coord)
        fit=robustness_fit(cfg,base,y,sd,{},'M0')
        training_results.append(dict(id=ref['id'],converged=fit['converged'],status=fit['status']))
        if fit['converged']:
            full.append(fit['driver'])
            coefficients.append(np.linalg.lstsq(wb,((y-fit['physical_prediction'])/sd).ravel(),rcond=1e-10)[0])
    if len(full)<3:raise ValueError('too few converged training fits for latent/component scale')
    full=np.array(full);coefficients=np.array(coefficients)
    floor=float(sd.mean())*1e-6
    cal=dict(key=key,driver_sd=max(float(np.sqrt(np.mean(full**2))),floor),
        coefficient_sd=np.maximum(np.sqrt(np.mean(coefficients**2,axis=0)),floor),
        prior_weight=.1,coefficient_multiplier=1.,training_ids=[r['id'] for r in training],
        selection_ids=[r['id'] for r in selection],training_results=training_results,
        training_subjects=sorted({r['subject'] for r in training}),selection_subjects=sorted(selection_subjects),
        coordinate_id=key,scale_source='training_H0_latent_RMS_and_Hb_residual_basis_coefficients_not_noise_estimate')
    scores=[]
    for arm,values in [('M-prior',cfg['prior']['amplitude_weights']),('M-observation',cfg['observation']['coefficient_scale_multipliers'])]:
        candidates=[]
        for value in values:
            rows=[]
            for ref in selection:
                y=semantics_target(ref,coord)
                for mode in cfg['calibration']['selection_modes']:
                    mask=semantics_missing_mask(mode)
                    fit=robustness_fit(cfg,base,y,sd,cal,arm,mask,
                        prior_weight=value if arm=='M-prior' else None,coefficient_multiplier=value if arm=='M-observation' else None)
                    row=robustness_metrics(fit,y,sd,mask);row.update(id=ref['id'],arm=arm,value=value,mode=mode)
                    rows.append(row);scores.append(row)
            candidates.append((value,rows))
        selected,ranking=robustness_select(candidates,'total_nrmse')
        cal['prior_weight' if arm=='M-prior' else 'coefficient_multiplier']=selected
        cal[arm+'_selection_scores']=ranking
    boots=[]
    # Resample complete training records, never individual time samples.
    successful=[r for r in training_results if r['converged']]
    lookup={r['id']:r for r in training}
    groups={}
    for i,row in enumerate(successful):
        ref=lookup[row['id']];groups.setdefault((ref['subject'],ref['record']),[]).append(i)
    group_keys=list(groups)
    for _ in range(2):
        indices=np.concatenate([groups[group_keys[i]] for i in rng.integers(len(group_keys),size=len(group_keys))])
        boots.append(dict(driver_sd=max(float(np.sqrt(np.mean(full[indices]**2))),floor),
            coefficient_sd=np.maximum(np.sqrt(np.mean(coefficients[indices]**2,axis=0)),floor)))
    cal.update(bootstrap_scales=boots,status='completed',seconds=time.monotonic()-start)
    write_json(path,cal);write_json(out/'calibration_scores'/(key+'.json'),scores);return cal


def robustness_measured_worker(payload):
    cfg,base,root,refs,ref=payload;out=Path(root);path=out/'measured'/ref['id']/'result.json'
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
    coord=json.loads((out/'coordinates'/(key+'.json')).read_text());sd=np.array(coord['sd'])
    cal=json.loads((out/'calibration'/(key+'.json')).read_text());y=semantics_target(ref,coord)
    library=[r for r in refs if r['dataset']==ref['dataset'] and r['site']==ref['site'] and r['subject_fold']!=ref['subject_fold']]
    library=semantics_balanced_select(library,18,cfg['seed']+401)
    train=np.array([semantics_target(r,coord) for r in library])
    donor_refs=[r for r in refs if r['dataset']==ref['dataset'] and r['site']==ref['site']
        and r['subject_fold']!=ref['subject_fold'] and r['task']==ref['task'] and r['condition']==ref['condition']]
    donor_ref=min(donor_refs,key=lambda r:r['id']) if donor_refs else None
    donor=semantics_target(donor_ref,coord) if donor_ref else None
    factors=[coord['eeg_factor'],coord['hb_factor'],coord['hb_factor']]
    rows=[];fits={};saved=dict(target=y,sd=sd,native_factors=factors)
    for mode in cfg['measured']['modes']:
        endpoint_mask=np.ones((120,3),bool) if mode=='full' else semantics_missing_mask(mode)
        pairings=[('real',y.copy(),endpoint_mask.copy())]
        if mode!='full':
            other=[1,2] if mode in ('center_EEG','EEG_hidden') else [0]
            if donor is not None:
                wrong=y.copy();wrong[:,other]=donor[:,other];pairings.append(('wrong_subject',wrong,endpoint_mask.copy()))
            support=endpoint_mask.copy();support[-48:,other]=False
            shifted=y.copy();shifted[:-48,other]=y[48:,other]
            pairings.extend([('real_shift_support',y.copy(),support),('nonwrapping_shift_12s',shifted,support)])
            own=np.full_like(y,np.nan)
            for j in range(3):
                visible=np.flatnonzero(endpoint_mask[:,j])
                if len(visible)>1:own[:,j]=np.interp(np.arange(120),visible,y[visible,j])
            predictions=dict(training_template=train.mean(axis=0),own_context=own,
                ridge_own=semantics_ridge_completion(train,y,endpoint_mask,cross=False),
                ridge_cross=semantics_ridge_completion(train,y,endpoint_mask,cross=True))
            for name,pred in predictions.items():
                available=np.isfinite(pred[~endpoint_mask]).all()
                baseline=dict(prediction=pred,physical_prediction=pred,observation_component=np.zeros_like(y),
                    driver=np.zeros(120),converged=bool(available),status='completed' if available else 'not_applicable_no_own_context')
                row=robustness_metrics(baseline,y,sd,endpoint_mask,native_factors=factors) if available else dict(converged=False,status=baseline['status'])
                rows.append(dict(mode=mode,arm=name,pairing='real',**row))
                saved[f'{mode}__{name}__prediction']=pred
        for pairing,data,mask in pairings:
            for arm in ROBUSTNESS_ARMS:
                fit=robustness_fit(cfg,base,data,sd,cal,arm,mask)
                row=robustness_metrics(fit,y,sd,endpoint_mask,native_factors=factors)
                rows.append(dict(mode=mode,arm=arm,pairing=pairing,**row))
                if pairing=='real':
                    fits[mode,arm]=fit
                    if 'driver' in fit:
                        for name in ('driver','prediction','physical_prediction','observation_component'):
                            saved[f'{mode}__{arm}__{name}']=fit[name]
    sensitivity=[];teachers={}
    for arm in ROBUSTNESS_ARMS:
        alternatives=[]
        for variant in cfg['measured']['sensitivity']:
            data=y.copy();mask=np.ones((120,3),bool);options={};c=deepcopy(cal)
            if variant.startswith('EEG_gain'):data[:,0]/=.9 if variant.endswith('low') else 1.1
            if variant.startswith('Hb_gain'):data[:,1:]/=.9 if variant.endswith('low') else 1.1
            if variant=='lag_minus_one_sample':data[1:,1:]=y[:-1,1:];mask[0,1:]=False
            if variant=='lag_plus_one_sample':data[:-1,1:]=y[1:,1:];mask[-1,1:]=False
            if variant.startswith('prior_'):options['prior_weight']=cal['prior_weight']*(.5 if variant=='prior_half' else 2.)
            if variant.startswith('rho_'):options['rho']=.25 if variant=='rho_low' else .45
            if variant.startswith('training_bootstrap'):c.update(cal['bootstrap_scales'][int(variant[-1])])
            unchanged=((variant.startswith('prior_') and arm not in ('M-prior','M-combined'))
                or (variant.startswith('rho_') and arm not in ('M-observation','M-combined'))
                or (variant.startswith('training_bootstrap') and arm=='M0'))
            fit=fits['full',arm] if unchanged else robustness_fit(cfg,base,data,sd,c,arm,mask,**options)
            alternatives.append(fit)
            row=robustness_metrics(fit,y,sd,np.ones((120,3),bool),native_factors=factors)
            if 'driver' in fit and 'driver' in fits['full',arm]:
                row['driver_change_SD']=float(np.sqrt(np.mean((fit['driver']-fits['full',arm]['driver'])**2))/cal['driver_sd'])
            sensitivity.append(dict(arm=arm,variant=variant,reused_identical_inactive_setting=unchanged,**row))
        if 'driver' not in fits['full',arm]:continue
        # Missingness changes are recorded separately: stability under small
        # calibration changes must not certify an unobserved modality.
        teacher=robustness_teacher(fits['full',arm],alternatives,cal['driver_sd'],cfg['teacher']['sensitivity_threshold_SD'])
        missing=[fits[mode,arm] for mode in ('center_EEG','EEG_hidden','Hb_hidden')]
        missing_teacher=robustness_teacher(fits['full',arm],missing,cal['driver_sd'],cfg['teacher']['sensitivity_threshold_SD'])
        for field in ('driver','reference_centered_driver','robustness_mask','centered_robustness_mask','sensitivity_SD','centered_sensitivity_SD'):
            saved[arm+'__teacher__'+field]=teacher[field]
        saved[arm+'__teacher__missingness_robustness_mask']=missing_teacher['robustness_mask']
        saved[arm+'__teacher__observation_residual']=y-fits['full',arm]['prediction']
        teachers[arm]=dict(coordinate_id=key,parameter_policy='H0_fixed',driver_scale=cal['driver_sd'],
            robust_fraction=float(teacher['robustness_mask'].mean()),
            centered_robust_fraction=float(teacher['centered_robustness_mask'].mean()),
            missingness_robust_fraction=float(missing_teacher['robustness_mask'].mean()),
            sensitivity_complete=teacher['sensitivity_complete'],claim=teacher['interpretation'])
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',ref=ref,coordinate_id=key,rows=rows,sensitivity=sensitivity,teachers=teachers,
        donor_id=donor_ref['id'] if donor_ref else None,donor_subject=donor_ref['subject'] if donor_ref else None,
        null_status='available' if donor_ref else 'no_task_condition_matched_training_donor',
        training_ids=[r['id'] for r in library],seconds=time.monotonic()-start,
        peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024)
    write_json(path,result);return result


def robustness_profile_worker(payload):
    cfg,base,root,ref=payload;out=Path(root);path=out/'profiles'/ref['id']/'result.json'
    if path.exists():return json.loads(path.read_text())
    key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
    coord=json.loads((out/'coordinates'/(key+'.json')).read_text());sd=np.array(coord['sd'])
    cal=json.loads((out/'calibration'/(key+'.json')).read_text());y=semantics_target(ref,coord)
    rows=[];saved={}
    for arm in ROBUSTNESS_ARMS:
        for parameter,values in [('tau',cfg['measured']['tau_profile']),('neurovascular_gain',cfg['measured']['gain_profile'])]:
            for value in values:
                fit=robustness_fit(cfg,base,y,sd,cal,arm,parameters=semantics_parameters(base,**{parameter:value}))
                row=robustness_metrics(fit,y,sd,np.ones((120,3),bool));rows.append(dict(arm=arm,parameter=parameter,value=value,**row))
                if 'driver' in fit:saved[f'{arm}__{parameter}__{value:g}']=fit['driver']
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',ref=ref,rows=rows,interpretation='fixed_one_parameter_grid_reoptimizes_driver_initial_and_component_not_confidence_interval')
    write_json(path,result);return result


def robustness_group_summary(frame, keys, metrics):
    rows=[]
    for values,group in frame.groupby(keys,dropna=False,sort=True):
        if not isinstance(values,tuple):values=(values,)
        row=dict(zip(keys,values));good=group[group.converged]
        row.update(denominator=len(group),converged=len(good),success_fraction=len(good)/len(group))
        for metric in metrics:
            if metric not in good:continue
            finite=pd.to_numeric(good[metric],errors='coerce').dropna()
            row[metric+'_median']=float(finite.median()) if len(finite) else None
            row[metric+'_mean']=float(finite.mean()) if len(finite) else None
            row[metric+'_p90']=float(finite.quantile(.9)) if len(finite) else None
        rows.append(row)
    return pd.DataFrame(rows)


def robustness_paired(frame, keys, *, control='M0', value='total_nrmse', cluster='subject', seed=20261001,
                      arms=ROBUSTNESS_ARMS):
    rows=[]
    for group_values,group in frame.groupby(keys,sort=True):
        if not isinstance(group_values,tuple):group_values=(group_values,)
        identity='id' if 'id' in group else 'key'
        reference=group[group.arm==control].set_index(identity)
        for arm in arms:
            if arm==control:continue
            candidate=group[group.arm==arm].set_index(identity)
            ids=reference.index.intersection(candidate.index)
            if not len(ids):continue
            both=reference.loc[ids].converged.to_numpy() & candidate.loc[ids].converged.to_numpy()
            pair=ids[both];deltas=reference.loc[pair,value]-candidate.loc[pair,value]
            labels=candidate.loc[pair,cluster]
            unit=pd.DataFrame(dict(delta=deltas.to_numpy(),unit=labels.to_numpy())).groupby('unit').delta.mean()
            interval=semantics_bootstrap_mean(unit.to_numpy(),seed,1000) if len(unit) else [None,None]
            rows.append(dict(zip(keys,group_values),arm=arm,control=control,denominator=len(ids),common_success=len(pair),
                independent_units=len(unit),mean_gain=float(unit.mean()) if len(unit) else None,
                median_gain=float(deltas.median()) if len(pair) else None,ci_low=interval[0],ci_high=interval[1],
                metric=value,interval='subject_or_seed_block_bootstrap_conditional_frozen_coordinates'))
    return rows


def robustness_summary(cfg,out):
    synthetic=[];contrasts=[];reliability=[];missing=[]
    for spec in json.loads((out/'synthetic_plan.json').read_text()):
        path=out/'synthetic'/spec['key']/'result.json'
        if not path.exists():missing.append(str(path));continue
        result=json.loads(path.read_text());synthetic.extend(result['rows']);contrasts.extend(result['contrasts']);reliability.extend(result['reliability'])
    syn=pd.DataFrame(synthetic);syn.to_csv(out/'synthetic_metrics.csv',index=False)
    syn_summary=robustness_group_summary(syn,['scenario','mode','arm'],['driver_nrmse','centered_driver_nrmse','total_nrmse','physical_nrmse','physical_truth_nrmse','component_truth_nrmse','driver_correlation'])
    syn_summary.to_csv(out/'synthetic_summary.csv',index=False)
    syn_pairs=robustness_paired(syn,['scenario','mode'],value='driver_nrmse',cluster='repeat',seed=cfg['seed'])
    pd.DataFrame(syn_pairs).to_csv(out/'synthetic_paired.csv',index=False)
    contrast=pd.DataFrame(contrasts);contrast.to_csv(out/'counterfactual_metrics.csv',index=False)
    robustness_group_summary(contrast,['scenario','mode','arm'],['change_error_SD','estimated_change_SD','truth_change_SD']).to_csv(out/'counterfactual_summary.csv',index=False)
    pd.DataFrame(reliability).to_csv(out/'synthetic_reliability.csv',index=False)
    measured=[];sensitivities=[];teachers=[];repeat_rows=[]
    plan=json.loads((out/'measured_plan.json').read_text())
    for ref in plan['windows']:
        path=out/'measured'/ref['id']/'result.json'
        if not path.exists():missing.append(str(path));continue
        result=json.loads(path.read_text());identity={k:ref.get(k) for k in ('id','dataset','subject','record','site','repeat_fold','repeat_kind','native_rho','quality_burden')}
        for row in result['rows']:
            row=dict(identity,**row)
            component=row.get('total_component_nrmse')
            row['full_pass']=bool(row['mode']=='full' and row['converged'] and component and all(x is not None and x<.5 for x in component))
            measured.append(row)
        sensitivities.extend(dict(identity,**row) for row in result['sensitivity'])
        teachers.extend(dict(identity,arm=arm,**value) for arm,value in result['teachers'].items())
        with np.load(path.with_suffix('.npz'),allow_pickle=False) as arrays:
            for arm,value in result['teachers'].items():
                driver=arrays[arm+'__teacher__driver'];prediction=arrays[f'full__{arm}__physical_prediction']
                component=arrays[f'full__{arm}__observation_component'];sd=arrays['sd']
                repeat_rows.append(dict(identity,arm=arm,driver_RMS_SD=float(np.sqrt(np.mean(driver**2)))/value['driver_scale'],
                    component_RMS_SD=float(np.sqrt(np.mean((component[:,1:]/sd[1:])**2))),
                    robust_fraction=value['robust_fraction']))
    frame=pd.DataFrame(measured);frame.to_csv(out/'measured_metrics.csv',index=False)
    measured_summary=robustness_group_summary(frame,['dataset','mode','pairing','arm'],
        ['total_nrmse','physical_nrmse','total_local_nrmse','component_rms_training_SD','driver_rms'])
    measured_summary.to_csv(out/'measured_summary.csv',index=False)
    paired=[]
    real=frame[frame.pairing=='real']
    for control in ['M0','training_template','own_context','ridge_own','ridge_cross']:
        paired.extend(robustness_paired(real,['dataset','mode'],control=control,seed=cfg['seed']))
    pd.DataFrame(paired).to_csv(out/'measured_paired.csv',index=False)
    nulls=[]
    for ds,mode,arm in sorted(set(zip(frame.dataset,frame['mode'],frame.arm))):
        group=frame[(frame.dataset==ds)&(frame['mode']==mode)&(frame.arm==arm)]
        for bad,reference in [('wrong_subject','real'),('nonwrapping_shift_12s','real_shift_support')]:
            wrong=group[group.pairing==bad].set_index('id');right=group[group.pairing==reference].set_index('id')
            ids=wrong.index.intersection(right.index)
            if not len(ids):continue
            good=wrong.loc[ids].converged.to_numpy()&right.loc[ids].converged.to_numpy();valid=ids[good]
            delta=wrong.loc[valid,'total_nrmse']-right.loc[valid,'total_nrmse']
            means=pd.DataFrame(dict(delta=delta.to_numpy(),subject=right.loc[valid,'subject'].to_numpy())).groupby('subject').delta.mean()
            ci=semantics_bootstrap_mean(means.to_numpy(),cfg['seed'],1000) if len(means) else [None,None]
            nulls.append(dict(dataset=ds,mode=mode,arm=arm,null=bad,denominator=len(ids),common_success=len(valid),
                independent_subjects=len(means),true_pair_gain=float(means.mean()) if len(means) else None,ci_low=ci[0],ci_high=ci[1]))
    pd.DataFrame(nulls).to_csv(out/'null_comparisons.csv',index=False)
    pd.DataFrame(sensitivities).to_csv(out/'sensitivity_metrics.csv',index=False)
    pd.DataFrame(teachers).to_csv(out/'teacher_summary.csv',index=False)
    repeat=pd.DataFrame(repeat_rows);repeat.to_csv(out/'repeatability_functions.csv',index=False)
    repeat_summary=[]
    for (ds,arm,kind),group in repeat.groupby(['dataset','arm','repeat_kind']):
        for metric in ('driver_RMS_SD','component_RMS_SD','robust_fraction'):
            grouped=group.groupby(['subject','repeat_fold'])[metric].mean().unstack()
            if not {0,1}.issubset(grouped.columns):continue
            matched=grouped[[0,1]].dropna();a,b=matched[0].to_numpy(),matched[1].to_numpy()
            relative=2*abs(a-b)/np.maximum(abs(a)+abs(b),1e-12)
            repeat_summary.append(dict(dataset=ds,arm=arm,repeat_kind=kind,metric=metric,subjects=len(matched),
                symmetric_relative_difference_median=float(np.median(relative)),icc_absolute=semantics_icc_absolute(matched.to_numpy()),
                interpretation='different_record_or_block_function_stability_not_same_latent_truth_or_individual_parameter_repeatability'))
    pd.DataFrame(repeat_summary).to_csv(out/'repeatability_summary.csv',index=False)
    profiles=[];profile_summary=[]
    for ref in json.loads((out/'profile_plan.json').read_text()):
        path=out/'profiles'/ref['id']/'result.json'
        if not path.exists():missing.append(str(path));continue
        result=json.loads(path.read_text());identity={k:ref[k] for k in ('id','dataset','subject')}
        profiles.extend(dict(identity,**r) for r in result['rows'])
        values=pd.DataFrame(result['rows']);key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
        cal=json.loads((out/'calibration'/(key+'.json')).read_text())
        with np.load(path.with_suffix('.npz'),allow_pickle=False) as arrays:
            for (arm,parameter),group in values.groupby(['arm','parameter']):
                good=group[group.converged]
                if good.empty:continue
                best=good.loc[good.objective.idxmin()]
                near=good[good.objective<=best.objective*(1+cfg['teacher']['near_equivalent_objective_fraction'])]
                drivers=np.array([arrays[f'{arm}__{parameter}__{v:g}'] for v in near.value])
                spread=float(np.sqrt(np.mean(np.ptp(drivers,axis=0)**2)))/cal['driver_sd']
                profile_summary.append(dict(identity,arm=arm,parameter=parameter,best_value=float(best.value),
                    denominator=len(group),converged=len(good),near_equivalent=len(near),near_min=float(near.value.min()),
                    near_max=float(near.value.max()),driver_spread_SD=spread,
                    grid_edge=bool(best.value in (group.value.min(),group.value.max()))))
    pd.DataFrame(profiles).to_csv(out/'profile_metrics.csv',index=False)
    pd.DataFrame(profile_summary).to_csv(out/'profile_summary.csv',index=False)
    summary=dict(schema='shared_driver_teacher_robustness_summary_v1',experiment_id=cfg['experiment_id'],
        execution='completed' if not missing else 'incomplete',missing_task_records=missing,
        synthetic=dict(cases=len(json.loads((out/'synthetic_plan.json').read_text())),fits=len(syn),converged=int(syn.converged.sum())),
        measured=dict(windows=len(plan['windows']),subjects=len({(r['dataset'],r['subject']) for r in plan['windows']}),
            fits=int(frame.arm.isin(ROBUSTNESS_ARMS).sum()),converged=int(frame[frame.arm.isin(ROBUSTNESS_ARMS)].converged.sum()),
            sensitivity_fits=len(sensitivities),profile_fits=len(profiles)),
        full_pass={ds:{arm:int(real[(real.dataset==ds)&(real.arm==arm)&(real['mode']=='full')].full_pass.sum())
            for arm in ROBUSTNESS_ARMS} for ds in sorted(real.dataset.unique())},
        endpoint_files=['synthetic_summary.csv','synthetic_paired.csv','counterfactual_summary.csv','measured_summary.csv',
            'measured_paired.csv','null_comparisons.csv','teacher_summary.csv','repeatability_summary.csv','profile_summary.csv'],
        claim_boundary='engineering conditional teacher candidate; no calibrated posterior, unique physiological source, individual parameter release or tokenizer qualification',
        finished_at=datetime.now(timezone.utc).isoformat())
    write_json(out/'summary.json',summary)
    if missing:raise ValueError('incomplete suite; per-task missing records retained')
    return summary


def robustness_verify(cfg,out):
    """Recompute saved real-pair errors and decomposition without refitting."""
    summary=json.loads((out/'summary.json').read_text())
    if summary['execution']!='completed':raise ValueError('incomplete robustness evidence')
    plan=json.loads((out/'measured_plan.json').read_text());maximum=closure=0.;scored=0;failures=[]
    for ref in plan['windows']:
        key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
        cal=json.loads((out/'calibration'/(key+'.json')).read_text())
        coord=json.loads((out/'coordinates'/(key+'.json')).read_text())
        if (ref['subject'] in set(cal['training_subjects'])|set(cal['selection_subjects'])|set(coord['training_subjects'])
                or set(cal['training_subjects'])&set(cal['selection_subjects'])):
            failures.append(ref['id']+'/training_subject_overlap')
        path=out/'measured'/ref['id']/'result.json';result=json.loads(path.read_text())
        real=[r for r in result['rows'] if r['pairing']=='real' and r['arm'] in ROBUSTNESS_ARMS]
        if len(real)!=len(cfg['measured']['modes'])*len(ROBUSTNESS_ARMS):failures.append(ref['id']+'/denominator')
        with np.load(path.with_suffix('.npz'),allow_pickle=False) as arrays:
            target,sd=arrays['target'],arrays['sd']
            if not np.array_equal(sd,np.asarray(coord['sd'])):failures.append(ref['id']+'/training_scale')
            for row in real:
                prefix=row['mode']+'__'+row['arm']+'__'
                if prefix+'prediction' not in arrays:
                    if row['converged']:failures.append(ref['id']+'/'+prefix+'missing_prediction')
                    continue
                mask=np.ones((120,3),bool) if row['mode']=='full' else ~semantics_missing_mask(row['mode'])
                for field,name in [('prediction','total'),('physical_prediction','physical')]:
                    value=float(np.sqrt(np.mean(((arrays[prefix+field]-target)/sd)[mask]**2)))
                    maximum=max(maximum,abs(value-row[name+'_nrmse']));scored+=1
                delta=arrays[prefix+'prediction']-arrays[prefix+'physical_prediction']-arrays[prefix+'observation_component']
                closure=max(closure,float(np.max(abs(delta))))
                if row['mode']=='Hb_hidden' and np.any(arrays[prefix+'observation_component']):failures.append(ref['id']+'/hidden_component')
    if maximum>1e-10 or closure>1e-10:failures.append('metric_or_decomposition_reproduction')
    result=dict(status='passed' if not failures else 'failed',windows=len(plan['windows']),scores_recomputed=scored,
        max_score_error=maximum,max_decomposition_error=closure,failures=failures,
        inherited_synthetic_run=cfg.get('retained_run'),native_arrays_read=0,refits=0)
    write_json(out/'verification.json',result)
    if failures:raise ValueError('robustness evidence verification failed')
    return result


def robustness_main(args):
    cfg=robustness_config(args.config);base=semantics_config(CODE_ROOT/cfg['source_config'])
    if args.check_only:
        print(json.dumps(dict(status='contract_valid',experiment_id=cfg['experiment_id'],measured_arrays_read=0,
            synthetic_cells=cfg['synthetic']['repeats']*len(cfg['synthetic']['spectra'])*len(cfg['synthetic']['initial']))));return
    if args.run_dir is None:raise ValueError('--run-dir required')
    out=args.run_dir.resolve();expected=(args.project_root/cfg['artifact_root']).resolve()
    if out.parent!=expected:raise ValueError('run must be direct child of registered artifact root')
    if not 1<=args.workers<=cfg['resources']['max_workers']:raise ValueError('worker bound')
    out.mkdir(parents=True,exist_ok=True)
    lock=(out/'controller.lock').open('w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    resolved=out/'resolved_config.yaml'
    if resolved.exists() and yaml.safe_load(resolved.read_text())!=cfg:raise ValueError('immutable run config mismatch')
    if not resolved.exists():resolved.write_text(yaml.safe_dump(cfg,sort_keys=False))
    stage=args.robustness_stage;manifest=out/(stage+'_manifest.json')
    if manifest.exists() and json.loads(manifest.read_text()).get('execution')=='completed':
        print('Already completed:',stage);return
    state=dict(experiment_id=cfg['experiment_id'],stage=stage,execution='running',controller_pid=os.getpid(),
        workers=args.workers,started_at=datetime.now(timezone.utc).isoformat(),source_root=str(CODE_ROOT))
    write_json(manifest,state)
    try:
        failures=[]
        if stage in ('synthetic_calibration','pilot'):
            if stage=='pilot':
                case=robustness_synthetic_case(cfg,base,0,'slow','rest','common_basis',calibration=True)
                cal=dict(driver_sd=.025,coefficient_sd=[.004,.003,.002,.001],prior_weight=.1,coefficient_multiplier=1.)
                sd=np.std(case['target'],axis=0);rows=[]
                for arm in ROBUSTNESS_ARMS:
                    start=time.monotonic();fit=robustness_fit(cfg,base,case['target'],sd,cal,arm)
                    rows.append(dict(arm=arm,seconds=time.monotonic()-start,**robustness_metrics(fit,case['target'],sd,np.ones((120,3),bool),driver=case['driver'],driver_sd=.025)))
                write_json(out/'pilot.json',dict(rows=rows,peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024))
            else:robustness_synthetic_calibration(cfg,base,out,args.workers)
        elif stage=='synthetic':
            specs=[dict(repeat=i,spectrum=s,initial=a,key=f'{s}_{a}_r{i}') for i in range(cfg['synthetic']['repeats'])
                for s in cfg['synthetic']['spectra'] for a in cfg['synthetic']['initial']]
            write_json(out/'synthetic_plan.json',specs)
            failures=semantics_parallel_stage(cfg,out,stage,robustness_synthetic_worker,
                [(cfg,base,str(out),s) for s in specs],args.workers,lambda p:p[-1]['key'])
        elif stage in ('calibration','measured','profiles'):
            # Synthetic implementation execution precedes the first measured read.
            if json.loads((out/'synthetic_manifest.json').read_text()).get('execution')!='completed':
                raise ValueError('complete synthetic execution before measured input')
            parent,refs,panel,coordinates=robustness_parent_inputs(cfg,args.project_root,out)
            if stage=='calibration':
                payloads=[(cfg,base,str(out),refs,key) for key in coordinates]
                failures=semantics_parallel_stage(cfg,out,stage,robustness_calibration_worker,payloads,args.workers,lambda p:p[-1])
            elif stage=='measured':
                payloads=[(cfg,base,str(out),refs,ref) for ref in panel]
                failures=semantics_parallel_stage(cfg,out,stage,robustness_measured_worker,payloads,args.workers,lambda p:p[-1]['id'])
            else:
                selected=[]
                for ds in sorted({r['dataset'] for r in panel}):
                    candidates=sorted([r for r in panel if r['dataset']==ds],key=lambda r:r['id'])
                    subjects=sorted({r['subject'] for r in candidates})[:cfg['measured']['profile_windows_per_dataset']]
                    selected.extend(next(r for r in candidates if r['subject']==s) for s in subjects)
                write_json(out/'profile_plan.json',selected)
                failures=semantics_parallel_stage(cfg,out,stage,robustness_profile_worker,
                    [(cfg,base,str(out),r) for r in selected],args.workers,lambda p:p[-1]['id'])
        elif stage=='summarize':robustness_summary(cfg,out)
        elif stage=='verify':robustness_verify(cfg,out)
        state.update(execution='completed' if not failures else 'completed_with_task_failures',task_failures=failures,
            finished_at=datetime.now(timezone.utc).isoformat())
    except Exception as exc:
        state.update(execution='failed',error=repr(exc),traceback=traceback.format_exc());raise
    finally:write_json(manifest,state)


ATTRIBUTION_ARMS = ('M0', 'D-fixed', 'D-trained', 'D-exchange')


def attribution_config(path):
    cfg = yaml.safe_load(Path(path).read_text())
    refed=cfg.get('schema')=='shared_driver_attribution_refed_v2'
    if (cfg.get('schema') not in ('shared_driver_attribution_v1','shared_driver_attribution_refed_v2')
            or cfg['source_run'] != 'experiments/runs/physiology_semantic_tokenizer/shared_driver_reconstruction/'+('20261013_refed_physiology_semantics_v3' if refed else '20260928_physiology_semantics_v1')
            or cfg['robustness_run'] != 'experiments/runs/physiology_semantic_tokenizer/shared_driver_teacher_robustness/'+('20261013_refed_v2' if refed else '20261001_v1')
            or cfg['source_config'] != 'experiments/configs/physiology_semantic_tokenizer/shared_driver_physiology_semantics_'+('refed_v2' if refed else 'v1')+'.yaml'
            or cfg['robustness_config'] != 'experiments/configs/physiology_semantic_tokenizer/shared_driver_teacher_robustness_'+('refed_v2' if refed else 'v1')+'.yaml'
            or cfg['protected_data'] != 'forbidden'
            or cfg['data_boundary'] != 'public_parent_panel_training_and_synchronous_regions_plus_registered_EOG'
            or cfg['direction']['arms'] != list(ATTRIBUTION_ARMS)
            or cfg['tensor'] != dict(steps=120, components=3, dt_s=.25, state_order=['r','s','f','v','p','q'])):
        raise ValueError('attribution identity, tensor or data boundary violated')
    if (cfg['direction']['modes'] != 4 or cfg['direction']['fixed_rho'] != .35
            or cfg['direction']['rho_candidates'] != [.1,.2,.35,.5,.65,.8,.9]
            or cfg['prototype']['scope'] != 'synthetic_only_continuous_typed_tokens_no_VQ_no_measured_training'
            or cfg['anchors']['dataset'] != 'simultaneous_eeg_nirs'):
        raise ValueError('unregistered direction or prototype contract')
    return cfg


def attribution_basis(cfg, arm, calibration):
    from src.inference.shared_driver_attribution import equal_capacity_hb_basis
    rho = calibration.get('selected_rho', .35) if arm == 'D-trained' else .35
    return equal_capacity_hb_basis(semantics_model_operator(), modes=cfg['direction']['modes'],
        rho=rho, exchange=arm == 'D-exchange')


def attribution_fit(cfg, base, target, sd, calibration, arm, visible=None, *,
                    parameters=None, jacobian=False, fixed_component=None):
    from src.inference.shared_driver_reconstruction import fit_nonlinear_shared_driver
    options = semantics_solver_options(base)
    if arm == 'D-combined':
        options.update(driver_amplitude_weight=calibration['prior_weight'], driver_prior_sd=calibration['driver_sd'])
    if arm not in ('M0', 'oracle') and fixed_component is None:
        key = arm if arm != 'D-combined' else 'D-fixed'
        options.update(observation_basis=attribution_basis(cfg, key, calibration),
            observation_coefficient_sd=np.asarray(calibration['direction_scales'][key])*calibration['coefficient_multiplier'])
    mask = np.ones_like(target, bool) if visible is None else np.asarray(visible, bool)
    y = np.array(target, copy=True)
    if fixed_component is not None:y -= fixed_component
    y[~mask] = np.nan
    fit = fit_nonlinear_shared_driver(y, parameters or semantics_parameters(base), .25,
        mean_operator=semantics_model_operator(), sd=sd, visible=mask, return_jacobian=jacobian,
        max_evaluations=base['solver']['max_evaluations_per_trial'], **options)
    if fixed_component is not None and 'prediction' in fit:
        fit['observation_component'] = fixed_component
        fit['prediction'] = fit['physical_prediction']+fixed_component
    return fit


def attribution_synthetic_case(cfg, base, repeat, spectrum, initial, scenario, *, calibration=False):
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    from src.inference.shared_driver_attribution import equal_capacity_hb_basis
    old = robustness_config(CODE_ROOT/cfg['robustness_config'])
    old['seed'] = cfg['seed']
    custom = scenario in ('common_rho070', 'common_exchange', 'physiology_kappa', 'unmodeled_dynamics')
    case = robustness_synthetic_case(old, base, repeat, spectrum, initial,
        'control' if custom else scenario, calibration=calibration)
    if not custom:return case
    op = semantics_model_operator()
    if scenario in ('common_rho070', 'common_exchange'):
        rng = np.random.default_rng(np.random.SeedSequence([cfg['seed'], 501 if calibration else 601,
            repeat, int(spectrum == 'mixed'), int(initial == 'nonrest')]))
        basis = equal_capacity_hb_basis(op, rho=.7, exchange=scenario == 'common_exchange')
        component = (basis@(rng.normal(size=4)*[.02,.015,.01,.005])).reshape(120,3)
        case['target'] += component;case['observation_truth'] = component
    else:
        driver = case['driver']
        parameters = semantics_parameters(base, **({'kappa':1.28} if scenario == 'physiology_kappa' else {}))
        if scenario == 'unmodeled_dynamics':
            delayed = np.r_[np.repeat(driver[0],8),driver[:-8]]
            driver = .65*driver+.35*delayed
        forward = nonlinear_driver_forward(driver, case['states'][0,1:], parameters, .25,
            derivative=False, substeps=8, numerical_backend='numba', hemodynamics='inlet_balance', viscoelastic_s=0.)
        physical = (op@forward['canonical_prediction'].ravel()).reshape(120,3)
        if scenario == 'unmodeled_dynamics':physical[:,0] = case['physical_truth'][:,0]
        case['target'] += physical-case['physical_truth'];case['physical_truth'] = physical
        case['states'] = forward['states']
    return case


def attribution_direction_select_worker(payload):
    cfg, base, cal, rho, repeat = payload
    c = dict(cal, selected_rho=rho)
    rows = []
    for scenario in ('control','common_basis','common_correlated'):
        case = attribution_synthetic_case(cfg,base,repeat,'slow','rest',scenario,calibration=True)
        for mode in cfg['direction']['selection_modes']:
            mask = semantics_missing_mask(mode)
            fit = attribution_fit(cfg,base,case['target'],cal['sd'],c,'D-trained',mask)
            rows.append(dict(rho=rho,repeat=repeat,scenario=scenario,mode=mode,
                **robustness_metrics(fit,case['target'],cal['sd'],mask)))
    return rows


def attribution_synthetic_calibration(cfg, base, out, workers, project_root):
    old = json.loads((Path(project_root)/cfg['robustness_run']/'synthetic_calibration.json').read_text())
    cases = [attribution_synthetic_case(cfg,base,i,'slow','rest','control',calibration=True)
        for i in range(cfg['synthetic']['training_repeats'])]
    # Fit no statistics on evaluation seeds; retain old regularization strengths.
    cal = dict(driver_sd=float(np.sqrt(np.mean([c['driver']**2 for c in cases]))),
        sd=np.std(np.concatenate([c['target'] for c in cases]),axis=0),
        direction_scales={a:[.02,.015,.01,.005] for a in ATTRIBUTION_ARMS if a!='M0'},
        prior_weight=old['prior_weight'], coefficient_multiplier=old['coefficient_multiplier'],
        selected_rho=.35, training_seed_stream=101, evaluation_seed_stream=201,
        interpretation='training_generator_scale_with_parent_regularization_no_test_selection')
    payloads = [(cfg,base,cal,rho,i) for rho in cfg['direction']['rho_candidates']
        for i in range(cfg['synthetic']['training_repeats'])]
    rows = []
    for _, result, error in bounded_nonlinear_work(attribution_direction_select_worker,payloads,workers,2*workers):
        if error:raise RuntimeError(error)
        rows.extend(result)
    selected, ranking = robustness_select([(rho,[r for r in rows if r['rho']==rho])
        for rho in cfg['direction']['rho_candidates']], 'total_nrmse')
    cal.update(selected_rho=selected,selection_scores=ranking)
    write_json(out/'synthetic_calibration.json',cal)
    pd.DataFrame(rows).to_csv(out/'synthetic_calibration_scores.csv',index=False)


def attribution_synthetic_worker(payload):
    cfg, base, root, spec = payload;out=Path(root);path=out/'synthetic'/spec['key']/'result.json'
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();cal=json.loads((out/'synthetic_calibration.json').read_text());sd=np.array(cal['sd'])
    rows=[];saved={};fits={};cases={}
    for scenario in cfg['synthetic']['scenarios']:
        case=attribution_synthetic_case(cfg,base,spec['repeat'],spec['spectrum'],spec['initial'],scenario)
        cases[scenario]=case
        for mode in cfg['synthetic']['modes']:
            mask=np.ones((120,3),bool) if mode=='full' else semantics_missing_mask(mode)
            arms=cfg['synthetic']['arms']+(['oracle'] if scenario in cfg['synthetic']['physiological_oracle'] else [])
            for arm in arms:
                parameters=semantics_parameters(base,**({'tau':4.} if scenario=='physiology_tau' else {'kappa':1.28})) if arm=='oracle' else None
                fit=attribution_fit(cfg,base,case['target'],sd,cal,arm,mask,parameters=parameters)
                fits[scenario,mode,arm]=fit
                row=robustness_metrics(fit,case['target'],sd,mask,driver=case['driver'],driver_sd=cal['driver_sd'])
                if 'prediction' in fit:
                    row.update(physical_truth_nrmse=float(np.sqrt(np.mean(((fit['physical_prediction']-case['physical_truth'])/sd)**2))),
                        component_truth_nrmse=float(np.sqrt(np.mean(((fit['observation_component']-case['observation_truth'])/sd)**2))))
                    for name in ('driver','prediction','physical_prediction','observation_component'):
                        saved[f'{scenario}__{mode}__{arm}__{name}']=fit[name]
                rows.append(dict(**spec,scenario=scenario,mode=mode,arm=arm,**row))
        for name in ('driver','target','physical_truth','observation_truth','states'):
            saved[f'{scenario}__truth__{name}']=case[name]
    contrasts=[]
    for mode in cfg['synthetic']['modes']:
        for arm in cfg['synthetic']['arms']:
            reference=fits['control',mode,arm]
            for scenario in cfg['synthetic']['scenarios']:
                fit=fits[scenario,mode,arm];case=cases[scenario]
                row=dict(**spec,mode=mode,arm=arm,scenario=scenario,
                    converged=bool(reference['converged'] and fit['converged']))
                if 'driver' in reference and 'driver' in fit:
                    change=fit['driver']-reference['driver'];truth=case['driver']-cases['control']['driver']
                    physical_delta=case['physical_truth']-cases['control']['physical_truth']
                    extra_delta=case['observation_truth']-cases['control']['observation_truth']
                    signal_delta=physical_delta+extra_delta
                    row.update(driver_change_error_SD=float(np.sqrt(np.mean((change-truth)**2)))/cal['driver_sd'],
                        driver_estimated_change_SD=float(np.sqrt(np.mean(change**2)))/cal['driver_sd'],
                        driver_truth_change_SD=float(np.sqrt(np.mean(truth**2)))/cal['driver_sd'])
                    for field,true in [('physical_prediction',physical_delta),('observation_component',extra_delta)]:
                        estimated=fit[field]-reference[field]
                        row[field+'_change_error_SD']=float(np.sqrt(np.mean(((estimated-true)/sd)**2)))
                        denominator=float(np.sum((signal_delta/sd)**2))
                        row[field+'_projection_fraction']=float(np.sum((estimated/sd)*(signal_delta/sd))/denominator) if denominator>1e-12 else None
                    residual_delta=(case['target']-fit['prediction'])-(cases['control']['target']-reference['prediction'])
                    denominator=float(np.sum((signal_delta/sd)**2))
                    row['residual_projection_fraction']=float(np.sum((residual_delta/sd)*(signal_delta/sd))/denominator) if denominator>1e-12 else None
                contrasts.append(row)
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',spec=spec,rows=rows,contrasts=contrasts,seconds=time.monotonic()-start,
        peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024)
    write_json(path,result);return result


def attribution_parent(cfg, project_root, out):
    old = robustness_config(CODE_ROOT/cfg['robustness_config'])
    parent, refs, panel, coordinates = robustness_parent_inputs(old, project_root, out)
    previous = Path(project_root)/cfg['robustness_run']
    if json.loads((previous/'summary.json').read_text())['execution'] != 'completed':
        raise ValueError('previous robustness evidence is not terminal')
    previous_panel = json.loads((previous/'measured_plan.json').read_text())['windows']
    if [r['id'] for r in panel] != [r['id'] for r in previous_panel]:
        raise ValueError('paired panel differs from retained robustness panel')
    if cfg.get('schema')=='shared_driver_attribution_refed_v2':
        write_json(out/'anchor_plan.json',dict(coordinate_keys=[],refs=[],status='not_run',
            source_status='no_REFED_EOG_in_current_native_reader',native_arrays_read=0))
    return parent, previous, refs, panel, coordinates


def attribution_donors(ref, refs):
    return sorted([r for r in refs if r['key']==ref['key'] and r['window']==ref['window']
        and r['site']!=ref['site'] and r['hb_channel']!=ref['hb_channel']
        and abs(r['eeg_start_s']-ref['eeg_start_s'])<1e-6
        and abs(r['hb_start_s']-ref['hb_start_s'])<1e-6],key=lambda r:r['id'])


def attribution_spatial_inputs(cfg, base, parent, refs, ref, coordinate, calibration):
    """Never inspect the target Hb: donors are distinct, synchronous Hb pairs."""
    from src.inference.shared_driver_attribution import project_component
    donors=attribution_donors(ref,refs);raw=[];residuals=[];records=[]
    for donor in donors:
        outer=coordinate['key'].rsplit('__outer',1)[1]
        key=f'{donor["dataset"]}__{donor["site"]}__outer{outer}'
        coord=json.loads((parent/'coordinates'/(key+'.json')).read_text())
        if ref['subject'] not in coordinate['training_subjects'] and ref['subject'] in coord['training_subjects']:
            raise ValueError('spatial donor coordinate leaked held-out subject')
        target=semantics_target(donor,coord)
        fit=attribution_fit(cfg,base,target,coord['sd'],calibration,'M0')
        records.append(dict(id=donor['id'],converged=fit['converged'],status=fit['status']))
        if 'physical_prediction' not in fit:continue
        ratio=coordinate['hb_factor']/coord['hb_factor']
        raw.append(target[:,1:]*ratio)
        residual=np.zeros_like(target);residual[:,1:]=(target[:,1:]-fit['physical_prediction'][:,1:])*ratio
        residuals.append(residual)
    available=bool(donors and len(raw)==len(donors) and all(r['converged'] for r in records))
    result=dict(available=available,donors=records,components={})
    if not available:return result
    result['raw_Hb']=np.mean(raw,axis=0)
    residual=np.mean(residuals,axis=0)
    for arm in ATTRIBUTION_ARMS[1:]:
        basis=attribution_basis(cfg,arm,calibration)
        coefficients=project_component(residual,basis,coordinate['sd'],
            np.array(calibration['direction_scales'][arm])*calibration['coefficient_multiplier'])
        result['components'][arm]=(basis@coefficients).reshape(120,3)
    return result


def attribution_calibration_worker(payload):
    from src.inference.shared_driver_attribution import project_component, equal_capacity_hb_basis, fit_standardized_ridge
    cfg,base,root,project_root,refs,key=payload;out=Path(root);path=out/'calibration'/(key+'.json')
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();parent=Path(project_root)/cfg['source_run'];previous=Path(project_root)/cfg['robustness_run']
    coord=json.loads((out/'coordinates'/(key+'.json')).read_text());sd=np.array(coord['sd'])
    old=json.loads((previous/'calibration'/(key+'.json')).read_text())
    lookup={r['id']:r for r in refs};training=[lookup[x] for x in old['training_ids']]
    selection=[lookup[x] for x in old['selection_ids']]
    if {r['subject'] for r in training}&{r['subject'] for r in selection}:
        raise ValueError('inner subject leakage')
    ys=[];full=[];hidden=[];fit_records=[]
    for ref in training:
        y=semantics_target(ref,coord)
        f=attribution_fit(cfg,base,y,sd,{},'M0')
        h=attribution_fit(cfg,base,y,sd,{},'M0',semantics_missing_mask('Hb_hidden'))
        ys.append(y);full.append(f);hidden.append(h)
        fit_records.append(dict(id=ref['id'],full_converged=f['converged'],hidden_converged=h['converged']))
    successful=[i for i,f in enumerate(full) if f['converged']]
    if len(successful)<3:raise ValueError('insufficient calibration fits')
    def scale_for(basis):
        coeff=[project_component(ys[i]-full[i]['physical_prediction'],basis,sd) for i in successful]
        return np.maximum(np.sqrt(np.mean(np.asarray(coeff)**2,axis=0)),sd.mean()*1e-6)
    cal=dict(key=key,driver_sd=old['driver_sd'],prior_weight=old['prior_weight'],
        coefficient_multiplier=old['coefficient_multiplier'],selected_rho=.35,
        direction_scales={'D-fixed':old['coefficient_sd']},training_ids=old['training_ids'],
        selection_ids=old['selection_ids'],training_subjects=old['training_subjects'],
        selection_subjects=old['selection_subjects'],training_records=fit_records,
        coordinate_id=key,selection_coordinate='frozen_parent_outer_training_PCA_scale',
        selection_claim='conditional_on_parent_coordinate_not_refitted_inner_nested_validation')
    candidate_scales={};scores=[]
    for rho in cfg['direction']['rho_candidates']:
        basis=equal_capacity_hb_basis(semantics_model_operator(),rho=rho)
        candidate_scales[str(rho)]=scale_for(basis)
        candidate=deepcopy(cal);candidate['selected_rho']=rho
        candidate['direction_scales']['D-trained']=candidate_scales[str(rho)]
        for ref in selection:
            y=semantics_target(ref,coord)
            for mode in cfg['direction']['selection_modes']:
                mask=semantics_missing_mask(mode)
                fit=attribution_fit(cfg,base,y,sd,candidate,'D-trained',mask)
                scores.append(dict(id=ref['id'],rho=rho,mode=mode,
                    **robustness_metrics(fit,y,sd,mask)))
    rho,ranking=robustness_select([(rho,[r for r in scores if r['rho']==rho])
        for rho in cfg['direction']['rho_candidates']],'total_nrmse')
    cal.update(selected_rho=rho,direction_selection_scores=ranking,candidate_coefficient_scales=candidate_scales)
    cal['direction_scales']['D-trained']=candidate_scales[str(rho)]
    cal['direction_scales']['D-exchange']=scale_for(attribution_basis(cfg,'D-exchange',cal))
    train_components=[];spatial=[];components_full={a:[] for a in ATTRIBUTION_ARMS[1:]}
    for i,ref in enumerate(training):
        item=attribution_spatial_inputs(cfg,base,parent,refs,ref,coord,cal);spatial.append(item)
        if full[i]['converged']:
            for arm in ATTRIBUTION_ARMS[1:]:
                basis=attribution_basis(cfg,arm,cal)
                c=project_component(ys[i]-full[i]['physical_prediction'],basis,sd,
                    np.array(cal['direction_scales'][arm])*cal['coefficient_multiplier'])
                components_full[arm].append((basis@c).reshape(120,3))
    cal['spatial_loading']={};cal['ar_coefficient']={}
    usable=[i for i in range(len(training)) if spatial[i]['available'] and hidden[i]['converged']]
    if len(usable)<3:raise ValueError('insufficient independent spatial training support')
    for arm in ATTRIBUTION_ARMS[1:]:
        x=np.concatenate([spatial[i]['components'][arm][:,1:]/sd[1:] for i in usable])
        y=np.concatenate([(ys[i]-hidden[i]['physical_prediction'])[:,1:]/sd[1:] for i in usable])
        cal['spatial_loading'][arm]=float(np.clip(np.sum(x*y)/(np.sum(x*x)+1e-12),
            *cfg['measured']['spatial']['loading_bounds']))
        c=np.array(components_full[arm])[:,:,1:]
        cal['ar_coefficient'][arm]=float(np.clip(np.sum(c[:,1:]*c[:,:-1])/(np.sum(c[:,:-1]**2)+1e-12),
            *cfg['measured']['temporal']['ar_coefficient_bounds']))
    x=np.concatenate([spatial[i]['raw_Hb'] for i in usable]);y=np.concatenate([ys[i][:,1:] for i in usable])
    cal['spatial_ridge']=fit_standardized_ridge(x,y,cfg['measured']['spatial']['ridge_weight'])
    cal['spatial_training_ids']=[training[i]['id'] for i in usable]
    cal['spatial_training_records']=[dict(id=r['id'],available=s['available'],donors=s['donors']) for r,s in zip(training,spatial)]
    cal['training_template']=np.mean(ys,axis=0)
    cal.update(status='completed',seconds=time.monotonic()-start)
    write_json(path,cal);write_json(out/'calibration_scores'/(key+'.json'),scores)
    path.parent.mkdir(parents=True,exist_ok=True)
    np.savez_compressed(path.with_suffix('.npz'),targets=np.array(ys),
        **{a:np.array(v) for a,v in components_full.items()})
    return cal


def attribution_measured_worker(payload):
    from src.inference.shared_driver_attribution import predict_standardized_ridge
    cfg,base,root,project_root,refs,ref=payload;out=Path(root);path=out/'measured'/ref['id']/'result.json'
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();parent=Path(project_root)/cfg['source_run']
    key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
    coord=json.loads((out/'coordinates'/(key+'.json')).read_text());sd=np.array(coord['sd'])
    cal=json.loads((out/'calibration'/(key+'.json')).read_text());y=semantics_target(ref,coord)
    rows=[];saved=dict(target=y,sd=sd);fits={}
    for mode in cfg['measured']['modes']:
        mask=np.ones((120,3),bool) if mode=='full' else semantics_missing_mask(mode)
        for arm in ATTRIBUTION_ARMS:
            fit=attribution_fit(cfg,base,y,sd,cal,arm,mask);fits[mode,arm]=fit
            row=robustness_metrics(fit,y,sd,mask)
            rows.append(dict(mode=mode,arm=arm,pairing='real',**row))
            if 'driver' in fit:
                for name in ('driver','prediction','physical_prediction','observation_component'):
                    saved[f'{mode}__{arm}__{name}']=fit[name]
    donor=attribution_spatial_inputs(cfg,base,parent,refs,ref,coord,cal)
    candidates=[r for r in refs if r['id'] in set(cal['training_ids'])
        and r['task']==ref['task'] and r['condition']==ref['condition'] and r['subject']!=ref['subject']]
    wrong_ref=min(candidates,key=lambda r:r['id']) if candidates else None
    wrong=attribution_spatial_inputs(cfg,base,parent,refs,wrong_ref,coord,cal) if wrong_ref else None
    physical=fits['Hb_hidden','M0']
    mask=semantics_missing_mask('Hb_hidden')
    if donor['available'] and 'prediction' in physical:
        for pairing,item in [('real',donor),('wrong_subject',wrong),('real_shift_support',donor),('nonwrapping_shift_12s',donor)]:
            if not item or not item['available']:continue
            endpoint=mask.copy()
            if 'shift' in pairing:endpoint[-48:,1:]=True
            for arm in ATTRIBUTION_ARMS[1:]:
                component=item['components'][arm].copy()*cal['spatial_loading'][arm]
                if pairing=='nonwrapping_shift_12s':component[:-48]=component[48:]
                pred=physical['prediction']+component
                fit=dict(physical,prediction=pred,observation_component=component)
                rows.append(dict(mode='hidden_channel',arm=arm,pairing=pairing,**robustness_metrics(fit,y,sd,endpoint)))
                if pairing=='real':saved[f'hidden_channel__{arm}__prediction']=pred
            raw=item['raw_Hb'].copy()
            if pairing=='nonwrapping_shift_12s':raw[:-48]=raw[48:]
            for arm,pred_h in [('spatial_ridge',predict_standardized_ridge(cal['spatial_ridge'],raw)),
                               ('training_template',np.array(cal['training_template'])[:,1:]),
                               ('M0',physical['prediction'][:,1:])]:
                pred=physical['prediction'].copy();pred[:,1:]=pred_h
                fit=dict(physical,prediction=pred,observation_component=pred-physical['prediction'])
                rows.append(dict(mode='hidden_channel',arm=arm,pairing=pairing,**robustness_metrics(fit,y,sd,endpoint)))
                if pairing=='real':saved[f'hidden_channel__{arm}__prediction']=pred
    else:
        for arm in list(ATTRIBUTION_ARMS)+['spatial_ridge','training_template']:
            rows.append(dict(mode='hidden_channel',arm=arm,pairing='real',converged=False,status='donor_or_physical_unavailable'))
    # This holds out processed Hb features; upstream offline filters prevent a causal claim.
    prefix=cfg['measured']['temporal']['prefix_steps'];mask=np.ones((120,3),bool);mask[prefix:,1:]=False
    for arm in ATTRIBUTION_ARMS[1:]:
        fit=attribution_fit(cfg,base,y,sd,cal,arm,mask)
        if 'prediction' not in fit:
            rows.append(dict(mode='suffix_Hb',arm=arm,pairing='cosine_extrapolation',converged=False,status=fit['status']));continue
        component=fit['observation_component']
        for method in ['cosine_extrapolation','AR1','zero','persistence']:
            c=component.copy()
            if method=='zero':c[prefix:]=0.
            if method=='persistence':c[prefix:]=c[prefix-1]
            if method=='AR1':c[prefix:]=c[prefix-1]*cal['ar_coefficient'][arm]**np.arange(1,121-prefix)[:,None]
            alternative=dict(fit,observation_component=c,prediction=fit['physical_prediction']+c)
            rows.append(dict(mode='suffix_Hb',arm=arm,pairing=method,**robustness_metrics(alternative,y,sd,mask)))
    result=dict(status='completed',ref=ref,coordinate_id=key,selected_rho=cal['selected_rho'],rows=rows,
        spatial_donors=donor['donors'],spatial_available=donor['available'],
        wrong_donor_id=wrong_ref['id'] if wrong_ref else None,wrong_donor_available=bool(wrong and wrong['available']),
        seconds=time.monotonic()-start,peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024)
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    write_json(path,result);return result


def attribution_audit_worker(payload):
    from src.inference.shared_driver_attribution import hb_diagnostic_coordinates, component_change_metrics
    cfg,base,root,project_root,ref=payload;out=Path(root);path=out/'audit'/ref['id']/'result.json'
    if path.exists():return json.loads(path.read_text())
    previous=Path(project_root)/cfg['robustness_run'];record=json.loads((previous/'measured'/ref['id']/'result.json').read_text())
    arrays=np.load(previous/'measured'/ref['id']/'result.npz',allow_pickle=False)
    key=record['coordinate_id'];y=arrays['target'];sd=arrays['sd']
    cal=json.loads((previous/'calibration'/(key+'.json')).read_text());old=robustness_config(CODE_ROOT/cfg['robustness_config'])
    metrics={(r['mode'],r['arm']):r for r in record['rows'] if r['pairing']=='real'}
    row={k:ref[k] for k in ('id','dataset','subject','record','site','native_rho','quality_burden')}
    row['converged']=all(metrics['full',a]['converged'] for a in ('M0','M-observation'))
    row['full_gain']=metrics['full','M0'].get('total_nrmse',np.nan)-metrics['full','M-observation'].get('total_nrmse',np.nan)
    for mode in ('HbO_hidden','HbR_hidden'):
        row[mode+'_harm']=metrics[mode,'M-observation'].get('total_nrmse',np.nan)-metrics[mode,'M0'].get('total_nrmse',np.nan)
        row[mode+'_pair_converged']=all(metrics[mode,a]['converged'] for a in ('M0','M-observation'))
    row['single_Hb_harm']=np.mean([row[m+'_harm'] for m in ('HbO_hidden','HbR_hidden')])
    row['processed_rho']=float(np.corrcoef(y[:,1],y[:,2])[0,1])
    diagnostic=hb_diagnostic_coordinates(y[:,1:]);energy=np.mean(diagnostic**2,axis=0)
    row['HbT_energy_fraction']=float(energy[0]/max(energy.sum(),1e-16))
    component=arrays['full__M-observation__observation_component']
    row['component_strength']=float(np.sqrt(np.mean((component[:,1:]/sd[1:])**2)))
    training=np.load(out/'calibration'/(key+'.npz'),allow_pickle=False)['targets']
    diagnostic_scale=hb_diagnostic_coordinates(training[:,:,1:]).std(axis=(0,1))
    for j,name in enumerate(('HbT','HbX')):
        for arm in ('M0','M-observation'):
            error=hb_diagnostic_coordinates(arrays[f'full__{arm}__prediction'][:,1:]-y[:,1:])
            row[name+'_'+arm+'_nrmse']=float(np.sqrt(np.mean(error[:,j]**2))/max(diagnostic_scale[j],1e-12))
        row[name+'_gain']=row[name+'_M0_nrmse']-row[name+'_M-observation_nrmse']
    sensitivities=[];saved={}
    for arm in cfg['audit']['sensitivity_arms']:
        reference={name:arrays[f'full__{arm}__{name}'] for name in ('driver','prediction','physical_prediction','observation_component')}
        reference['converged']=metrics['full',arm]['converged']
        for variant in old['measured']['sensitivity']:
            data=y.copy();mask=np.ones_like(y,bool);options={};c=deepcopy(cal)
            if variant.startswith('EEG_gain'):data[:,0]/=.9 if variant.endswith('low') else 1.1
            if variant.startswith('Hb_gain'):data[:,1:]/=.9 if variant.endswith('low') else 1.1
            if variant=='lag_minus_one_sample':data[1:,1:]=y[:-1,1:];mask[0,1:]=False
            if variant=='lag_plus_one_sample':data[:-1,1:]=y[1:,1:];mask[-1,1:]=False
            if variant.startswith('prior_'):options['prior_weight']=cal['prior_weight']*(.5 if variant=='prior_half' else 2.)
            if variant.startswith('rho_'):options['rho']=.25 if variant=='rho_low' else .45
            if variant.startswith('training_bootstrap'):c.update(cal['bootstrap_scales'][int(variant[-1])])
            fit=robustness_fit(old,base,data,sd,c,arm,mask,**options)
            sensitivities.append(dict(arm=arm,variant=variant,converged=bool(fit['converged'] and reference['converged']),
                loading_rho=options.get('rho',.35),**component_change_metrics(reference,fit,sd,cal['driver_sd'])))
            if 'driver' in fit:
                for name in ('driver','physical_prediction','observation_component'):
                    saved[f'{arm}__{variant}__{name}']=fit[name]
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',ref=ref,audit=row,sensitivity=sensitivities,
        diagnostic_scale=diagnostic_scale,diagnostic_scale_source='same_parent_calibration_training_windows',
        quality_scope='native_rho_and_quality_are_record_channel_statistics_not_window_truth')
    write_json(path,result);return result


def attribution_profile_worker(payload):
    from src.inference.shared_driver_attribution import subspace_overlap, component_change_metrics
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    cfg,base,root,ref=payload;out=Path(root);path=out/'profiles'/ref['id']/'result.json'
    if path.exists():return json.loads(path.read_text())
    key=f'{ref["dataset"]}__{ref["site"]}__outer{ref["subject_fold"]}'
    coord=json.loads((out/'coordinates'/(key+'.json')).read_text());sd=np.array(coord['sd'])
    cal=json.loads((out/'calibration'/(key+'.json')).read_text());y=semantics_target(ref,coord)
    rows=[];overlaps=[];saved={};op=semantics_model_operator()
    for arm in ATTRIBUTION_ARMS[1:]:
        fit=attribution_fit(cfg,base,y,sd,cal,arm,jacobian=True)
        if 'canonical_jacobian' not in fit:
            overlaps.append(dict(arm=arm,converged=False,status=fit['status']));continue
        basis=attribution_basis(cfg,arm,cal);j=op@fit['canonical_jacobian']
        overlap=subspace_overlap(j,basis,sd)
        # Physiological tangents are reported separately from the fixed-H0 free coordinates.
        derivatives=[]
        for parameter,value in [('tau',base['fixed']['tau']),('kappa',base['fixed']['kappa']),('neurovascular_gain',base['fixed']['neurovascular_gain'])]:
            predictions=[]
            for sign in (-1,1):
                p=semantics_parameters(base,**{parameter:value*np.exp(sign*1e-4)})
                f=nonlinear_driver_forward(fit['driver'],fit['initial_state'],p,.25,substeps=4,derivative=False,numerical_backend='numba', hemodynamics='inlet_balance', viscoelastic_s=0.)
                predictions.append(op@f['canonical_prediction'].ravel())
            derivatives.append((predictions[1]-predictions[0])/2e-4)
        expanded=subspace_overlap(np.column_stack([j]+derivatives),basis,sd)
        overlaps.append(dict(arm=arm,converged=fit['converged'],fixed_H0=overlap,with_parameter_tangents=expanded))
        cs=np.asarray(cal['direction_scales'][arm])*cal['coefficient_multiplier']
        direction=np.array(overlap['coefficient_direction'])*np.sqrt(240)
        for offset in cfg['audit']['overlap_offsets_SD']:
            coefficients=fit['observation_coefficients']+offset*direction
            component=(basis@coefficients).reshape(120,3)
            alternative=attribution_fit(cfg,base,y,sd,cal,arm,fixed_component=component)
            objective=alternative.get('objective',np.nan)+float(np.sum((coefficients/cs)**2))
            fraction=(objective-fit['objective'])/max(fit['objective'],1e-12)
            rows.append(dict(arm=arm,offset_SD=offset,converged=bool(fit['converged'] and alternative['converged']),
                objective=objective,reference_objective=fit['objective'],objective_fraction=fraction,
                near_equivalent=bool(fit['converged'] and alternative['converged'] and fraction<=cfg['audit']['near_equivalent_objective_fraction']),
                **component_change_metrics(fit,alternative,sd,cal['driver_sd'])))
            if 'driver' in alternative:
                for name in ('driver','prediction','physical_prediction','observation_component'):
                    saved[f'{arm}__{offset}__{name}']=alternative[name]
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',ref=ref,rows=rows,overlaps=overlaps,
        interpretation='fixed_component_displacement_then_physical_refit_proper_component_cost_retained_not_confidence_interval')
    write_json(path,result);return result


def attribution_anchor_prepare_worker(payload):
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.unified_physiology import load_native_eeg_record
    cfg,base,root,project_root,refs=payload;out=Path(root);key=refs[0]['key'];path=out/'auxiliary'/key/'record.json'
    if path.exists():return json.loads(path.read_text())
    if any(r['dataset']!='simultaneous_eeg_nirs' or r['key']!=key for r in refs):
        raise ValueError('auxiliary scope is one registered public Simultaneous record')
    index=CleanPhysiologyCacheIndex(Path(project_root)/base['data']['cache_root'])
    join=f"simultaneous_eeg_nirs|{refs[0]['subject']}|{refs[0]['record']}"
    record=next(r for r in index.records if r.join_key==join)
    native=load_native_eeg_record(Path(project_root),record)
    if native.auxiliary_values is None or not native.auxiliary_channel_names:
        raise ValueError('registered EOG unavailable')
    width=round(native.sample_rate_hz*.25)
    if abs(width-native.sample_rate_hz*.25)>1e-8:raise ValueError('nonintegral EOG bins')
    path.parent.mkdir(parents=True,exist_ok=True);rows=[]
    for ref in refs:
        start=round(ref['eeg_start_s']*native.sample_rate_hz)
        values=native.auxiliary_values[start:start+120*width]
        if values.shape!=(120*width,len(native.auxiliary_channel_names)) or not np.isfinite(values).all():
            rows.append(dict(id=ref['id'],status='missing_EOG_support'));continue
        envelope=np.log(np.maximum(np.mean(values.reshape(120,width,-1)**2,axis=1),1e-12))
        envelope=native_feature_operators(120)['eeg']@envelope
        features=[]
        for lag in cfg['anchors']['lags_s']:
            shift=round(lag/.25);v=envelope.copy()
            if shift:v[shift:]=envelope[:-shift];v[:shift]=np.nan
            features.append(v)
        np.savez_compressed(path.parent/(ref['id']+'.npz'),features=np.concatenate(features,axis=1))
        rows.append(dict(id=ref['id'],status='completed',start_sample=start,eeg_start_s=ref['eeg_start_s']))
    result=dict(status='completed',key=key,join_key=join,rows=rows,auxiliary_names=native.auxiliary_channel_names,
        source_path=str(native.source_path),native_unit=native.native_unit,sample_rate=native.sample_rate_hz,
        target='EOG association only; neither short-separation Hb nor an autonomic source measurement')
    write_json(path,result);return result


def attribution_anchor_worker(payload):
    from src.inference.shared_driver_attribution import fit_standardized_ridge, predict_standardized_ridge
    cfg,base,root,refs,panel,key=payload;out=Path(root);path=out/'anchors'/(key+'.json')
    if path.exists():return json.loads(path.read_text())
    coord=json.loads((out/'coordinates'/(key+'.json')).read_text());cal=json.loads((out/'calibration'/(key+'.json')).read_text())
    lookup={r['id']:r for r in refs};training=[lookup[x] for x in cal['training_ids']]
    valid_start=round(max(cfg['anchors']['lags_s'])/.25);support=np.arange(120)>=valid_start
    def features(ref):
        return np.load(out/'auxiliary'/ref['key']/(ref['id']+'.npz'),allow_pickle=False)['features']
    xs=[];cs=[];fit_rows=[];available=[]
    for ref in training:
        y=semantics_target(ref,coord);fit=attribution_fit(cfg,base,y,coord['sd'],cal,'D-fixed')
        fit_rows.append(dict(id=ref['id'],converged=fit['converged']))
        if not fit['converged']:continue
        x=features(ref);c=fit['observation_component'][:,1:].sum(axis=1,keepdims=True)
        xs.append(x[support]);cs.append(c[support]);available.append(ref)
    if len(xs)<3:raise ValueError('insufficient EOG training targets')
    scale=max(float(np.std(np.concatenate(cs))),1e-10)
    model=fit_standardized_ridge(np.concatenate(xs),np.concatenate(cs),cfg['anchors']['ridge_weight'])
    rows=[];saved={}
    selected=[r for r in panel if f'{r["dataset"]}__{r["site"]}__outer{r["subject_fold"]}'==key]
    for ref in selected:
        arrays=np.load(out/'measured'/ref['id']/'result.npz',allow_pickle=False)
        result=json.loads((out/'measured'/ref['id']/'result.json').read_text())
        successful=all(next(row for row in result['rows'] if row['mode']==mode and row['arm']==arm and row['pairing']=='real')['converged']
            for mode,arm in [('full','D-fixed'),('Hb_hidden','M0')])
        c=arrays['full__D-fixed__observation_component'][:,1:].sum(axis=1)
        y=arrays['target'];physical=arrays['Hb_hidden__M0__prediction'];sd=arrays['sd']
        wrongs=[r for r in available if r['task']==ref['task'] and r['condition']==ref['condition'] and r['subject']!=ref['subject']]
        wrong=min(wrongs,key=lambda r:r['id']) if wrongs else None
        for pairing,feature_ref in [('real',ref),('wrong_subject',wrong),('zero',ref),('training_mean',ref)]:
            if feature_ref is None:continue
            predicted=predict_standardized_ridge(model,features(feature_ref)[support]).ravel()
            if pairing=='zero':predicted[:]=0.
            if pairing=='training_mean':predicted[:]=np.asarray(model['target_mean']).item()
            completion=physical[support,1:]+predicted[:,None]*[.65,.35]
            rows.append(dict(id=ref['id'],subject=ref['subject'],dataset=ref['dataset'],key=key,
                pairing=pairing,converged=successful,donor_id=feature_ref['id'],
                component_nrmse=float(np.sqrt(np.mean((predicted-c[support])**2)))/scale,
                component_correlation=float(np.corrcoef(predicted,c[support])[0,1]) if np.std(predicted)>1e-12 and np.std(c[support])>1e-12 else None,
                hidden_Hb_nrmse=float(np.sqrt(np.mean(((completion-y[support,1:])/sd[1:])**2)))))
            saved[f'{ref["id"]}__{pairing}']=predicted
    path.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(path.with_suffix('.npz'),**saved)
    result=dict(status='completed',key=key,model=model,training_target_scale=scale,
        training_fit_records=fit_rows,training_ids=[r['id'] for r in available],rows=rows,
        source_status='unresolved_EOG_predictability_is_association_not_causal_origin')
    write_json(path,result);return result


def attribution_prototype_data_worker(payload):
    cfg,base,split,index=payload
    stream={'train':10000,'validation':20000,'test':30000}[split]
    scenarios=cfg['prototype']['test_interventions' if split=='test' else 'train_interventions']
    ys=[];targets=[];labels=[]
    # Project true structured total Hb into the same processed cosine coordinate.
    time=np.cos(np.pi*(np.arange(120)[:,None]+.5)*np.arange(1,5)/120)
    basis=semantics_model_operator()[1::3,1::3]@time
    for scenario in scenarios:
        case=attribution_synthetic_case(cfg,base,stream+index,
            'slow' if index%2==0 else 'mixed','rest' if index%4<2 else 'nonrest',scenario,calibration=True)
        r=case['driver']-np.mean(case['driver'][:20])
        neural=r.reshape(cfg['prototype']['driver_patches'],-1).mean(axis=1)
        hbtotal=case['observation_truth'][:,1:].sum(axis=1)
        morphology=np.linalg.lstsq(basis,hbtotal,rcond=1e-10)[0]
        ys.append(case['target']);targets.append(np.r_[neural,morphology]);labels.append(scenario)
    return dict(values=np.array(ys),targets=np.array(targets),scenarios=labels,index=index,split=split)


def attribution_prototype_prepare(cfg, base, out, workers):
    collected={split:[] for split in ('train','validation','test')}
    payloads=[(cfg,base,split,i) for split in collected for i in range(cfg['prototype'][split+'_seeds'])]
    for _,result,error in bounded_nonlinear_work(attribution_prototype_data_worker,payloads,workers,2*workers):
        if error:raise RuntimeError(error)
        collected[result['split']].append(result)
    arrays={}
    for split,records in collected.items():
        records.sort(key=lambda r:r['index'])
        arrays[split+'_values']=np.concatenate([r['values'] for r in records])
        arrays[split+'_targets']=np.concatenate([r['targets'] for r in records])
        arrays[split+'_scenarios']=np.array([s for r in records for s in r['scenarios']])
        arrays[split+'_identities']=np.array([r['index'] for r in records for _ in r['scenarios']])
    arrays['input_mean']=arrays['train_values'].mean(axis=(0,1))
    arrays['input_scale']=np.maximum(arrays['train_values'].std(axis=(0,1)),1e-8)
    arrays['target_mean']=arrays['train_targets'].mean(axis=0)
    arrays['target_scale']=np.maximum(arrays['train_targets'].std(axis=0),1e-8)
    np.savez_compressed(out/'prototype_data.npz',**arrays)
    write_json(out/'prototype_data.json',dict(schema='typed_component_synthetic_data_v1',
        split_seed_offsets={'train':10000,'validation':20000,'test':30000},
        shapes={k:v.shape for k,v in arrays.items()},normalization='training_only',
        truth='known_generator_driver_and_structured_HbT_projection_not_measured_teacher',
        input_ownership='EEG_only_driver_encoder_Hb_only_morphology_encoder'))


def attribution_prototype_worker(payload):
    import torch
    from src.tokenizers.typed_component_prototype import TypedComponentPrototype
    from src.inference.shared_driver_attribution import fit_standardized_ridge, predict_standardized_ridge
    cfg,root,seed,arm=payload;out=Path(root);path=out/'prototype'/f'{arm}_s{seed}'/'result.json'
    if path.exists():return json.loads(path.read_text())
    start=time.monotonic();torch.set_num_threads(1);torch.manual_seed(seed);np.random.seed(seed)
    data=np.load(out/'prototype_data.npz',allow_pickle=False);p=cfg['prototype']
    x={s:torch.tensor((data[s+'_values']-data['input_mean'])/data['input_scale'],dtype=torch.float32)
        for s in ('train','validation','test')}
    y={s:torch.tensor((data[s+'_targets']-data['target_mean'])/data['target_scale'],dtype=torch.float32)
        for s in ('train','validation','test')}
    typed=arm=='typed_supervision'
    model=TypedComponentPrototype(width=p['hidden_width'],driver_patches=p['driver_patches'],
        morphology_modes=p['morphology_modes'],observation_dimensions=p['observation_dimensions'],detach_semantic=typed)
    optimizer=torch.optim.Adam(model.parameters(),lr=p['learning_rate'])
    history=[];best=None;best_score=float('inf');best_epoch=None
    for epoch in range(p['epochs']):
        model.train();total=0.
        permutation=torch.randperm(len(x['train']))
        for indices in permutation.split(p['batch_size']):
            output=model(x['train'][indices]);loss=torch.mean((output['reconstruction']-x['train'][indices])**2)
            if typed:loss=loss+torch.mean((output['semantic']-y['train'][indices])**2)
            optimizer.zero_grad();loss.backward();optimizer.step();total+=float(loss.detach())*len(indices)
        model.eval()
        with torch.no_grad():
            output=model(x['validation']);validation=torch.mean((output['reconstruction']-x['validation'])**2)
            if typed:validation=validation+torch.mean((output['semantic']-y['validation'])**2)
            score=float(validation)
        history.append(dict(epoch=epoch+1,train_loss=total/len(x['train']),validation_loss=score))
        if score<best_score:
            best_score=score;best_epoch=epoch+1;best={k:v.detach().clone() for k,v in model.state_dict().items()}
    model.load_state_dict(best);model.eval()
    with torch.no_grad():
        train={k:v.numpy() for k,v in model(x['train']).items()}
        test={k:v.numpy() for k,v in model(x['test']).items()}
    neural=p['driver_patches'];probes={}
    prediction=test['semantic'].copy()
    if not typed:
        for name,part in [('neural',slice(0,neural)),('morphology',slice(neural,None))]:
            probe=fit_standardized_ridge(train['semantic'][:,part],y['train'].numpy()[:,part],.01)
            prediction[:,part]=predict_standardized_ridge(probe,test['semantic'][:,part]);probes[name]=probe
    rows=[];contrasts=[];truth=y['test'].numpy();identity=data['test_identities'];scenarios=data['test_scenarios']
    obs_scale=np.maximum(np.std(train['observation'],axis=0),1e-8)
    for index in sorted(set(identity)):
        controls=np.flatnonzero((identity==index)&(scenarios=='control'))
        control=int(controls[0])
        for i in np.flatnonzero(identity==index):
            row=dict(seed=seed,arm=arm,identity=int(index),scenario=str(scenarios[i]),
                neural_nrmse=float(np.sqrt(np.mean((prediction[i,:neural]-truth[i,:neural])**2))),
                morphology_nrmse=float(np.sqrt(np.mean((prediction[i,neural:]-truth[i,neural:])**2))),
                reconstruction_nrmse=float(np.sqrt(np.mean((test['reconstruction'][i]-x['test'][i].numpy())**2))))
            rows.append(row)
            contrasts.append(dict(seed=seed,arm=arm,identity=int(index),scenario=str(scenarios[i]),
                neural_change_SD=float(np.sqrt(np.mean((prediction[i,:neural]-prediction[control,:neural])**2))),
                morphology_change_SD=float(np.sqrt(np.mean((prediction[i,neural:]-prediction[control,neural:])**2))),
                neural_change_error_SD=float(np.sqrt(np.mean(((prediction[i]-prediction[control])-(truth[i]-truth[control]))[:neural]**2))),
                morphology_change_error_SD=float(np.sqrt(np.mean(((prediction[i]-prediction[control])-(truth[i]-truth[control]))[neural:]**2))),
                observation_change_SD=float(np.sqrt(np.mean(((test['observation'][i]-test['observation'][control])/obs_scale)**2))),
                neural_truth_change_SD=float(np.sqrt(np.mean((truth[i,:neural]-truth[control,:neural])**2))),
                morphology_truth_change_SD=float(np.sqrt(np.mean((truth[i,neural:]-truth[control,neural:])**2)))))
    path.parent.mkdir(parents=True,exist_ok=True)
    torch.save(dict(state_dict=best,config=p,input_mean=data['input_mean'],input_scale=data['input_scale'],
        target_mean=data['target_mean'],target_scale=data['target_scale']),path.parent/'model.pt')
    np.savez_compressed(path.with_suffix('.npz'),prediction=prediction,truth=truth,**test)
    result=dict(status='completed',seed=seed,arm=arm,selected_epoch=best_epoch,validation_loss=best_score,
        history=history,rows=rows,contrasts=contrasts,probes=probes,token_metadata=model.token_metadata(),
        parameter_count=sum(v.numel() for v in model.parameters()),seconds=time.monotonic()-start,
        interpretation='synthetic_continuous_prototype_only_no_measured_semantic_qualification')
    write_json(path,result);return result


def attribution_pilot_worker(payload):
    cfg,base,index=payload;start=time.monotonic();cpu=time.process_time()
    case=attribution_synthetic_case(cfg,base,index,'mixed','nonrest','common_rho070',calibration=True)
    cal=dict(driver_sd=.025,prior_weight=.1,coefficient_multiplier=1.,selected_rho=.35,
        direction_scales={a:[.02,.015,.01,.005] for a in ATTRIBUTION_ARMS[1:]})
    sd=np.maximum(case['target'].std(axis=0),1e-5);rows=[]
    for mode in ('full','HbR_hidden'):
        mask=np.ones((120,3),bool) if mode=='full' else semantics_missing_mask(mode)
        for arm in ATTRIBUTION_ARMS:
            clock=time.monotonic();fit=attribution_fit(cfg,base,case['target'],sd,cal,arm,mask)
            rows.append(dict(mode=mode,arm=arm,seconds=time.monotonic()-clock,
                **robustness_metrics(fit,case['target'],sd,mask)))
    return dict(index=index,rows=rows,wall_s=time.monotonic()-start,cpu_s=time.process_time()-cpu,
        peak_rss_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024)


def attribution_associations(frame, seed):
    from scipy.stats import spearmanr
    rows=[]
    features=['native_rho','processed_rho','HbT_energy_fraction','quality_burden','component_strength','single_Hb_harm']
    for dataset,group in frame.groupby('dataset'):
        for feature in features:
            g=group[group.converged].dropna(subset=['full_gain',feature])
            if feature=='single_Hb_harm':g=g[g.HbO_hidden_pair_converged & g.HbR_hidden_pair_converged]
            rho=float(spearmanr(g.full_gain,g[feature]).statistic) if len(g)>2 else np.nan
            rng=np.random.default_rng(seed);subjects=sorted(set(g.subject));draw=[]
            for _ in range(1000):
                if not subjects:break
                indices=np.concatenate([np.flatnonzero(g.subject.to_numpy()==s) for s in rng.choice(subjects,len(subjects))])
                a=g.full_gain.to_numpy()[indices];b=g[feature].to_numpy()[indices]
                if np.std(a)>1e-12 and np.std(b)>1e-12:draw.append(float(spearmanr(a,b).statistic))
            interval=np.quantile(draw,[.025,.975]) if draw else [np.nan,np.nan]
            rows.append(dict(dataset=dataset,feature=feature,spearman=rho,ci_low=interval[0],ci_high=interval[1],
                windows=len(g),subjects=len(subjects),interval='resample_subject_blocks_exploratory_QC_selected_panel'))
    return pd.DataFrame(rows)


def attribution_summarize(cfg, out, project_root):
    missing=[]
    def read(path):
        if not path.exists():missing.append(str(path.relative_to(out)));return None
        return json.loads(path.read_text())
    def table(records, field, identity=None):
        rows=[]
        for record in records:
            if record is None:continue
            common={k:record['ref'][k] for k in ('id','dataset','subject','record','site')} if identity=='ref' else {}
            rows.extend([dict(common,**r) for r in record[field]])
        return pd.DataFrame(rows)
    syn_specs=json.loads((out/'synthetic_plan.json').read_text())
    syn_records=[read(out/'synthetic'/s['key']/'result.json') for s in syn_specs]
    panel=json.loads((out/'measured_plan.json').read_text())['windows']
    measured_records=[read(out/'measured'/r['id']/'result.json') for r in panel]
    audit_records=[read(out/'audit'/r['id']/'result.json') for r in panel]
    profile_plan=json.loads((out/'profile_plan.json').read_text())
    profile_records=[read(out/'profiles'/r['id']/'result.json') for r in profile_plan]
    anchor_keys=json.loads((out/'anchor_plan.json').read_text())['coordinate_keys']
    anchor_records=[read(out/'anchors'/(key+'.json')) for key in anchor_keys]
    prototype_records=[read(out/'prototype'/f'{arm}_s{seed}'/'result.json')
        for arm in cfg['prototype']['arms'] for seed in cfg['prototype']['optimization_seeds']]
    syn=table(syn_records,'rows');syn.to_csv(out/'synthetic_metrics.csv',index=False)
    robustness_group_summary(syn,['scenario','mode','arm'],['driver_nrmse','centered_driver_nrmse',
        'physical_truth_nrmse','component_truth_nrmse','total_nrmse']).to_csv(out/'synthetic_summary.csv',index=False)
    pd.DataFrame(robustness_paired(syn,['scenario','mode'],value='driver_nrmse',cluster='repeat',seed=cfg['seed'],
        arms=cfg['synthetic']['arms']+['oracle'])).to_csv(out/'synthetic_paired.csv',index=False)
    contrasts=table(syn_records,'contrasts');contrasts.to_csv(out/'counterfactual_metrics.csv',index=False)
    robustness_group_summary(contrasts,['scenario','mode','arm'],['driver_change_error_SD','driver_estimated_change_SD',
        'driver_truth_change_SD','physical_prediction_change_error_SD','observation_component_change_error_SD',
        'physical_prediction_projection_fraction','observation_component_projection_fraction','residual_projection_fraction']).to_csv(out/'counterfactual_summary.csv',index=False)
    meas=table(measured_records,'rows','ref');meas.to_csv(out/'measured_metrics.csv',index=False)
    robustness_group_summary(meas,['dataset','mode','pairing','arm'],['total_nrmse','physical_nrmse',
        'component_rms_training_SD']).to_csv(out/'measured_summary.csv',index=False)
    real=meas[meas.pairing=='real'];paired=[]
    for control in ('M0','D-fixed','spatial_ridge','training_template'):
        paired.extend(robustness_paired(real,['dataset','mode'],control=control,seed=cfg['seed'],
            arms=list(ATTRIBUTION_ARMS)+['spatial_ridge','training_template']))
    pd.DataFrame(paired).to_csv(out/'measured_paired.csv',index=False)
    nulls=[]
    for control,arm in [('wrong_subject','real'),('nonwrapping_shift_12s','real_shift_support')]:
        frame=meas[meas['mode']=='hidden_channel'].rename(columns={'arm':'method','pairing':'arm'})
        nulls.extend(robustness_paired(frame,['dataset','method'],control=control,arms=[arm],seed=cfg['seed']))
    pd.DataFrame(nulls).to_csv(out/'spatial_nulls.csv',index=False)
    temporal=meas[meas['mode']=='suffix_Hb'].rename(columns={'arm':'method','pairing':'arm'})
    pd.DataFrame(robustness_paired(temporal,['dataset','method'],control='zero',
        arms=['AR1','persistence','cosine_extrapolation'],seed=cfg['seed'])).to_csv(out/'temporal_paired.csv',index=False)
    audit=pd.DataFrame([r['audit'] for r in audit_records if r]);audit.to_csv(out/'audit_metrics.csv',index=False)
    attribution_associations(audit,cfg['seed']).to_csv(out/'audit_associations.csv',index=False)
    sensitivity=table(audit_records,'sensitivity','ref');sensitivity.to_csv(out/'component_sensitivity.csv',index=False)
    robustness_group_summary(sensitivity,['dataset','arm'],['driver_change_SD','physical_change_SD',
        'component_change_SD','component_shape_cosine']).to_csv(out/'sensitivity_summary.csv',index=False)
    profiles=table(profile_records,'rows','ref');profiles.to_csv(out/'confounding_profiles.csv',index=False)
    overlap_rows=[]
    for record in profile_records:
        if not record:continue
        for row in record['overlaps']:
            for family in ('fixed_H0','with_parameter_tangents'):
                if family not in row:continue
                values=row[family]
                overlap_rows.append(dict(id=record['ref']['id'],dataset=record['ref']['dataset'],arm=row['arm'],
                    family=family,converged=row['converged'],maximum_cosine=max(values['principal_cosines']),
                    minimum_cosine=min(values['principal_cosines']),physical_rank=values['physical_rank'],
                    component_rank=values['component_rank']))
    pd.DataFrame(overlap_rows).to_csv(out/'jacobian_overlap.csv',index=False)
    anchors=table(anchor_records,'rows');anchors.to_csv(out/'anchor_metrics.csv',index=False)
    ap=[]
    for control in (('zero','training_mean','wrong_subject') if len(anchors) else ()):
        for metric in ('component_nrmse','hidden_Hb_nrmse'):
            ap.extend(robustness_paired(anchors.rename(columns={'pairing':'arm'}),['dataset'],
                control=control,value=metric,arms=['real'],seed=cfg['seed']))
    pd.DataFrame(ap).to_csv(out/'anchor_paired.csv',index=False)
    proto=table(prototype_records,'rows');proto.to_csv(out/'prototype_metrics.csv',index=False)
    pc=table(prototype_records,'contrasts');pc.to_csv(out/'prototype_contrasts.csv',index=False)
    proto.groupby(['scenario','arm','seed'])[['neural_nrmse','morphology_nrmse','reconstruction_nrmse']].mean().reset_index().to_csv(out/'prototype_summary.csv',index=False)
    pc.groupby(['scenario','arm','seed']).mean(numeric_only=True).reset_index().to_csv(out/'prototype_intervention_summary.csv',index=False)
    previous=Path(project_root)/cfg['robustness_run']
    reliability=pd.read_csv(previous/'synthetic_reliability.csv')
    summary=dict(schema='shared_driver_attribution_summary_v1',experiment_id=cfg['experiment_id'],
        execution='completed' if not missing else 'completed_with_task_failures',missing_task_records=missing,
        synthetic=dict(cases=len(syn_specs),fits=len(syn),converged=int(syn.converged.sum())),
        measured=dict(windows=len(panel),subjects=len({(r['dataset'],r['subject']) for r in panel}),
            rows=len(meas),converged=int(meas.converged.sum()),spatial_available=sum(bool(r and r['spatial_available']) for r in measured_records)),
        audit=dict(windows=len(audit),sensitivity_fits=len(sensitivity),
            previous_false_reassurance_max=float(reliability.false_reassurance_fraction.max())),
        confounding=dict(profile_fits=len(profiles),near_equivalent_rows=int(profiles.near_equivalent.sum())),
        anchors=dict(coordinates=len(anchor_keys),rows=len(anchors),source_status='unresolved' if anchor_keys else 'unavailable_no_REFED_EOG'),
        prototype=dict(models=len(prototype_records),test_rows=len(proto),scope=cfg['prototype']['scope']),
        endpoint_files=['audit_metrics.csv','audit_associations.csv','component_sensitivity.csv','measured_paired.csv',
            'spatial_nulls.csv','temporal_paired.csv','synthetic_summary.csv','counterfactual_summary.csv',
            'jacobian_overlap.csv','confounding_profiles.csv','anchor_paired.csv','prototype_summary.csv','prototype_intervention_summary.csv'],
        claim_boundary='exploratory_public_development_and_known_truth_synthetic; no_unique_source_or_measured_tokenizer_qualification',
        finished_at=datetime.now(timezone.utc).isoformat())
    write_json(out/'summary.json',summary)
    return summary


def attribution_verify(cfg, out, project_root):
    """Read-only evidence checks; this does not authorize or rerun any experiment."""
    summary=json.loads((out/'summary.json').read_text())
    if summary['execution']!='completed':raise ValueError('cannot verify incomplete task records')
    previous=Path(project_root)/cfg['robustness_run'];parent=Path(project_root)/cfg['source_run']
    refs=json.loads((parent/'cohort.json').read_text())['refs'];lookup={r['id']:r for r in refs}
    panel=json.loads((out/'measured_plan.json').read_text())['windows']
    checks=[];failures=[];maximum_decomposition=0.;maximum_parent_difference=0.;hidden_component_maximum=0.
    def check(name,passed,**details):
        record=dict(name=name,passed=bool(passed),**details);checks.append(record)
        if not passed:failures.append(record)
    specifications=json.loads((out/'synthetic_plan.json').read_text())
    expected_per_case=len(cfg['synthetic']['scenarios'])*len(cfg['synthetic']['modes'])*len(cfg['synthetic']['arms'])+len(cfg['synthetic']['physiological_oracle'])*len(cfg['synthetic']['modes'])
    synthetic_failures=[]
    for spec in specifications:
        result=json.loads((out/'synthetic'/spec['key']/'result.json').read_text())
        check('synthetic_task_denominator',len(result['rows'])==expected_per_case,key=spec['key'],rows=len(result['rows']))
        with np.load(out/'synthetic'/spec['key']/'result.npz',allow_pickle=False) as arrays:
            for row in result['rows']:
                prefix=f"{row['scenario']}__{row['mode']}__{row['arm']}__"
                if not row['converged']:synthetic_failures.append({k:row[k] for k in ('key','scenario','mode','arm','status')})
                if prefix+'prediction' in arrays:
                    delta=float(np.max(abs(arrays[prefix+'prediction']-arrays[prefix+'physical_prediction']-arrays[prefix+'observation_component'])))
                    maximum_decomposition=max(maximum_decomposition,delta)
    coverage=[];fit_failures=[]
    for ref in panel:
        record=json.loads((out/'measured'/ref['id']/'result.json').read_text())
        core=[r for r in record['rows'] if r['mode'] in cfg['measured']['modes']]
        check('measured_direction_denominator',len(core)==len(cfg['measured']['modes'])*len(ATTRIBUTION_ARMS),id=ref['id'],rows=len(core))
        for row in core:
            if not row['converged']:fit_failures.append(dict(id=ref['id'],**row))
        with np.load(out/'measured'/ref['id']/'result.npz',allow_pickle=False) as arrays, np.load(previous/'measured'/ref['id']/'result.npz',allow_pickle=False) as old:
            for mode in cfg['measured']['modes']:
                for arm in ATTRIBUTION_ARMS:
                    prefix=f'{mode}__{arm}__'
                    if prefix+'prediction' not in arrays:continue
                    delta=float(np.max(abs(arrays[prefix+'prediction']-arrays[prefix+'physical_prediction']-arrays[prefix+'observation_component'])))
                    maximum_decomposition=max(maximum_decomposition,delta)
                    if mode=='Hb_hidden':hidden_component_maximum=max(hidden_component_maximum,float(np.max(abs(arrays[prefix+'observation_component']))))
                for arm,oldarm in [('M0','M0'),('D-fixed','M-observation')]:
                    prefix=f'{mode}__{arm}__prediction';oldkey=f'{mode}__{oldarm}__prediction'
                    if prefix in arrays and oldkey in old:
                        maximum_parent_difference=max(maximum_parent_difference,float(np.max(abs(arrays[prefix]-old[oldkey]))))
        for d in record['spatial_donors']:
            donor=lookup[d['id']]
            check('spatial_target_exclusion',donor['id']!=ref['id'] and donor['hb_channel']!=ref['hb_channel']
                and donor['key']==ref['key'] and donor['window']==ref['window'],id=ref['id'],donor_id=donor['id'])
        wrong=lookup[record['wrong_donor_id']] if record['wrong_donor_id'] else None
        if wrong:
            check('spatial_null_subject_task_match',wrong['subject']!=ref['subject'] and wrong['task']==ref['task']
                and wrong['condition']==ref['condition'],id=ref['id'],donor_id=wrong['id'])
        coverage.append(dict(id=ref['id'],dataset=ref['dataset'],subject=ref['subject'],
            real_available=record['spatial_available'],wrong_available=record['wrong_donor_available']))
    check('physical_plus_component_equals_prediction',maximum_decomposition<1e-12,max_abs=maximum_decomposition)
    check('fixed_baselines_match_retained_parent',maximum_parent_difference<1e-10,max_abs=maximum_parent_difference)
    check('no_self_component_when_all_Hb_hidden',hidden_component_maximum==0.,max_abs=hidden_component_maximum)
    cal_rows=[]
    for path in sorted((out/'calibration').glob('*.json')):
        cal=json.loads(path.read_text());coord=json.loads((out/'coordinates'/(cal['key']+'.json')).read_text())
        train={lookup[x]['subject'] for x in cal['training_ids']};selection={lookup[x]['subject'] for x in cal['selection_ids']}
        evaluation={r['subject'] for r in panel if f'{r["dataset"]}__{r["site"]}__outer{r["subject_fold"]}'==cal['key']}
        check('training_selection_evaluation_disjoint',not (train&selection or train&evaluation or selection&evaluation),key=cal['key'])
        check('coordinate_excludes_evaluation',not evaluation&set(coord['training_subjects']),key=cal['key'])
        check('spatial_training_subset',set(cal['spatial_training_ids']).issubset(cal['training_ids']),key=cal['key'])
        outer=cal['key'].rsplit('__outer',1)[1]
        for target in [lookup[x] for x in cal['training_ids']]+[r for r in panel if r['subject'] in evaluation and r['dataset']==lookup[cal['training_ids'][0]]['dataset']]:
            for donor in attribution_donors(target,refs):
                key=f'{donor["dataset"]}__{donor["site"]}__outer{outer}'
                coordinate=json.loads((parent/'coordinates'/(key+'.json')).read_text())
                if evaluation&set(coordinate['training_subjects']):raise ValueError('donor coordinate outer-fold leakage')
        cal_rows.append(dict(key=cal['key'],selected_rho=cal['selected_rho'],training_windows=len(cal['training_ids']),
            selection_windows=len(cal['selection_ids']),spatial_training_windows=len(cal['spatial_training_ids'])))
    anchor_plan=json.loads((out/'anchor_plan.json').read_text());allowed={r['id'] for r in anchor_plan['refs']}
    aux=[]
    for path in sorted((out/'auxiliary').glob('*/record.json')):
        record=json.loads(path.read_text());check('auxiliary_exact_public_scope',all(r['id'] in allowed for r in record['rows'])
            and record['join_key'].startswith('simultaneous_eeg_nirs|'),key=record['key'])
        aux.append(dict(key=record['key'],source_path=record['source_path'],channels=record['auxiliary_names'],
            unit=record['native_unit'],sample_rate=record['sample_rate'],windows=len(record['rows'])))
    prototypes=[]
    for seed in cfg['prototype']['optimization_seeds']:
        for arm in cfg['prototype']['arms']:
            result=json.loads((out/'prototype'/f'{arm}_s{seed}'/'result.json').read_text())
            history=result['history'];best=min(history,key=lambda r:r['validation_loss'])
            check('prototype_validation_only_selection',result['selected_epoch']==best['epoch'] and len(history)==cfg['prototype']['epochs'],seed=seed,arm=arm)
            check('prototype_full_test_denominator',len(result['rows'])==cfg['prototype']['test_seeds']*len(cfg['prototype']['test_interventions']),seed=seed,arm=arm)
            prototypes.append(dict(seed=seed,arm=arm,selected_epoch=result['selected_epoch'],parameter_count=result['parameter_count']))
    with np.load(out/'prototype_data.npz',allow_pickle=False) as arrays:
        check('prototype_training_normalization',np.allclose(arrays['input_mean'],arrays['train_values'].mean(axis=(0,1)))
            and np.allclose(arrays['target_mean'],arrays['train_targets'].mean(axis=0)))
        check('prototype_independent_draws',not np.array_equal(arrays['train_values'][0],arrays['validation_values'][0])
            and not np.array_equal(arrays['train_values'][0],arrays['test_values'][0]))
    check('all_declared_tasks_present',not summary['missing_task_records'])
    pd.DataFrame(coverage).to_csv(out/'spatial_coverage.csv',index=False)
    result=dict(schema='shared_driver_attribution_verification_v1',status='passed' if not failures else 'failed',
        checked_at=datetime.now(timezone.utc).isoformat(),source_root=str(CODE_ROOT),checks=checks,failures=failures,
        synthetic_numerical_failures=synthetic_failures,measured_core_numerical_failures=fit_failures,
        calibrations=cal_rows,auxiliary_inventory=aux,prototype_models=prototypes,
        auxiliary_source_limits=dict(Single_Trial='original_document_mentions_ECG_and_respiration_acquisition; not_read_in_this_scope; current_EOG_auxiliary_loader_does_not_establish_their_availability',
            Simultaneous='actual_HEOG_VEOG_read; original_document_all_Hb_distances_30mm_no_short_separation',
            Visual='graphical_template_no_exact_source_detector_distances'),
        limitations=['QC_selected_small_public_development_panel','bootstrap_conditional_on_frozen_coordinate',
            'null_missing_support_reported_separately','synthetic_generator_scope_limits_mechanism_claims',
            'no_native_causal_or_cross_window_continuity_claim','prototype_not_measured_teacher_qualification'])
    write_json(out/'verification.json',result)
    if failures:raise ValueError(f'{len(failures)} attribution verification checks failed')
    return result


def attribution_main(args):
    cfg=attribution_config(args.config);base=semantics_config(CODE_ROOT/cfg['source_config'])
    if args.check_only:
        print(json.dumps(dict(status='contract_valid',experiment_id=cfg['experiment_id'],measured_arrays_read=0,
            groups=['attribution_audit','direction_spatial','counterfactuals','anchors_typed_prototype'])));return
    if args.run_dir is None:raise ValueError('--run-dir required')
    out=args.run_dir.resolve();expected=(args.project_root/cfg['artifact_root']).resolve()
    if out.parent!=expected:raise ValueError('run must be direct child of attribution root')
    if not 1<=args.workers<=cfg['resources']['max_workers']:raise ValueError('worker bound')
    out.mkdir(parents=True,exist_ok=True)
    lock=(out/'controller.lock').open('w');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    resolved=out/'resolved_config.yaml'
    if resolved.exists() and yaml.safe_load(resolved.read_text())!=cfg:raise ValueError('immutable attribution config mismatch')
    if not resolved.exists():resolved.write_text(yaml.safe_dump(cfg,sort_keys=False))
    stage=args.attribution_stage;manifest=out/(stage+'_manifest.json')
    if manifest.exists() and json.loads(manifest.read_text()).get('execution')=='completed':
        print('Already completed:',stage);return
    state=dict(experiment_id=cfg['experiment_id'],stage=stage,execution='running',controller_pid=os.getpid(),
        workers=args.workers,started_at=datetime.now(timezone.utc).isoformat(),source_root=str(CODE_ROOT))
    write_json(manifest,state)
    try:
        failures=[]
        if stage=='pilot':
            records=[];start=time.monotonic()
            for _,result,error in bounded_nonlinear_work(attribution_pilot_worker,[(cfg,base,i) for i in range(8)],min(args.workers,8),16):
                if error:raise RuntimeError(error)
                records.append(result)
            write_json(out/'pilot.json',dict(records=records,wall_s=time.monotonic()-start))
        elif stage=='synthetic_calibration':
            attribution_synthetic_calibration(cfg,base,out,args.workers,args.project_root)
        elif stage=='synthetic':
            specs=[dict(repeat=i,spectrum=s,initial=a,key=f'{s}_{a}_r{i}') for i in range(cfg['synthetic']['repeats'])
                for s in cfg['synthetic']['spectra'] for a in cfg['synthetic']['initial']]
            write_json(out/'synthetic_plan.json',specs)
            failures=semantics_parallel_stage(cfg,out,stage,attribution_synthetic_worker,
                [(cfg,base,str(out),s) for s in specs],args.workers,lambda p:p[-1]['key'])
        elif stage=='prototype_data':attribution_prototype_prepare(cfg,base,out,args.workers)
        elif stage=='prototype':
            payloads=[(cfg,str(out),seed,arm) for seed in cfg['prototype']['optimization_seeds'] for arm in cfg['prototype']['arms']]
            failures=semantics_parallel_stage(cfg,out,stage,attribution_prototype_worker,payloads,min(args.workers,len(payloads)),lambda p:f'{p[-1]}_s{p[-2]}')
        elif stage=='summarize':attribution_summarize(cfg,out,args.project_root)
        elif stage=='verify':attribution_verify(cfg,out,args.project_root)
        else:
            if json.loads((out/'synthetic_manifest.json').read_text()).get('execution')!='completed':
                raise ValueError('complete synthetic execution before measured input')
            parent,previous,refs,panel,coordinates=attribution_parent(cfg,args.project_root,out)
            if stage=='calibration':
                payloads=[(cfg,base,str(out),str(args.project_root),refs,key) for key in coordinates]
                failures=semantics_parallel_stage(cfg,out,stage,attribution_calibration_worker,payloads,args.workers,lambda p:p[-1])
            elif stage=='measured':
                payloads=[(cfg,base,str(out),str(args.project_root),refs,ref) for ref in panel]
                failures=semantics_parallel_stage(cfg,out,stage,attribution_measured_worker,payloads,args.workers,lambda p:p[-1]['id'])
            elif stage=='audit':
                payloads=[(cfg,base,str(out),str(args.project_root),ref) for ref in panel]
                failures=semantics_parallel_stage(cfg,out,stage,attribution_audit_worker,payloads,args.workers,lambda p:p[-1]['id'])
            elif stage=='profiles':
                selected=json.loads((previous/'profile_plan.json').read_text());write_json(out/'profile_plan.json',selected)
                failures=semantics_parallel_stage(cfg,out,stage,attribution_profile_worker,
                    [(cfg,base,str(out),ref) for ref in selected],args.workers,lambda p:p[-1]['id'])
            elif stage in ('auxiliary','anchors'):
                keys=[key for key in coordinates if key.startswith('simultaneous_eeg_nirs__')]
                ids={r['id'] for r in panel if r['dataset']=='simultaneous_eeg_nirs'}
                for key in keys:ids.update(json.loads((out/'calibration'/(key+'.json')).read_text())['training_ids'])
                selected=[r for r in refs if r['id'] in ids]
                write_json(out/'anchor_plan.json',dict(coordinate_keys=keys,refs=selected,
                    short_separation='not_available_all_Simultaneous_channels_documented_30mm',
                    source_status='unresolved_EOG_is_ocular_association_anchor_only'))
                if stage=='auxiliary':
                    groups={}
                    for ref in selected:groups.setdefault(ref['key'],[]).append(ref)
                    payloads=[(cfg,base,str(out),str(args.project_root),group) for group in groups.values()]
                    failures=semantics_parallel_stage(cfg,out,stage,attribution_anchor_prepare_worker,payloads,min(args.workers,8),lambda p:p[-1][0]['key'])
                else:
                    failures=semantics_parallel_stage(cfg,out,stage,attribution_anchor_worker,
                        [(cfg,base,str(out),refs,panel,key) for key in keys],args.workers,lambda p:p[-1])
            else:raise ValueError('unknown attribution stage')
        state.update(execution='completed' if not failures else 'completed_with_task_failures',task_failures=failures,
            finished_at=datetime.now(timezone.utc).isoformat())
    except Exception as exc:
        state.update(execution='failed',error=repr(exc),traceback=traceback.format_exc());raise
    finally:write_json(manifest,state)


def volume_drive_config(path):
    cfg = yaml.safe_load(Path(path).read_text())
    expected = ['experiments/runs/physiology_semantic_tokenizer/ssm_output_support/20261010_v1',
                'experiments/runs/physiology_semantic_tokenizer/ssm_output_support/20261013_refed_v2']
    if (cfg.get('schema') != 'shared_driver_volume_drive_v1'
            or cfg.get('experiment_id') != 'SSM-VOLUME-DRIVE-v1'
            or cfg['parents'] != expected or cfg['data']['protected_data'] != 'forbidden'
            or cfg['data']['raw_reads'] or cfg['data']['labels_as_inputs']
            or cfg['tensor']['lengths_s'] != [30, 90] or cfg['tensor']['dt_s'] != .25
            or cfg['tensor']['slices'] != [[120, 240], [0, 360]]
            or cfg['component']['modes'] != {30: 6, 90: 18}
            or cfg['conditions'] != ['joint_full', 'Hb_only_full', 'joint_blocked']):
        raise ValueError('volume-drive contract boundary violated')
    return cfg


def volume_drive_parameters(cfg, **changes):
    p = dict(cfg['parameters']); p.pop('policy')
    p.update(changes)
    free = BalloonFreeParameters(tau=p.pop('tau'), kappa=p.pop('kappa'))
    return BalloonParameters(fixed=BalloonFixedParameters(**p), free=free)


def volume_drive_plan(cfg, root):
    """Metadata-only admission of exact completed public parent records."""
    refs = []
    for relative in cfg['parents']:
        parent = Path(root)/relative
        summary = json.loads((parent/'summary.json').read_text())
        plan = json.loads((parent/'plan.json').read_text())
        pcfg = yaml.safe_load((parent/'resolved_config.yaml').read_text())
        coordinates = json.loads((parent/'coordinates.json').read_text())
        if (summary['schema'] != 'ssm_output_support_summary_v1' or summary['status'] != 'completed'
                or plan['schema'] != 'ssm_output_support_plan_v1'
                or pcfg['data']['protected_data'] != 'forbidden'
                or pcfg['schema'] not in ('ssm_output_support_v1', 'ssm_output_support_refed_v2')):
            raise ValueError('completed public output-support parent boundary violated')
        for record in plan['records']:
            if record['partition'] != 'evaluation':
                continue
            if (record['dataset'] not in cfg['data']['datasets'] or record['duration_s'] != 90
                    or Path(record['id']).name != record['id']
                    or record['subject'] in coordinates[record['coordinate']]['training_subjects']
                    or record['subject'] not in plan['evaluation_subjects'][record['dataset']]):
                raise ValueError('public evaluation identity or training-coordinate boundary violated')
            refs.append(dict(record, parent=relative))
    identities = [(r['dataset'], r['id']) for r in refs]
    if len(identities) != len(set(identities)):
        raise ValueError('duplicate public record identity')
    return dict(schema='shared_driver_volume_drive_plan_v1', records=refs,
        measured_arrays_read=0, sample_lengths_s=cfg['tensor']['lengths_s'],
        independent_subjects={ds: len({r['subject'] for r in refs if r['dataset'] == ds})
                              for ds in cfg['data']['datasets']},
        paired_windows='middle_30_seconds_and_whole_original_90_seconds',
        source='parent native continuous record; no concatenation of independent trials')


def volume_drive_crop(y, operators, length_s, *, dt=.25, reference_seconds=5.):
    """Re-reference the same retained samples; drop the final interpolation bin.

    Cancellation of the old constant reference is checked in the FULL operator,
    before restricting its columns. Every used row has zero dependence outside
    the cropped model support. No new interpolation of measured data occurs.
    """
    if dt not in (.1,.25):
        raise ValueError('declared 4 or 10 Hz clock required')
    whole,short,reference_steps = round(90/dt),round(30/dt),round(reference_seconds/dt)
    if length_s not in (30, 90) or np.shape(y) != (whole, 3) or not 1<=reference_steps<=short:
        raise ValueError('expected a 90s parent and 30/90s sample length')
    left, right = (short, 2*short) if length_s == 30 else (0, whole)
    n = right-left
    reference = np.eye(n); reference[:, :reference_steps] -= 1/reference_steps
    target = reference@np.asarray(y)[left:right]
    operator = np.zeros((3*n, 3*n))
    outside = np.r_[np.arange(left), np.arange(right, whole)]
    for column, name in enumerate(('eeg', 'hb', 'hb')):
        original = np.asarray(operators[name], float)
        if original.shape != (whole, whole) or not np.isfinite(original).all():
            raise ValueError('invalid parent observation operator')
        complete = reference@original[left:right]
        if outside.size and np.max(np.abs(complete[:-1, outside])) > 1e-12:
            raise ValueError('cropped visible bins depend on outside-window values')
        operator[column::3, column::3] = complete[:, left:right]
    if not np.isfinite(target).all():
        raise ValueError('nonfinite retained public target')
    return target, operator


def volume_drive_arrays(cfg, root, ref, length_s):
    # This reader consumes the parent producer's prepared schema, never raw data.
    if ref['parent'] not in cfg['parents'] or ref['partition'] != 'evaluation':
        raise ValueError('unregistered prepared-array boundary')
    parent = Path(root)/ref['parent']
    identity = next((r for r in json.loads((parent/'plan.json').read_text())['records']
                     if r['id'] == ref['id']), None)
    if identity is None or any(identity[k] != ref[k] for k in ('dataset','subject','coordinate','partition')):
        raise ValueError('parent identity mismatch before array read')
    co = json.loads((parent/'coordinates.json').read_text())[ref['coordinate']]
    if ref['subject'] in co['training_subjects']:
        raise ValueError('training/evaluation overlap')
    prepared = json.loads((parent/'tasks'/'prepare'/(ref['id']+'.json')).read_text())
    if prepared['status'] != 'completed':
        raise ValueError('parent preparation failed')
    with np.load(parent/'prepared'/(ref['id']+'.npz'), allow_pickle=False) as a:
        if a['eeg'].shape != (360,30) or a['hb'].shape != (360,2):
            raise ValueError('parent prepared shape mismatch')
        y = np.column_stack((a['eeg']@np.asarray(co['pc'])*co['eeg_factor'], a['hb']*co['hb_factor']))
        ops = dict(eeg=a['eeg_operator'], hb=a['hb_operator'])
        target, operator = volume_drive_crop(y, ops, length_s)
    sd = np.asarray(co['sd'], float)
    if sd.shape != (3,) or not np.isfinite(sd).all() or np.any(sd <= 0):
        raise ValueError('invalid frozen training scale')
    return target, operator, sd


def volume_drive_basis(cfg, operator, sd, arm):
    from src.inference.shared_driver_reconstruction import waveform_component_basis
    if arm == 'base':
        return None
    n = len(operator)//3
    basis = waveform_component_basis(volume_drive_parameters(cfg), n, .25, operator,
        arm, modes=cfg['component']['modes'][int(n*.25)])
    scale = np.sqrt(np.mean((basis.reshape(n,3,-1)[:-1,1:]/sd[None,1:,None])**2, axis=(0,1)))
    if np.any(scale <= 1e-12):
        raise ValueError('degenerate independent component')
    return basis/scale


def volume_drive_mask(n, condition, *, dt=.25):
    if dt not in (.1,.25):raise ValueError('declared 4 or 10 Hz clock required')
    short,long = round(30/dt),round(90/dt)
    if n not in (short,long) or condition not in ('joint_full','Hb_only_full','joint_blocked'):
        raise ValueError('unregistered sample shape or condition')
    mask = np.ones((n,3), bool); mask[-1] = False
    if condition == 'Hb_only_full':
        mask[:,0] = False
    if condition == 'joint_blocked':
        for start in range(0,n,short):
            mask[start+round(10/dt):start+round(15/dt),1:] = False
            mask[start+round(20/dt):start+round(25/dt),1:] = False
    return mask


def volume_drive_metrics(target, prediction, sd, condition, *, dt=.25):
    from scipy.fft import dct
    y, pred = np.asarray(target), np.asarray(prediction)
    n = len(y); error = (pred-y)/sd
    valid = np.ones(n,bool); valid[-1] = False
    mask = volume_drive_mask(n,condition,dt=dt)
    score = ~mask[:,1] & valid if condition == 'joint_blocked' else valid
    short,long = round(30/dt),round(90/dt)
    center = np.zeros(n,bool); center[short:2*short-1] = True if n == long else False
    if n == short: center = valid.copy()
    tail = np.zeros(n,bool); tail[-short:-1] = True
    result = dict(full_hb_nmse=float(np.mean(error[valid,1:]**2)),
        score_hb_nmse=float(np.mean(error[score,1:]**2)),
        center_hb_nmse=float(np.mean(error[center,1:]**2)),
        tail_hb_nmse=float(np.mean(error[tail,1:]**2)),
        full_hbo_nmse=float(np.mean(error[valid,1]**2)),
        full_hbr_nmse=float(np.mean(error[valid,2]**2)),
        eeg_nmse=float(np.mean(error[valid,0]**2)),
        hbt_training_component_scale_nmse=float(np.mean((pred[valid,1:].sum(1)-y[valid,1:].sum(1))**2)/np.sum(sd[1:]**2)),
        target_hb_correlation=float(np.corrcoef(y[valid,1:].T)[0,1]),
        local_hb_nmse=float(np.mean(((pred[valid,1:]-y[valid,1:])/np.maximum(y[valid,1:].std(0),1e-12))**2)))
    # DCT on the scored support, identical for target and reconstruction. The
    # narrow physical band is a descriptive waveform endpoint, not a fit filter.
    spectrum = dct(error[valid,1:], axis=0, norm='ortho')
    freq = np.arange(valid.sum())/(2*valid.sum()*dt)
    band = (freq >= 1/30-1e-12)&(freq <= .1+1e-12)
    result['oscillation_band_nmse'] = float(np.sum(spectrum[band]**2)/(2*valid.sum()))
    return result


def volume_drive_synthetic(cfg, seed, scenario, length_s):
    from src.inference.observation_baselines import disjoint_native_bin_operator
    from src.inference.shared_driver_rk4 import compiled_forward
    p = volume_drive_parameters(cfg); t = np.arange(360)*.25
    rng = np.random.default_rng(np.random.SeedSequence([cfg['seed'],seed,9101]))
    driver = .024*np.sin(2*np.pi*.043*t+rng.uniform(-np.pi,np.pi))+.012*np.cos(2*np.pi*.077*t)
    initial = np.array([0.,1.,1.,1.,1.])
    if scenario == 'nonrest': initial = np.array([.01,1.03,.98,1.03,1.01])
    forward = compiled_forward(driver,initial,p,.25,8,False,False,state=True)
    ops = disjoint_native_bin_operator(np.arange(900)/10., steps=360, dt=.25, reference_steps=20)
    operators = dict(eeg=ops['eeg'],hb=ops['model'])
    canonical = forward['canonical_prediction'].copy()
    sd = np.array([.025,.025,.015])
    extra = np.zeros_like(canonical)
    if scenario in ('volume','exchange'):
        direction = np.array(cfg['component']['loading'][scenario])
        direction /= np.sqrt(np.mean((direction/sd[1:])**2))
        wave = np.sqrt(2)*np.cos(np.pi*(np.arange(360)+.5)*9/360)
        extra[:,1:] = wave[:,None]*direction
    clean = canonical+extra
    noise = rng.normal(size=clean.shape)*sd*cfg['synthetic']['noise_training_sd']
    observed = np.column_stack((operators['eeg']@(clean[:,0]+noise[:,0]),
                               operators['hb']@(clean[:,1:]+noise[:,1:])))
    target, operator = volume_drive_crop(observed,operators,length_s)
    truth, _ = volume_drive_crop(np.column_stack((operators['eeg']@clean[:,0],operators['hb']@clean[:,1:])),operators,length_s)
    return target, operator, sd, truth


def volume_drive_linear(cfg, target, operator, sd):
    from itertools import product
    from scipy.linalg import svd
    from src.inference.shared_driver_reconstruction import _volume_tied_initial_embedding
    n = len(target); rows = []
    def project(p, condition, arm, rcond):
        d = build_shared_driver_design(p,n,.25,processed_mean_operator=operator)
        x = d.observation_design
        if arm == 'tied_initial': x = x@_volume_tied_initial_embedding(n)
        if arm in ('volume','exchange'): x = np.column_stack((x,volume_drive_basis(cfg,operator,sd,arm)))
        mask = volume_drive_mask(n,condition); scale = np.tile(sd,(n,1))
        w = scale[mask]
        u,s,vt = svd(x[mask.ravel()]/w[:,None],full_matrices=False,check_finite=False)
        keep = s > s[0]*rcond
        b = ((target-d.offset)[mask]/w)
        coef = (vt[keep].T/s[keep])@(u[:,keep].T@b)
        pred = (x@coef).reshape(n,3)+d.offset
        canonical_coef = _volume_tied_initial_embedding(n)@coef if arm == 'tied_initial' else coef[:n+5]
        states = np.einsum('tij,j->ti',d.state_design,canonical_coef)
        return dict(**volume_drive_metrics(target,pred,sd,condition),rank=int(keep.sum()),
            max_linear_state_excursion=float(np.max(np.abs(states[:,1:]))))
    p = volume_drive_parameters(cfg)
    for condition in ('joint_full','Hb_only_full'):
        for arm in cfg['linear']['arms']:
            for rcond in cfg['linear']['rconds']:
                rows.append(dict(condition=condition,arm=arm,rcond=rcond,**project(p,condition,arm,rcond)))
    grid = cfg['linear']['parameter_grid']; profile = []
    for tau,alpha,e0 in product(grid['tau'],grid['alpha'],grid['E0']):
        pp = volume_drive_parameters(cfg,tau=tau,alpha=alpha,E0=e0)
        profile.append(dict(tau=tau,alpha=alpha,E0=e0,
            **project(pp,'Hb_only_full','free_initial',cfg['linear']['rconds'][0])))
    best = min(profile,key=lambda r:r['full_hb_nmse'])
    rows.append(dict(condition='Hb_only_full',arm='parameter_grid_best',rcond=cfg['linear']['rconds'][0],**best))
    return rows, profile


def volume_drive_worker(payload):
    from src.inference.shared_driver_reconstruction import fit_nonlinear_shared_driver
    from src.inference.shared_driver_rk4 import compiled_forward
    cfg,root,out,stage,spec = payload
    start = time.perf_counter(); out = Path(out)
    folder = out/stage; folder.mkdir(parents=True,exist_ok=True)
    result = dict(spec=spec,key=spec['key'],rows=[],status='failed',started_at=datetime.now(timezone.utc).isoformat())
    arrays = {}
    try:
        if spec.get('synthetic'):
            y,op,sd,truth = volume_drive_synthetic(cfg,spec['seed'],spec['scenario'],spec['length_s'])
        else:
            y,op,sd = volume_drive_arrays(cfg,root,spec['ref'],spec['length_s']); truth = None
        arrays.update(target=y,operator=op,sd=sd)
        if stage == 'linear':
            result['rows'],result['parameter_profile'] = volume_drive_linear(cfg,y,op,sd)
        else:
            p = volume_drive_parameters(cfg); condition = spec['condition']
            mask = volume_drive_mask(len(y),condition); visible_y = y.copy(); visible_y[~mask] = np.nan
            arrays['visible'] = mask
            base = None
            for arm in cfg['component']['arms']:
                starts = [dict(driver=np.zeros(len(y)),initial_state=np.r_[0.,np.ones(4)])]
                if base is not None and 'driver' in base:
                    starts.insert(0,dict(driver=base['driver'],initial_state=base['initial_state']))
                basis = volume_drive_basis(cfg,op,sd,arm)
                s = cfg['solver']
                fit = fit_nonlinear_shared_driver(visible_y,p,.25,sd=sd,mean_operator=op,visible=mask,
                    starts=starts,penalty=s['penalty'],initial_penalty=s['initial_penalty'],
                    flow_prior_weight=s['flow_prior_weight'],flow_prior_log_sd=s['flow_prior_log_sd'],
                    max_evaluations=s['max_evaluations'],gradient_tolerance=s['gradient_tolerance'],
                    substeps=s['substeps'],numerical_backend=s['numerical_backend'],
                    observation_basis=basis,observation_coefficient_sd=cfg['component']['coefficient_sd'])
                if arm == 'base': base = fit
                row = dict(arm=arm,condition=condition,converged=fit['converged'],fit_status=fit['status'],
                    starts=fit['starts'],evaluations=fit['evaluations'])
                if 'prediction' in fit:
                    finer = compiled_forward(fit['driver'],fit['initial_state'],p,.25,s['validation_substeps'],False,False)
                    fine_pred = (op@finer['canonical_prediction'].ravel()).reshape(y.shape)+fit['observation_component']
                    integration = float(np.max(np.abs((fine_pred-fit['prediction'])[:-1]/sd)))
                    row.update(integration_max_training_sd=integration,
                        qualified=bool(fit['converged'] and integration <= s['maximum_integration_difference_training_sd']),
                        objective=fit['objective'],scaled_gradient=fit['scaled_gradient_inf_norm'],
                        **volume_drive_metrics(y,fit['prediction'],sd,condition))
                    delta = fit['states'][:,4]-fit['states'][:,3]
                    row['p_minus_v_abs_increases'] = int(np.sum(np.diff(np.abs(delta))>1e-8))
                    row['initial_p_minus_v'] = float(delta[0])
                    row['final_p_minus_v'] = float(delta[-1])
                    if truth is not None:
                        row['noiseless_hb_nmse'] = volume_drive_metrics(truth,fit['prediction'],sd,condition)['full_hb_nmse']
                    for name in ('prediction','physical_prediction','observation_component','states','driver','initial_state','observation_coefficients'):
                        arrays[arm+'_'+name] = fit[name]
                else:
                    row['qualified'] = False
                result['rows'].append(row)
        result['status'] = 'completed'
    except Exception:
        result['error'] = traceback.format_exc()
    result.update(seconds=time.perf_counter()-start,max_rss_mb=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    if arrays:
        np.savez_compressed(folder/(spec['key']+'.npz'),**arrays)
    write_json(folder/(spec['key']+'.json'),result)
    return dict(key=spec['key'],status=result['status'],seconds=result['seconds'],max_rss_mb=result['max_rss_mb'])


def volume_drive_specs(cfg,plan,stage):
    specs = []
    if stage in ('synthetic','pilot'):
        for seed in (cfg['synthetic']['seeds'] if stage == 'synthetic' else [0]):
            for scenario in (cfg['synthetic']['scenarios'] if stage == 'synthetic' else ['matched','volume']):
                for length in cfg['tensor']['lengths_s']:
                    for condition in (cfg['conditions'] if stage == 'synthetic' else ['joint_full']):
                        specs.append(dict(synthetic=True,seed=seed,scenario=scenario,length_s=length,condition=condition,
                            dataset='synthetic',subject=str(seed),id=f'seed{seed}_{scenario}',
                            key=f's{seed}_{scenario}_{length}_{condition}'))
    else:
        for ref in plan['records']:
            for length in cfg['tensor']['lengths_s']:
                for condition in (['all'] if stage == 'linear' else cfg['conditions']):
                    specs.append(dict(ref=ref,length_s=length,condition=condition,dataset=ref['dataset'],
                        subject=ref['subject'],id=ref['id'],key=f'{ref["id"]}_{length}_{condition}'))
    return specs


def volume_drive_summarize(cfg,out,plan):
    out = Path(out); all_rows = []; manifests = {}
    for stage in ('pilot','synthetic','linear','measured'):
        specs = volume_drive_specs(cfg,plan,stage); counts = dict(planned=len(specs),terminal=0,completed=0,failed=0)
        for spec in specs:
            path = out/stage/(spec['key']+'.json')
            if not path.exists(): continue
            task = json.loads(path.read_text()); counts['terminal'] += 1
            counts['completed' if task['status']=='completed' else 'failed'] += 1
            for row in task['rows']:
                all_rows.append(dict(stage=stage,dataset=spec['dataset'],subject=spec['subject'],id=spec['id'],
                    length_s=spec['length_s'],key=spec['key'],scenario=spec.get('scenario','measured'),
                    **{k:v for k,v in row.items() if k!='starts'}))
        manifests[stage] = counts
    frame = pd.DataFrame(all_rows); frame.to_csv(out/'metrics.csv',index=False)
    summaries = []; paired = []
    metrics = ['full_hb_nmse','score_hb_nmse','center_hb_nmse','tail_hb_nmse','full_hbo_nmse','full_hbr_nmse',
               'oscillation_band_nmse','local_hb_nmse','hbt_training_component_scale_nmse','eeg_nmse']
    for keys,g in frame.groupby(['stage','dataset','scenario','length_s','condition','arm'],dropna=False):
        if keys[0]=='linear': g = g[np.isclose(g.rcond,cfg['linear']['rconds'][0])]
        good = g if keys[0]=='linear' else g[g.qualified==True]
        row = dict(zip(['stage','dataset','scenario','length_s','condition','arm'],keys))
        row.update(planned=len(g),qualified=len(good),subjects=int(good.subject.nunique()))
        for metric in metrics:
            row[metric.replace('nmse','nrmse')] = float(np.sqrt(good.groupby('subject')[metric].mean().mean())) if len(good) else None
        summaries.append(row)
    for keys,g in frame[frame.stage.isin(['measured','synthetic'])].groupby(['stage','dataset','scenario','length_s','condition']):
        for candidate in ('volume','exchange'):
            base=g[g.arm=='base']; extra=g[g.arm==candidate]
            merged=base.merge(extra,on=['subject','id'],suffixes=('_base','_extra'))
            good=merged[(merged.qualified_base==True)&(merged.qualified_extra==True)]
            item=dict(zip(['stage','dataset','scenario','length_s','condition'],keys),candidate=candidate,
                planned_pairs=len(base),qualified_pairs=len(good),subjects=int(good.subject.nunique()))
            for metric in metrics:
                if not len(good): continue
                units=good.groupby('subject')[[metric+'_base',metric+'_extra']].mean().to_numpy()
                br,er=np.sqrt(units.mean(0));delta=br-er
                rng=np.random.default_rng(cfg['seed'])
                indices=rng.integers(0,len(units),size=(cfg['endpoints']['bootstrap_repeats'],len(units)))
                boot=np.sqrt(units[indices].mean(1)); ci=np.quantile(boot[:,0]-boot[:,1],[.025,.975])
                item[metric]=dict(base_nrmse=br,candidate_nrmse=er,improvement=delta,ci95=ci,
                    relative_rmse_reduction=delta/br if br>0 else None)
            paired.append(item)
    write_json(out/'summary.json',dict(schema='shared_driver_volume_drive_summary_v1',experiment_id=cfg['experiment_id'],
        status='completed' if all(manifests[s]['terminal']==manifests[s]['planned'] for s in ('synthetic','linear','measured')) else 'in_progress',
        stages=manifests,independent_subjects=plan['independent_subjects'],groups=summaries,paired=paired,
        inference='conditional public reanalysis; extra compartment source unidentifiable; no confirmation or teacher qualification'))
    pd.DataFrame(summaries).to_csv(out/'group_summary.csv',index=False)
    return manifests


def volume_drive_main(args):
    cfg = volume_drive_config(args.config)
    if args.check_only:
        print(json.dumps(dict(experiment_id=cfg['experiment_id'],measured_arrays_read=0,config_valid=True)))
        return
    if args.run_dir is None: raise ValueError('fresh explicit run directory required')
    root=args.project_root.resolve();out=args.run_dir.resolve()
    if not out.is_relative_to(root/cfg['output_root']): raise ValueError('volume-drive output namespace mismatch')
    out.mkdir(parents=True,exist_ok=True)
    config_path=out/'resolved_config.yaml'
    if config_path.exists() and yaml.safe_load(config_path.read_text())!=cfg:
        raise ValueError('resume configuration mismatch')
    if not config_path.exists(): config_path.write_text(yaml.safe_dump(cfg,sort_keys=False,allow_unicode=True))
    plan=volume_drive_plan(cfg,root)
    if (out/'plan.json').exists() and json.loads((out/'plan.json').read_text())!=serial(plan):
        raise ValueError('resume parent plan mismatch')
    write_json(out/'plan.json',plan)
    stage=args.volume_stage
    if stage=='summarize':
        print(volume_drive_summarize(cfg,out,plan));return
    if stage in ('linear','measured'):
        synthetic=out/'synthetic'
        expected=volume_drive_specs(cfg,plan,'synthetic')
        if not all((synthetic/(s['key']+'.json')).is_file() for s in expected):
            raise ValueError('complete independent synthetic controls required before measured array reads')
        for spec in expected:
            task=json.loads((synthetic/(spec['key']+'.json')).read_text())
            if task['status']!='completed': raise ValueError('synthetic software failure before measured read')
    specs=volume_drive_specs(cfg,plan,stage)
    workers=min(args.workers,cfg['resources']['max_workers'],len(specs))
    if workers<1: raise ValueError('positive worker count required')
    folder=out/stage;folder.mkdir(exist_ok=True)
    with (out/'run.lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        pending=[s for s in specs if not (folder/(s['key']+'.json')).exists()]
        write_json(out/(stage+'_manifest.json'),dict(status='running',planned=len(specs),previous_terminal=len(specs)-len(pending),
            workers=workers,numerical_threads=1,pid=os.getpid(),started_at=datetime.now(timezone.utc).isoformat()))
        completed=len(specs)-len(pending);iterator=iter(pending)
        with ProcessPoolExecutor(max_workers=workers) as pool:
            active={}
            def submit():
                spec=next(iterator,None)
                if spec is None:return False
                active[pool.submit(volume_drive_worker,(cfg,str(root),str(out),stage,spec))]=spec
                return True
            for _ in range(workers*cfg['resources']['in_flight_per_worker']):
                if not submit():break
            while active:
                done,_=wait(active,return_when=FIRST_COMPLETED)
                for future in done:
                    spec=active.pop(future)
                    try: result=future.result()
                    except Exception:
                        result=dict(key=spec['key'],status='failed',spec=spec,rows=[],error=traceback.format_exc())
                        write_json(folder/(spec['key']+'.json'),result)
                    completed+=1
                    print(json.dumps(dict(stage=stage,terminal=completed,total=len(specs),**result)),flush=True)
                    write_json(out/'progress.json',dict(stage=stage,terminal=completed,total=len(specs),last=result))
                    submit()
        write_json(out/(stage+'_manifest.json'),dict(status='completed',planned=len(specs),terminal=completed,
            workers=workers,numerical_threads=1,completed_at=datetime.now(timezone.utc).isoformat()))
    print(volume_drive_summarize(cfg,out,plan))


def decay_config(path):
    """Admit only the fixed six-arm retained-public decay diagnostic."""
    cfg = yaml.safe_load(Path(path).read_text())
    expected_arms = [dict(name=name, multiplier=multiplier, input=driven)
        for driven in (False, True)
        for name, multiplier in zip(('driven_original','driven_slow','driven_no_decay') if driven
                                    else ('original','slow','no_decay'), (1., .1, 0.))]
    expected_parents = ['experiments/runs/physiology_semantic_tokenizer/ssm_output_support/20261010_v1',
                        'experiments/runs/physiology_semantic_tokenizer/ssm_output_support/20261013_refed_v2']
    expected_parameters = dict(tau=2., kappa=.64, gamma=.32, alpha=.32, E0=.32,
        P0=1., Q0=.35, neurovascular_gain=1., policy='fixed_reference_in_all_fits')
    if (cfg.get('schema') != 'shared_driver_decay_v1' or cfg.get('experiment_id') != 'SSM-DECAY-v1'
            or cfg.get('seed') != 20261023
            or cfg.get('parents') != expected_parents
            or cfg.get('output_root') != 'experiments/runs/physiology_semantic_tokenizer/shared_driver_reconstruction'
            or cfg.get('run_name') != '20261023_decay_v1'
            or cfg['data']['protected_data'] != 'forbidden' or cfg['data']['raw_reads']
            or cfg['data']['labels_as_inputs'] or cfg['data']['expected_records'] != 48
            or cfg['data']['datasets'] != ['eeg_fnirs_single_trial','simultaneous_eeg_nirs','visual_cognitive_motivation','refed']
            or cfg['data']['arrays'] != 'exact_parent_plan_prepared_and_training_coordinates_only'
            or cfg['data']['partition'] != 'parent_evaluation_all_records'
            or cfg['tensor'] != dict(dt_s=.25, lengths_s=[30,90], slices=[[120,240],[0,360]],
                components=list(MODALITIES), reference_steps=20,
                last_bin='excluded_from_fit_and_score_to_avoid_30s_interpolation_halo')
            or cfg['parameters'] != expected_parameters or cfg['decay']['arms'] != expected_arms
            or cfg['conditions'] != ['joint_full','Hb_only_full','joint_blocked']
            or cfg['forcing']['modes'] != {30:7,90:19}
            or cfg['forcing']['basis'] != 'DC_plus_cosine_k_1_to_6_or_18_at_physical_time_plus_dt_over_two_continuous_RK_stages'
            or cfg['forcing']['units'] != 'state_per_second'
            or cfg['forcing']['prior_sd'] != .025 or cfg['forcing']['prior_weight'] != 1.
            or cfg['forcing']['prior'] != 'weight_times_dt_sum_u_squared_divided_by_sd_squared'
            or cfg['forcing']['prior_interpretation'] != 'engineering_input_energy_scale_not_physiological_noise_SD'
            or cfg['forcing']['normalization'] != 'none_no_length_or_lambda_specific_rescaling'
            or cfg['synthetic']['seeds'] != list(range(6))
            or cfg['synthetic']['scenarios'] != ['matched','original_transient','slow_transient','sustained_input']
            or cfg['synthetic']['truth_in_fitting'] is not False
            or cfg['synthetic']['training_sd'] != [.025,.025,.015]
            or cfg['resources']['numerical_threads'] != 1
            or cfg['resources']['in_flight_per_worker'] != 2
            or not 1 <= cfg['resources']['max_workers'] <= 36
            or cfg['resources']['supervisor'] != 'user_systemd'):
        raise ValueError('decay diagnostic contract boundary violated')
    s = cfg['solver']
    if (s['penalty'] != .01 or s['initial_penalty'] != 100. or s['flow_prior_weight'] != 1.
            or s['flow_prior_log_sd'] != float(np.log(2)) or s['max_evaluations'] != 600
            or s['gradient_tolerance'] != 1e-5 or s['substeps'] != 4 or s['validation_substeps'] != 8
            or s['maximum_integration_difference_training_sd'] != .005
            or s['numerical_backend'] != 'numba'
            or s['starts'] != 'rest_then_original_fit_and_rest_for_alternatives'
            or s['initial_state'] != 'five_independent_physical_coordinates'
            or cfg['decay']['replay_hbr_tolerance'] != 1e-10
            or cfg['endpoints']['bootstrap_repeats'] != 2000
            or cfg['synthetic']['transient_delta0'] != .08
            or cfg['synthetic']['sustained_mode_90s'] != 9
            or cfg['synthetic']['sustained_amplitude_state_per_s'] != .012
            or cfg['synthetic']['amplitude_seed_relative_step'] != .03
            or cfg['synthetic']['noise_training_sd'] != .03
            or cfg['synthetic']['generation_substeps'] != 8
            or cfg['synthetic']['same_90s_driver_and_noise_within_seed'] is not True
            or cfg['hidden'] != dict(block_s=[[10,15],[20,25]], repeat_every_s=30,
                components=['HbO','HbR'], interpretation='within_record_offline_blocked_interpolation_not_future_prediction')):
        raise ValueError('decay diagnostic numerical contract boundary violated')
    return cfg


def decay_plan(cfg, root):
    plan = volume_drive_plan(cfg, root)
    if len(plan['records']) != cfg['data']['expected_records']:
        raise ValueError('decay diagnostic retained public record count mismatch')
    if len({record['id'] for record in plan['records']}) != len(plan['records']):
        raise ValueError('decay diagnostic task identity collision')
    return dict(plan, schema='shared_driver_decay_plan_v1',
        arms=cfg['decay']['arms'], planned_synthetic_tasks=144, planned_measured_tasks=288,
        paired_windows_are_independent=False)


def decay_synthetic(cfg, seed, scenario, length_s):
    """One canonical 90s trajectory per seed/scenario; the 30s view is a crop.

    Driver and noise depend on seed alone, and every target uses the existing
    native-bin and reference operators. Truth is exported for scoring only.
    """
    from src.inference.observation_baselines import disjoint_native_bin_operator
    from src.inference.shared_driver_rk4 import decay_forward
    if seed not in cfg['synthetic']['seeds'] or scenario not in cfg['synthetic']['scenarios']:
        raise ValueError('unregistered synthetic seed/scenario')
    p = volume_drive_parameters(cfg); dt = cfg['tensor']['dt_s']; t = np.arange(360)*dt
    rng = np.random.default_rng(np.random.SeedSequence([cfg['seed'],seed,9101]))
    driver = .024*np.sin(2*np.pi*.043*t+rng.uniform(-np.pi,np.pi))+.012*np.cos(2*np.pi*.077*t)
    initial = np.r_[0., np.ones(4)]
    if scenario in ('original_transient','slow_transient'):
        initial[3] += cfg['synthetic']['transient_delta0']
    multiplier = .1 if scenario == 'slow_transient' else 1.
    coefficients = None
    if scenario == 'sustained_input':
        coefficients = np.zeros(cfg['forcing']['modes'][90])
        coefficients[cfg['synthetic']['sustained_mode_90s']] = (
            cfg['synthetic']['sustained_amplitude_state_per_s']
            *(1+cfg['synthetic']['amplitude_seed_relative_step']*seed)*(-1 if seed%2 else 1))
    forward = decay_forward(driver,initial,p,dt,decay_multiplier=multiplier,
        forcing_coefficients=coefficients,substeps=cfg['synthetic']['generation_substeps'])
    clean = forward['canonical_prediction']; sd = np.asarray(cfg['synthetic']['training_sd'])
    noise = rng.normal(size=clean.shape)*sd*cfg['synthetic']['noise_training_sd']
    native = disjoint_native_bin_operator(np.arange(900)/10., steps=360, dt=.25, reference_steps=20)
    operators = dict(eeg=native['eeg'],hb=native['model'])
    def observe(values):
        return np.column_stack((operators['eeg']@values[:,0],operators['hb']@values[:,1:]))
    target, operator = volume_drive_crop(observe(clean+noise),operators,length_s)
    noiseless, _ = volume_drive_crop(observe(clean),operators,length_s)
    support = slice(120,240) if length_s == 30 else slice(0,360)
    truth = dict(states=forward['states'][support], driver=driver[support],
        forcing=forward['forcing'][support], delta=(forward['states'][:,4]-forward['states'][:,3])[support],
        prediction=noiseless, canonical_prediction=clean[support], noise=noise[support],
        decay_multiplier=float(multiplier), original_time_s=t[support],
        original_90s_delta0=float(initial[3]-initial[2]))
    return target, operator, sd, truth


def decay_metrics(target, prediction, sd, condition, states, forcing, forward, cfg):
    """Training-SD observation errors and explicitly separate state diagnostics."""
    n = len(target); dt = cfg['tensor']['dt_s']; time_s = np.arange(n)*dt
    result = volume_drive_metrics(target,prediction,sd,condition)
    error = (np.asarray(prediction)-np.asarray(target))/sd
    valid = np.arange(n) < n-1
    score = ~volume_drive_mask(n,condition)[:,1] & valid if condition == 'joint_blocked' else valid
    result['score_hbo_nmse'] = float(np.mean(error[score,1]**2))
    result['score_hbr_nmse'] = float(np.mean(error[score,2]**2))
    regions = {'first_0_5s':(0,5), 'next_5_10s':(5,10), 'ten_to_thirty_s':(10,30)}
    if n == 360:
        regions.update(middle_30s=(30,60),last_30s=(60,90))
    for name,(left,right) in regions.items():
        use = valid & (time_s >= left) & (time_s < right)
        result[name+'_hb_nmse'] = float(np.mean(error[use,1:]**2))
    late = valid & (time_s >= (10 if n == 120 else 60))
    demeaned = error[late,1:]-np.mean(error[late,1:],axis=0)
    result['late_demeaned_hb_nmse'] = float(np.mean(demeaned**2))
    center = np.zeros(n,bool); center[120:239] = True
    if n == 120: center = valid.copy()
    center_error = error[center,1:]-np.mean(error[center,1:],axis=0)
    result['center_demeaned_hb_nmse'] = float(np.mean(center_error**2))
    result['late_hbo_nmse'] = float(np.mean(error[late,1]**2))
    result['late_hbr_nmse'] = float(np.mean(error[late,2]**2))
    delta = states[:,4]-states[:,3]
    nonzero = np.sign(delta[np.abs(delta) > 1e-8])
    late_nonzero = np.sign(delta[late & (np.abs(delta)>1e-8)])
    retention = np.asarray(forward['decay_retention'])
    def first_crossing(threshold):
        crossings = np.flatnonzero(retention <= threshold)
        return float(time_s[crossings[0]]) if crossings.size else None
    result.update(initial_p_minus_v=float(delta[0]), final_p_minus_v=float(delta[-1]),
        full_hb_nrmse=float(np.sqrt(result['full_hb_nmse'])),
        late_hb_nmse=float(np.mean(error[late,1:]**2)),
        late_hb_nrmse=float(np.sqrt(np.mean(error[late,1:]**2))),
        delta_late_sd=float(np.std(delta[late])), delta_late_rms=float(np.sqrt(np.mean(delta[late]**2))),
        delta_sign_changes=int(np.sum(nonzero[1:] != nonzero[:-1])),
        delta_late_sign_changes=int(np.sum(late_nonzero[1:] != late_nonzero[:-1])),
        sign_change_tolerance=1e-8,
        retention_end=float(retention[-1]), retention_e_fold_s=first_crossing(np.exp(-1)),
        retention_95_loss_s=first_crossing(.05),
        retention_integral_end=float(forward['retention_integral'][-1]),
        forcing_rms_state_per_s=float(np.sqrt(np.mean(np.asarray(forcing)[valid]**2))),
        forcing_late_rms_state_per_s=float(np.sqrt(np.mean(np.asarray(forcing)[late]**2))))
    return result


def decay_delta_contributions(states, operator, parameters):
    """Raw P0*(p-v) contributes to HbO/HbT only; reference can leave an offset."""
    raw = np.zeros((len(states),3)); raw[:,1] = parameters.fixed.P0*(states[:,4]-states[:,3])
    referenced = (operator@raw.ravel()).reshape(raw.shape)
    return raw,referenced


def decay_upstream_compensation(states, original):
    result = {}
    for name,column in (('driver',0),('s',1),('f',2),('v',3),('q',5)):
        result[name+'_change_rms_from_original'] = float(np.sqrt(np.mean((states[:,column]-original[:,column])**2)))
    return result


def decay_fixed_upstream_replays(cfg, original, operator, sd):
    """Change only lambda: driver, s/f/v/p/q initial values all stay fixed."""
    from src.inference.shared_driver_rk4 import decay_forward
    p = volume_drive_parameters(cfg); arrays = {}; audits = []
    reference = None
    for arm in cfg['decay']['arms'][:3]:
        name = arm['name']
        try:
            forward = decay_forward(original['driver'],original['initial_state'],p,cfg['tensor']['dt_s'],
                decay_multiplier=arm['multiplier'],substeps=cfg['solver']['substeps'])
        except FloatingPointError as exc:
            if name == 'original':
                raise
            audits.append(dict(arm=name,decay_multiplier=arm['multiplier'],
                status='infeasible_counterfactual',error=repr(exc),
                upstream_max_abs_difference=None,hbr_max_abs_difference=None,
                identical_upstream_and_hbr=None,original_fit_prediction_max_training_sd=None))
            continue
        prediction = (operator@forward['canonical_prediction'].ravel()).reshape(-1,3)
        states = forward['states']
        if reference is None:
            reference = (states,prediction)
        upstream = float(np.max(np.abs(states[:,[0,1,2,3,5]]-reference[0][:,[0,1,2,3,5]])))
        hbr = float(np.max(np.abs(prediction[:,2]-reference[1][:,2])))
        if max(upstream,hbr) > cfg['decay']['replay_hbr_tolerance']:
            raise AssertionError('fixed-upstream decay replay changed upstream states or HbR')
        raw,ref = decay_delta_contributions(states,operator,p)
        prefix = 'replay_'+name+'_'
        arrays.update({prefix+key:value for key,value in dict(states=states,prediction=prediction,
            delta=states[:,4]-states[:,3],forcing=forward['forcing'],
            retention_integral=forward['retention_integral'],decay_retention=forward['decay_retention'],
            raw_delta_contribution=raw,referenced_delta_contribution=ref).items()})
        audits.append(dict(arm=name,decay_multiplier=arm['multiplier'],status='completed',
            upstream_max_abs_difference=upstream,hbr_max_abs_difference=hbr,
            identical_upstream_and_hbr=True,
            original_fit_prediction_max_training_sd=float(np.max(np.abs((prediction-original['prediction'])[:-1]/sd)))
                if name == 'original' else None))
    return arrays,audits


def decay_worker(payload):
    from src.inference.shared_driver_reconstruction import fit_decay_shared_driver
    from src.inference.shared_driver_rk4 import decay_forward
    cfg,root,out,stage,spec = payload
    begin = time.perf_counter(); folder = Path(out)/stage; folder.mkdir(parents=True,exist_ok=True)
    result = dict(schema='shared_driver_decay_task_v1',spec=spec,key=spec['key'],rows=[],
        status='failed',started_at=datetime.now(timezone.utc).isoformat(),replay_audits=[])
    arrays = {}; original = None; arm_errors = 0
    try:
        if spec.get('synthetic'):
            target,operator,sd,truth = decay_synthetic(cfg,spec['seed'],spec['scenario'],spec['length_s'])
        else:
            target,operator,sd = volume_drive_arrays(cfg,root,spec['ref'],spec['length_s']); truth = None
        mask = volume_drive_mask(len(target),spec['condition'])
        visible_target = target.copy(); visible_target[~mask] = np.nan
        arrays.update(target=target,operator=operator,sd=sd,visible=mask)
        if truth is not None:
            arrays.update({'truth_'+name:value for name,value in truth.items()})
        parameters_ = volume_drive_parameters(cfg); s = cfg['solver']; dt = cfg['tensor']['dt_s']
        for arm in cfg['decay']['arms']:
            name = arm['name']; row = dict(arm=name,condition=spec['condition'],
                decay_multiplier=arm['multiplier'],input_present=arm['input'],
                forcing_modes=cfg['forcing']['modes'][spec['length_s']] if arm['input'] else 0,
                converged=False,qualified=False,software_error=False)
            try:
                starts = [dict(driver=np.zeros(len(target)),initial_state=np.r_[0.,np.ones(4)])]
                if original is not None:
                    starts.insert(0,dict(driver=original['driver'],initial_state=original['initial_state']))
                if arm['input']:
                    for start in starts:
                        start['forcing_coefficients'] = np.zeros(row['forcing_modes'])
                fit = fit_decay_shared_driver(visible_target,parameters_,dt,mean_operator=operator,sd=sd,visible=mask,
                    decay_multiplier=arm['multiplier'],forcing_modes=row['forcing_modes'],
                    forcing_sd=cfg['forcing']['prior_sd'],forcing_weight=cfg['forcing']['prior_weight'],
                    penalty=s['penalty'],initial_penalty=s['initial_penalty'],
                    flow_prior_weight=s['flow_prior_weight'],flow_prior_log_sd=s['flow_prior_log_sd'],
                    max_evaluations=s['max_evaluations'],gradient_tolerance=s['gradient_tolerance'],
                    substeps=s['substeps'],starts=starts)
                row.update(converged=bool(fit['converged']),fit_status=fit['status'],starts=fit['starts'],
                    evaluations=fit['evaluations'])
                if 'prediction' in fit:
                    coefficients = fit['forcing_coefficients']
                    forward = decay_forward(fit['driver'],fit['initial_state'],parameters_,dt,
                        decay_multiplier=arm['multiplier'],forcing_coefficients=coefficients,substeps=s['substeps'])
                    fine = decay_forward(fit['driver'],fit['initial_state'],parameters_,dt,
                        decay_multiplier=arm['multiplier'],forcing_coefficients=coefficients,substeps=s['validation_substeps'])
                    fine_prediction = (operator@fine['canonical_prediction'].ravel()).reshape(target.shape)
                    integration = float(np.max(np.abs((fine_prediction-fit['prediction'])[:-1]/sd)))
                    row.update(integration_max_training_sd=integration,
                        integration_passed=integration <= s['maximum_integration_difference_training_sd'],
                        qualified=bool(fit['converged'] and integration <= s['maximum_integration_difference_training_sd']),
                        objective=fit['objective'],scaled_gradient=fit['scaled_gradient_inf_norm'],
                        costs=fit['costs'],**fit['costs'],
                        **decay_metrics(target,fit['prediction'],sd,spec['condition'],fit['states'],forward['forcing'],forward,cfg))
                    raw,referenced = decay_delta_contributions(fit['states'],operator,parameters_)
                    late_start = 40 if len(target) == 120 else 240
                    row.update(raw_delta_late_hbo_mean=float(np.mean(raw[late_start:-1,1])),
                        referenced_delta_late_hbo_mean=float(np.mean(referenced[late_start:-1,1])))
                    if truth is not None:
                        row['noiseless_hb_nmse'] = volume_drive_metrics(truth['prediction'],fit['prediction'],sd,spec['condition'])['full_hb_nmse']
                        for state,column in (('driver',0),('s',1),('f',2),('v',3),('p',4),('q',5)):
                            row['truth_'+state+'_rmse'] = float(np.sqrt(np.mean((fit['states'][:-1,column]-truth['states'][:-1,column])**2)))
                        row['truth_delta_rmse'] = float(np.sqrt(np.mean(((fit['states'][:,4]-fit['states'][:,3])-truth['delta'])[:-1]**2)))
                        row['state_delta_rmse'] = row['truth_delta_rmse']
                        row['truth_delta_initial'] = float(truth['delta'][0])
                        row['truth_delta_final'] = float(truth['delta'][-1])
                        row['truth_forcing_rmse_state_per_s'] = float(np.sqrt(np.mean((forward['forcing'][:-1]-truth['forcing'][:-1])**2)))
                    for key in ('prediction','states','driver','initial_state','forcing_coefficients'):
                        arrays[name+'_'+key] = fit[key]
                    for key in ('forcing','retention_integral','decay_retention'):
                        arrays[name+'_'+key] = forward[key]
                    arrays[name+'_delta'] = fit['states'][:,4]-fit['states'][:,3]
                    arrays[name+'_transient_delta'] = arrays[name+'_delta'][0]*forward['decay_retention']
                    arrays[name+'_forced_delta'] = arrays[name+'_delta']-arrays[name+'_transient_delta']
                    arrays[name+'_raw_delta_contribution'] = raw
                    arrays[name+'_referenced_delta_contribution'] = referenced
                    if name == 'original':
                        original = fit
                        replay_arrays,result['replay_audits'] = decay_fixed_upstream_replays(cfg,original,operator,sd)
                        arrays.update(replay_arrays)
                    if original is not None:
                        row.update(decay_upstream_compensation(fit['states'],original['states']))
            except Exception:
                arm_errors += 1
                row.update(software_error=True,qualified=False,fit_status='exception',error=traceback.format_exc())
            result['rows'].append(row)
        result['status'] = 'completed_with_arm_errors' if arm_errors else 'completed'
    except Exception:
        result['error'] = traceback.format_exc()
    result.update(seconds=time.perf_counter()-begin,software_errors=arm_errors,
        max_rss_mb=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    if arrays:
        destination = folder/(spec['key']+'.npz'); temporary = folder/(spec['key']+'.tmp.npz')
        np.savez_compressed(temporary,**arrays); temporary.replace(destination)
    write_json(folder/(spec['key']+'.json'),result)
    return dict(key=spec['key'],status=result['status'],seconds=result['seconds'],
        qualified_arms=sum(row['qualified'] for row in result['rows']),software_errors=arm_errors,max_rss_mb=result['max_rss_mb'])


def decay_specs(cfg,plan,stage):
    if stage not in ('pilot','synthetic','measured'):
        raise ValueError('unregistered decay task stage')
    if stage == 'measured':
        return volume_drive_specs(cfg,plan,'measured')
    specs = []
    for seed in (cfg['synthetic']['seeds'] if stage == 'synthetic' else [0]):
        for scenario in (cfg['synthetic']['scenarios'] if stage == 'synthetic' else ['matched','sustained_input']):
            for length in cfg['tensor']['lengths_s']:
                for condition in (cfg['conditions'] if stage == 'synthetic' else ['joint_full']):
                    specs.append(dict(synthetic=True,seed=seed,scenario=scenario,length_s=length,condition=condition,
                        dataset='synthetic',subject=str(seed),id=f'seed{seed}_{scenario}',
                        key=f's{seed}_{scenario}_{length}_{condition}'))
    return specs


def decay_paired_contrast(cfg,group,reference,candidate,metric):
    """Whole-subject bootstrap after averaging paired records within subject."""
    left = group[group.arm == reference]; right = group[group.arm == candidate]
    item = dict(reference=reference,candidate=candidate,metric=metric,planned_pairs=len(left),
        qualified_pairs=0,subjects=0)
    if (not (left.qualified == True).any() or not (right.qualified == True).any()
            or metric not in group or not group[metric].notna().any()):
        return item
    merged = left.merge(right,on=['subject','id'],suffixes=('_reference','_candidate'))
    good = merged[(merged.qualified_reference == True)&(merged.qualified_candidate == True)]
    item.update(qualified_pairs=len(good),subjects=int(good.subject.nunique()))
    if not len(good) or metric+'_reference' not in good:
        return item
    units = good.groupby('subject')[[metric+'_reference',metric+'_candidate']].mean().to_numpy()
    if not np.isfinite(units).all():
        return item
    ref,alt = np.sqrt(units.mean(0)); difference = ref-alt
    rng = np.random.default_rng(cfg['seed'])
    indices = rng.integers(0,len(units),size=(cfg['endpoints']['bootstrap_repeats'],len(units)))
    boot = np.sqrt(units[indices].mean(1))
    item.update(reference_nrmse=float(ref),candidate_nrmse=float(alt),improvement=float(difference),
        relative_rmse_reduction=float(difference/ref) if ref>0 else None,
        ci95=np.quantile(boot[:,0]-boot[:,1],[.025,.975]),bootstrap_unit='whole_subject',
        multiplicity='descriptive_unadjusted_intervals_no_confirmatory_significance_claim')
    return item


def decay_summarize(cfg,out,plan,*,source_out=None):
    out = Path(out); rows = []; stages = {}; replay_audits = []
    source_out = Path(source_out) if source_out is not None else out
    for stage in ('pilot','synthetic','measured'):
        specs = decay_specs(cfg,plan,stage)
        counts = dict(planned=len(specs),terminal=0,completed=0,software_failed_tasks=0,
            planned_arms=len(specs)*len(cfg['decay']['arms']),qualified_arms=0,
            nonconverged_arms=0,integration_failed_arms=0,software_error_arms=0,missing_arms=0,
            completed_replays=0,infeasible_counterfactual_replays=0)
        for spec in specs:
            path = out/stage/(spec['key']+'.json')
            if not path.exists(): path = source_out/stage/(spec['key']+'.json')
            task = json.loads(path.read_text()) if path.exists() else None
            if task is not None:
                counts['terminal'] += 1
                counts['completed' if task['status']=='completed' else 'software_failed_tasks'] += 1
                for audit in task.get('replay_audits',[]):
                    audit = dict(status='completed',**audit) if 'status' not in audit else audit
                    counts['infeasible_counterfactual_replays' if audit['status']=='infeasible_counterfactual'
                           else 'completed_replays'] += 1
                    replay_audits.append(dict(stage=stage,key=spec['key'],**audit))
            available = {row['arm']:row for row in task.get('rows',[])} if task else {}
            for arm in cfg['decay']['arms']:
                row = available.get(arm['name'])
                if row is None:
                    row = dict(arm=arm['name'],condition=spec['condition'],qualified=False,converged=False,
                        software_error=task is not None,fit_status='task_failed' if task else 'pending')
                    counts['missing_arms'] += 1
                elif row['qualified']:
                    counts['qualified_arms'] += 1
                elif row.get('software_error'):
                    counts['software_error_arms'] += 1
                elif not row.get('converged'):
                    counts['nonconverged_arms'] += 1
                elif row.get('integration_passed') is False:
                    counts['integration_failed_arms'] += 1
                rows.append(dict(stage=stage,dataset=spec['dataset'],subject=spec['subject'],id=spec['id'],
                    length_s=spec['length_s'],key=spec['key'],scenario=spec.get('scenario','measured'),
                    task_status=task['status'] if task else 'pending',
                    **{key:value for key,value in row.items() if key not in ('starts','costs','error')}))
        stages[stage] = counts
    frame = pd.DataFrame(rows)
    groups = []; paired = []
    metrics = ['full_hb_nmse','score_hb_nmse','full_hbo_nmse','full_hbr_nmse','score_hbo_nmse','score_hbr_nmse',
        'center_hb_nmse','tail_hb_nmse','oscillation_band_nmse','local_hb_nmse',
        'hbt_training_component_scale_nmse','eeg_nmse','first_0_5s_hb_nmse','next_5_10s_hb_nmse',
        'ten_to_thirty_s_hb_nmse','middle_30s_hb_nmse','last_30s_hb_nmse','late_hb_nmse',
        'late_demeaned_hb_nmse','center_demeaned_hb_nmse','late_hbo_nmse','late_hbr_nmse','noiseless_hb_nmse']
    for metric in metrics:
        if metric not in frame: frame[metric] = np.nan
    frame.to_csv(out/'metrics.csv',index=False)
    diagnostics = ['retention_end','retention_e_fold_s','retention_95_loss_s','initial_p_minus_v','final_p_minus_v',
        'delta_late_sd','delta_late_rms','delta_sign_changes','delta_late_sign_changes',
        'forcing_rms_state_per_s','forcing_late_rms_state_per_s',
        'weighted_data_sse','driver_curvature_cost','initial_prior_cost','flow_prior_cost','forcing_prior_cost',
        'driver_change_rms_from_original','s_change_rms_from_original','f_change_rms_from_original',
        'v_change_rms_from_original','q_change_rms_from_original',
        'truth_driver_rmse','truth_v_rmse','truth_p_rmse','truth_q_rmse','truth_delta_rmse','truth_forcing_rmse_state_per_s']
    keys = ['stage','dataset','scenario','length_s','condition','arm']
    for identity,group in frame.groupby(keys,dropna=False):
        good = group[group.qualified == True]
        item = dict(zip(keys,identity)); item.update(planned=len(group),terminal=int((group.task_status!='pending').sum()),
            qualified=len(good),subjects=int(good.subject.nunique()),
            nonconverged=int(((group.converged==False)&(group.software_error==False)&(group.task_status!='pending')).sum()),
            software_errors=int((group.software_error==True).sum()))
        for metric in metrics:
            present = good[good[metric].notna()]
            item[metric.replace('_nmse','_nrmse')] = float(np.sqrt(present.groupby('subject')[metric].mean().mean())) if len(present) else None
        for metric in diagnostics:
            if metric not in good: continue
            values = good[metric].dropna()
            item[metric+'_median'] = float(values.median()) if len(values) else None
            item[metric+'_available'] = len(values)
        groups.append(item)
    contrasts = [('original','slow'),('original','no_decay'),('original','driven_original'),
                 ('original','driven_slow'),('original','driven_no_decay'),
                 ('slow','driven_slow'),('no_decay','driven_no_decay')]
    contrast_keys = keys[:-1]
    for identity,group in frame[frame.stage.isin(['synthetic','measured'])].groupby(contrast_keys,dropna=False):
        for reference,candidate in contrasts:
            for metric in metrics:
                paired.append(dict(zip(contrast_keys,identity),
                    **decay_paired_contrast(cfg,group,reference,candidate,metric)))
    complete = all(stages[stage]['terminal']==stages[stage]['planned'] for stage in ('synthetic','measured'))
    software_failed = any(stages[stage]['software_failed_tasks'] for stage in ('synthetic','measured'))
    summary = dict(schema='shared_driver_decay_summary_v1',experiment_id=cfg['experiment_id'],
        status=('completed_with_software_errors' if software_failed else 'completed') if complete else 'in_progress',
        stages=stages,independent_subjects=plan.get('independent_subjects',{}),groups=groups,paired=paired,
        fixed_upstream_replay_audits=replay_audits,
        retention='exp_minus_lambda_times_integral_a_v_separate_from_forced_delta_and_optical_reference',
        inference='conditional_public_reconstruction_not_physiological_truth_no_multiplicity_adjusted_inference')
    if source_out != out:
        summary.update(evidence_migration='migration.json',parent_run=os.path.relpath(source_out,out))
    write_json(out/'summary.json',summary)
    pd.DataFrame(groups).to_csv(out/'group_summary.csv',index=False)
    write_json(out/'paired_contrasts.json',paired)
    return stages


def decay_replay_migrate(cfg,run,plan):
    """Repair v1 replay-only misclassification without refitting or rewriting it.

    Only affected task JSON and small replay-only NPZ files are written under
    evidence_v2. All fitted arrays and unaffected tasks stay in the parent run.
    """
    run = Path(run).resolve(); out = run/'evidence_v2'
    if out.exists():
        raise ValueError('decay evidence_v2 already exists; retained evidence is never overwritten')
    if yaml.safe_load((run/'resolved_config.yaml').read_text()) != cfg:
        raise ValueError('decay replay migration configuration mismatch')
    if json.loads((run/'plan.json').read_text()) != serial(plan):
        raise ValueError('decay replay migration plan mismatch')
    for stage in ('synthetic','measured'):
        manifest = json.loads((run/(stage+'_manifest.json')).read_text())
        if manifest['status'] not in ('completed','completed_with_software_errors'):
            raise ValueError('complete parent matrix required before replay migration')
        if not all((run/stage/(spec['key']+'.json')).is_file() for spec in decay_specs(cfg,plan,stage)):
            raise ValueError('missing terminal parent task before replay migration')
    solver_sources = ['src/inference/shared_driver_rk4.py','src/inference/t3a_balloon_robust_ssm.py']
    for relative in solver_sources:
        if (CODE_ROOT/relative).read_bytes() != (run/'source_snapshot'/relative).read_bytes():
            raise ValueError('decay replay solver differs from immutable parent source')
    out.mkdir()
    runner_relative = 'experiments/scripts/evaluate_shared_driver_reconstruction.py'
    snapshot = out/'source_snapshot'/runner_relative
    snapshot.parent.mkdir(parents=True); shutil.copyfile(Path(__file__),snapshot)
    migration = dict(schema='shared_driver_decay_replay_migration_v2',status='running',parent_run='..',
        reason='v1_counterfactual_domain_failure_misclassified_valid_original_fit',
        data_policy='exact_saved_fitted_arrays_only_no_refits_no_raw_reads',
        parent_config='../resolved_config.yaml',parent_plan='../plan.json',
        corrected_runner='source_snapshot/'+runner_relative,
        parent_runner='../source_snapshot/'+runner_relative,
        unchanged_solver_sources=['../source_snapshot/'+relative for relative in solver_sources],
        solver_byte_equal_to_parent=True,command_argv=sys.argv,code_root=str(CODE_ROOT),
        started_at=datetime.now(timezone.utc).isoformat(),task_overrides=[])
    write_json(out/'migration.json',migration)
    try:
        for stage in ('pilot','synthetic','measured'):
            for spec in decay_specs(cfg,plan,stage):
                source = run/stage/(spec['key']+'.json')
                if not source.is_file(): continue
                task_bytes = source.read_bytes(); task = json.loads(task_bytes)
                failed = [row for row in task['rows'] if row.get('software_error')]
                if not failed: continue
                if (len(failed) != 1 or failed[0]['arm'] != 'original'
                        or 'decay_fixed_upstream_replays' not in failed[0].get('error','')
                        or not failed[0]['error'].rstrip().endswith('FloatingPointError: invalid physical decay RK stage')):
                    raise ValueError('unrecognized software failure; replay migration cannot repair fits')
                row = failed[0]
                if not row['converged'] or not row['integration_passed']:
                    raise ValueError('replay migration cannot qualify an unconverged or integration-failed original fit')
                selected = min((start for start in row['starts'] if start.get('converged')),
                    key=lambda start:start['objective'])
                if not np.isclose(selected['objective'],row['objective'],rtol=1e-12,atol=1e-10):
                    raise ValueError('saved original selected-start objective mismatch')
                arrays_path = source.with_suffix('.npz'); arrays_bytes = arrays_path.read_bytes()
                with np.load(arrays_path,allow_pickle=False) as archive:
                    original = {key:archive['original_'+key].copy()
                        for key in ('driver','initial_state','states','prediction')}
                    operator = archive['operator'].copy(); sd = archive['sd'].copy()
                replay_arrays,audits = decay_fixed_upstream_replays(cfg,original,operator,sd)
                np.testing.assert_allclose(replay_arrays['replay_original_states'],original['states'],rtol=0,atol=1e-12)
                np.testing.assert_allclose(replay_arrays['replay_original_prediction'],original['prediction'],rtol=0,atol=1e-12)
                row.update(legacy_error=row.pop('error'),legacy_fit_status=row['fit_status'],
                    fit_status=selected['status'],software_error=False,
                    qualified=bool(row['converged'] and row['integration_passed']),
                    replay_migration=dict(source_task='../'+str(source.relative_to(run)),
                        source_arrays='../'+str(arrays_path.relative_to(run)),no_refit=True),
                    **decay_upstream_compensation(original['states'],original['states']))
                task.update(schema='shared_driver_decay_task_evidence_v2',replay_audits=audits,
                    legacy_status=task['status'],status='completed',software_errors=0,
                    fit_arrays='../'+str(arrays_path.relative_to(run)),
                    replay_arrays=str(arrays_path.relative_to(run)),evidence_migration='../migration.json')
                destination = out/stage/(spec['key']+'.json'); destination.parent.mkdir(exist_ok=True)
                np.savez_compressed(destination.with_suffix('.npz'),**replay_arrays)
                write_json(destination,task)
                if source.read_bytes() != task_bytes or arrays_path.read_bytes() != arrays_bytes:
                    raise AssertionError('replay migration modified immutable parent evidence')
                migration['task_overrides'].append(dict(stage=stage,key=spec['key'],
                    task=str(destination.relative_to(out)),replay_arrays=str(destination.with_suffix('.npz').relative_to(out)),
                    source_task='../'+str(source.relative_to(run)),fit_arrays='../'+str(arrays_path.relative_to(run)),
                    original_fit_restored=True,fit_arrays_unchanged=True,
                    replay_statuses={audit['arm']:audit['status'] for audit in audits}))
        migration['stages'] = decay_summarize(cfg,out,plan,source_out=run)
        migration.update(status='completed',completed_at=datetime.now(timezone.utc).isoformat(),
            corrected_tasks=len(migration['task_overrides']),fitted_parameters_changed=0,refits=0)
    except Exception:
        migration.update(status='failed',error=traceback.format_exc())
        raise
    finally:
        write_json(out/'migration.json',migration)
    return migration


def decay_main(args):
    cfg = decay_config(args.config)
    if args.check_only:
        print(json.dumps(dict(experiment_id=cfg['experiment_id'],measured_arrays_read=0,config_valid=True,
            pilot_tasks=4,synthetic_tasks=144,measured_tasks=288,arms=6)))
        return
    if args.run_dir is None:
        raise ValueError('explicit decay run directory required')
    root = args.project_root.resolve(); out = args.run_dir.resolve()
    if out != root/cfg['output_root']/cfg['run_name']:
        raise ValueError('decay diagnostic output namespace mismatch')
    if args.decay_stage == 'replay-migrate':
        plan = json.loads((out/'plan.json').read_text())
        print(json.dumps(decay_replay_migrate(cfg,out,plan)))
        return
    out.mkdir(parents=True,exist_ok=True)
    config_path = out/'resolved_config.yaml'
    if config_path.exists() and yaml.safe_load(config_path.read_text()) != cfg:
        raise ValueError('resume decay configuration mismatch')
    if not config_path.exists():
        config_path.write_text(yaml.safe_dump(cfg,sort_keys=False,allow_unicode=True))
    plan = decay_plan(cfg,root)
    if (out/'plan.json').exists() and json.loads((out/'plan.json').read_text()) != serial(plan):
        raise ValueError('resume decay parent plan mismatch')
    write_json(out/'plan.json',plan)
    stage = args.decay_stage
    if stage == 'check':
        print(json.dumps(dict(experiment_id=cfg['experiment_id'],records=len(plan['records']),measured_arrays_read=0)))
        return
    if stage == 'summarize':
        print(json.dumps(decay_summarize(cfg,out,plan)))
        return
    if stage == 'measured':
        for spec in decay_specs(cfg,plan,'synthetic'):
            path = out/'synthetic'/(spec['key']+'.json')
            if not path.is_file() or json.loads(path.read_text())['status'] != 'completed':
                raise ValueError('complete synthetic software controls required before measured array reads; nonconvergence is retained')
    specs = decay_specs(cfg,plan,stage)
    workers = min(args.workers,cfg['resources']['max_workers'],len(specs))
    if workers < 1:
        raise ValueError('positive worker count required')
    folder = out/stage; folder.mkdir(exist_ok=True)
    with (out/'run.lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        pending = [spec for spec in specs if not (folder/(spec['key']+'.json')).exists()]
        manifest = dict(schema='shared_driver_decay_stage_v1',stage=stage,status='running',planned=len(specs),
            previous_terminal=len(specs)-len(pending),workers=workers,numerical_threads=1,
            in_flight_limit=workers*cfg['resources']['in_flight_per_worker'],pid=os.getpid(),
            code_root=str(CODE_ROOT),project_root=str(root),started_at=datetime.now(timezone.utc).isoformat())
        write_json(out/(stage+'_manifest.json'),manifest)
        completed = len(specs)-len(pending); iterator = iter(pending)
        with ProcessPoolExecutor(max_workers=workers) as pool:
            active = {}
            def submit():
                spec = next(iterator,None)
                if spec is None: return False
                active[pool.submit(decay_worker,(cfg,str(root),str(out),stage,spec))] = spec
                return True
            for _ in range(workers*cfg['resources']['in_flight_per_worker']):
                if not submit(): break
            while active:
                done,_ = wait(active,return_when=FIRST_COMPLETED)
                for future in done:
                    spec = active.pop(future)
                    try:
                        result = future.result()
                    except Exception:
                        result = dict(schema='shared_driver_decay_task_v1',key=spec['key'],status='failed',
                            spec=spec,rows=[],error=traceback.format_exc())
                        write_json(folder/(spec['key']+'.json'),result)
                    completed += 1
                    print(json.dumps(dict(stage=stage,terminal=completed,total=len(specs),**result)),flush=True)
                    write_json(out/'progress.json',dict(stage=stage,terminal=completed,total=len(specs),last=result))
                    submit()
        counts = decay_summarize(cfg,out,plan)[stage]
        manifest.update(status='completed_with_software_errors' if counts['software_failed_tasks'] else 'completed',
            terminal=completed,counts=counts,completed_at=datetime.now(timezone.utc).isoformat())
        write_json(out/(stage+'_manifest.json'),manifest)
    print(json.dumps(counts))


def filter_retest_config(path):
    cfg = yaml.safe_load(Path(path).read_text())
    if (cfg.get('schema') != 'shared_driver_filter_retest_v1'
            or cfg['protected_data'] != 'forbidden' or cfg['raw_source_reads'] != 'forbidden'
            or cfg['arms'] != ['original', 'slow', 'no_decay'] or cfg['forcing_modes'] != 0
            or cfg['branches'] != ['retained_unfiltered', 'unified_cache']
            or cfg['lengths_s'] != [30, 90]
            or cfg['conditions'] != ['joint_full', 'Hb_only_full', 'joint_blocked']
            or cfg['selection']['records_per_dataset'] != 1
            or cfg['selection']['datasets'] != ['eeg_fnirs_single_trial', 'simultaneous_eeg_nirs', 'visual_cognitive_motivation', 'refed']
            or cfg['cache_root'] != 'data/cache/physiology_semantic_clean_v5'
            or cfg['source_run'] != 'experiments/runs/physiology_semantic_tokenizer/shared_driver_reconstruction/20261023_decay_v1'
            or cfg['resources']['numerical_threads'] != 1
            or cfg['solver']['max_evaluations'] != 600):
        raise ValueError('bounded post-10.20 no-extra-component filter retest contract changed')
    base = decay_config(CODE_ROOT / cfg['source_config'])
    if any(cfg['solver'][k] != base['solver'][k] for k in cfg['solver'] if k in base['solver']):
        raise ValueError('retest cannot change the retained numerical budget')
    return cfg, base


def filter_retest_select(records, scores, datasets):
    """Select before new data/fits; the old median is an illustration rule."""
    chosen, denominators = [], {}
    for dataset in datasets:
        candidates = [r for r in records if r['dataset'] == dataset]
        usable = [r for r in candidates if r['id'] in scores and np.isfinite(scores[r['id']])]
        if not usable:
            raise ValueError('no finite retained baseline for ' + dataset)
        median = float(np.median([scores[r['id']] for r in usable]))
        selected = min(usable, key=lambda r: (abs(scores[r['id']] - median), r['id']))
        chosen.append(dict(selected, selection_score=scores[selected['id']], selection_median=median))
        denominators[dataset] = dict(planned_records=len(candidates), usable_records=len(usable),
            independent_subjects=len({r['subject'] for r in candidates}),
            missing_or_failed=[r['id'] for r in candidates if r not in usable])
    return chosen, denominators


def filter_retest_source_task(parent, record_id, length_s, condition):
    """Use the owning replay correction; original fitted arrays stay retained."""
    name = f'{record_id}_{length_s}_{condition}.json'
    corrected = parent / 'evidence_v2' / 'measured' / name
    path = corrected if corrected.exists() else parent / 'measured' / name
    return json.loads(path.read_text())


def filter_retest_plan(cfg, base, root, out):
    parent = root / cfg['source_run']
    if json.loads((parent / 'evidence_v2/summary.json').read_text())['status'] != 'completed':
        raise ValueError('completed retained post-10.20 source required')
    pp = json.loads((parent / 'plan.json').read_text())
    if len(pp['records']) != 48 or any(r['parent'] not in base['parents'] or r['partition'] != 'evaluation' for r in pp['records']):
        raise ValueError('retained public source inventory changed')
    scores = {}
    for ref in pp['records']:
        result = filter_retest_source_task(parent, ref['id'], 90, 'joint_full')
        row = next(r for r in result['rows'] if r['arm'] == 'original')
        if row.get('qualified'):
            scores[ref['id']] = row['full_hb_nmse']
    selected, denominators = filter_retest_select(pp['records'], scores, cfg['selection']['datasets'])
    jobs = [dict(key=f"{ref['id']}__{branch}__{length}__{condition}", ref=ref,
                 branch=branch, length_s=length, condition=condition)
            for ref in selected for branch in cfg['branches']
            for length in cfg['lengths_s'] for condition in cfg['conditions']]
    plan = dict(schema=cfg['schema'], selected=selected, selection_denominators=denominators,
        jobs=jobs, planned_jobs=len(jobs), planned_no_extra_fits=3 * len(jobs),
        independent_evaluation_subjects=len({(r['dataset'], r['subject']) for r in selected}),
        inference='selected_example_sensitivity_no_population_interval_or_confirmation',
        excluded_models=['volume', 'exchange', 'driven_original', 'driven_slow', 'driven_no_decay', 'tokenizer_teacher_extra_component'])
    path = out / 'plan.json'
    if path.exists() and json.loads(path.read_text()) != serial(plan):
        raise ValueError('frozen selection cannot change')
    write_json(path, plan)
    return plan


def filter_retest_prepare(cfg, base, root, out, plan):
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.unified_physiology import load_cached_fnirs_record
    from src.data.ssm_prepared import fit_feature_coordinate
    from src.inference.observation_baselines import disjoint_native_bin_operator
    check = json.loads((out / 'software_checks.json').read_text())
    if check['status'] != 'passed':
        raise ValueError('software/synthetic checks required before cache access')
    index = CleanPhysiologyCacheIndex(root / cfg['cache_root'])
    lookup = {r.join_key: r for r in index.records}
    coordinates, failures = {}, []

    def read_pair(parent, ref):
        if ref['dataset'] not in cfg['selection']['datasets']:
            raise ValueError('dataset outside the bounded public contract')
        with np.load(parent / 'prepared' / (ref['id'] + '.npz'), allow_pickle=False) as a:
            old = {k: a[k].copy() for k in ('eeg', 'hb', 'eeg_operator', 'hb_operator')}
        if old['eeg'].shape != (360, 30) or old['hb'].shape != (360, 2):
            raise ValueError('retained prepared shape changed')
        record = lookup[ref['join_key']]
        cached = load_cached_fnirs_record(root, record)
        pair = int(ref['anchor']['hb_pair'])
        if cached['channel_names'][2 * pair] != ref['anchor']['hb_channel'] + '_HbO':
            raise ValueError('cached channel identity mismatch')
        factor = 1000. if ref['dataset'] == 'simultaneous_eeg_nirs' else 1.
        if factor != 1 and (cached['provenance']['native_unit'] != 'mmol/L' or cached['provenance']['output_unit'] != 'uM'):
            raise ValueError('retained-to-cached unit conversion not established')
        old['hb'] *= factor
        take = (cached['time_s'] >= ref['hb_start_s']) & (cached['time_s'] < ref['hb_start_s'] + 90)
        t = cached['time_s'][take] - ref['hb_start_s']
        native = cached['values'][take, pair]
        if not np.isfinite(native).all() or not np.isfinite(old['hb']).all():
            raise ValueError('unsupported Hb pair in one branch')
        op = disjoint_native_bin_operator(t, steps=360, dt=.25, reference_steps=20)
        new = dict(eeg=old['eeg'], hb=op['raw'] @ native,
                   eeg_operator=old['eeg_operator'], hb_operator=op['model'])
        return dict(retained_unfiltered=old, unified_cache=new), cached['provenance']

    for selected in plan['selected']:
        parent = root / selected['parent']
        pp = json.loads((parent / 'plan.json').read_text())
        candidates = [r for r in pp['records'] if r['coordinate'] == selected['coordinate'] and r['partition'] == 'development']
        chunks = {branch: [] for branch in cfg['branches']}
        good = []
        for ref in candidates:
            if ref['subject'] == selected['subject']:
                raise ValueError('evaluation subject entered calibration')
            try:
                pair, _ = read_pair(parent, ref)
                for branch in cfg['branches']:
                    chunks[branch].append((pair[branch]['eeg'], pair[branch]['hb']))
                good.append(ref)
            except (ValueError, KeyError, FileNotFoundError) as exc:
                failures.append(dict(id=ref['id'], coordinate=ref['coordinate'], reason=str(exc)))
        co = {branch: fit_feature_coordinate(chunks[branch]) for branch in cfg['branches']}
        for branch in cfg['branches']:
            co[branch].update(training_ids=[r['id'] for r in good],
                training_subjects=sorted({r['subject'] for r in good}), planned_training_records=len(candidates))
        coordinates[selected['coordinate']] = co
        pair, provenance = read_pair(parent, selected)
        for branch in cfg['branches']:
            a, c = pair[branch], co[branch]
            y = np.column_stack((a['eeg'] @ np.asarray(c['pc']) * c['eeg_factor'], a['hb'] * c['hb_factor']))
            for length in cfg['lengths_s']:
                target, operator = volume_drive_crop(y, dict(eeg=a['eeg_operator'], hb=a['hb_operator']), length)
                path = out / 'prepared' / f"{selected['id']}__{branch}__{length}.npz"
                path.parent.mkdir(parents=True, exist_ok=True)
                np.savez_compressed(path, target=target, operator=operator, sd=np.asarray(c['sd']),
                    hb_factor=np.array(c['hb_factor']),
                    common_cached_sd_physical=np.asarray(co['unified_cache']['sd'])[1:] / co['unified_cache']['hb_factor'])
        write_json(out / 'prepared' / (selected['id'] + '.json'),
            dict(status='completed', ref=selected, cache_provenance=provenance,
                 calibration=co, original_source='retained_prepared_arrays_only_no_raw_file_parser'))
    result = dict(status='completed', selected_records=len(plan['selected']),
        prepared_pairs=len(plan['selected']) * len(cfg['lengths_s']), coordinates=coordinates,
        calibration_failures=failures, raw_source_reads=0, protected_data_reads=0)
    write_json(out / 'preparation.json', result)
    return result


def filter_retest_waveform_metrics(target, prediction, sd, *, mask=None, hb_factor=1., common_sd=None, dt=.25):
    y, p, sd = np.asarray(target), np.asarray(prediction), np.asarray(sd)
    use = np.ones(len(y), bool) if mask is None else np.asarray(mask, bool)
    use[-1] = False
    rows = []
    for col, name in enumerate(('EEG', 'HbO', 'HbR')):
        a, b = y[use, col], p[use, col]
        ac, bc = a - a.mean(), b - b.mean()
        rms = float(np.sqrt(np.mean((b - a) ** 2)))
        scale = 1. if col == 0 else hb_factor
        row = dict(component=name, nrmse=rms / sd[col], zero_predictor_nrmse=float(np.sqrt(np.mean(a*a)) / sd[col]),
            local_centered_nrmse=rms / max(float(a.std()), 1e-12),
            pearson_r=float(np.corrcoef(a, b)[0, 1]) if min(a.std(), b.std()) > 1e-12 else None,
            centered_amplitude_ratio=float(b.std() / max(a.std(), 1e-12)),
            signed_gain=float(ac @ bc / max(ac @ ac, 1e-24)),
            bias_training_sd=float((b - a).mean() / sd[col]),
            absolute_rmse_in_cache_unit=rms / scale,
            target_centered_rms_in_cache_unit=float(a.std() / scale),
            peak_time_difference_s=float((np.flatnonzero(use)[np.argmax(b)] - np.flatnonzero(use)[np.argmax(a)]) * dt))
        if col and common_sd is not None:
            row['nrmse_common_cached_training_sd'] = rms / scale / common_sd[col - 1]
        rows.append(row)
    return rows


def filter_retest_worker(payload):
    from src.inference.shared_driver_reconstruction import fit_decay_shared_driver
    from src.inference.shared_driver_rk4 import decay_forward
    from src.inference.model_compatibility import weak_hb_profiles, linear_panel_profiles
    cfg, base, root_string, out_string, spec = payload
    root, out = Path(root_string), Path(out_string)
    path = out / 'tasks' / (spec['key'] + '.json')
    started = time.monotonic()
    result = dict(spec=spec, status='failed', rows=[], compatibility=None)
    saved, original = {}, None
    try:
        prepared = out / 'prepared' / f"{spec['ref']['id']}__{spec['branch']}__{spec['length_s']}.npz"
        with np.load(prepared, allow_pickle=False) as a:
            y, op, sd, factor, common_sd = (a[k].copy() for k in
                ('target', 'operator', 'sd', 'hb_factor', 'common_cached_sd_physical'))
        mask = volume_drive_mask(len(y), spec['condition'])
        observed = np.where(mask, y, np.nan)
        saved.update(target=y, operator=op, sd=sd, visible=mask, hb_factor=factor,
                     common_cached_sd_physical=common_sd)
        p = volume_drive_parameters(base)
        source_path = root / cfg['source_run'] / 'measured' / f"{spec['ref']['id']}_{spec['length_s']}_{spec['condition']}.npz"
        retained = None
        if spec['branch'] == 'retained_unfiltered' and source_path.exists():
            with np.load(source_path, allow_pickle=False) as a:
                same = (a['target'].shape == y.shape and np.allclose(a['target'], y, rtol=1e-10, atol=1e-12)
                    and np.allclose(a['operator'], op, rtol=0, atol=1e-12)
                    and np.allclose(a['sd'], sd, rtol=1e-10, atol=1e-12))
                if same:
                    retained = {k: a[k].copy() for k in a.files if
                        any(k.startswith(arm + '_') for arm in cfg['arms'])}
        for name, multiplier in [('original', 1.), ('slow', .1), ('no_decay', 0.)]:
            row = dict(arm=name, decay_multiplier=multiplier, forcing_modes=0, input_present=False)
            if retained is not None and name + '_prediction' in retained:
                meta = filter_retest_source_task(root / cfg['source_run'], spec['ref']['id'],
                                                spec['length_s'], spec['condition'])
                old = next(r for r in meta['rows'] if r['arm'] == name)
                fit = {k: retained[name + '_' + k] for k in ('prediction', 'states', 'driver', 'initial_state')}
                fit.update(converged=old['converged'], status=old['fit_status'],
                    objective=old['objective'], scaled_gradient_inf_norm=old['scaled_gradient'],
                    costs=old.get('costs', {}), evaluations=old.get('evaluations'))
                row['fit_source'] = 'retained_exact_target_operator_SD_match'
            else:
                starts = [dict(driver=np.zeros(len(y)), initial_state=np.r_[0., np.ones(4)])]
                if original is not None:
                    starts.insert(0, dict(driver=original['driver'], initial_state=original['initial_state']))
                s = base['solver']
                fit = fit_decay_shared_driver(observed, p, .25, mean_operator=op, sd=sd, visible=mask,
                    decay_multiplier=multiplier, forcing_modes=0,
                    penalty=s['penalty'], initial_penalty=s['initial_penalty'],
                    flow_prior_weight=s['flow_prior_weight'], flow_prior_log_sd=s['flow_prior_log_sd'],
                    max_evaluations=cfg['solver']['max_evaluations'], gradient_tolerance=s['gradient_tolerance'],
                    substeps=4, starts=starts)
                row['fit_source'] = 'new_same_budget_fit'
            row.update(converged=bool(fit['converged']), fit_status=fit['status'],
                evaluations=fit.get('evaluations'), objective=fit.get('objective'),
                scaled_gradient=fit.get('scaled_gradient_inf_norm'), costs=fit.get('costs'))
            if 'prediction' in fit:
                forward = decay_forward(fit['driver'], fit['initial_state'], p, .25,
                    decay_multiplier=multiplier, forcing_coefficients=np.empty(0), substeps=4)
                fine = decay_forward(fit['driver'], fit['initial_state'], p, .25,
                    decay_multiplier=multiplier, forcing_coefficients=np.empty(0), substeps=8)
                fine_prediction = (op @ fine['canonical_prediction'].ravel()).reshape(y.shape)
                error = float(np.max(abs((fine_prediction - fit['prediction'])[:-1] / sd)))
                score = ~mask[:, 1] if spec['condition'] == 'joint_blocked' else np.ones(len(y), bool)
                row.update(qualified=bool(fit['converged'] and error <= .005),
                    integration_max_training_sd=error,
                    waveform=filter_retest_waveform_metrics(y, fit['prediction'], sd, mask=score,
                        hb_factor=float(factor), common_sd=common_sd),
                    **decay_metrics(y, fit['prediction'], sd, spec['condition'],
                        fit['states'], np.zeros(len(y)), forward, base),
                    state_extrema={state: [float(fit['states'][:, j].min()), float(fit['states'][:, j].max())]
                        for j, state in enumerate(('r', 's', 'f', 'v', 'p', 'q'))},
                    initial_state=fit['initial_state'], driver_rms=float(np.sqrt(np.mean(fit['driver']**2))))
                for key in ('prediction', 'states', 'driver', 'initial_state'):
                    saved[name + '_' + key] = fit[key]
                if name == 'original':
                    original = fit
            else:
                row['qualified'] = False
            result['rows'].append(row)
        if spec['condition'] == 'joint_full':
            weak = weak_hb_profiles(y[:, 1:], dt=.25, return_details=False)
            grid = yaml.safe_load((CODE_ROOT / cfg['compatibility_config']).read_text())['panels']['linear']
            taus = grid['tau_grid'] if spec['length_s'] in cfg['compatibility']['linear_grid_lengths_s'] else [2.]
            kappas = grid['kappa_grid'] if len(taus) > 1 else [.64]
            scoring = np.ones_like(y, bool); scoring[-1] = False
            linear = linear_panel_profiles(y, op, sd, taus, kappas, scoring, dt=.25, parameters=p)
            nodes = [r for r in linear['profiles'] if max(r['joint_eeg_nmse'], r['joint_hbo_nmse'], r['joint_hbr_nmse']) <= .25]
            result['compatibility'] = dict(weak=weak, linear=linear,
                common_tolerance=.5, common_nodes=len(nodes), grid_nodes=len(taus)*len(kappas),
                compatible_parameters=[dict(tau=r['tau'], kappa=r['kappa']) for r in nodes],
                interpretation='no_extra_component_linear_relaxation; weak_Hb_metric_descriptive_after_processing')
        result['status'] = 'completed'
    except Exception:
        result['error'] = traceback.format_exc()
    result.update(seconds=time.monotonic() - started,
        peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024)
    path.parent.mkdir(parents=True, exist_ok=True)
    if saved:
        np.savez_compressed(path.with_suffix('.npz'), **saved)
    write_json(path, result)
    return dict(key=spec['key'], status=result['status'], seconds=result['seconds'], peak_rss_mib=result['peak_rss_mib'])


def filter_retest_run(cfg, base, root, out, plan, workers, pilot=False):
    jobs = [j for j in plan['jobs'] if (not pilot or
        (j['branch'] == 'unified_cache' and j['length_s'] == 90 and j['condition'] == 'joint_full'))]
    pending_jobs = [j for j in jobs if not (out / 'tasks' / (j['key'] + '.json')).exists()]
    if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):
        raise ValueError('Fitting requires the recorded durable user-systemd supervisor')
    start = time.monotonic(); terminal = []
    iterator = iter(pending_jobs)
    with ProcessPoolExecutor(max_workers=workers) as pool:
        active = {}
        def submit():
            try:
                spec = next(iterator)
            except StopIteration:
                return False
            active[pool.submit(filter_retest_worker, (cfg, base, str(root), str(out), spec))] = spec
            return True
        for _ in range(2 * workers):
            if not submit(): break
        while active:
            ready, _ = wait(active, return_when=FIRST_COMPLETED)
            for future in ready:
                spec = active.pop(future)
                try:
                    terminal.append(future.result())
                except Exception as exc:
                    failure = dict(spec=spec, status='failed_worker', rows=[], error=repr(exc))
                    write_json(out / 'tasks' / (spec['key'] + '.json'), failure)
                    terminal.append(dict(key=spec['key'], status='failed_worker'))
                submit()
            write_json(out / 'progress.json', dict(stage='pilot' if pilot else 'run',
                planned=len(jobs), previously_terminal=len(jobs)-len(pending_jobs),
                newly_terminal=len(terminal), running=len(active), elapsed_s=time.monotonic()-start))
    result = dict(status='completed', stage='pilot' if pilot else 'run', workers=workers,
        planned=len(jobs), newly_executed=len(terminal), elapsed_s=time.monotonic()-start,
        terminal=terminal, supervisor=os.environ['SSM_SYSTEMD_UNIT'])
    write_json(out / ('pilot.json' if pilot else 'execution.json'), result)
    return result


def filter_retest_summarize(cfg, out, plan):
    all_rows, cases, failures = [], [], []
    for spec in plan['jobs']:
        path = out / 'tasks' / (spec['key'] + '.json')
        if not path.exists():
            raise ValueError('all planned cases must be terminal before summary: ' + spec['key'])
        result = json.loads(path.read_text())
        if result['status'] != 'completed':
            failures.append(dict(key=spec['key'], status=result['status'], error=result.get('error')))
        common = dict(dataset=spec['ref']['dataset'], subject=spec['ref']['subject'],
            id=spec['ref']['id'], branch=spec['branch'], length_s=spec['length_s'], condition=spec['condition'], key=spec['key'])
        cases.append(dict(**common, status=result['status'], compatibility=result.get('compatibility')))
        for row in result['rows']:
            all_rows.append(dict(**common, **row))
    table = [{**{k:v for k,v in r.items() if not isinstance(v,(dict,list))},
              **{f"{w['component']}_{k}":v for w in r.get('waveform',[]) for k,v in w.items() if k != 'component'}}
             for r in all_rows]
    pd.DataFrame(table).to_csv(out / 'metrics.csv', index=False)
    result = dict(schema=cfg['schema'], experiment_id=cfg['experiment_id'],
        status='completed_with_failures' if failures else 'completed',
        selected_records=plan['selected'], planned_jobs=len(plan['jobs']), terminal_jobs=len(cases),
        planned_no_extra_fits=plan['planned_no_extra_fits'], returned_fits=len(all_rows),
        qualified_fits=sum(r.get('qualified',False) for r in all_rows),
        reused_fits=sum(r.get('fit_source')=='retained_exact_target_operator_SD_match' for r in all_rows),
        failures=failures, rows=all_rows, cases=cases,
        interpretation='four_selected_public_records; branch-specific_training_scales; no_population_significance_or_latent_truth',
        qualification='lower_NRMSE_does_not_override_correlation_amplitude_or_convergence')
    write_json(out / 'summary.json', result)
    return {k:v for k,v in result.items() if k not in ('rows','cases','selected_records')}


def filter_retest_verify(cfg, base, root, out, plan):
    """Independently recompute saved-array scores and observation/state closure."""
    path = out / 'verification.json'
    if path.exists():
        raise ValueError('verification evidence already exists; preserve the retained result')
    summary = json.loads((out / 'summary.json').read_text())
    maxima = dict(score=0., waveform=0., observation=0., reused_arrays=0.,
                  no_decay_drift=0., absolute_delta_increase=0., integration_training_sd=0.)
    failures, checked = [], 0
    for spec in plan['jobs']:
        task = json.loads((out / 'tasks' / (spec['key'] + '.json')).read_text())
        with np.load(out / 'tasks' / (spec['key'] + '.npz'), allow_pickle=False) as a:
            y, op, sd = (a[k] for k in ('target', 'operator', 'sd'))
            valid = np.arange(len(y)) < len(y)-1
            score = valid & ~a['visible'][:, 1] if spec['condition'] == 'joint_blocked' else valid
            expected_mask = np.ones(y.shape, bool); expected_mask[-1] = False
            if spec['condition'] == 'Hb_only_full': expected_mask[:, 0] = False
            if spec['condition'] == 'joint_blocked':
                for start in range(0, len(y), 120):
                    expected_mask[start+40:start+60, 1:] = False
                    expected_mask[start+80:start+100, 1:] = False
            if not np.array_equal(expected_mask, a['visible']): failures.append(spec['key'] + ': mask')
            for row in task['rows']:
                checked += 1
                arm = row['arm']; pred, states = a[arm+'_prediction'], a[arm+'_states']
                error = (pred-y)/sd
                for key, value in [('full_hb_nmse', np.mean(error[valid, 1:]**2)),
                                   ('score_hb_nmse', np.mean(error[score, 1:]**2))]:
                    maxima['score'] = max(maxima['score'], abs(value-row[key]))
                for j, w in enumerate(row['waveform']):
                    target, fitted = y[score, j], pred[score, j]
                    ac, bc = target-target.mean(), fitted-fitted.mean()
                    rmse = np.sqrt(np.mean((fitted-target)**2))
                    physical_factor = 1. if j == 0 else float(a['hb_factor'])
                    values = dict(nrmse=rmse/sd[j], zero_predictor_nrmse=np.sqrt(np.mean(target**2))/sd[j],
                        local_centered_nrmse=rmse/np.std(target),
                        pearson_r=(ac@bc)/np.sqrt((ac@ac)*(bc@bc)),
                        centered_amplitude_ratio=np.linalg.norm(bc)/np.linalg.norm(ac),
                        signed_gain=(ac@bc)/(ac@ac), bias_training_sd=np.mean(fitted-target)/sd[j],
                        absolute_rmse_in_cache_unit=rmse/physical_factor,
                        target_centered_rms_in_cache_unit=np.std(target)/physical_factor,
                        peak_time_difference_s=.25*(np.flatnonzero(score)[np.argmax(fitted)]-np.flatnonzero(score)[np.argmax(target)]))
                    if j: values['nrmse_common_cached_training_sd'] = rmse/physical_factor/a['common_cached_sd_physical'][j-1]
                    maxima['waveform'] = max(maxima['waveform'], *(abs(w[k]-v) for k,v in values.items()))
                fixed = volume_drive_parameters(base).fixed
                canonical = np.column_stack((fixed.eeg_loading*a[arm+'_driver']+fixed.eeg_offset,
                    fixed.P0*(states[:,4]-1)-fixed.Q0*(states[:,5]-1), fixed.Q0*(states[:,5]-1)))
                maxima['observation'] = max(maxima['observation'], float(np.max(abs((op@canonical.ravel()).reshape(y.shape)-pred))))
                delta = states[:,4]-states[:,3]
                maxima['absolute_delta_increase'] = max(maxima['absolute_delta_increase'], float(np.max(np.diff(abs(delta)))))
                if arm == 'no_decay': maxima['no_decay_drift'] = max(maxima['no_decay_drift'], float(np.ptp(delta)))
                maxima['integration_training_sd'] = max(maxima['integration_training_sd'], row['integration_max_training_sd'])
                if (np.any(states[:,2:] <= 0) or np.any(fixed.P0*states[:,4] < fixed.Q0*states[:,5])
                        or row['forcing_modes'] != 0 or row['input_present'] or not row['qualified']):
                    failures.append(spec['key'] + ':' + arm + ': domain/qualification')
                if row['fit_source'].startswith('retained_'):
                    source = root/cfg['source_run']/'measured'/f"{spec['ref']['id']}_{spec['length_s']}_{spec['condition']}.npz"
                    with np.load(source, allow_pickle=False) as old:
                        for key in ('prediction','states','driver','initial_state'):
                            maxima['reused_arrays'] = max(maxima['reused_arrays'], float(np.max(abs(a[arm+'_'+key]-old[arm+'_'+key]))))
        compatibility = task.get('compatibility')
        if compatibility:
            profiles = compatibility['linear']['profiles']
            count = sum(max(p['joint_eeg_nmse'], p['joint_hbo_nmse'], p['joint_hbr_nmse']) <= .25 for p in profiles)
            if count != compatibility['common_nodes']: failures.append(spec['key'] + ': common nodes')
    if any(value > (0.005 if key == 'integration_training_sd' else 1e-9) for key,value in maxima.items()):
        failures.append('independent numerical tolerance exceeded')
    if checked != summary['returned_fits'] or checked != plan['planned_no_extra_fits']:
        failures.append('fit denominator')
    parent = root/cfg['source_run']; original_plan = json.loads((parent/'plan.json').read_text())
    scores = {}
    for ref in original_plan['records']:
        row = next(r for r in filter_retest_source_task(parent, ref['id'], 90, 'joint_full')['rows'] if r['arm']=='original')
        if row['qualified']: scores[ref['id']] = row['full_hb_nmse']
    selected, counts = filter_retest_select(original_plan['records'], scores, cfg['selection']['datasets'])
    unchanged = [r['id'] for r in selected] == [r['id'] for r in plan['selected']]
    if not unchanged: failures.append('corrected owning selection changes selected identities')
    audit = dict(source=str(parent/'evidence_v2'), selected_identities_unchanged=unchanged,
        corrected_selection_denominators=counts,
        corrected_medians={r['dataset']: r['selection_median'] for r in selected},
        correction='initial plan used pre-migration task qualification; corrected evidence restores one Simultaneous original fit; selected records and all fit arrays unchanged',
        retained_plan='plan.json is preserved as executed; use this audit for corrected selection denominators')
    result = dict(status='passed' if not failures else 'failed', fits_checked=checked, maxima=maxima,
        failures=failures, selection_audit=audit, raw_source_reads=0, refits=0,
        integration_check='retained 4/8-substep comparison; other maxima independently recomputed from saved arrays',
        verification_source='verification_source.py')
    write_json(path, result)
    shutil.copy2(Path(__file__), out/'verification_source.py')
    if failures: raise ValueError(f'verification failed: {failures}')
    return result


def filter_retest_main(args):
    cfg, base = filter_retest_config(args.config)
    root, out = args.project_root.resolve(), args.run_dir.resolve()
    if not out.is_relative_to(root / cfg['artifact_root']) or out == root / cfg['artifact_root']:
        raise ValueError('fresh versioned owning run directory required')
    out.mkdir(parents=True, exist_ok=True)
    path = out / 'resolved_config.json'
    if path.exists() and json.loads(path.read_text()) != cfg:
        raise ValueError('resolved retest contract is immutable')
    write_json(path, cfg)
    stage = args.filter_stage
    if stage == 'check':
        y, op, sd, truth = decay_synthetic(base, 0, 'matched', 30)
        assert y.shape == (120,3) and op.shape == (360,360) and np.isfinite(y).all()
        metrics = filter_retest_waveform_metrics(y, y, sd)
        assert max(r['nrmse'] for r in metrics) == 0.
        result = dict(status='passed', synthetic_shape=list(y.shape), forcing_modes=0,
            no_extra_arms=cfg['arms'], measured_arrays_read=0)
        write_json(out / 'software_checks.json', result)
    elif stage == 'plan':
        result = filter_retest_plan(cfg, base, root, out)
    else:
        plan = json.loads((out / 'plan.json').read_text())
        if stage == 'prepare':
            result = filter_retest_prepare(cfg, base, root, out, plan)
        elif stage in ('pilot', 'run'):
            if not 1 <= args.workers <= cfg['resources']['max_workers']:
                raise ValueError('workers outside resource envelope')
            result = filter_retest_run(cfg, base, root, out, plan, args.workers, pilot=stage=='pilot')
        elif stage == 'verify':
            result = filter_retest_verify(cfg, base, root, out, plan)
        else:
            result = filter_retest_summarize(cfg, out, plan)
    print(json.dumps(serial({k:v for k,v in result.items() if k not in ('jobs','coordinates','selected','terminal')})), flush=True)


def tak_config(path):
    path = Path(path)
    cfg = json.loads(path.read_text()) if path.suffix.lower()=='.json' else yaml.safe_load(path.read_text())
    current = cfg.get('schema') == 'shared_driver_tak_10hz_v2'
    dt = .1 if current else .25
    if (cfg.get('schema') not in ('shared_driver_tak_v1','shared_driver_tak_10hz_v2') or cfg['data']['protected_data'] != 'forbidden'
            or (cfg['data']['raw_reads'] != 'registered_EEG_only' if current else cfg['data']['raw_reads'] is not False)
            or cfg['data']['fnirs_input'] != 'unified_cached_fnirs_v1'
            or cfg['data']['expected_records'] != 48
            or cfg['data']['datasets'] != ['eeg_fnirs_single_trial','simultaneous_eeg_nirs','visual_cognitive_motivation','refed']
            or cfg['tensor']['lengths_s'] != [30,90] or cfg['tensor']['dt_s'] != dt
            or cfg['tensor']['reference_steps'] != round(5/dt) or cfg['synthetic']['dt_s'] != dt
            or cfg['conditions'] != ['joint_full','Hb_only_full','joint_blocked']):
        raise ValueError('Tak public cached-input contract mismatch')
    if current:
        from src.data.ssm_prepared import EEG_PROXY_INPUT_SCHEMA
        if (cfg['tensor'].get('eeg_proxy_input') != EEG_PROXY_INPUT_SCHEMA
                or cfg['tensor'].get('eeg_proxy_rate_hz') != 10.
                or cfg['tensor'].get('eeg_bands_hz') != [[1,4],[4,8],[8,13],[13,30],[30,45]]
                or cfg['solver'].get('observation_reference_dt_s') != .25
                or cfg['solver'].get('data_weight') != 'dt_over_reference_dt_standardized_SSE_preserve_per_second_weight'):
            raise ValueError('Tak 10 Hz EEG proxy or time-weight contract mismatch')
    expected = ['legacy_free','legacy_tied','tak_fixed','tak_rest','legacy_free_fit','legacy_tied_fit','tak_fit','tak_spm_prior']
    if [a['name'] for a in cfg['arms']] != expected or cfg['model']['primary'] != 'tak_fit':
        raise ValueError('Tak paired arm contract mismatch')
    for arm in cfg['arms']:
        if arm['hemodynamics'] == 'tak' and arm['initial'] not in ('volume_tied','rest'):
            raise ValueError('Tak requires elimination of independent p')
        if len(arm.get('log_sd', [])) != len(arm['fit']):
            raise ValueError('one prior SD required per fitted parameter')
    if (cfg['solver']['substeps'] != 4 or cfg['solver']['validation_substeps'] != 8
            or cfg['solver']['initial_weights_tied'] != [1,1,1,0,1]
            or cfg['resources']['numerical_threads'] != 1):
        raise ValueError('Tak integration or matched initial-prior contract mismatch')
    return cfg


def tak_plan(cfg, root):
    plan = volume_drive_plan(cfg, root)
    if len(plan['records']) != cfg['data']['expected_records']:
        raise ValueError('Tak evaluation record denominator mismatch')
    groups = {}
    for ref in plan['records']:
        # In concatenated native exports, the admitted continuous session
        # support is part of the key. Never pool different session supports.
        key = (ref['join_key'], ref['anchor']['hb_channel'], ref.get('native_session'),
               json.dumps(ref.get('alignment_support'), sort_keys=True))
        groups.setdefault(key, []).append(ref)
    plan['groups'] = []
    for i, (key, refs) in enumerate(sorted(groups.items(), key=lambda item: str(item[0]))):
        refs = sorted(refs, key=lambda r: r['hb_start_s'])
        if any(a['hb_start_s']+90 > b['hb_start_s']+1e-8 for a,b in zip(refs, refs[1:])):
            raise ValueError('overlapping records cannot multiply shared-parameter evidence')
        plan['groups'].append(dict(id=f'g{i:03d}', sharing_identity=key, refs=refs))
    plan.update(schema='shared_driver_tak_plan_v1', selection='all_exact_parent_public_evaluation_records',
        independent_subjects={ds: len({r['subject'] for r in plan['records'] if r['dataset']==ds})
            for ds in cfg['data']['datasets']})
    if cfg['schema']=='shared_driver_tak_10hz_v2':
        plan.update(schema='shared_driver_tak_plan_v2',dt_s=cfg['tensor']['dt_s'],eeg_proxy_rate_hz=10.)
    return plan


def tak_prepare(cfg, root, out, plan):
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.unified_physiology import load_cached_fnirs_record, load_native_eeg_record
    from src.data.ssm_prepared import fit_feature_coordinate, EEG_PROXY_INPUT_SCHEMA
    from src.inference.observation_baselines import disjoint_native_bin_operator, eeg_band_power
    if serial(plan) != serial(tak_plan(cfg, root)):
        raise ValueError('Tak plan no longer matches the admitted public metadata')
    if json.loads((out/'software_checks.json').read_text())['status'] != 'passed':
        raise ValueError('Tak software checks required before cache access')
    if json.loads((out/'synthetic_summary.json').read_text())['status'] != 'completed':
        raise ValueError('completed synthetic experiment required before measured preparation')
    lookup = {r.join_key: r for r in CleanPhysiologyCacheIndex(root/cfg['data']['cache_root']).records}
    current = cfg['schema']=='shared_driver_tak_10hz_v2'
    dt = cfg['tensor']['dt_s'];steps=round(90/dt);reference_steps=cfg['tensor']['reference_steps']
    native_eeg_reads=0
    coordinates, failures, prepared = {}, [], []
    for relative in cfg['parents']:
        parent = root/relative
        pp = json.loads((parent/'plan.json').read_text())
        for coordinate in sorted({r['coordinate'] for r in pp['records']}):
            dev = [r for r in pp['records'] if r['coordinate']==coordinate and r['partition']=='development']
            evaluation = [r for r in plan['records'] if r['coordinate']==coordinate and r['parent']==relative]
            if {r['subject'] for r in dev} & {r['subject'] for r in evaluation}:
                raise ValueError('calibration/evaluation subject overlap')
            raw, provenance, good = {}, {}, []
            for ref in dev+evaluation:
                try:
                    if ref['dataset'] not in cfg['data']['datasets'] or Path(ref['id']).name != ref['id']:
                        raise ValueError('unregistered public identity')
                    record=lookup[ref['join_key']]
                    eeg_provenance=None
                    if current:
                        native=load_native_eeg_record(root,record);native_eeg_reads+=1
                        channels={str(name).upper():i for i,name in enumerate(native.channel_names)}
                        selected=[channels[name.upper()] for name in ref['anchor']['eeg_channels']]
                        start=round(ref['eeg_start_s']*native.sample_rate_hz);length=round(90*native.sample_rate_hz)
                        values=native.values[start:start+length,selected]
                        if start<0 or values.shape!=(length,6) or not np.isfinite(values).all():
                            raise ValueError('complete registered EEG support required for 10 Hz proxy')
                        power=eeg_band_power(values,bands=cfg['tensor']['eeg_bands_hz'],
                            sample_rate=native.sample_rate_hz,target_rate=cfg['tensor']['eeg_proxy_rate_hz'])
                        if power.shape!=(steps,6,5) or not np.isfinite(power).all() or np.any(power<=0):
                            raise ValueError('invalid native 10 Hz bandpower tensor')
                        eeg_op=np.eye(steps);eeg_op[:,:reference_steps]-=1/reference_steps
                        eeg=eeg_op@np.log(power).reshape(steps,30)
                        eeg_provenance=dict(schema=EEG_PROXY_INPUT_SCHEMA,source=str(native.source_path),
                            source_rate_hz=native.sample_rate_hz,source_unit=native.native_unit,
                            proxy_rate_hz=10.,bin_seconds=dt,channels=ref['anchor']['eeg_channels'],
                            bands_hz=cfg['tensor']['eeg_bands_hz'],native_start_sample=start,native_samples=length,
                            start_rounding_s=start/native.sample_rate_hz-ref['eeg_start_s'],
                            estimator=cfg['tensor']['eeg_power'],timestamps=cfg['tensor']['timestamps'])
                    else:
                        meta = json.loads((parent/'tasks'/'prepare'/(ref['id']+'.json')).read_text())
                        if meta['status'] != 'completed': raise ValueError('parent EEG preparation failed')
                        with np.load(parent/'prepared'/(ref['id']+'.npz'), allow_pickle=False) as a:
                            eeg, eeg_op = a['eeg'].copy(), a['eeg_operator'].copy()
                        if eeg.shape != (steps,30) or eeg_op.shape != (steps,steps):
                            raise ValueError('parent EEG shape mismatch')
                    cached = load_cached_fnirs_record(root, record)
                    pair = int(ref['anchor']['hb_pair'])
                    if cached['channel_names'][2*pair] != ref['anchor']['hb_channel']+'_HbO':
                        raise ValueError('cached Hb channel identity mismatch')
                    take = (cached['time_s']>=ref['hb_start_s']) & (cached['time_s']<ref['hb_start_s']+90)
                    times = cached['time_s'][take]-ref['hb_start_s']
                    hb = cached['values'][take,pair]
                    if not np.isfinite(hb).all(): raise ValueError('unsupported cached Hb samples')
                    op = disjoint_native_bin_operator(times,steps=steps,dt=dt,reference_steps=reference_steps)
                    hb = op['raw']@hb
                    if hb.shape != (steps,2): raise ValueError('cached Hb shape mismatch')
                    raw[ref['id']] = dict(eeg=eeg, hb=hb, eeg_op=eeg_op, hb_op=op['model'])
                    provenance[ref['id']] = dict(hb=cached['provenance'],eeg=eeg_provenance) if current else cached['provenance']
                    if ref in dev: good.append(ref)
                except (ValueError,KeyError,FileNotFoundError) as exc:
                    failures.append(dict(id=ref['id'], coordinate=coordinate, partition=ref['partition'], reason=str(exc)))
            co = fit_feature_coordinate([(raw[r['id']]['eeg'],raw[r['id']]['hb']) for r in good])
            co.update(training_ids=[r['id'] for r in good], training_subjects=sorted({r['subject'] for r in good}),
                planned_training_records=len(dev), successful_training_records=len(good),
                fnirs_input='unified_cached_fnirs_v1')
            if current:co.update(eeg_proxy_input=EEG_PROXY_INPUT_SCHEMA,eeg_proxy_rate_hz=10.,dt_s=dt)
            coordinates[coordinate] = co
            for ref in evaluation:
                if ref['id'] not in raw: continue
                a = raw[ref['id']]
                y = np.column_stack((a['eeg']@np.asarray(co['pc'])*co['eeg_factor'],a['hb']*co['hb_factor']))
                for length in cfg['tensor']['lengths_s']:
                    target, operator = volume_drive_crop(y,dict(eeg=a['eeg_op'],hb=a['hb_op']),length,dt=dt)
                    path = out/'prepared'/f"{ref['id']}__{length}.npz"
                    path.parent.mkdir(parents=True,exist_ok=True)
                    extra=dict(eeg_proxy_input=np.array(EEG_PROXY_INPUT_SCHEMA),eeg_proxy_rate_hz=np.array(10.),
                        time_s=np.arange(len(target))*dt) if current else {}
                    np.savez_compressed(path,target=target,operator=operator,sd=np.asarray(co['sd']),
                        hb_factor=np.array(co['hb_factor']),fnirs_input=np.array('unified_cached_fnirs_v1'),**extra)
                write_json(out/'prepared'/(ref['id']+'.json'),dict(status='completed',ref=ref,
                    cache_provenance=provenance[ref['id']],calibration_coordinate=coordinate,
                    source='native_10Hz_EEG_proxy_and_cached_Hb' if current else 'new_cached_Hb_and_retained_EEG_no_raw_Hb_reads'))
                prepared.append(ref['id'])
    result = dict(status='completed', planned_records=len(plan['records']), prepared_records=len(prepared),
        prepared_ids=prepared,coordinates=coordinates,failures=failures,raw_reads=native_eeg_reads,protected_reads=0)
    if current:result.update(native_eeg_reads=native_eeg_reads,raw_fnirs_reads=0,eeg_proxy_rate_hz=10.,dt_s=dt)
    write_json(out/'preparation.json',result)
    return result


def tak_synthetic(cfg, seed, scenario):
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    dt=cfg['tensor']['dt_s'];reference_steps=cfg['tensor']['reference_steps']
    n = round(cfg['synthetic']['length_s']/dt)
    t = np.arange(n)*dt
    driver = .04*np.sin(2*np.pi*t/17)+.018*np.cos(2*np.pi*t/7)
    driver *= 1+.12*seed
    initial = (np.array([.02,1.04,1.025,1.025,.99]) if scenario=='tak_nonrest' else
               np.array([.02,1.04,1.025,1.105,.99]) if scenario=='legacy_unbound' else np.r_[0.,np.ones(4)])
    p = volume_drive_parameters(cfg,kappa=.55+.08*seed,tau=1.5+.5*seed)
    hemo = 'inlet_balance' if scenario=='legacy_unbound' else 'tak'
    truth = nonlinear_driver_forward(driver,initial,p,dt,substeps=cfg['synthetic']['generation_substeps'],
        derivative=False,numerical_backend='numba',hemodynamics=hemo,viscoelastic_s=0. if hemo=='inlet_balance' else 2.)
    ref = np.eye(n);ref[:,:reference_steps]-=1/reference_steps
    operator = np.kron(ref,np.eye(3))
    clean = (operator@truth['canonical_prediction'].ravel()).reshape(n,3)
    noise = np.random.default_rng(cfg['seed']+seed).normal(size=(n,3))*cfg['synthetic']['noise_sd']
    target = clean+ref@noise
    truth.update(driver=driver,initial_state=initial,kappa=p.free.kappa,tau=p.free.tau,clean=clean)
    return target,operator,np.array(cfg['synthetic']['training_sd']),truth


def tak_specs(cfg, plan, phase):
    arms = cfg['arms']
    if phase=='sensitivity':
        base = next(a for a in arms if a['name']==cfg['sensitivity']['base_arm'])
        arms = [dict(base,**v,warm='tak_fit') for v in cfg['sensitivity']['variants']]
    jobs = []
    if phase=='synthetic':
        groups = [dict(id=f'seed{s}_{scenario}',seed=s,scenario=scenario,refs=[dict(
            id=f'seed{s}_{scenario}',dataset='synthetic',subject=f'seed{s}',record=scenario)])
            for s in cfg['synthetic']['seeds'] for scenario in cfg['synthetic']['scenarios']]
        lengths,conditions = [cfg['synthetic']['length_s']],['joint_full']
    else:
        groups = plan['groups']
        lengths = [90] if phase=='sensitivity' else cfg['tensor']['lengths_s']
        conditions = ['joint_full'] if phase=='sensitivity' else cfg['conditions']
    for g in groups:
        for length in lengths:
            for condition in conditions:
                for arm in arms:
                    key = f"{phase}__{g['id']}__{length}__{condition}__{arm['name']}"
                    jobs.append(dict(key=key,phase=phase,group=g,length_s=length,condition=condition,arm=arm))
    return jobs


def tak_fit_group(cfg, arm, y, operator, sd, mask, warm=None, *,
                  observation_reference_steps=None, linear_solver=None, starts_override=None):
    from src.inference.shared_driver_reconstruction import fit_nonlinear_shared_parameters
    names = arm['fit'];s=cfg['solver'];f=cfg['fitting'];batch,n,_=y.shape
    dt=cfg['tensor']['dt_s'];data_weight=dt/s.get('observation_reference_dt_s',dt)
    starts = []
    references = np.array([f['reference'][name] for name in names])
    values = ([references] if not names else [np.array(v,float) for v in arm['start_values']]
        if 'start_values' in arm else [np.array(kt if len(names)==2 else kt+gv)
        for kt,gv in zip(f['starts_kappa_tau'],f['starts_gamma_tau_v'])])
    if any(v.shape!=(len(names),) for v in values):raise ValueError('One start value per named fitted parameter required')
    for v in values:
        start = dict(parameter_values=v)
        if warm is not None:
            start.update(driver=warm['driver'],initial_state=warm['initial_state'])
        starts.append(start)
    if starts_override is not None:
        if not starts_override:raise ValueError('At least one explicit start required')
        starts=deepcopy(starts_override)
    weights = s['initial_weights_free'] if arm['initial']=='free' else s['initial_weights_tied']
    kwargs = dict(parameter_names=names,parameter_bounds=[f['bounds'][name] for name in names],
        sd=sd,mean_operator=operator,visible=mask,starts=starts,penalty=s['penalty'],
        initial_penalty=arm.get('initial_penalty',s['initial_penalty']),initial_coordinate_weights=weights,
        flow_prior_weight=s['flow_prior_weight'],flow_prior_log_sd=s['flow_prior_log_sd'],
        substeps=s['substeps'],max_iterations=s['max_iterations'],
        max_evaluations_per_trial=s['max_evaluations_per_trial'],gradient_tolerance=s['gradient_tolerance'],
        numerical_backend='numba',hemodynamics=arm['hemodynamics'],viscoelastic_s=arm['tau_v'],
        initial_state_mode=arm['initial'],data_weight=data_weight,
        observation_reference_steps=observation_reference_steps,linear_solver=linear_solver)
    if names:
        kwargs.update(parameter_prior_log_mean=np.log(references),
                      parameter_prior_precision=1/np.square(arm['log_sd']))
    return fit_nonlinear_shared_parameters(np.where(mask,y,np.nan),volume_drive_parameters(cfg),dt,**kwargs)


def tak_worker(payload):
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    from src.data.ssm_prepared import require_cached_hb_array, require_10hz_eeg_proxy_array
    cfg,out_string,spec = payload;out=Path(out_string)
    start=time.monotonic();arm=spec['arm'];refs=spec['group']['refs'];dt=cfg['tensor']['dt_s']
    result=dict(spec=spec,status='failed',rows=[]);saved={}
    try:
        truth=None;factors=[]
        if spec['phase']=='synthetic':
            yy,oo,ss,truth=(tak_task_parameter_synthetic(cfg,spec['group']['case'])
                if cfg['schema'] in ('shared_driver_tak_task_parameters_v1','shared_driver_tak_topography_v1')
                else tak_synthetic(cfg,spec['group']['seed'],spec['group']['scenario']))
            y,op,sd=yy[None],oo[None],ss[None];factors=[1.]
        else:
            ys,ops,sds=[],[],[]
            for ref in refs:
                with np.load(out/'prepared'/f"{ref['id']}__{spec['length_s']}.npz",allow_pickle=False) as a:
                    require_cached_hb_array(a)
                    if cfg['schema'] in ('shared_driver_tak_10hz_v2','shared_driver_tak_repeatability_v1','shared_driver_tak_task_parameters_v1','shared_driver_tak_topography_v1'):
                        require_10hz_eeg_proxy_array(a,steps=round(spec['length_s']/dt))
                    ys.append(a['target']);ops.append(a['operator']);sds.append(a['sd']);factors.append(float(a['hb_factor']))
            y,op,sd=np.array(ys),np.array(ops),np.array(sds)
        mask=np.array([volume_drive_mask(len(yi),spec['condition'],dt=dt) for yi in y])
        warm=None
        if 'warm' in arm:
            phase='measured' if spec['phase']=='sensitivity' else spec['phase']
            key=f"{phase}__{spec['group']['id']}__{spec['length_s']}__{spec['condition']}__{arm['warm']}"
            warm_path=out/'tasks'/(key+'.npz')
            if warm_path.exists():
                with np.load(warm_path,allow_pickle=False) as a:
                    if 'driver' in a and 'initial_state' in a:
                        warm=dict(driver=a['driver'],initial_state=a['initial_state'])
        fit=tak_fit_group(cfg,arm,y,op,sd,mask,warm)
        # A failed warm fit may still supply a feasible start. If it produced no
        # trajectory the explicit rest start above is used; no rows disappear.
        result.update(status='completed',fit={k:v for k,v in fit.items() if k not in
            ('driver','initial_state','prediction','canonical_prediction','states')})
        if 'prediction' in fit:
            saved.update({k:fit[k] for k in ('driver','initial_state','prediction','canonical_prediction','states')})
        saved.update(target=y,operator=op,sd=sd,visible=mask,hb_factor=np.array(factors))
        if cfg['schema'] in ('shared_driver_tak_10hz_v2','shared_driver_tak_repeatability_v1','shared_driver_tak_task_parameters_v1','shared_driver_tak_topography_v1'):
            saved.update(time_s=np.arange(y.shape[1])*dt,dt_s=np.array(dt),eeg_proxy_rate_hz=np.array(10.))
        for i,ref in enumerate(refs):
            row=dict(id=ref['id'],dataset=ref['dataset'],subject=ref['subject'],record=ref['record'],
                group=spec['group']['id'],group_size=len(refs),length_s=spec['length_s'],condition=spec['condition'],
                phase=spec['phase'],arm=arm['name'],qualified=False,fit_status=fit['status'],
                converged=fit['converged'],parameter_names=fit['parameter_names'],parameter_values=fit['parameter_values'],
                objective=fit.get('objective'),objective_components=fit.get('objective_components'),
                scaled_gradient=fit.get('projected_scaled_gradient_inf_norm'),evaluations=fit.get('evaluations'))
            score=~mask[i,:,1] if spec['condition']=='joint_blocked' else np.ones(len(y[i]),bool)
            row['zero_baseline']=volume_drive_metrics(y[i],np.zeros_like(y[i]),sd[i],spec['condition'],dt=dt)
            if spec['condition']=='joint_blocked':
                baseline=y[i].copy()
                for j in (1,2):
                    visible=mask[i,:,j];time_axis=np.arange(len(y[i]))
                    baseline[:,j]=np.interp(time_axis,time_axis[visible],y[i,visible,j])
                row['interpolation_baseline']=volume_drive_metrics(y[i],baseline,sd[i],spec['condition'],dt=dt)
            if 'prediction' in fit:
                pp=volume_drive_parameters(cfg,kappa=fit['kappa'],tau=fit['tau'],gamma=fit['gamma'],
                                           neurovascular_gain=fit['neurovascular_gain'])
                fine=nonlinear_driver_forward(fit['driver'][i],fit['initial_state'][i],pp,dt,
                    substeps=8,derivative=False,numerical_backend='numba',hemodynamics=arm['hemodynamics'],
                    viscoelastic_s=fit['viscoelastic_s'])
                pred=(op[i]@fine['canonical_prediction'].ravel()).reshape(y[i].shape)
                err=float(np.max(abs((pred-fit['prediction'][i])[:-1]/sd[i])))
                states=fit['states'][i]
                pv=float(np.max(abs(states[:,4]-states[:,3])))
                row.update(qualified=bool(fit['converged'] and err<=.005 and (arm['hemodynamics']!='tak' or pv==0)),
                    integration_max_training_sd=err,p_minus_v_max=pv,
                    waveform=filter_retest_waveform_metrics(y[i],fit['prediction'][i],sd[i],mask=score,hb_factor=factors[i],dt=dt),
                    **volume_drive_metrics(y[i],fit['prediction'][i],sd[i],spec['condition'],dt=dt),
                    initial_state=fit['initial_state'][i],driver_rms=float(np.sqrt(np.mean(fit['driver'][i]**2))),
                    state_extrema={name:[float(states[:,j].min()),float(states[:,j].max())]
                        for j,name in enumerate(('r','s','f','v','p','q'))},
                    kappa=fit['kappa'],tau=fit['tau'],beta=fit['neurovascular_gain'],gamma=fit['gamma'],tau_v=fit['viscoelastic_s'])
                if truth is not None:
                    if 'beta' in truth:row.update(truth_beta=truth['beta'],beta_relative_error=fit['neurovascular_gain']/truth['beta']-1)
                    row.update(truth_kappa=truth['kappa'],truth_tau=truth['tau'],
                        kappa_relative_error=(fit['kappa']/truth['kappa']-1),tau_relative_error=(fit['tau']/truth['tau']-1),
                        driver_relative_rmse=float(np.sqrt(np.mean((fit['driver'][i]-truth['driver'])**2)/np.mean(truth['driver']**2))),
                        state_rmse=np.sqrt(np.mean((states-truth['states'])**2,axis=0)))
                    saved.update(truth_states=truth['states'],truth_driver=truth['driver'],truth_clean=truth['clean'])
            result['rows'].append(row)
    except Exception:
        result['error']=traceback.format_exc()
        known={r['id'] for r in result['rows']}
        for ref in refs:
            if ref['id'] not in known:
                result['rows'].append(dict(id=ref['id'],dataset=ref['dataset'],subject=ref['subject'],
                    record=ref['record'],group=spec['group']['id'],length_s=spec['length_s'],
                    condition=spec['condition'],phase=spec['phase'],arm=arm['name'],qualified=False,
                    converged=False,fit_status='task_exception'))
    result.update(seconds=time.monotonic()-start,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    path=out/'tasks'/(spec['key']+'.json');path.parent.mkdir(parents=True,exist_ok=True)
    if saved:np.savez_compressed(path.with_suffix('.npz'),**saved)
    write_json(path,result)
    return dict(key=spec['key'],status=result['status'],seconds=result['seconds'],peak_rss_mib=result['peak_rss_mib'],
        qualified=sum(r['qualified'] for r in result['rows']),rows=len(result['rows']))


def tak_run(cfg,out,plan,phase,workers,pilot=False,*,specs=None,pilot_groups=None):
    if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):
        raise ValueError('Tak fitting requires the recorded durable user-systemd supervisor')
    jobs=tak_specs(cfg,plan,phase) if specs is None else specs
    if pilot:
        if pilot_groups is None:
            selected={}
            for g in plan['groups']:selected.setdefault(g['refs'][0]['dataset'],g['id'])
            pilot_groups=set(selected.values())
        jobs=[j for j in jobs if j['group']['id'] in pilot_groups and j['length_s']==90 and j['condition']=='joint_full']
    t=time.monotonic();terminal=[]
    # Warm-start dependencies are explicit phases, with all fixed fits complete
    # before parameter fitting. Each task is resumable and retains failed rows.
    for fitted in (False,True):
        pending=[j for j in jobs if bool(j['arm']['fit'])==fitted and not (out/'tasks'/(j['key']+'.json')).exists()]
        iterator=iter(pending)
        with ProcessPoolExecutor(max_workers=workers) as pool:
            active={}
            def submit():
                try:job=next(iterator)
                except StopIteration:return False
                active[pool.submit(tak_worker,(cfg,str(out),job))]=job
                return True
            for _ in range(workers*2):
                if not submit():break
            while active:
                ready,_=wait(active,return_when=FIRST_COMPLETED)
                for future in ready:
                    spec=active.pop(future)
                    try:terminal.append(future.result())
                    except Exception as exc:
                        failed=dict(spec=spec,status='failed_worker',error=repr(exc),rows=[dict(
                            id=r['id'],dataset=r['dataset'],subject=r['subject'],record=r['record'],group=spec['group']['id'],
                            length_s=spec['length_s'],condition=spec['condition'],phase=phase,arm=spec['arm']['name'],
                            qualified=False,converged=False,fit_status='failed_worker') for r in spec['group']['refs']])
                        write_json(out/'tasks'/(spec['key']+'.json'),failed)
                        terminal.append(dict(key=spec['key'],status='failed_worker'))
                    submit()
                write_json(out/'progress.json',dict(phase=phase,pilot=pilot,planned=len(jobs),newly_terminal=len(terminal),
                    terminal=sum((out/'tasks'/(j['key']+'.json')).exists() for j in jobs),
                    in_flight=len(active),elapsed_s=time.monotonic()-t,supervisor=os.environ['SSM_SYSTEMD_UNIT']))
    result=dict(status='completed',phase=phase,pilot=pilot,planned=len(jobs),newly_executed=len(terminal),
        workers=workers,seconds=time.monotonic()-t,terminal=terminal,supervisor=os.environ['SSM_SYSTEMD_UNIT'])
    write_json(out/(('pilot' if pilot else phase)+'_execution.json'),result)
    return result


def tak_summarize(cfg,out,plan,phase='measured',*,specs=None):
    jobs=tak_specs(cfg,plan,phase) if specs is None else specs;rows=[];missing=[]
    for spec in jobs:
        p=out/'tasks'/(spec['key']+'.json')
        if not p.exists():missing.append(spec['key']);continue
        rows.extend(json.loads(p.read_text())['rows'])
    groups=[];contrasts=[]
    frame=pd.DataFrame(rows)
    if len(frame):
        for key,g in frame.groupby(['dataset','length_s','condition','arm'],sort=True):
            good=g[g.qualified];entry=dict(zip(['dataset','length_s','condition','arm'],key))
            entry.update(planned=len(g),qualified=len(good),subjects=g.subject.nunique(),
                qualified_subjects=good.subject.nunique(),failures=dict(g[~g.qualified].fit_status.value_counts()))
            for metric in ('score_hb_nmse','full_hb_nmse','eeg_nmse','full_hbo_nmse','full_hbr_nmse'):
                if metric in good and len(good):entry[metric.replace('nmse','nrmse')]=float(np.sqrt(good.groupby('subject')[metric].mean().mean()))
            if len(good):
                entry['integration_max_training_sd']=float(good.integration_max_training_sd.max())
                for name in ('kappa','tau','gamma','tau_v','driver_rms'):
                    entry[name+'_median']=float(good[name].median())
            groups.append(entry)
        pairs=cfg['endpoints']['contrasts']+([['legacy_free','tak_fit']] if specs is None else []) if phase!='sensitivity' else []
        for key,g in frame.groupby(['dataset','length_s','condition']):
            for reference,candidate in pairs:
                a=g[(g.arm==reference)&g.qualified];b=g[(g.arm==candidate)&g.qualified]
                if 'score_hb_nmse' not in g:continue
                pair=a[['id','subject','score_hb_nmse']].merge(b[['id','score_hb_nmse']],on='id',suffixes=('_reference','_candidate'))
                item=dict(zip(['dataset','length_s','condition'],key),reference=reference,candidate=candidate,
                    planned_records=len(g[g.arm==reference]),paired_records=len(pair),paired_subjects=pair.subject.nunique())
                if len(pair):
                    means=pair.groupby('subject')[['score_hb_nmse_reference','score_hb_nmse_candidate']].mean().to_numpy()
                    difference=np.sqrt(means[:,0].mean())-np.sqrt(means[:,1].mean())
                    rng=np.random.default_rng(cfg['seed']);ix=rng.integers(0,len(means),(2000,len(means)))
                    boot=np.sqrt(means[ix,0].mean(1))-np.sqrt(means[ix,1].mean(1))
                    item.update(reference_nrmse=float(np.sqrt(means[:,0].mean())),candidate_nrmse=float(np.sqrt(means[:,1].mean())),
                        improvement=float(difference),ci95=np.quantile(boot,[.025,.975]),interval='exploratory_whole_subject_percentile_no_multiplicity_adjustment')
                contrasts.append(item)
    result=dict(schema='shared_driver_tak_summary_v1',status='completed' if not missing else 'incomplete',phase=phase,
        planned_tasks=len(jobs),terminal_tasks=len(jobs)-len(missing),missing=missing,
        planned_rows=sum(len(j['group']['refs']) for j in jobs),terminal_rows=len(rows),
        qualified_rows=sum(r['qualified'] for r in rows),groups=groups,paired_contrasts=contrasts,
        claim_limits=cfg['claim_limits'],source='tasks/*.json_and_matching_npz',
        aggregation=cfg['endpoints']['aggregation'],failure_policy=cfg['endpoints']['failures'])
    if cfg['schema'] in ('shared_driver_tak_10hz_v2','shared_driver_tak_repeatability_v1','shared_driver_tak_task_parameters_v1','shared_driver_tak_topography_v1'):
        result.update(schema='shared_driver_tak_summary_v2',dt_s=cfg['tensor']['dt_s'],eeg_proxy_rate_hz=10.)
    write_json(out/(phase+'_summary.json'),result)
    write_json(out/(phase+'_rows.json'),rows)
    return result


def tak_verify_arrays(cfg,out,plan):
    """Independently recompute scores, objectives and observation closure."""
    maxima=dict(score=0.,observation=0.,objective_relative=0.,waveform=0.,physical_domain_violation=0.)
    checked=0;failed_tasks=0;problems=[];dt=cfg['tensor']['dt_s']
    data_weight=dt/cfg['solver'].get('observation_reference_dt_s',dt)
    for phase in ('synthetic','measured','sensitivity'):
        for spec in tak_specs(cfg,plan,phase):
            path=out/'tasks'/(spec['key']+'.json');meta=json.loads(path.read_text())
            if meta['status']!='completed':
                failed_tasks+=1;continue
            with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
                if 'prediction' not in a:
                    failed_tasks+=1;continue
                y,pred,states,driver,initial,sd,mask,ops=(a[k] for k in ('target','prediction','states','driver','initial_state','sd','visible','operator'))
            arm=spec['arm'];fit=meta['fit'];s=cfg['solver'];costs=dict(data=0.,driver=0.,initial=0.,flow=0.,parameter_prior=0.)
            weights=np.array(s['initial_weights_free'] if arm['initial']=='free' else s['initial_weights_tied'])
            for i,row in enumerate(meta['rows']):
                n=len(y[i]);valid=np.ones(n,bool);valid[-1]=False
                expected_mask=volume_drive_mask(n,spec['condition'],dt=dt)
                if not np.array_equal(mask[i],expected_mask):problems.append(spec['key']+'_mask')
                score=valid&~mask[i,:,1] if spec['condition']=='joint_blocked' else valid
                e=(pred[i]-y[i])/sd[i]
                for key,val in [('score_hb_nmse',np.mean(e[score,1:]**2)),('full_hb_nmse',np.mean(e[valid,1:]**2)),
                    ('eeg_nmse',np.mean(e[valid,0]**2)),('full_hbo_nmse',np.mean(e[valid,1]**2)),('full_hbr_nmse',np.mean(e[valid,2]**2))]:
                    maxima['score']=max(maxima['score'],float(abs(val-row[key])))
                canonical=np.column_stack((driver[i],cfg['parameters']['P0']*(states[i,:,4]-1)-cfg['parameters']['Q0']*(states[i,:,5]-1),
                    cfg['parameters']['Q0']*(states[i,:,5]-1)))
                closed=(ops[i]@canonical.ravel()).reshape(pred[i].shape)
                maxima['observation']=max(maxima['observation'],float(np.max(abs(closed-pred[i]))))
                if not np.isfinite(states[i]).all() or np.any(states[i,:,2:]<=0) or np.any(cfg['parameters']['Q0']*states[i,:,5]>cfg['parameters']['P0']*states[i,:,4]):
                    problems.append(spec['key']+'_physical_domain')
                if arm['hemodynamics']=='tak' and not np.array_equal(states[i,:,3],states[i,:,4]):problems.append(spec['key']+'_p_v')
                if arm['initial']=='rest' and not np.array_equal(initial[i],np.r_[0.,np.ones(4)]):problems.append(spec['key']+'_rest')
                for c,w in enumerate(row['waveform']):
                    aa,bb=y[i,score,c],pred[i,score,c];ac,bc=aa-aa.mean(),bb-bb.mean()
                    values=dict(nrmse=np.sqrt(np.mean((bb-aa)**2))/sd[i,c],centered_amplitude_ratio=bb.std()/max(aa.std(),1e-12),
                        signed_gain=ac@bc/max(ac@ac,1e-24),bias_training_sd=(bb-aa).mean()/sd[i,c])
                    if min(aa.std(),bb.std())>1e-12:values['pearson_r']=np.corrcoef(aa,bb)[0,1]
                    maxima['waveform']=max(maxima['waveform'],*[float(abs(value-w[key])) for key,value in values.items()])
                costs['data']+=float(data_weight*np.sum(e[mask[i]]**2))
                costs['driver']+=float(s['penalty']/dt**3*np.sum(np.diff(driver[i],n=2)**2))
                costs['initial']+=float(arm.get('initial_penalty',s['initial_penalty'])*np.sum(weights*(initial[i]-np.r_[0.,np.ones(4)])**2))
                costs['flow']+=float(s['flow_prior_weight']*dt*np.sum((np.log(states[i,:,2])/s['flow_prior_log_sd'])**2))
                checked+=1
            if arm['fit']:
                refs=np.array([cfg['fitting']['reference'][name] for name in arm['fit']])
                costs['parameter_prior']=float(np.sum((np.log(np.asarray(fit['parameter_values'])/refs)/arm['log_sd'])**2))
            for key,value in costs.items():
                maxima['objective_relative']=max(maxima['objective_relative'],abs(value-fit['objective_components'][key])/max(1.,abs(value)))
            maxima['objective_relative']=max(maxima['objective_relative'],abs(sum(costs.values())-fit['objective'])/max(1.,abs(fit['objective'])))
    if any(v>1e-9 for v in maxima.values()):problems.append('numerical_evidence_mismatch')
    result=dict(status='passed' if not problems else 'failed',checked_rows=checked,unfitted_failed_tasks=failed_tasks,
        maxima=maxima,problems=problems,source='retained_task_arrays_independent_recomputation_no_refit')
    write_json(out/'array_verification.json',result)
    if problems:raise ValueError('Tak array verification failed: '+str(problems[:10]))
    return result


def tak_morphology_export(cfg, parent, output, settings_path=None):
    """Read the retained 48-record waveform-atlas scope without mutating its run."""
    from src.metrics.fnirs_morphology import MorphologySettings, fnirs_morphology_metrics
    parent = Path(parent).resolve()
    output = Path(output).resolve()
    if output.parent != parent or output.exists():
        raise ValueError('morphology output must be a fresh direct child of the retained run')

    def retained_path(relative):
        relative = Path(relative)
        path = (parent/relative).resolve()
        if relative.is_absolute() or '..' in relative.parts or not path.is_relative_to(parent):
            raise ValueError('morphology retained path escapes the parent run')
        return path

    def read(relative):
        return json.loads(retained_path(relative).read_text())

    def basename(value):
        return isinstance(value,str) and value not in ('','.','..') and Path(value).name==value and '\\' not in value

    if (read('resolved_config.json') != cfg or cfg.get('schema') != 'shared_driver_tak_v1'
            or cfg.get('scope') != 'exploratory_public_cached_Hb_conditional_reconstruction'
            or cfg['data'].get('protected_data') != 'forbidden' or cfg['data'].get('raw_reads') is not False
            or cfg['data'].get('identities') != 'exact_parent_evaluation_records_no_result_based_selection'
            or cfg['tensor'].get('last_bin') != 'excluded_from_fit_and_score'):
        raise ValueError('morphology requires the unchanged retained public Tak contract')
    plan = read('plan.json')
    records = plan.get('records',[])
    if (plan.get('schema') != 'shared_driver_tak_plan_v1'
            or plan.get('selection') != 'all_exact_parent_public_evaluation_records'
            or len(records) != cfg['data']['expected_records']):
        raise ValueError('morphology retained plan denominator or schema mismatch')
    by_id = {}
    for ref in records:
        if (not basename(ref.get('id')) or ref['id'] in by_id
                or ref.get('dataset') not in cfg['data']['datasets']
                or ref.get('partition') != 'evaluation' or ref.get('duration_s') != 90
                or ref.get('parent') not in cfg['parents']
                or not all(isinstance(ref.get(k),str) and ref[k] for k in ('subject','record'))):
            raise ValueError('morphology public plan identity mismatch')
        by_id[ref['id']] = ref
    grouped, group_ids = [], set()
    for group in plan.get('groups',[]):
        if not basename(group.get('id')) or group['id'] in group_ids or not group.get('refs'):
            raise ValueError('morphology plan group identity mismatch')
        group_ids.add(group['id'])
        for ref in group['refs']:
            if ref.get('id') not in by_id or ref != by_id[ref['id']]:
                raise ValueError('morphology plan group record mismatch')
            grouped.append(ref['id'])
    if sorted(grouped) != sorted(by_id):
        raise ValueError('morphology plan groups must contain every record exactly once')
    jobs = tak_specs(cfg,plan,'measured')
    summary = read('measured_summary.json')
    planned_rows = sum(len(j['group']['refs']) for j in jobs)
    if (summary.get('schema') != 'shared_driver_tak_summary_v1' or summary.get('status') != 'completed'
            or summary.get('phase') != 'measured' or summary.get('missing') != []
            or summary.get('planned_tasks') != len(jobs) or summary.get('terminal_tasks') != len(jobs)
            or summary.get('planned_rows') != planned_rows or summary.get('terminal_rows') != planned_rows):
        raise ValueError('morphology requires a completed measured parent with its full denominator')
    selected = [j for j in jobs if j['length_s']==90 and j['condition'] in ('joint_full','joint_blocked')
                and j['arm']['name'] in ('legacy_free','legacy_free_fit','tak_fit')]
    admitted = []
    for spec in selected:
        relative = Path('tasks')/(spec['key']+'.json')
        meta = read(relative)
        refs = spec['group']['refs']
        if (meta.get('spec') != spec or meta.get('status') not in ('completed','failed','failed_worker')
                or len(meta.get('rows',[])) != len(refs)):
            raise ValueError('morphology retained task spec or row denominator mismatch: '+spec['key'])
        index_by_id = {r['id']:i for i,r in enumerate(refs)}
        seen = set()
        for row in meta['rows']:
            identity = {k:row.get(k) for k in ('id','dataset','subject','record')}
            ref = by_id.get(identity['id'])
            if (ref is None or identity['id'] not in index_by_id or identity['id'] in seen
                    or identity != {k:ref[k] for k in identity}
                    or any(row.get(k)!=v for k,v in dict(group=spec['group']['id'],length_s=90,
                        condition=spec['condition'],phase='measured',arm=spec['arm']['name']).items())
                    or not isinstance(row.get('qualified'),bool) or not isinstance(row.get('converged'),bool)
                    or not isinstance(row.get('fit_status'),str)):
                raise ValueError('morphology retained row identity mismatch: '+spec['key'])
            seen.add(identity['id'])
        admitted.append((spec,meta,relative,index_by_id))
    overrides = {} if settings_path is None else json.loads(Path(settings_path).read_text())
    if not isinstance(overrides,dict) or set(overrides)-{f.name for f in fields(MorphologySettings)}:
        raise ValueError('unknown morphology settings field')
    settings = MorphologySettings(**overrides)
    n = int(90/cfg['tensor']['dt_s'])
    time_s = np.arange(n)*cfg['tensor']['dt_s']
    result_rows, csv_rows = [], []

    def scalars(value, prefix=''):
        result = {}
        for key,item in value.items():
            name = prefix+str(key)
            if isinstance(item,dict):
                result.update(scalars(item,name+'_'))
            elif key in ('slope_direction','slope_relationship') and isinstance(item,list):
                for scale in item:
                    result.update(scalars(scale,f"{name}_{scale['window_s']:g}s_"))
            elif not isinstance(item,(list,tuple)):
                result[name] = item
        return result

    # All contracts and retained identities are checked before the first array read.
    for spec,meta,relative,index_by_id in admitted:
        array_relative = relative.with_suffix('.npz')
        path = retained_path(array_relative)
        arrays, failure = {}, None
        if not path.exists():
            failure = 'missing_npz'
        else:
            with np.load(path,allow_pickle=False) as archive:
                arrays = {k:archive[k].copy() for k in ('target','prediction','sd','visible') if k in archive}
            missing = [k for k in ('target','prediction','sd','visible') if k not in arrays]
            if missing:
                failure = 'missing_arrays:'+','.join(missing)
            batch = len(spec['group']['refs'])
            for key,shape in (('target',(batch,n,3)),('prediction',(batch,n,3)),('sd',(batch,3)),('visible',(batch,n,3))):
                if key in arrays and arrays[key].shape != shape:
                    raise ValueError('morphology retained array shape mismatch: '+spec['key']+'/'+key)
            if 'sd' in arrays and (not np.isfinite(arrays['sd']).all() or np.any(arrays['sd']<=0)):
                raise ValueError('morphology retained training SD mismatch: '+spec['key'])
            if 'visible' in arrays:
                expected = np.broadcast_to(volume_drive_mask(n,spec['condition']),(batch,n,3))
                if arrays['visible'].dtype != np.bool_ or not np.array_equal(arrays['visible'],expected):
                    raise ValueError('morphology retained scoring mask mismatch: '+spec['key'])
        for source_row_index,row in enumerate(meta['rows']):
            index = index_by_id[row['id']]
            score = np.ones((n,2),bool); score[-1] = False
            if spec['condition']=='joint_blocked':
                visible = arrays['visible'][index] if 'visible' in arrays else volume_drive_mask(n,spec['condition'])
                score &= ~visible[:,1:]
            support = 'hidden_Hb_blocks_last_bin_excluded' if spec['condition']=='joint_blocked' else 'full_curve_last_bin_excluded'
            identity = {k:row[k] for k in ('id','dataset','subject','record','group','length_s','condition','phase','arm',
                                         'qualified','converged','fit_status')}
            identity.update(source_task=str(relative),source_arrays=str(array_relative),source_row_index=source_row_index,
                array_row_index=index,task_status=meta['status'],support=support)
            if failure:
                metrics = dict(components=[dict(component=c,status=failure,requested_points=int(score[:,i].sum()),
                    scored_points=0,na_reason=failure) for i,c in enumerate(('HbO','HbR'))],
                    pair=dict(status=failure,na_reason=failure))
            else:
                metrics = fnirs_morphology_metrics(arrays['target'][index,:,1:],arrays['prediction'][index,:,1:],
                    time_s=time_s,score_mask=score,training_sd=arrays['sd'][index,1:],settings=settings)
            result_rows.append(dict(**identity,ref=by_id[row['id']],metrics=metrics))
            for component in metrics['components']:
                scalar = scalars(component)
                scalar['morphology_status'] = scalar.pop('status')
                csv_rows.append(dict(**identity,**scalar,**scalars(metrics['pair'],'pair_')))
    frame = pd.DataFrame(csv_rows)
    counts = dict(planned_records=len(records),planned_curves=len(records)*6,terminal_curves=len(result_rows),
        component_rows=len(csv_rows),qualified_curves=sum(r['qualified'] for r in result_rows),
        component_status_counts=dict(frame.morphology_status.value_counts()),
        component_na_reason_counts={k:dict(frame[k].dropna().value_counts()) for k in frame
            if k.endswith('na_reason') and frame[k].notna().any()},
        component_na_field_counts={k:int(frame[k].isna().sum()) for k in frame if frame[k].isna().any()})
    if counts['terminal_curves'] != counts['planned_curves']:
        raise ValueError('morphology export denominator mismatch')
    result = dict(schema='shared_driver_tak_morphology_export_v1',status='completed',
        scope='retained_tak_waveform_atlas_90s',parent=str(parent),settings=asdict(settings),
        source_summary='measured_summary.json',parent_measured_planned_rows=planned_rows,
        raw_reads=0,protected_reads=0,refits=0,summary=counts,rows=result_rows)
    output.mkdir()
    write_json(output/'morphology.json',result)
    frame.to_csv(output/'morphology.csv',index=False)
    shutil.copy2(Path(__file__),output/'export_source.py')
    shutil.copy2(CODE_ROOT/'src/metrics/fnirs_morphology.py',output/'metrics_source.py')
    return {k:v for k,v in result.items() if k!='rows'}


def tak_repeatability_config(path):
    default=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_tak_repeatability_v1.yaml'
    cfg=yaml.safe_load(Path(path or default).read_text())
    if cfg != yaml.safe_load(default.read_text()):
        raise ValueError('Tak repeatability requires its unchanged versioned scope and estimator')
    core=tak_config(CODE_ROOT/cfg['base_config'])
    core['schema']=cfg['schema'];core['experiment_id']=cfg['experiment_id'];core['seed']=cfg['seed']
    fixed=next(deepcopy(a) for a in core['arms'] if a['name']=='tak_fixed')
    narrow=next(deepcopy(a) for a in core['arms'] if a['name']=='tak_fit')
    narrow.update(name='tak_repeat_narrow',log_sd=cfg['model']['log_prior_sd'],warm='tak_fixed')
    core['arms']=[fixed,narrow];core['conditions']=['joint_full'];core['tensor']['lengths_s']=[90]
    core['synthetic'].update(seeds=cfg['synthetic']['seeds'],scenarios=cfg['synthetic']['scenarios'],length_s=90)
    core['endpoints']['contrasts']=[['tak_fixed','tak_repeat_narrow']]
    core['claim_limits']=cfg['claim_limits']
    return cfg,core


def _tak_repeat_select(candidates, count):
    """Select without outcomes, checking nonoverlap in both modality clocks."""
    disjoint=[]
    for row in sorted(candidates,key=lambda r:(r['eeg_start_s'],r['hb_start_s'],r['event_id'])):
        if not disjoint or (row['eeg_start_s']>=disjoint[-1]['eeg_start_s']+90-1e-8
                            and row['hb_start_s']>=disjoint[-1]['hb_start_s']+90-1e-8):
            disjoint.append(row)
    if len(disjoint)<=count:return disjoint
    return [disjoint[i] for i in np.rint(np.linspace(0,len(disjoint)-1,count)).astype(int)]


def _tak_repeat_candidates(record, events, anchor, *, coordinate=None, allowed_tasks=None):
    from collections import Counter
    from src.data.event_alignment import window_within_alignment_support
    de=record.manifest['array_shapes']['eeg'][0]/200.;dh=record.manifest['array_shapes']['fnirs'][0]/10.
    ds=record.dataset_id;result=[]
    ordered=sorted([e for e in events if e.get('eeg_time_ms') is not None and e.get('fnirs_time_ms') is not None],key=lambda e:e['eeg_time_ms'])
    for event in ordered[:1] if ds=='refed' else ordered:
        es,hs=(0.,0.) if ds=='refed' else (event['eeg_time_ms']/1000.-5.,event['fnirs_time_ms']/1000.-5.)
        if min(es,hs)<0 or es+90>de+1e-8 or hs+90>dh+1e-8:continue
        if ds!='refed' and not window_within_alignment_support(event,-5.,90.):continue
        metadata=event.get('metadata',{});task=metadata.get('task')
        if allowed_tasks is not None:
            if task not in allowed_tasks:continue
        else:
            if ds=='eeg_fnirs_single_trial' and task!='motor_imagery':continue
            if ds=='simultaneous_eeg_nirs' and task!='wg':continue
        within=[e for e in ordered if es<=e['eeg_time_ms']/1000.<es+90]
        counts=dict(Counter(str(e.get('metadata',{}).get('condition_label',e['label'])) for e in within))
        if not counts or 'unknown' in counts:continue
        support=metadata.get('alignment_support_ms')
        native_key=json.dumps([record.join_key,anchor['hb_channel'],metadata.get('session_idx'),support],sort_keys=True)
        result.append(dict(join_key=record.join_key,record=record.base_record_id,dataset=ds,
            subject=record.canonical_subject_id,region='prefrontal',site='prefrontal',coordinate=coordinate or ds+'__prefrontal',
            task=task,event_id=event['event_index'],eeg_start_s=es,hb_start_s=hs,duration_s=90,
            condition_counts=counts,anchor=anchor,alignment_support=support,native_session=metadata.get('session_idx'),
            native_group_key=native_key,partition='evaluation',source_files=record.manifest['source_files'],
            analysis_tier='primary' if ds!='refed' or set(counts)=={'LVLA (Sad)'} else 'supplementary'))
    return result


def tak_repeatability_plan(cfg,core,root):
    from collections import defaultdict
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.event_alignment import ADMISSIBLE_ALIGNMENT_CASES
    parent=root/cfg['identity_parent'];old_cfg=json.loads((parent/'resolved_config.json').read_text())
    if (old_cfg.get('schema')!='shared_driver_tak_v1' or old_cfg['data']['protected_data']!='forbidden'
            or json.loads((parent/'verification.json').read_text())['status']!='passed'):
        raise ValueError('Exact completed public Tak identity parent required')
    old=json.loads((parent/'plan.json').read_text());cohort={};coordinate_by_subject={}
    for ref in old['records']:
        key=(ref['dataset'],ref['subject']);anchor=ref['anchor']
        if key in cohort and (cohort[key]['hb_channel']!=anchor['hb_channel'] or cohort[key]['eeg_channels']!=anchor['eeg_channels']):
            raise ValueError('Original subject montage is not unique')
        cohort[key]=anchor
        coordinate_by_subject[key]=ref['coordinate']
    if len(old['records'])!=48 or len(cohort)!=24:raise ValueError('Expected exact 24-subject parent cohort')
    index=CleanPhysiologyCacheIndex(root/cfg['data']['cache_root'])
    candidate_groups=defaultdict(list);excluded=[]
    for record in index.records:
        key=(record.dataset_id,record.canonical_subject_id)
        if key not in cohort:continue
        ds=record.dataset_id
        if ds=='eeg_fnirs_single_trial' and record.base_record_id not in ('session_00','session_02','session_04'):continue
        if ds=='simultaneous_eeg_nirs' and record.base_record_id!='cnt_wg':continue
        if ds=='visual_cognitive_motivation' and not record.base_record_id.endswith('_Probe1'):continue
        if ds=='refed' and record.signal_branch!='hbo_hbr':continue
        reports=index.reports_by_join_key.get(record.join_key,[])
        if not reports or any(r.get('alignment_case') not in ADMISSIBLE_ALIGNMENT_CASES or r.get('label_sequence_match') is False for r in reports):
            excluded.append(dict(join_key=record.join_key,reason='nonadmitted_central_alignment'));continue
        anchor=deepcopy(cohort[key]);names=record.manifest['measurement']['fnirs_channel_names'];channel=anchor['hb_channel']+'_HbO'
        if channel not in names:
            excluded.append(dict(join_key=record.join_key,reason='original_Hb_channel_missing'));continue
        anchor['hb_pair']=names.index(channel)//2
        candidates=_tak_repeat_candidates(record,index.events_by_join_key.get(record.join_key,[]),anchor,coordinate=coordinate_by_subject[key])
        if not candidates:excluded.append(dict(join_key=record.join_key,reason='no_complete_90s_aligned_candidate'))
        for ref in candidates:candidate_groups[ref['native_group_key']].append(ref)
    by_subject=defaultdict(list)
    for key,refs in candidate_groups.items():by_subject[(refs[0]['dataset'],refs[0]['subject'])].append(key)
    selected=[];native_groups=[]
    for subject in sorted(cohort):
        keys=sorted(by_subject[subject]);ds=subject[0]
        for j,key in enumerate(keys):
            count=(6//len(keys)+int(j<6%len(keys))) if ds=='visual_cognitive_motivation' else (1 if ds=='refed' else 2)
            choices=_tak_repeat_select(candidate_groups[key],count)
            gid=f'ng{len(native_groups):03d}'
            native_groups.append(dict(id=gid,native_group_key=key,dataset=ds,subject=subject[1],
                available_candidates=len(candidate_groups[key]),requested_windows=count,selected_windows=len(choices),
                repeat_interpretation='disjoint_subset_reestimation_of_one_constant_pair_not_independent_subjects'))
            for k,ref in enumerate(choices):
                ref=dict(ref,native_group=gid,subset_index=k,side=k)
                ref['id']=f'{ds}__{ref["subject"]}__{ref["record"]}__{gid}__w{k:02d}'
                selected.append(ref)
    training=[]
    for relative in old_cfg['parents']:
        pp=json.loads((root/relative/'plan.json').read_text())
        for ref in pp['records']:
            if ref['partition']=='development' and ref['coordinate'] in {r['coordinate'] for r in selected}:
                if (ref['dataset'],ref['subject']) in cohort:raise ValueError('Calibration/evaluation subject overlap')
                if ref['join_key'] not in index.records_by_join_key:raise ValueError('Calibration identity missing from central registry')
                training.append(dict(ref,parent=relative))
    if len({r['id'] for r in training})!=len(training):raise ValueError('Duplicate calibration identity')
    if {r['coordinate'] for r in selected}!={r['coordinate'] for r in training}:
        raise ValueError('Every evaluation coordinate needs its original development identities')
    groups=[dict(id=f'g{i:03d}',native_group=ref['native_group'],refs=[ref]) for i,ref in enumerate(selected)]
    counts=[]
    for ds,subject in sorted(cohort):
        rows=[r for r in selected if (r['dataset'],r['subject'])==(ds,subject)]
        counts.append(dict(dataset=ds,subject=subject,primary=sum(r['analysis_tier']=='primary' for r in rows),
            supplementary=sum(r['analysis_tier']=='supplementary' for r in rows),native_groups=len({r['native_group'] for r in rows})))
    return dict(schema='tak_repeatability_plan_v1',records=selected,groups=groups,native_groups=native_groups,
        calibration_records=training,subject_counts=counts,excluded=excluded,selection=cfg['selection'],
        measured_arrays_read=0,protected_reads=0,dt_s=core['tensor']['dt_s'],eeg_proxy_rate_hz=10.)


def _tak_repeat_prepare_record(payload):
    """One central native EEG/cache record read, possibly several disjoint windows."""
    core,root_string,out_string,record,refs=payload;root,out=Path(root_string),Path(out_string)
    from src.data.unified_physiology import load_native_eeg_record,load_cached_fnirs_record
    from src.inference.observation_baselines import eeg_band_power,disjoint_native_bin_operator
    t=time.monotonic();rows=[]
    pending=[r for r in refs if not (out/'feature_cache'/(r['id']+'.json')).exists()]
    if not pending:return dict(join_key=record.join_key,rows=[],seconds=0.,cached=True)
    try:
        native=load_native_eeg_record(root,record);cached=load_cached_fnirs_record(root,record)
        channels={str(n).upper():i for i,n in enumerate(native.channel_names)}
        for ref in pending:
            try:
                selected=[channels[n.upper()] for n in ref['anchor']['eeg_channels']]
                start=round(ref['eeg_start_s']*native.sample_rate_hz);length=round(90*native.sample_rate_hz)
                values=native.values[start:start+length,selected]
                if start<0 or values.shape!=(length,6) or not np.isfinite(values).all():raise ValueError('Incomplete native EEG support')
                power=eeg_band_power(values,bands=core['tensor']['eeg_bands_hz'],sample_rate=native.sample_rate_hz,target_rate=10.)
                if power.shape!=(900,6,5) or not np.isfinite(power).all() or np.any(power<=0):raise ValueError('Invalid native 10Hz power')
                eeg_op=np.eye(900);eeg_op[:,:50]-=1/50
                eeg=eeg_op@np.log(power).reshape(900,30)
                pair=int(ref['anchor']['hb_pair'])
                if cached['channel_names'][2*pair]!=ref['anchor']['hb_channel']+'_HbO':raise ValueError('Hb channel mismatch')
                take=(cached['time_s']>=ref['hb_start_s'])&(cached['time_s']<ref['hb_start_s']+90)
                if not cached['valid_mask'][take,pair].all():raise ValueError('Unsupported cached Hb channel')
                op=disjoint_native_bin_operator(cached['time_s'][take]-ref['hb_start_s'],steps=900,dt=.1,reference_steps=50)
                hb=op['raw']@cached['values'][take,pair]
                if hb.shape!=(900,2) or not np.isfinite(hb).all():raise ValueError('Incomplete cached Hb support')
                path=out/'feature_cache'/(ref['id']+'.npz');path.parent.mkdir(parents=True,exist_ok=True)
                np.savez_compressed(path,eeg=eeg,hb=hb,eeg_op=eeg_op,hb_op=op['model'])
                row=dict(id=ref['id'],status='completed',ref=ref,fnirs_provenance=cached['provenance'],
                    eeg_provenance=dict(schema='eeg_log_bandpower_10hz_v1',source=str(native.source_path),
                        native_rate_hz=native.sample_rate_hz,native_unit=native.native_unit,proxy_rate_hz=10.,
                        native_start_sample=start,native_samples=length,start_rounding_s=start/native.sample_rate_hz-ref['eeg_start_s'],
                        channels=ref['anchor']['eeg_channels'],bands_hz=core['tensor']['eeg_bands_hz']))
            except Exception as exc:row=dict(id=ref['id'],status='failed',ref=ref,error=repr(exc))
            write_json(out/'feature_cache'/(ref['id']+'.json'),row);rows.append(row)
    except Exception as exc:
        for ref in pending:
            row=dict(id=ref['id'],status='failed',ref=ref,error=repr(exc));write_json(out/'feature_cache'/(ref['id']+'.json'),row);rows.append(row)
    return dict(join_key=record.join_key,rows=[dict(id=r['id'],status=r['status']) for r in rows],
        seconds=time.monotonic()-t,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)


def tak_repeatability_prepare(cfg,core,root,out,plan,workers):
    from collections import defaultdict
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.ssm_prepared import fit_feature_coordinate
    if serial(plan)!=serial(tak_repeatability_plan(cfg,core,root)):raise ValueError('Repeatability metadata plan changed')
    syn=json.loads((out/'synthetic_summary.json').read_text())
    narrow=[r for r in json.loads((out/'synthetic_rows.json').read_text()) if r['arm']=='tak_repeat_narrow']
    if syn['status']!='completed' or len(narrow)!=3 or not all(r['qualified'] for r in narrow):
        raise ValueError('Three successful synthetic narrow-prior tasks required before measured reads')
    index=CleanPhysiologyCacheIndex(root/cfg['data']['cache_root']);lookup={r.join_key:r for r in index.records}
    by_record=defaultdict(list)
    for ref in plan['calibration_records']+plan['records']:by_record[ref['join_key']].append(ref)
    jobs=[(core,str(root),str(out),lookup[key],refs) for key,refs in sorted(by_record.items())]
    details=[];t=time.monotonic()
    with ProcessPoolExecutor(max_workers=workers) as pool:
        iterator=iter(jobs);active={}
        def submit():
            try:payload=next(iterator)
            except StopIteration:return
            active[pool.submit(_tak_repeat_prepare_record,payload)]=payload[3].join_key
        for _ in range(workers*2):submit()
        while active:
            ready,_=wait(active,return_when=FIRST_COMPLETED)
            for future in ready:
                details.append(future.result());active.pop(future);submit()
            write_json(out/'progress.json',dict(phase='prepare',terminal_records=len(details),planned_records=len(jobs),elapsed_s=time.monotonic()-t))
    coordinates={};failures=[];prepared=[]
    for coordinate in sorted({r['coordinate'] for r in plan['records']}):
        training=[r for r in plan['calibration_records'] if r['coordinate']==coordinate];chunks=[];good=[]
        for ref in training:
            meta=json.loads((out/'feature_cache'/(ref['id']+'.json')).read_text())
            if meta['status']!='completed':failures.append(meta);continue
            with np.load(out/'feature_cache'/(ref['id']+'.npz'),allow_pickle=False) as a:chunks.append((a['eeg'].copy(),a['hb'].copy()))
            good.append(ref)
        if len({r['subject'] for r in good})<3:raise ValueError('Insufficient distinct calibration subjects')
        co=fit_feature_coordinate(chunks);co.update(training_ids=[r['id'] for r in good],training_subjects=sorted({r['subject'] for r in good}),
            planned_training_records=len(training),successful_training_records=len(good),fnirs_input='unified_cached_fnirs_v1',
            eeg_proxy_input='eeg_log_bandpower_10hz_v1',eeg_proxy_rate_hz=10.,dt_s=.1)
        coordinates[coordinate]=co
        for ref in [r for r in plan['records'] if r['coordinate']==coordinate]:
            meta=json.loads((out/'feature_cache'/(ref['id']+'.json')).read_text())
            if meta['status']!='completed':failures.append(meta);continue
            with np.load(out/'feature_cache'/(ref['id']+'.npz'),allow_pickle=False) as a:
                y=np.column_stack((a['eeg']@co['pc']*co['eeg_factor'],a['hb']*co['hb_factor']))
                target,operator=volume_drive_crop(y,dict(eeg=a['eeg_op'],hb=a['hb_op']),90,dt=.1)
            path=out/'prepared'/f'{ref["id"]}__90.npz';path.parent.mkdir(parents=True,exist_ok=True)
            np.savez_compressed(path,target=target,operator=operator,sd=co['sd'],hb_factor=np.array(co['hb_factor']),
                fnirs_input=np.array('unified_cached_fnirs_v1'),eeg_proxy_input=np.array('eeg_log_bandpower_10hz_v1'),
                eeg_proxy_rate_hz=np.array(10.),time_s=np.arange(900)*.1)
            write_json(path.with_suffix('.json'),dict(status='completed',ref=ref,feature_source='../feature_cache/'+ref['id']+'.json',coordinate=coordinate))
            prepared.append(ref['id'])
    result=dict(status='completed',planned_records=len(plan['records']),prepared_records=len(prepared),prepared_ids=prepared,
        coordinates=coordinates,failures=failures,record_workers=details,seconds=time.monotonic()-t,
        raw_EEG_reads=sum(not r.get('cached',False) for r in details),raw_fnirs_reads=0,protected_reads=0)
    write_json(out/'preparation.json',result);return result


def _tak_repeatability_statistics(frame, *, seed=20261028, bootstrap_repeats=2000, parameters=('kappa','tau')):
    """Describe nested log estimates; clusters are subjects, never windows."""
    subjects=[];datasets=[];comparisons=[]
    for (dataset,tier,subject),part in frame.groupby(['dataset','analysis_tier','subject'],sort=True):
        for parameter in parameters:
            good=part[part.qualified & np.isfinite(part[parameter]) & part[parameter].gt(0)]
            group_logs=[np.log(g[parameter].to_numpy(float)) for _,g in good.groupby('native_group')]
            means=np.array([v.mean() for v in group_logs]);center=float(means.mean()) if len(means) else np.nan
            repeated=[v for v in group_logs if len(v)>=2]
            within=float(np.sqrt(np.mean([np.mean((v-v.mean())**2) for v in repeated]))) if repeated else np.nan
            across=float(np.sqrt(np.mean((means-center)**2))) if len(means)>=2 else np.nan
            total=float(np.sqrt(np.mean([np.mean((v-center)**2) for v in group_logs]))) if len(good)>=2 else np.nan
            subjects.append(dict(dataset=dataset,analysis_tier=tier,subject=subject,parameter=parameter,
                planned_windows=len(part),qualified_windows=len(good),planned_native_groups=part.native_group.nunique(),
                qualified_native_groups=len(means),groups_with_repeated_estimates=len(repeated),
                log_center=center,geometric_center=np.exp(center),
                minimum=good[parameter].min(),maximum=good[parameter].max(),
                within_support_log_rms=within,between_support_log_rms=across,total_within_subject_log_rms=total,
                within_support_multiplicative_pct=100*np.expm1(within),
                between_support_multiplicative_pct=100*np.expm1(across),
                total_within_subject_multiplicative_pct=100*np.expm1(total)))
    subject_frame=pd.DataFrame(subjects)
    for (dataset,tier,parameter),part in subject_frame.groupby(['dataset','analysis_tier','parameter'],sort=True):
        eligible=part[np.isfinite(part.log_center)&np.isfinite(part.total_within_subject_log_rms)]
        n=len(eligible);means=eligible.log_center.to_numpy();within=eligible.total_within_subject_log_rms.to_numpy()
        b=float(np.sqrt(np.mean((means-means.mean())**2))) if n>=2 else np.nan
        w=float(np.sqrt(np.mean(within**2))) if n else np.nan
        ratio=b/w if np.isfinite(b) and w>0 else np.nan
        ci=[np.nan,np.nan]
        if n>=2 and w>0:
            ix=np.random.default_rng(seed).integers(0,n,(bootstrap_repeats,n))
            boot_b=np.sqrt(np.mean((means[ix]-means[ix].mean(axis=1,keepdims=True))**2,axis=1))
            boot_w=np.sqrt(np.mean(within[ix]**2,axis=1));valid=boot_w>0
            if valid.any():ci=np.quantile(boot_b[valid]/boot_w[valid],[.025,.975])
        datasets.append(dict(dataset=dataset,analysis_tier=tier,parameter=parameter,planned_subjects=len(part),
            included_subjects=n,complete_subjects=int(part.qualified_windows.eq(part.planned_windows).sum()),
            planned_windows=int(part.planned_windows.sum()),qualified_windows=int(part.qualified_windows.sum()),
            between_subject_log_rms=b,within_subject_log_rms=w,between_within_ratio=ratio,
            ratio_ci95_low=ci[0],ratio_ci95_high=ci[1],
            between_subject_multiplicative_pct=100*np.expm1(b),within_subject_multiplicative_pct=100*np.expm1(w)))
    for (dataset,tier),part in frame.groupby(['dataset','analysis_tier'],sort=True):
        common=part[part.qualified & part.fixed_qualified]
        stats={}
        for label,field in [('narrow','full_hb_nmse'),('fixed','fixed_full_hb_nmse')]:
            x=common.groupby(['subject','native_group'])[field].mean().groupby('subject').mean()
            stats[label+'_hb_nrmse']=float(np.sqrt(x.mean())) if len(x) else np.nan
        comparisons.append(dict(dataset=dataset,analysis_tier=tier,planned_windows=len(part),
            narrow_qualified=int(part.qualified.sum()),fixed_qualified=int(part.fixed_qualified.sum()),
            paired_windows=len(common),paired_subjects=common.subject.nunique(),**stats,
            fixed_minus_narrow=stats['fixed_hb_nrmse']-stats['narrow_hb_nrmse']))
    return subject_frame,pd.DataFrame(datasets),pd.DataFrame(comparisons)


def tak_repeatability_analyze(out, target):
    cfg=json.loads((out/'resolved_config.json').read_text());core=json.loads((out/'resolved_model_config.json').read_text())
    if cfg.get('schema')!='shared_driver_tak_repeatability_v1' or cfg['data']['protected_data']!='forbidden':
        raise ValueError('Only this public repeatability contract can be analyzed')
    if target.parent!=out or target.exists():raise ValueError('Choose a fresh direct-child analysis export')
    plan=json.loads((out/'plan.json').read_text());summary=json.loads((out/'measured_summary.json').read_text())
    if summary['status']!='completed' or summary['terminal_rows']!=len(plan['records'])*2:
        raise ValueError('Complete planned denominator required before final analysis')
    rows=[];checked=0;max_error=0.;failed=[]
    for group in plan['groups']:
        ref=group['refs'][0];arms={}
        for arm in ('tak_fixed','tak_repeat_narrow'):
            relative=Path('tasks')/f'measured__{group["id"]}__90__joint_full__{arm}.json'
            task=json.loads((out/relative).read_text())
            if (len(task['rows'])!=1 or task['rows'][0]['id']!=ref['id'] or task['spec']['group']['refs']!=group['refs']
                    or task['spec']['arm']['name']!=arm or task['rows'][0]['arm']!=arm
                    or task['spec']['condition']!='joint_full' or task['spec']['length_s']!=90):
                raise ValueError('Task/sample identity mismatch in repeatability analysis')
            if arm=='tak_repeat_narrow' and task['spec']['arm']['log_sd']!=[.125,.125]:
                raise ValueError('Repeatability prior changed')
            row=task['rows'][0];fit=task.get('fit',{});arms[arm]=(row,fit,str(relative))
            if row['qualified']:
                with np.load((out/relative).with_suffix('.npz'),allow_pickle=False) as a:
                    y,p,sd=a['target'],a['prediction'],a['sd']
                    if y.shape!=(1,900,3) or p.shape!=y.shape or sd.shape!=(1,3):raise ValueError('Retained 10Hz tensor mismatch')
                    nmse=np.mean(((p[0,:-1]-y[0,:-1])/sd[0])**2,axis=0)
                    discrepancy=max(abs(float(nmse[1:].mean())-row['full_hb_nmse']),abs(float(nmse[0])-row['eeg_nmse']))
                    if discrepancy>1e-10:raise ValueError('Retained reconstruction metric mismatch')
                    max_error=max(max_error,discrepancy);checked+=1
            else:failed.append(dict(id=ref['id'],arm=arm,status=row['fit_status'],source_task=str(relative)))
        row,fit,source=arms['tak_repeat_narrow'];fixed=arms['tak_fixed'][0]
        start_values=[s['parameter_values'] for s in fit.get('starts',[]) if s['converged']]
        detail=dict(id=ref['id'],dataset=ref['dataset'],subject=ref['subject'],record=ref['record'],
            native_group=ref['native_group'],subset_index=ref['subset_index'],analysis_tier=ref['analysis_tier'],
            task=ref['task'],condition_counts=json.dumps(ref['condition_counts'],ensure_ascii=False,sort_keys=True),
            eeg_start_s=ref['eeg_start_s'],hb_start_s=ref['hb_start_s'],hb_channel=ref['anchor']['hb_channel'],
            qualified=row['qualified'],fit_status=row['fit_status'],kappa=row.get('kappa',np.nan),tau=row.get('tau',np.nan),
            full_hb_nmse=row.get('full_hb_nmse',np.nan),eeg_nmse=row.get('eeg_nmse',np.nan),
            fixed_qualified=fixed['qualified'],fixed_full_hb_nmse=fixed.get('full_hb_nmse',np.nan),
            converged_starts=len(start_values),planned_starts=len(fit.get('starts',[])),source_task=source,
            minimum_log_parameter_boundary_distance=min(fit.get('log_parameter_boundary_distance',[np.nan])),
            integration_max_training_sd=row.get('integration_max_training_sd',np.nan))
        for i,parameter in enumerate(('kappa','tau')):
            detail[parameter+'_start_span_pct']=(100*np.ptp(np.asarray(start_values)[:,i])/detail[parameter]
                if row['qualified'] and len(start_values)>=2 else np.nan)
        rows.append(detail)
    frame=pd.DataFrame(rows);subjects,dispersion,comparison=_tak_repeatability_statistics(frame,seed=cfg['seed'])
    target.mkdir();frame.to_csv(target/'parameter_reestimates.csv',index=False,encoding='utf-8-sig')
    subjects.to_csv(target/'subject_parameters.csv',index=False,encoding='utf-8-sig')
    dispersion.to_csv(target/'dispersion_summary.csv',index=False,encoding='utf-8-sig')
    comparison.to_csv(target/'paired_reconstruction.csv',index=False,encoding='utf-8-sig')
    result=dict(schema='tak_repeatability_analysis_v1',status='completed',source_run=str(out),
        planned_windows=len(frame),primary_windows=int(frame.analysis_tier.eq('primary').sum()),
        supplementary_windows=int(frame.analysis_tier.eq('supplementary').sum()),qualified_windows=int(frame.qualified.sum()),
        failed_rows=failed,planned_subjects=24,independent_array_rows_checked=checked,max_nmse_discrepancy=max_error,
        numerical=dict(qualified_windows=int(frame.qualified.sum()),
            qualified_with_at_least_two_starts=int((frame.qualified&frame.converged_starts.ge(2)).sum()),
            max_kappa_start_span_pct=frame.kappa_start_span_pct.max(),max_tau_start_span_pct=frame.tau_start_span_pct.max(),
            qualified_boundary_windows=int((frame.qualified&frame.minimum_log_parameter_boundary_distance.lt(1e-6)).sum()),
            maximum_qualified_integration_difference=frame.loc[frame.qualified,'integration_max_training_sd'].max()),
        definitions=dict(center='mean log parameter within native group, then equal native-group mean within subject; exp for geometric center',
            within='sqrt of subject-equal mean of native-group-equal mean of squared log deviations from each subject center',
            between='RMS of included subject log centers around their equal mean; no degrees-of-freedom correction',
            ratio='between RMS / within RMS; descriptive contrast, not ICC or biological reliability',
            interval='2000 whole-subject bootstrap percentile intervals, frozen fits and scales, exploratory and no multiplicity correction',
            incomplete='all planned/failure counts retained; dispersion uses subjects with at least two qualified primary estimates; source-group membership retained',
            multiplicative_percent='100 * (exp(log RMS) - 1), a dispersion scale, not a confidence interval',
            reconstruction='paired valid windows; time/chromophore NMSE, then equal native-group mean, equal subject mean, sqrt'),
        dispersion=dispersion.to_dict('records'),paired_reconstruction=comparison.to_dict('records'),
        raw_signal_reads=0,protected_reads=0,refits=0)
    write_json(target/'summary.json',result);shutil.copy2(Path(__file__),target/'analysis_source.py')
    return result


def tak_repeatability_main(args):
    cfg,core=tak_repeatability_config(args.config);root=args.project_root.resolve();out=args.run_dir.resolve()
    if not out.is_relative_to(root/cfg['output_root']) or out==root/cfg['output_root']:
        raise ValueError('Repeatability output must be below the existing Tak run root')
    out.mkdir(parents=True,exist_ok=True);lock=(out/'controller.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    for name,value in [('resolved_config.json',cfg),('resolved_model_config.json',core)]:
        path=out/name
        if path.exists() and json.loads(path.read_text())!=serial(value):raise ValueError('Immutable repeatability resolved configuration changed')
        if not path.exists():write_json(path,value)
    stage=args.repeat_stage
    if stage in ('synthetic','prepare','pilot','run'):
        if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):
            raise ValueError('Repeatability preparation/fitting requires durable user systemd')
        if not 1<=args.workers<=cfg['resources']['max_workers']:raise ValueError('Worker count outside resource contract')
    if stage=='analyze':
        result=tak_repeatability_analyze(out,(args.repeat_analysis_output or out/'repeatability_analysis_v1').resolve())
    elif stage=='check':
        y,op,sd,truth=tak_synthetic(core,0,'tak_nonrest')
        if y.shape!=(900,3) or op.shape!=(2700,2700) or sd.shape!=(3,):raise ValueError('Repeatability tensor mismatch')
        result=dict(status='passed',schema=cfg['schema'],shape=list(y.shape),dt_s=.1,measured_arrays_read=0,protected_reads=0)
        write_json(out/'software_checks.json',result)
    elif stage=='plan':
        result=tak_repeatability_plan(cfg,core,root);path=out/'plan.json'
        if path.exists() and json.loads(path.read_text())!=serial(result):raise ValueError('Immutable repeatability plan changed')
        if not path.exists():write_json(path,result)
    else:
        if json.loads((out/'software_checks.json').read_text())['status']!='passed':raise ValueError('Software checks required')
        plan=json.loads((out/'plan.json').read_text())
        if stage=='prepare':result=tak_repeatability_prepare(cfg,core,root,out,plan,args.workers)
        else:
            phase='synthetic' if stage=='synthetic' else 'measured'
            specs=tak_specs(core,plan,phase)
            if stage in ('synthetic','pilot','run'):
                if phase=='measured' and json.loads((out/'preparation.json').read_text())['status']!='completed':raise ValueError('Preparation required')
                result=tak_run(core,out,plan,phase,args.workers,pilot=stage=='pilot',specs=specs)
                if stage!='pilot':result=tak_summarize(core,out,plan,phase,specs=specs)
            else:result=tak_summarize(core,out,plan,'measured',specs=specs)
    print(json.dumps(serial({k:v for k,v in result.items() if k not in ('records','groups','native_groups','calibration_records','coordinates','record_workers','terminal','paired_contrasts','prepared_ids','failures')})),flush=True)


def tak_task_parameter_config(path,root):
    default=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_tak_task_parameters_v1.yaml'
    cfg=yaml.safe_load(Path(path or default).read_text())
    if cfg!=yaml.safe_load(default.read_text()):raise ValueError('Unchanged task-parameter scope required')
    parent=Path(root)/cfg['parent'];pcfg=json.loads((parent/'resolved_config.json').read_text())
    if pcfg['schema']!='shared_driver_tak_repeatability_v1' or pcfg['data']['protected_data']!='forbidden':
        raise ValueError('Exact public 10Hz repeatability parent required')
    core=json.loads((parent/'resolved_model_config.json').read_text())
    if core['tensor']['dt_s']!=.1 or core['arms'][1]['log_sd']!=[.125,.125]:raise ValueError('Parent model/clock mismatch')
    core.update(schema=cfg['schema'],experiment_id=cfg['experiment_id'],seed=cfg['seed'])
    core['fitting']['reference']['neurovascular_gain']=1.
    core['fitting']['bounds']['neurovascular_gain']=cfg['model']['beta_bounds']
    core['arms'].append(dict(name='tak_tau_beta',hemodynamics='tak',initial='volume_tied',tau_v=2,
        fit=['tau','neurovascular_gain'],log_sd=[.125,.125],start_values=cfg['model']['tau_beta_starts'],warm='tak_fixed'))
    core['task_synthetic']=cfg['synthetic'];core['claim_limits']=cfg['claim_limits']
    core['data']['expected_records']=168+cfg['selection']['admitted_additional_windows']
    core['endpoints']['contrasts']=[['tak_fixed','tak_repeat_narrow'],['tak_fixed','tak_tau_beta'],['tak_repeat_narrow','tak_tau_beta']]
    return cfg,core


def tak_task_parameter_synthetic(core,case):
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    seed,repeat,task,scenario=case['subject'],case['repeat'],case['task'],case['scenario']
    rng=np.random.default_rng(core['seed']+100*seed+10*repeat+(task=='B'))
    dt=.1;n=900;t=np.arange(n)*dt;phase=.7*repeat+.2*seed
    driver=((.04*np.sin(2*np.pi*t/17+phase)+.018*np.cos(2*np.pi*t/7)) if task=='A'
            else (.055*np.sin(2*np.pi*t/13+phase)+.012*np.cos(2*np.pi*t/5)))
    driver*=1+.08*seed
    tau=1.7+.3*seed;beta=.85+.15*seed
    if task=='B' and scenario=='tau_shift':tau*=1.5
    if task=='B' and scenario=='beta_shift':beta*=1.5
    if 'spatial_node' in case:
        theta=2*np.pi*case['spatial_node']/6
        driver*=1+.15*np.cos(theta+.4*seed)
        if scenario=='structured':
            tau*=np.exp(.3*np.cos(theta+.7*seed));beta*=np.exp(.3*np.sin(theta+.7*seed))
    parameters=volume_drive_parameters(core,tau=tau,kappa=.64,neurovascular_gain=beta)
    initial=np.array([.02,1.04,1.025,1.025,.99])
    truth=nonlinear_driver_forward(driver,initial,parameters,dt,substeps=8,derivative=False,
        numerical_backend='numba',hemodynamics='tak',viscoelastic_s=2.)
    ref=np.eye(n);ref[:,:50]-=1/50;operator=np.kron(ref,np.eye(3))
    clean=(operator@truth['canonical_prediction'].ravel()).reshape(n,3)
    noise=rng.normal(size=(n,3))*np.array(core['synthetic']['noise_sd']);target=clean+ref@noise
    truth.update(driver=driver,initial_state=initial,kappa=.64,tau=tau,beta=beta,clean=clean)
    return target,operator,np.array(core['synthetic']['training_sd']),truth


def tak_task_parameter_specs(core,plan,phase):
    if phase!='synthetic':return tak_specs(core,plan,phase)
    jobs=[];s=core['task_synthetic']
    for scenario in s['scenarios']:
        for subject in s['subjects']:
            for repeat in s['repeats']:
                for task in s['tasks']:
                    case=dict(scenario=scenario,subject=subject,repeat=repeat,task=task)
                    key=f'{scenario}__s{subject}__r{repeat}__{task}'
                    group=dict(id=key,case=case,refs=[dict(id=key,dataset='synthetic',subject=f'seed{subject}',record=scenario)])
                    for arm in core['arms']:
                        jobs.append(dict(key=f'synthetic__{key}__90__joint_full__{arm["name"]}',phase='synthetic',
                            group=group,length_s=90,condition='joint_full',arm=arm))
    return jobs


def tak_task_parameter_plan(cfg,core,root):
    from collections import defaultdict
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.event_alignment import ADMISSIBLE_ALIGNMENT_CASES
    parent=root/cfg['parent'];pp=json.loads((parent/'plan.json').read_text())
    if json.loads((parent/'measured_summary.json').read_text())['status']!='completed':raise ValueError('Completed parent required')
    if len(pp['records'])!=168:raise ValueError('Exact parent 168-window scope required')
    templates={}
    for ref in pp['records']:templates.setdefault((ref['dataset'],ref['subject']),ref)
    index=CleanPhysiologyCacheIndex(root/cfg['data']['cache_root']);candidates={};excluded=[]
    for record in index.records:
        identity=(record.dataset_id,record.canonical_subject_id)
        if identity not in templates or record.dataset_id not in cfg['endpoints']['task_sets']:continue
        selection=cfg['selection'][record.dataset_id]
        if record.base_record_id not in selection['additional_records']:continue
        reports=index.reports_by_join_key.get(record.join_key,[])
        if not reports or any(r.get('alignment_case') not in ADMISSIBLE_ALIGNMENT_CASES or r.get('label_sequence_match') is False for r in reports):
            excluded.append(dict(join_key=record.join_key,reason='nonadmitted_alignment'));continue
        template=templates[identity];anchor=deepcopy(template['anchor']);names=record.manifest['measurement']['fnirs_channel_names']
        channel=anchor['hb_channel']+'_HbO'
        if channel not in names:excluded.append(dict(join_key=record.join_key,reason='missing_parent_channel'));continue
        anchor['hb_pair']=names.index(channel)//2
        tasks=selection.get('additional_tasks',[selection.get('additional_task')])
        rows=_tak_repeat_candidates(record,index.events_by_join_key.get(record.join_key,[]),anchor,
            coordinate=template['coordinate'],allowed_tasks=tasks)
        if not rows:excluded.append(dict(join_key=record.join_key,reason='no_complete_90s_task_candidate'))
        for row in rows:candidates.setdefault(row['native_group_key'],[]).append(row)
    refs=deepcopy(pp['records']);groups=deepcopy(pp['groups']);native_groups=deepcopy(pp['native_groups'])
    added=[]
    for key,rows in sorted(candidates.items()):
        gid=f'ng{len(native_groups):03d}';selected=_tak_repeat_select(rows,2)
        native_groups.append(dict(id=gid,native_group_key=key,dataset=rows[0]['dataset'],subject=rows[0]['subject'],
            task=rows[0]['task'],available_candidates=len(rows),requested_windows=2,selected_windows=len(selected)))
        for i,row in enumerate(selected):
            ref=dict(row,native_group=gid,subset_index=i,side=i,analysis_tier='task_extension')
            ref['id']=f'{ref["dataset"]}__{ref["subject"]}__{ref["record"]}__{gid}__w{i:02d}'
            group=dict(id=f'g{len(groups):03d}',native_group=gid,refs=[ref]);groups.append(group);refs.append(ref);added.append(ref['id'])
    if (len(added)!=cfg['selection']['admitted_additional_windows'] or
            excluded!=[dict(join_key=cfg['selection']['metadata_exclusion'],reason='nonadmitted_alignment')]):
        raise ValueError('Metadata-admissible task windows or exclusions changed')
    annotations={r['id']:dict(scope='new_task' if r['id'] in added else 'parent',task=r['task']) for r in refs}
    by_task=defaultdict(list)
    for group in groups:
        r=group['refs'][0]
        if r['dataset'] in cfg['endpoints']['task_sets']:
            by_task[(r['dataset'],r['subject'],r['task'])].append(r)
    for identity,rows in by_task.items():
        by_support=defaultdict(list)
        for r in rows:by_support[r['native_group']].append(r)
        ordered=sorted(by_support,key=lambda k:(by_support[k][0]['record'],min(r['eeg_start_s'] for r in by_support[k])))
        if len(ordered)!=3 or any(len(by_support[k])!=2 for k in ordered):raise ValueError('Each primary task requires three supports and two disjoint windows per support')
        for ordinal,key in enumerate(ordered):
            for ref in by_support[key]:annotations[ref['id']]['task_repeat']=ordinal
    return dict(schema='tak_task_parameter_plan_v1',records=refs,groups=groups,native_groups=native_groups,
        annotations=annotations,new_window_ids=added,parent_window_ids=[r['id'] for r in pp['records']],
        calibration_records=pp['calibration_records'],excluded=excluded,planned_windows=len(refs),
        new_windows=len(added),inherited_task_rows=336,new_fitting_tasks=len(refs)*3-336,measured_arrays_read=0,
        requested_new_windows=cfg['selection']['requested_additional_windows'],excluded_new_windows=6,
        task_sets=cfg['endpoints']['task_sets'],dt_s=.1,eeg_proxy_rate_hz=10.,protected_reads=0)


def tak_task_parameter_prepare(cfg,core,root,out,plan,workers):
    from collections import defaultdict
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.ssm_prepared import fit_feature_coordinate,require_10hz_eeg_proxy_array,require_cached_hb_array
    if serial(plan)!=serial(tak_task_parameter_plan(cfg,core,root)):raise ValueError('Frozen task metadata plan changed')
    syn=json.loads((out/'synthetic_summary.json').read_text())
    if syn['status']!='completed' or syn['terminal_rows']!=108:raise ValueError('Complete synthetic matrix required before new measured access')
    parent=root/cfg['parent'];prep=json.loads((parent/'preparation.json').read_text());coordinates=prep['coordinates']
    audit={}
    for coordinate,co in coordinates.items():
        chunks=[]
        for ref in [r for r in plan['calibration_records'] if r['coordinate']==coordinate]:
            with np.load(parent/'feature_cache'/(ref['id']+'.npz'),allow_pickle=False) as a:chunks.append((a['eeg'].copy(),a['hb'].copy()))
        check=fit_feature_coordinate(chunks)
        differences={key:float(np.max(np.abs(np.asarray(check[key])-np.asarray(co[key])))) for key in ('pc','eeg_factor','hb_factor','sd')}
        if max(differences.values())>1e-12:raise ValueError('Parent development coordinate no longer reproduces')
        audit[coordinate]=differences
    # Copies preserve the original byte identity; their origin is explicit.
    reused=[];(out/'prepared').mkdir(exist_ok=True);(out/'tasks').mkdir(exist_ok=True)
    parent_ids=set(plan['parent_window_ids'])
    for group in plan['groups']:
        ref=group['refs'][0]
        if ref['id'] not in parent_ids:continue
        source=parent/'prepared'/f'{ref["id"]}__90.npz';destination=out/'prepared'/source.name
        if not destination.exists():shutil.copy2(source,destination)
        with np.load(destination,allow_pickle=False) as a:require_cached_hb_array(a);require_10hz_eeg_proxy_array(a,steps=900)
        for arm in core['arms'][:2]:
            stem=f'measured__{group["id"]}__90__joint_full__{arm["name"]}'
            for extension in ('.json','.npz'):
                source=parent/'tasks'/(stem+extension);destination=out/'tasks'/source.name
                if source.exists() and not destination.exists():shutil.copy2(source,destination)
                if source.exists() and source.read_bytes()!=destination.read_bytes():raise ValueError('Inherited task bytes changed')
            reused.append(dict(key=stem,source=str(parent/'tasks'/(stem+'.json'))))
    write_json(out/'inherited_tasks.json',dict(parent=str(parent),rows=reused,not_new_replications=True))
    index=CleanPhysiologyCacheIndex(root/cfg['data']['cache_root']);lookup={r.join_key:r for r in index.records}
    by_record=defaultdict(list)
    for ref in plan['records']:
        if ref['id'] not in parent_ids:by_record[ref['join_key']].append(ref)
    jobs=[(core,str(root),str(out),lookup[key],refs) for key,refs in sorted(by_record.items())]
    results=[];started=time.monotonic()
    with ProcessPoolExecutor(max_workers=workers) as pool:
        futures={pool.submit(_tak_repeat_prepare_record,payload):payload[3].join_key for payload in jobs}
        for future in as_completed(futures):
            results.append(future.result());write_json(out/'progress.json',dict(phase='prepare',terminal_records=len(results),planned_records=len(jobs),elapsed_s=time.monotonic()-started))
    prepared=list(parent_ids);failures=[]
    for ref in [r for r in plan['records'] if r['id'] not in parent_ids]:
        metadata=json.loads((out/'feature_cache'/(ref['id']+'.json')).read_text())
        if metadata['status']!='completed':failures.append(metadata);continue
        co=coordinates[ref['coordinate']]
        with np.load(out/'feature_cache'/(ref['id']+'.npz'),allow_pickle=False) as a:
            y=np.column_stack((a['eeg']@np.asarray(co['pc'])*co['eeg_factor'],a['hb']*co['hb_factor']))
            target,operator=volume_drive_crop(y,dict(eeg=a['eeg_op'],hb=a['hb_op']),90,dt=.1)
        np.savez_compressed(out/'prepared'/f'{ref["id"]}__90.npz',target=target,operator=operator,sd=np.array(co['sd']),
            hb_factor=np.array(co['hb_factor']),fnirs_input=np.array('unified_cached_fnirs_v1'),eeg_proxy_input=np.array('eeg_log_bandpower_10hz_v1'),
            eeg_proxy_rate_hz=np.array(10.),time_s=np.arange(900)*.1)
        prepared.append(ref['id'])
    result=dict(status='completed',planned_records=len(plan['records']),prepared_records=len(prepared),inherited_records=168,
        new_records=len(prepared)-168,coordinates=coordinates,coordinate_audit=audit,failures=failures,record_workers=results,
        raw_EEG_reads=sum(not r.get('cached',False) for r in results),raw_fnirs_reads=0,protected_reads=0,seconds=time.monotonic()-started)
    write_json(out/'preparation.json',result);return result


def _tak_task_predictions(x):
    """Leave an entire support ordinal out; require both training supports/class.

    x has [..., subject, repeat, task, feature] axes. NaNs yield abstentions.
    Equidistant centroids also abstain rather than favoring the first label.
    """
    x=np.asarray(x,float);pred=np.full(x.shape[:-1],-1,dtype=int)
    for fold in range(x.shape[-3]):
        training=np.delete(x,fold,axis=-3);center=training.mean(axis=-3)
        valid=np.isfinite(training).all(axis=(-3,-2,-1))
        test=x[...,fold,:,:]
        distance=np.sum((test[..., :,None,:]-center[...,None,:,:])**2,axis=-1)
        distance=np.where(np.isfinite(distance),distance,np.inf)
        best=np.argmin(distance,axis=-1)
        minimum=distance.min(axis=-1,keepdims=True)
        unique=np.sum(np.isclose(distance,minimum,rtol=1e-12,atol=1e-12),axis=-1)==1
        valid=valid[...,None]&np.isfinite(test).all(axis=-1)&unique
        pred[...,fold,:]=np.where(valid,best,-1)
    return pred


def _tak_task_discrimination(x, *, seed=20261028, permutations=10000):
    x=np.asarray(x,float);n,repeats,classes,_=x.shape
    expected=np.arange(classes);pred=_tak_task_predictions(x)
    subject_accuracy=(pred==expected).mean(axis=(1,2));observed=float(subject_accuracy.mean())
    rng=np.random.default_rng(seed)
    order=np.argsort(rng.random((permutations,n,repeats,classes)),axis=-1)
    shuffled=np.take_along_axis(np.broadcast_to(x,(permutations,)+x.shape),order[...,None],axis=-2)
    null=(_tak_task_predictions(shuffled)==expected).mean(axis=(-3,-2,-1))
    ix=np.random.default_rng(seed).integers(0,n,(2000,n))
    ci=np.quantile(subject_accuracy[ix].mean(1),[.025,.975])
    return dict(planned_subjects=n,planned_tests=pred.size,correct=int((pred==expected).sum()),
        abstentions=int((pred<0).sum()),accuracy=observed,chance=1/classes,
        ci95_low=ci[0],ci95_high=ci[1],permutation_p=(1+np.count_nonzero(null>=observed-1e-12))/(permutations+1),
        null_mean=float(null.mean()),null_q95=float(np.quantile(null,.95)),
        subject_accuracy=subject_accuracy,predictions=pred,null_accuracy=null)


def tak_task_parameter_analyze(out,target):
    cfg=json.loads((out/'resolved_config.json').read_text());core=json.loads((out/'resolved_model_config.json').read_text())
    plan=json.loads((out/'plan.json').read_text());summary=json.loads((out/'measured_summary.json').read_text())
    if cfg['schema']!='shared_driver_tak_task_parameters_v1' or cfg['data']['protected_data']!='forbidden':
        raise ValueError('Exact public task-parameter evidence required')
    if target.parent!=out or target.exists():raise ValueError('Fresh direct-child analysis required')
    if summary['status']!='completed' or summary['terminal_rows']!=len(plan['records'])*3:
        raise ValueError('All planned fits must be terminal')
    rows=[];failures=[];checked=0;max_error=0.;parent_ids=set(plan['parent_window_ids'])
    for group in plan['groups']:
        ref=group['refs'][0];annotation=plan['annotations'][ref['id']]
        for arm in core['arms']:
            relative=Path('tasks')/f'measured__{group["id"]}__90__joint_full__{arm["name"]}.json'
            meta=json.loads((out/relative).read_text());row=meta['rows'][0];fit=meta.get('fit',{})
            if (len(meta['rows'])!=1 or meta['spec']['group']!=group or meta['spec']['arm']!=arm
                    or row['id']!=ref['id'] or row['arm']!=arm['name']):raise ValueError('Task identity/arm mismatch')
            values=dict(id=ref['id'],dataset=ref['dataset'],subject=ref['subject'],record=ref['record'],
                native_group=ref['native_group'],subset_index=ref['subset_index'],analysis_tier=ref['analysis_tier'],
                scope=annotation['scope'],task=annotation['task'],task_repeat=annotation.get('task_repeat',-1),
                eeg_start_s=ref['eeg_start_s'],hb_start_s=ref['hb_start_s'],hb_channel=ref['anchor']['hb_channel'],
                arm=arm['name'],qualified=row['qualified'],fit_status=row['fit_status'],
                inherited=ref['id'] in parent_ids and arm['name']!='tak_tau_beta',source_task=str(relative))
            for key in ('kappa','tau','full_hb_nmse','eeg_nmse','integration_max_training_sd'):values[key]=row.get(key,np.nan)
            values['beta']=row.get('beta',fit.get('neurovascular_gain',np.nan))
            starts=[s['parameter_values'] for s in fit.get('starts',[]) if s['converged']]
            values['converged_starts']=len(starts)
            values['minimum_log_parameter_boundary_distance']=min(fit.get('log_parameter_boundary_distance',[]) or [np.nan])
            for i,name in enumerate(arm['fit']):
                key='beta' if name=='neurovascular_gain' else name
                values[key+'_start_span_pct']=(100*np.ptp(np.asarray(starts)[:,i])/values[key]
                    if row['qualified'] and len(starts)>=2 else np.nan)
            if row['qualified']:
                with np.load((out/relative).with_suffix('.npz'),allow_pickle=False) as a:
                    y,p,sd=a['target'],a['prediction'],a['sd']
                    if y.shape!=(1,900,3) or p.shape!=y.shape or sd.shape!=(1,3):raise ValueError('10Hz tensor mismatch')
                    e=np.mean(((p[0,:-1]-y[0,:-1])/sd[0])**2,axis=0)
                    discrepancy=max(abs(e[1:].mean()-row['full_hb_nmse']),abs(e[0]-row['eeg_nmse']))
                    if discrepancy>1e-10:raise ValueError('Saved score mismatch')
                    max_error=max(max_error,float(discrepancy));checked+=1
            else:failures.append(dict(id=ref['id'],arm=arm['name'],source_task=str(relative),fit_status=row['fit_status']))
            rows.append(values)
    frame=pd.DataFrame(rows);subjects=[];dispersions=[];comparisons=[]
    arms=['tak_repeat_narrow','tak_tau_beta'];parameters={'tak_repeat_narrow':('kappa','tau'),'tak_tau_beta':('tau','beta')}
    fixed=frame[frame.arm.eq('tak_fixed')][['id','qualified','full_hb_nmse']].rename(columns={'qualified':'fixed_qualified','full_hb_nmse':'fixed_full_hb_nmse'})
    for arm in arms:
        part=frame[frame.arm.eq(arm)&frame.scope.eq('parent')].merge(fixed,on='id',validate='one_to_one')
        s,d,c=_tak_repeatability_statistics(part,parameters=parameters[arm],seed=cfg['seed'])
        subjects.append(s.assign(arm=arm));dispersions.append(d.assign(arm=arm));comparisons.append(c.assign(arm=arm))
    # All three arms use exactly the same successful windows in the main fit comparison.
    reconstruction=[]
    for (dataset,tier),part in frame[frame.scope.eq('parent')].groupby(['dataset','analysis_tier']):
        valid=part.groupby('id').qualified.all();common=part[part.id.isin(valid[valid].index)]
        r=dict(dataset=dataset,analysis_tier=tier,planned_windows=part.id.nunique(),paired_windows=int(valid.sum()),subjects=common.subject.nunique())
        for arm in ['tak_fixed']+arms:
            g=common[common.arm.eq(arm)].groupby(['subject','native_group']).full_hb_nmse.mean().groupby('subject').mean()
            r[arm]=float(np.sqrt(g.mean()))
            r[arm+'_qualified']=int(part[part.arm.eq(arm)].qualified.sum())
        r['kappa_tau_minus_tau_beta']=r['tak_repeat_narrow']-r['tak_tau_beta'];reconstruction.append(r)
    groups=[];task_subjects=[];classification=[];prediction_rows=[];contrast_rows=[];accuracy_comparisons=[];nulls={}
    for dataset,tasks in cfg['endpoints']['task_sets'].items():
        identities=sorted(frame[frame.dataset.eq(dataset)].subject.unique());by_arm={}
        for arm in arms:
            params=parameters[arm];reference=np.array([core['fitting']['reference']['neurovascular_gain' if p=='beta' else p] for p in params])
            x=np.full((len(identities),3,len(tasks),2),np.nan)
            for si,subject in enumerate(identities):
                for ti,task in enumerate(tasks):
                    for repeat in range(3):
                        part=frame[frame.dataset.eq(dataset)&frame.subject.eq(subject)&frame.arm.eq(arm)&frame.task.eq(task)&frame.task_repeat.eq(repeat)]
                        complete=len(part)==2 and part.qualified.all()
                        logs=np.log(part[list(params)].to_numpy()).mean(0) if complete else np.full(2,np.nan)
                        if complete:x[si,repeat,ti]=(logs-np.log(reference))/.125
                        groups.append(dict(dataset=dataset,subject=subject,task=task,task_repeat=repeat,arm=arm,
                            admitted_windows=len(part),qualified_windows=int(part.qualified.sum()),requested_windows=2,
                            complete=bool(complete),**{p:np.exp(logs[j]) for j,p in enumerate(params)}))
                    center=x[si,:,ti].mean(0)*.125+np.log(reference)
                    task_subjects.append(dict(dataset=dataset,subject=subject,task=task,arm=arm,
                        complete=bool(np.isfinite(center).all()),**{p:np.exp(center[j]) for j,p in enumerate(params)}))
            result=_tak_task_discrimination(x,seed=cfg['seed'],permutations=cfg['endpoints']['classifier']['null_repeats'])
            by_arm[arm]=result['subject_accuracy'];nulls[dataset+'__'+arm]=result.pop('null_accuracy')
            predictions=result.pop('predictions');result.pop('subject_accuracy')
            classification.append(dict(dataset=dataset,arm=arm,**result))
            for si,subject in enumerate(identities):
                for repeat in range(3):
                    for ti,task in enumerate(tasks):
                        p=int(predictions[si,repeat,ti]);prediction_rows.append(dict(dataset=dataset,arm=arm,subject=subject,
                            heldout_support_ordinal=repeat,task=task,prediction=tasks[p] if p>=0 else 'abstain',correct=p==ti))
            for ds,a,b in cfg['endpoints']['contrasts']:
                if ds!=dataset:continue
                delta=(x[:,:,tasks.index(b)]-x[:,:,tasks.index(a)]).mean(1)*.125
                for j,parameter in enumerate(params):
                    values=delta[:,j];good=values[np.isfinite(values)];n=len(good)
                    ix=np.random.default_rng(cfg['seed']).integers(0,n,(2000,n)) if n else np.empty((0,0),int)
                    ci=np.quantile(good[ix].mean(1),[.025,.975]) if n else [np.nan,np.nan]
                    contrast_rows.append(dict(dataset=dataset,arm=arm,parameter=parameter,reference_task=a,candidate_task=b,
                        planned_subjects=len(identities),paired_subjects=n,positive_subjects=int((good>0).sum()),
                        mean_log_ratio=float(good.mean()) if n else np.nan,ratio_pct=100*np.expm1(good.mean()) if n else np.nan,
                        ci95_low_pct=100*np.expm1(ci[0]),ci95_high_pct=100*np.expm1(ci[1])))
        diff=by_arm[arms[1]]-by_arm[arms[0]];ix=np.random.default_rng(cfg['seed']).integers(0,len(diff),(2000,len(diff)))
        ci=np.quantile(diff[ix].mean(1),[.025,.975]);accuracy_comparisons.append(dict(dataset=dataset,subjects=len(diff),
            tau_beta_minus_kappa_tau=float(diff.mean()),ci95_low=ci[0],ci95_high=ci[1]))
    p=np.array([r['permutation_p'] for r in classification]);order=np.argsort(p);adjusted=np.maximum.accumulate(p[order]*np.arange(len(p),0,-1))
    for i,value in zip(order,adjusted):classification[i]['holm_p']=min(1.,float(value))
    synthetic=[];synthetic_contrasts=[]
    for spec in tak_task_parameter_specs(core,plan,'synthetic'):
        row=json.loads((out/'tasks'/(spec['key']+'.json')).read_text())['rows'][0]
        synthetic.append(dict(**spec['group']['case'],arm=spec['arm']['name'],qualified=row['qualified'],
            **{k:row.get(k,np.nan) for k in ('tau','beta','truth_tau','truth_beta','full_hb_nmse','integration_max_training_sd')}))
    sf=pd.DataFrame(synthetic)
    for (scenario,arm,subject,repeat),part in sf.groupby(['scenario','arm','subject','repeat']):
        a=part[part.task.eq('A')].iloc[0];b=part[part.task.eq('B')].iloc[0]
        for parameter in ('tau','beta'):
            synthetic_contrasts.append(dict(scenario=scenario,arm=arm,subject=subject,repeat=repeat,parameter=parameter,
                qualified=bool(a.qualified and b.qualified),truth_log_ratio=np.log(b['truth_'+parameter]/a['truth_'+parameter]),
                estimated_log_ratio=np.log(b[parameter]/a[parameter]) if a.qualified and b.qualified else np.nan))
    target.mkdir();tables=dict(parameter_estimates=frame,subject_parameters=pd.concat(subjects),dispersion=pd.concat(dispersions),
        reconstruction=pd.DataFrame(reconstruction),native_support_parameters=pd.DataFrame(groups),task_subject_parameters=pd.DataFrame(task_subjects),
        task_classification=pd.DataFrame(classification),task_predictions=pd.DataFrame(prediction_rows),task_contrasts=pd.DataFrame(contrast_rows),
        accuracy_pair_comparison=pd.DataFrame(accuracy_comparisons),synthetic_parameters=sf,synthetic_contrasts=pd.DataFrame(synthetic_contrasts))
    for name,data in tables.items():data.to_csv(target/(name+'.csv'),index=False,encoding='utf-8-sig')
    np.savez_compressed(target/'permutation_nulls.npz',**nulls)
    result=dict(schema='tak_task_parameter_analysis_v1',status='completed',source_run=str(out),planned_windows=len(plan['records']),
        requested_windows=len(plan['records'])+plan['excluded_new_windows'],excluded=plan['excluded'],planned_subjects=24,
        planned_fits=len(frame),qualified_by_arm=frame.groupby('arm').qualified.sum().to_dict(),failures=failures,
        checked_array_rows=checked,max_nmse_discrepancy=max_error,classification=classification,
        accuracy_pair_comparison=accuracy_comparisons,reconstruction=reconstruction,contrasts=contrast_rows,
        numerical=dict(maximum_start_span_pct=frame[[c for c in frame if c.endswith('_start_span_pct')]].max().max(),
            maximum_integration_error=frame.loc[frame.qualified,'integration_max_training_sd'].max(),
            boundary_fits=int((frame.qualified&frame.minimum_log_parameter_boundary_distance.lt(1e-6)).sum())),
        definitions=dict(nrmse='last bin excluded; time/chromophore mean normalized squared error; native-support mean then subject mean then square root',
            classification='within-subject leave-one-support-ordinal out; two 90s estimates form each support geometric center; two training supports per task; nearest centroid in log(parameter/reference)/0.125; incomplete training, missing test or tie abstains; all planned tests remain denominator',
            null='10000 task-label permutations within subject and support ordinal; centroids recomputed; plus-one p; Holm over four dataset/pair tests',
            intervals='2000 subject-cluster percentile bootstrap; parameter/accuracy differences are paired; frozen fits/scales; secondary intervals exploratory',
            contrast='mean subject log(taskB/taskA), then exp minus 1; only subjects with all three complete supports in both tasks; signs are per subject',
            causality='task, recording context, order and preprocessing can be confounded; parameter task association does not establish physiological identifiability'),
        protected_reads=0,raw_signal_reads=0,refits=0)
    write_json(target/'summary.json',result);shutil.copy2(Path(__file__),target/'analysis_source.py')
    return result


def tak_task_parameter_main(args):
    root=args.project_root.resolve();cfg,core=tak_task_parameter_config(args.config,root);out=args.run_dir.resolve()
    if not out.is_relative_to(root/cfg['output_root']) or out==root/cfg['output_root']:raise ValueError('Task-parameter output must be below the owning run root')
    out.mkdir(parents=True,exist_ok=True);lock=(out/'controller.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    for name,value in [('resolved_config.json',cfg),('resolved_model_config.json',core)]:
        path=out/name
        if path.exists() and json.loads(path.read_text())!=serial(value):raise ValueError('Immutable task-parameter contract changed')
        if not path.exists():write_json(path,value)
    stage=args.task_parameter_stage
    if stage in ('synthetic','prepare','pilot','run'):
        if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable supervisor required')
        if not 1<=args.workers<=cfg['resources']['max_workers']:raise ValueError('Workers outside resource envelope')
    if stage=='analyze':
        result=tak_task_parameter_analyze(out,(args.task_parameter_analysis_output or out/'task_parameter_analysis_v1').resolve())
    elif stage=='check':
        from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
        case=dict(subject=0,repeat=0,task='B',scenario='beta_shift')
        y,op,sd,truth=tak_task_parameter_synthetic(core,case)
        if y.shape!=(900,3) or op.shape!=(2700,2700):raise ValueError('Synthetic tensor mismatch')
        driver=truth['driver'][:40];initial=truth['initial_state']
        params=dict(tau=truth['tau'],neurovascular_gain=truth['beta'])
        def forward(values,substeps=2):
            return nonlinear_driver_forward(driver,initial,volume_drive_parameters(core,**values),.1,
                substeps=substeps,numerical_backend='numba',hemodynamics='tak',viscoelastic_s=2.)
        prediction=forward(params);errors={};eps=1e-5
        for name in params:
            hi=forward(dict(params,**{name:params[name]+eps}))['canonical_prediction']
            lo=forward(dict(params,**{name:params[name]-eps}))['canonical_prediction']
            errors[name]=float(np.max(abs((hi-lo)/(2*eps)-prediction[name+'_jacobian'])))
        replay_error=float(np.max(abs(forward(params,8)['canonical_prediction']-prediction['canonical_prediction'])))
        if max(*errors.values(),replay_error)>1e-7:raise ValueError('Tau/beta tangent or replay check failed')
        result=dict(status='passed',shape=list(y.shape),dt_s=.1,parameter_pair=['tau','neurovascular_gain'],
            measured_arrays_read=0,protected_reads=0,truth_beta=truth['beta'],tangent_max_errors=errors,
            integration_refinement_max_error=replay_error)
        write_json(out/'software_checks.json',result)
    elif stage=='plan':
        result=tak_task_parameter_plan(cfg,core,root);path=out/'plan.json'
        if path.exists() and json.loads(path.read_text())!=serial(result):raise ValueError('Immutable task plan changed')
        if not path.exists():write_json(path,result)
    else:
        if json.loads((out/'software_checks.json').read_text())['status']!='passed':raise ValueError('Software checks required')
        plan=json.loads((out/'plan.json').read_text())
        if stage=='prepare':result=tak_task_parameter_prepare(cfg,core,root,out,plan,args.workers)
        else:
            phase='synthetic' if stage=='synthetic' else 'measured';specs=tak_task_parameter_specs(core,plan,phase)
            if stage in ('synthetic','pilot','run'):
                if phase=='measured' and json.loads((out/'preparation.json').read_text())['status']!='completed':raise ValueError('Prepared current inputs required')
                pilot_groups=None
                if stage=='pilot':
                    chosen={}
                    for g in plan['groups']:
                        r=g['refs'][0];chosen.setdefault((r['dataset'],r['task']),g['id'])
                    pilot_groups=set(chosen.values())
                result=tak_run(core,out,plan,phase,args.workers,pilot=stage=='pilot',specs=specs,pilot_groups=pilot_groups)
                if stage!='pilot':result=tak_summarize(core,out,plan,phase,specs=specs)
            else:result=tak_summarize(core,out,plan,'measured',specs=specs)
    print(json.dumps(serial({k:v for k,v in result.items() if k not in ('records','groups','native_groups','calibration_records','annotations','coordinates','record_workers','terminal','paired_contrasts','new_window_ids','parent_window_ids')})),flush=True)


def tak_topography_config(path,root):
    default=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_tak_topography_v1.yaml'
    cfg=yaml.safe_load(Path(path or default).read_text())
    if cfg!=yaml.safe_load(default.read_text()):raise ValueError('Unchanged versioned topography scope required')
    parent=Path(root)/cfg['parent'];previous=json.loads((parent/'resolved_config.json').read_text())
    if previous['schema']!='shared_driver_tak_task_parameters_v1' or previous['data']['protected_data']!='forbidden':raise ValueError('Exact public tau/beta parent required')
    if json.loads((parent/'measured_summary.json').read_text())['status']!='completed':raise ValueError('Completed parameter parent required')
    core=json.loads((parent/'resolved_model_config.json').read_text())
    core.update(schema=cfg['schema'],experiment_id=cfg['experiment_id'],seed=cfg['seed'])
    core['arms']=[a for a in core['arms'] if a['name'] in ('tak_fixed','tak_tau_beta')]
    core['endpoints']['contrasts']=[['tak_fixed','tak_tau_beta']]
    core['claim_limits']=['exploratory_observation_selected_examples_not_population_confirmation',
        'shared_development_coordinate_across_sites_not_per_site_normalization',
        'template_sensor_projection_not_individual_cortical_registration',
        'parameter_maps_are_conditional_estimates_not_physiological_truth']
    core['data']['expected_records']='frozen_topography_plan';return cfg,core


def _tak_topography_subject_plan(cfg,index,geometries,dataset,subject,role):
    from collections import defaultdict
    from src.data.event_alignment import ADMISSIBLE_ALIGNMENT_CASES
    from src.data.tak_mismatch import select_tak_mismatch_channels
    records=[r for r in index.records if r.dataset_id==dataset and r.canonical_subject_id==subject
        and (dataset!='refed' or r.signal_branch=='hbo_hbr')]
    candidates={};record_meta={};excluded=[]
    for record in sorted(records,key=lambda r:r.base_record_id):
        name=record.base_record_id
        wanted=(name in ('session_00','session_02') if dataset=='eeg_fnirs_single_trial' else
            name=='cnt_wg' if dataset=='simultaneous_eeg_nirs' else
            name in ('video_2','video_6') if dataset=='refed' else 'Probe' in name)
        if not wanted:continue
        reports=index.reports_by_join_key.get(record.join_key,[])
        if (not reports or any(r.get('alignment_case') not in ADMISSIBLE_ALIGNMENT_CASES or r.get('label_sequence_match') is False for r in reports)
                or (dataset=='visual_cognitive_motivation' and subject=='S06' and 'part1' in name.lower())):
            excluded.append(dict(record=name,reason='nonadmitted_alignment_or_Visual_S06_Part1'));continue
        m=record.manifest['measurement'];gi=geometries[dataset]
        e=gi.for_channels(record=record,modality='eeg',channel_names=m['eeg_channel_names'])
        h=gi.for_channels(record=record,modality='fnirs',channel_names=m['fnirs_channel_names'])
        pairs=select_tak_mismatch_channels(e,h,seed=cfg['seed'])
        probe=(re.search(r'Probe[12]',name).group() if dataset=='visual_cognitive_motivation' else None)
        for pair in pairs:
            pair['site_id']=(probe+':'+pair['name']) if probe else pair['name']
            try:pair['xy']=_tak_topography_xy(h[pair['component_indices'][0]]).tolist()
            except ValueError:pair['xy']=None
        anchor=dict(hb_channel=pairs[0]['name'],hb_pair=pairs[0]['native_index'],eeg_channels=pairs[0].get('channel_set_names',{}).get('nearest6',[]))
        rows=_tak_repeat_candidates(record,index.events_by_join_key.get(record.join_key,[]),anchor,coordinate=dataset+'__spatial')
        if not rows:excluded.append(dict(record=name,reason='no_admitted_90s_window'));continue
        for row in rows:row.update(region='spatial',site='all_pairs',partition=role)
        candidates[name]=rows;record_meta[name]=dict(join_key=record.join_key,record=name,pairs=pairs,
            eeg_channels=m['eeg_channel_names'],hb_channels=m['fnirs_channel_names'],geometry=dict(eeg=e,fnirs=h),source_files=record.manifest['source_files'])
    chosen=[]
    if dataset=='eeg_fnirs_single_trial' or dataset=='refed':
        names=['session_00','session_02'] if dataset=='eeg_fnirs_single_trial' else ['video_2','video_6']
        if any(n not in candidates for n in names):raise ValueError('Both prespecified native records required')
        chosen=[(candidates[n][0],i) for i,n in enumerate(names)]
    elif dataset=='simultaneous_eeg_nirs':
        support=defaultdict(list)
        for row in candidates.get('cnt_wg',[]):support[row['native_group_key']].append(row)
        groups=sorted(support.values(),key=lambda g:g[0]['eeg_start_s'])
        if len(groups)<2:raise ValueError('Two distinct admitted WG supports required')
        chosen=[(groups[i][0],i) for i in range(2)]
    else:
        stems=sorted({re.sub(r'_Probe[12]$','',name) for name in candidates})
        for stem in stems:
            if stem+'_Probe1' not in candidates or stem+'_Probe2' not in candidates:continue
            a=candidates[stem+'_Probe1'];b={r['event_id']:r for r in candidates[stem+'_Probe2']}
            common=[r for r in a if r['event_id'] in b and abs(r['eeg_start_s']-b[r['event_id']]['eeg_start_s'])<.001]
            selected=_tak_repeat_select(common,2)
            if len(selected)==2 and abs(b[selected[1]['event_id']]['hb_start_s']-b[selected[0]['event_id']]['hb_start_s'])>=90:
                chosen=[(r,i) for i,ref in enumerate(selected) for r in (ref,b[ref['event_id']])];break
        if len(chosen)!=4:raise ValueError('Two matched nonoverlap windows in both Visual probes required')
    windows=[]
    for ref,repeat in chosen:
        record=record_meta[ref['record']]
        windows.append(dict(ref,id=f'{dataset}__{subject}__{ref["record"]}__map{repeat}',map_repeat=repeat,
            pairs=record['pairs'],eeg_channels=record['eeg_channels'],hb_channels=record['hb_channels'],geometry=record['geometry']))
    return dict(id=dataset+'__'+subject,dataset=dataset,subject=subject,role=role,windows=windows,metadata_exclusions=excluded)


def tak_topography_plan(cfg,root):
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.unified_physiology import ChannelGeometryIndex
    parent_plan=json.loads((root/cfg['parent']/'plan.json').read_text())
    training={ds:sorted({r['subject'] for r in parent_plan['calibration_records'] if r['dataset']==ds}) for ds in cfg['data']['datasets']}
    if any(len(s)!=6 for s in training.values()):raise ValueError('Six original development subjects per dataset required')
    cache=root/cfg['data']['cache_root'];index=CleanPhysiologyCacheIndex(cache)
    geometry=ChannelGeometryIndex(cache,geometry_root=root/cfg['data']['geometry_root'])
    geometries={ds:geometry for ds in cfg['data']['datasets']}
    geometries['refed']=ChannelGeometryIndex(cache,geometry_root=root/cfg['data']['refed_geometry_root'])
    identities=sorted({(r.dataset_id,r.canonical_subject_id) for r in index.records if r.dataset_id in cfg['data']['datasets']})
    subjects=[];excluded=[]
    for ds,subject in identities:
        role='development' if subject in training[ds] else 'candidate'
        try:subjects.append(_tak_topography_subject_plan(cfg,index,geometries,ds,subject,role))
        except (ValueError,KeyError,TypeError) as exc:excluded.append(dict(dataset=ds,subject=subject,role=role,reason=str(exc)))
    if any(r['role']=='development' for r in excluded):raise ValueError('Original development coverage incomplete: '+str(excluded))
    return dict(schema='tak_topography_plan_v1',subjects=subjects,excluded=excluded,development_subjects=training,
        registered_subjects=len(identities),planned_candidates=sum(s['role']=='candidate' for s in subjects),
        planned_development=sum(s['role']=='development' for s in subjects),measured_signal_reads=0,protected_reads=0)


def _tak_topography_screen_score(a,b,minimum_fraction=.8):
    from scipy.stats import spearmanr
    keys=sorted(set(a)|set(b));common=[k for k in keys if k in a and k in b and np.isfinite([a[k],b[k]]).all() and min(a[k],b[k])>0]
    result=dict(planned_sites=len(keys),common_sites=len(common),coverage=len(common)/len(keys) if keys else 0.,eligible=False,
        score=np.nan,rank_correlation=np.nan,minimum_log_spatial_range=np.nan)
    if len(common)<3 or len(common)<minimum_fraction*len(keys):return result
    x=np.log([a[k] for k in common]);y=np.log([b[k] for k in common])
    rho=float(spearmanr(x,y).statistic) if min(np.std(x),np.std(y))>0 else 0.
    spread=min(float(np.diff(np.quantile(z,[.1,.9]))[0]) for z in (x,y))
    result.update(eligible=True,score=max(0.,rho)*spread,rank_correlation=rho,minimum_log_spatial_range=spread)
    return result


def _tak_topography_screen_worker(payload):
    cfg,root_string,out_string,subject=payload;root,out=Path(root_string),Path(out_string)
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.unified_physiology import load_cached_fnirs_record
    from src.inference.observation_baselines import disjoint_native_bin_operator
    path=out/'screen'/(subject['id']+'.json')
    if path.exists():return json.loads(path.read_text())
    index=CleanPhysiologyCacheIndex(root/cfg['data']['cache_root']);records={r.join_key:r for r in index.records}
    maps=[{},{}];failures=[];cache={};started=time.monotonic()
    for ref in subject['windows']:
        target=out/'spatial_features'/(ref['id']+'.npz');target.parent.mkdir(exist_ok=True)
        try:
            if ref['join_key'] not in cache:cache[ref['join_key']]=load_cached_fnirs_record(root,records[ref['join_key']])
            c=cache[ref['join_key']];take=(c['time_s']>=ref['hb_start_s'])&(c['time_s']<ref['hb_start_s']+90)
            op=disjoint_native_bin_operator(c['time_s'][take]-ref['hb_start_s'],steps=900,dt=.1,reference_steps=50)
            count=len(ref['pairs']);hb=(op['raw']@c['values'][take].reshape(take.sum(),-1)).reshape(900,count,2)
            valid=np.asarray(c['valid_mask'][take].all(axis=(0,2)))&np.isfinite(hb).all(axis=(0,2))
            np.savez_compressed(target,hb=hb,hb_op=op['model'],valid=valid)
            for pair in ref['pairs']:
                i=pair['native_index'];good=bool(valid[i] and pair['status']=='available' and pair['xy'] is not None)
                maps[ref['map_repeat']][pair['site_id']]=float(np.sqrt(np.var(hb[:-1,i],axis=0).mean())) if good else np.nan
            write_json(target.with_suffix('.json'),dict(status='completed',ref=ref,fnirs_provenance=c['provenance']))
        except Exception as exc:
            failures.append(dict(id=ref['id'],reason=repr(exc)))
            for pair in ref['pairs']:maps[ref['map_repeat']][pair['site_id']]=np.nan
            write_json(target.with_suffix('.json'),dict(status='failed',ref=ref,error=repr(exc)))
    result=dict(id=subject['id'],dataset=subject['dataset'],subject=subject['subject'],role=subject['role'],
        **_tak_topography_screen_score(*maps,minimum_fraction=cfg['screen']['minimum_common_site_fraction']),
        maps=maps,failures=failures,seconds=time.monotonic()-started,protected_reads=0,raw_reads=0)
    write_json(path,result);return result


def tak_topography_screen(cfg,root,out,plan,workers):
    syn=json.loads((out/'synthetic_summary.json').read_text())
    if syn['status']!='completed' or syn['terminal_rows']!=96:raise ValueError('Complete spatial synthetic matrix required before measured screen')
    if serial(plan)!=serial(tak_topography_plan(cfg,root)):raise ValueError('Frozen public metadata changed')
    rows=[];started=time.monotonic()
    with ProcessPoolExecutor(max_workers=workers) as pool:
        iterator=iter(plan['subjects']);active={}
        def submit():
            try:s=next(iterator)
            except StopIteration:return
            active[pool.submit(_tak_topography_screen_worker,(cfg,str(root),str(out),s))]=s['id']
        for _ in range(workers*2):submit()
        while active:
            ready,_=wait(active,return_when=FIRST_COMPLETED)
            for f in ready:rows.append(f.result());active.pop(f);submit()
            write_json(out/'progress.json',dict(phase='screen',terminal=len(rows),planned=len(plan['subjects']),seconds=time.monotonic()-started))
    selected=[]
    for ds in cfg['data']['datasets']:
        candidates=[r for r in rows if r['dataset']==ds and r['role']=='candidate' and r['eligible']]
        ordered=sorted(candidates,key=lambda r:(-r['score'],r['subject']))
        if len(ordered)<3:raise ValueError('Insufficient eligible subjects for spatial case screen: '+ds)
        selected.extend(r['id'] for r in ordered[:3])
    result=dict(schema='tak_topography_screen_v1',status='completed',selected_subject_ids=selected,
        selection_rule=cfg['screen'],subjects=[{k:v for k,v in r.items() if k!='maps'} for r in rows],
        source='screen/*.json_and_spatial_features/*.npz',seconds=time.monotonic()-started,protected_reads=0)
    write_json(out/'screen_summary.json',result);return result


def tak_topography_specs(core,phase):
    if phase!='synthetic':raise ValueError('Spatial synthetic specs only')
    jobs=[]
    for scenario in ('uniform','structured'):
        for subject in (0,1):
            for repeat in (0,1):
                for node in range(6):
                    key=f'{scenario}__s{subject}__r{repeat}__n{node}'
                    case=dict(subject=subject,repeat=repeat,task='A' if repeat==0 else 'B',scenario=scenario,spatial_node=node)
                    group=dict(id=key,case=case,refs=[dict(id=key,dataset='synthetic',subject=f'seed{subject}',record=scenario)])
                    for arm in core['arms']:jobs.append(dict(key=f'synthetic__{key}__90__joint_full__{arm["name"]}',phase='synthetic',group=group,length_s=90,condition='joint_full',arm=arm))
    return jobs


def _tak_topography_eeg_worker(payload):
    cfg,core,root_string,out_string,subject=payload;root,out=Path(root_string),Path(out_string)
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    from src.data.unified_physiology import load_native_eeg_record,canonical_channel_name
    from src.inference.observation_baselines import eeg_band_power
    index=CleanPhysiologyCacheIndex(root/cfg['data']['cache_root']);lookup={r.join_key:r for r in index.records}
    native_cache={};power_cache={};rows=[];started=time.monotonic()
    for ref in subject['windows']:
        path=out/'spatial_features'/(ref['id']+'_eeg.npz');meta=path.with_suffix('.json')
        if meta.exists():rows.append(json.loads(meta.read_text()));continue
        try:
            record=lookup[ref['join_key']]
            if record.manifest['source_files']!=ref['source_files']:raise ValueError('Frozen registered native EEG source changed')
            if ref['join_key'] not in native_cache:native_cache[ref['join_key']]=load_native_eeg_record(root,record)
            native=native_cache[ref['join_key']];start=round(ref['eeg_start_s']*native.sample_rate_hz);n=round(90*native.sample_rate_hz)
            key=(str(native.source_path),start,n)
            if key not in power_cache:
                channels={canonical_channel_name(str(name)).upper():i for i,name in enumerate(native.channel_names)}
                indices=[channels[canonical_channel_name(name).upper()] for name in ref['eeg_channels']]
                values=native.values[start:start+n,indices]
                if start<0 or len(values)!=n:raise ValueError('Incomplete native 90s EEG window')
                valid=np.isfinite(values).all(0);features=np.full((900,len(indices),5),np.nan)
                if valid.any():
                    power=eeg_band_power(values[:,valid],bands=core['tensor']['eeg_bands_hz'],sample_rate=native.sample_rate_hz,target_rate=10.)
                    if np.any(power<=0):raise ValueError('Nonpositive EEG power')
                    features[:,valid]=np.log(power);features[:,valid]-=features[:50,valid].mean(0,keepdims=True)
                power_cache[key]=features
            features=power_cache[key]
            if features.shape!=(900,len(ref['eeg_channels']),5):raise ValueError('EEG feature/channel identity mismatch')
            np.savez_compressed(path,eeg=features)
            result=dict(id=ref['id'],status='completed',source=str(native.source_path),native_rate=native.sample_rate_hz,
                native_unit=native.native_unit,eeg_proxy_rate_hz=10.,reference_steps=50,
                channels=ref['eeg_channels'],valid_channels=int(np.isfinite(features).all(axis=(0,2)).sum()))
        except Exception as exc:result=dict(id=ref['id'],status='failed',error=repr(exc))
        write_json(meta,result);rows.append(result)
    return dict(id=subject['id'],rows=rows,seconds=time.monotonic()-started,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)


def tak_topography_prepare(cfg,core,root,out,plan,workers):
    from src.data.ssm_prepared import fit_feature_coordinate
    if serial(plan)!=serial(tak_topography_plan(cfg,root)):raise ValueError('Frozen public plan changed before native reads')
    screen=json.loads((out/'screen_summary.json').read_text())
    if screen['status']!='completed':raise ValueError('Completed frozen case selection required')
    selected=set(screen['selected_subject_ids']);subjects=[s for s in plan['subjects'] if s['role']=='development' or s['id'] in selected]
    if len(selected)!=12 or any(s['role']=='development' and s['id'] in selected for s in subjects):raise ValueError('Three candidate subjects per dataset disjoint from development required')
    details=[];started=time.monotonic()
    with ProcessPoolExecutor(max_workers=workers) as pool:
        jobs={pool.submit(_tak_topography_eeg_worker,(cfg,core,str(root),str(out),s)):s['id'] for s in subjects}
        for f in as_completed(jobs):
            details.append(f.result());write_json(out/'progress.json',dict(phase='native_features',terminal=len(details),planned=len(subjects),seconds=time.monotonic()-started))
    coordinates={};coordinate_sources={}
    def features(ref):
        h=out/'spatial_features'/(ref['id']+'.npz');e=out/'spatial_features'/(ref['id']+'_eeg.npz')
        if not h.exists() or not e.exists():return None
        with np.load(h,allow_pickle=False) as a:hb=a['hb'];op=a['hb_op'];valid=a['valid']
        with np.load(e,allow_pickle=False) as a:eeg=a['eeg']
        return eeg,hb,valid,op
    for ds in cfg['data']['datasets']:
        sources=[]
        def chunks():
            for subject in subjects:
                if subject['dataset']!=ds or subject['role']!='development':continue
                for ref in subject['windows']:
                    arrays=features(ref)
                    if arrays is None:continue
                    eeg,hb,valid,_=arrays
                    for pair in ref['pairs']:
                        if pair['status']!='available' or not valid[pair['native_index']]:continue
                        x=eeg[:,pair['channel_sets']['nearest6']].reshape(900,30);y=hb[:,pair['native_index']]
                        if not np.isfinite(x).all():continue
                        sources.append(dict(subject=subject['subject'],window=ref['id'],site=pair['site_id']))
                        yield x,y
        co=fit_feature_coordinate(chunks())
        if {s['subject'] for s in sources}!=set(plan['development_subjects'][ds]):raise ValueError('All six original development subjects must contribute the shared spatial coordinate')
        coordinates[ds]=co;coordinate_sources[ds]=sources
    write_json(out/'spatial_coordinates.json',dict(schema='tak_spatial_coordinate_v1',coordinates=coordinates,training_sources=coordinate_sources,
        grouping='one_common_coordinate_per_dataset_all_regions_both_repeats',evaluation_subjects_used=False))
    (out/'prepared').mkdir(exist_ok=True);refs=[];groups=[];failures=[];spatial_subjects=[]
    for subject in subjects:
        if subject['id'] not in selected:continue
        spatial_subjects.append(subject)
        for ref in subject['windows']:
            arrays=features(ref);co=coordinates[ref['dataset']]
            for pair in ref['pairs']:
                key=ref['id']+'__'+pair['site_id'].replace(':','_')
                item={k:ref[k] for k in ('dataset','subject','record','join_key','eeg_start_s','hb_start_s','map_repeat','condition_counts','alignment_support','native_session')}
                item.update(id=key,site_id=pair['site_id'],xy=pair['xy'],window_id=ref['id'],hb_pair=pair['native_index'],
                    eeg_channels=pair.get('channel_set_names',{}).get('nearest6',[]),native_group=key,geometry_status=pair['status'])
                refs.append(item);groups.append(dict(id=f'g{len(groups):04d}',refs=[item]))
                destination=out/'prepared'/(key+'__90.npz')
                if destination.exists():continue
                try:
                    if arrays is None or pair['status']!='available' or pair['xy'] is None:raise ValueError('Unavailable features or geometry')
                    eeg,hb,valid,hb_op=arrays;i=pair['native_index']
                    x=eeg[:,pair['channel_sets']['nearest6']].reshape(900,30)
                    if not valid[i] or not np.isfinite(x).all():raise ValueError('Unavailable Hb pair or required EEG channel')
                    y=np.column_stack((x@np.asarray(co['pc'])*co['eeg_factor'],hb[:,i]*co['hb_factor']))
                    eeg_op=np.eye(900);eeg_op[:,:50]-=1/50
                    target,operator=volume_drive_crop(y,dict(eeg=eeg_op,hb=hb_op),90,dt=.1)
                    np.savez_compressed(destination,target=target,operator=operator,sd=np.array(co['sd']),hb_factor=np.array(co['hb_factor']),
                        fnirs_input=np.array('unified_cached_fnirs_v1'),eeg_proxy_input=np.array('eeg_log_bandpower_10hz_v1'),
                        eeg_proxy_rate_hz=np.array(10.),time_s=np.arange(900)*.1)
                except Exception as exc:failures.append(dict(id=key,error=repr(exc)))
    measured=dict(schema='tak_topography_measured_plan_v1',records=refs,groups=groups,subjects=spatial_subjects,
        selected_subject_ids=screen['selected_subject_ids'],selection_source='screen_summary.json',planned_windows=len(refs),protected_reads=0)
    path=out/'measured_plan.json'
    if path.exists() and json.loads(path.read_text())!=serial(measured):raise ValueError('Immutable measured spatial plan changed')
    if not path.exists():write_json(path,measured)
    result=dict(status='completed',planned_windows=len(refs),prepared_windows=sum((out/'prepared'/(r['id']+'__90.npz')).exists() for r in refs),
        failures=failures,coordinates='spatial_coordinates.json',feature_workers=details,seconds=time.monotonic()-started,raw_fnirs_reads=0,protected_reads=0)
    write_json(out/'preparation.json',result);return result


def _tak_topography_map_statistics(locations):
    """Describe paired map shape without treating locations as subjects."""
    from scipy.stats import spearmanr
    from itertools import combinations
    repeat_rows=[];means=[];between=[];regions=[]
    def rho(a,b):
        return float(spearmanr(a,b).statistic) if len(a)>=3 and min(np.std(a),np.std(b))>1e-12 else np.nan
    for (ds,subject),part in locations.groupby(['dataset','subject'],sort=True):
        a=part[part.map_repeat.eq(0)].set_index('location_id');b=part[part.map_repeat.eq(1)].set_index('location_id')
        planned=sorted(set(a.index)|set(b.index));common=sorted(set(a[a.complete].index)&set(b[b.complete].index))
        for parameter in ('tau','beta'):
            x=np.log(a.loc[common,parameter].to_numpy(float));y=np.log(b.loc[common,parameter].to_numpy(float))
            center=(x+y)/2;cx=x-x.mean() if len(x) else x;cy=y-y.mean() if len(y) else y
            record=dict(dataset=ds,subject=subject,parameter=parameter,planned_locations=len(planned),paired_locations=len(common),
                coverage=len(common)/len(planned) if planned else 0.,spearman=rho(x,y),
                absolute_log_rms=float(np.sqrt(np.mean((x-y)**2))) if len(x) else np.nan,
                centered_log_rms=float(np.sqrt(np.mean((cx-cy)**2))) if len(x) else np.nan,
                mean_map_geometric_center=float(np.exp(center.mean())) if len(center) else np.nan,
                mean_map_spatial_range_pct=100*np.expm1(np.quantile(center,.9)-np.quantile(center,.1)) if len(center) else np.nan,
                median_hb_relative_rmse=float(np.median(np.r_[a.loc[common,'hb_relative_rmse'],b.loc[common,'hb_relative_rmse']])) if len(common) else np.nan)
            repeat_rows.append(record)
            for key,value in zip(common,center):
                row=a.loc[key];ratio=(float(value-center.mean()))
                means.append(dict(dataset=ds,subject=subject,parameter=parameter,location_id=key,x=row.x,y=row.y,
                    value=float(np.exp(value)),centered_log=ratio,relative_percent=100*np.expm1(ratio),
                    member_sites=row.member_sites,member_count=int(row.member_count)))
    mean_frame=pd.DataFrame(means,columns=['dataset','subject','parameter','location_id','x','y','value','centered_log','relative_percent','member_sites','member_count'])
    for (ds,parameter),part in mean_frame.groupby(['dataset','parameter'],sort=True):
        for a,b in combinations(sorted(part.subject.unique()),2):
            left=part[part.subject.eq(a)].set_index('location_id');right=part[part.subject.eq(b)].set_index('location_id')
            common=sorted(set(left.index)&set(right.index));x=np.log(left.loc[common,'value'].to_numpy());y=np.log(right.loc[common,'value'].to_numpy())
            if len(x):cx=x-x.mean();cy=y-y.mean()
            between.append(dict(dataset=ds,parameter=parameter,subject_a=a,subject_b=b,common_locations=len(common),spearman=rho(x,y),
                absolute_log_rms=float(np.sqrt(np.mean((x-y)**2))) if len(x) else np.nan,
                centered_log_rms=float(np.sqrt(np.mean((cx-cy)**2))) if len(x) else np.nan))
        for subject,g in part.groupby('subject'):
            for region,v in g.assign(region=np.where(g.y>.33,'anterior',np.where(g.y<-.33,'posterior','central'))).groupby('region'):
                regions.append(dict(dataset=ds,subject=subject,parameter=parameter,projection_region=region,
                    locations=len(v),geometric_mean=float(np.exp(np.log(v.value).mean())),
                    interpretation='coarse_sensor_projection_region_not_cortical_parcellation'))
    repeats=pd.DataFrame(repeat_rows);other=pd.DataFrame(between,columns=['dataset','parameter','subject_a','subject_b','common_locations','spearman','absolute_log_rms','centered_log_rms']);datasets=[]
    for (ds,parameter),g in repeats.groupby(['dataset','parameter']):
        bb=other[(other.dataset==ds)&(other.parameter==parameter)]
        within=float(np.sqrt(np.mean(g.centered_log_rms**2)));inter=float(np.sqrt(np.mean(bb.centered_log_rms**2))) if len(bb) else np.nan
        datasets.append(dict(dataset=ds,parameter=parameter,selected_subjects=len(g),subject_pairs=len(bb),
            median_within_spearman=float(g.spearman.dropna().median()) if g.spearman.notna().any() else np.nan,
            median_between_spearman=float(bb.spearman.dropna().median()) if len(bb) and bb.spearman.notna().any() else np.nan,
            within_centered_log_rms=within,between_centered_log_rms=inter,between_within_shape_ratio=inter/within if within>1e-12 else np.nan))
    return dict(repeatability=repeats,mean_maps=mean_frame,between_subject=other,regions=pd.DataFrame(regions,columns=['dataset','subject','parameter','projection_region','locations','geometric_mean','interpretation']),dataset_summary=pd.DataFrame(datasets))


def _tak_topography_identity_impact(plan,audit):
    """Trace the independently documented Visual name defect to this frozen plan."""
    if audit.get('schema')!='visual_channel_identity_audit_v2':raise ValueError('Documented native-channel identity audit required')
    named={r['current'].upper():r for r in audit['channel_comparison'] if r['current'] is not None}
    rows=[]
    for ref in plan['records']:
        if ref['dataset']!='visual_cognitive_motivation':continue
        bad=[]
        for channel in ref['eeg_channels']:
            row=named[channel.upper()]
            if not row['matches']:bad.append(dict(declared=channel,actual=row['documented'],raw_channel=row['raw_channel']))
        rows.append(dict(id=ref['id'],subject=ref['subject'],site_id=ref['site_id'],map_repeat=ref['map_repeat'],mismatched_local_channels=bad))
    return dict(schema='tak_topography_identity_impact_v1',dataset='visual_cognitive_motivation',
        interpretation='diagnostic_only_invalid_EEG_identity',planned_cells=len(rows),
        cells_with_directly_mismatched_local_channels=sum(bool(r['mismatched_local_channels']) for r in rows),
        reason='Frozen native reader uses Location.ced Number as raw A-channel ID and excludes A64/FCz; shared coordinate also inherits this mapping. All Visual maps lack the declared local EEG identity, including positions whose nearest-six names happen to match.',
        cells=rows)


def tak_topography_analyze(out,target):
    from scipy.stats import spearmanr
    cfg=json.loads((out/'resolved_config.json').read_text());core=json.loads((out/'resolved_model_config.json').read_text())
    plan=json.loads((out/'measured_plan.json').read_text());summary=json.loads((out/'measured_summary.json').read_text())
    if cfg['schema']!='shared_driver_tak_topography_v1' or cfg['data']['protected_data']!='forbidden':raise ValueError('Public spatial contract required')
    if target.exists() or target.parent!=out:raise ValueError('Fresh direct-child spatial analysis required')
    if summary['status']!='completed' or summary['terminal_rows']!=2*len(plan['records']):raise ValueError('All spatial fitting tasks must be terminal')
    audit_path=CODE_ROOT/'comparative_methods/runs/performance_analysis/20261029_visual_investigation_v1/channel_identity_audit_v2.json'
    identity=_tak_topography_identity_impact(plan,json.loads(audit_path.read_text()))
    identity['owning_audit']=str(audit_path)
    identity['frozen_reader']=str(out/'data_source_snapshot_v2/src/data/unified_physiology.py')
    rows=[];failures=[];checked=0;max_error=0.;spans=[]
    for group in plan['groups']:
        ref=group['refs'][0];arms={}
        for arm in core['arms']:
            path=out/'tasks'/f'measured__{group["id"]}__90__joint_full__{arm["name"]}.json';task=json.loads(path.read_text())
            if task['spec']['group']!=group or task['spec']['arm']!=arm or len(task['rows'])!=1 or task['rows'][0]['id']!=ref['id']:raise ValueError('Spatial task identity mismatch')
            row=task['rows'][0];fit=task.get('fit',{});detail=dict(row)
            if row['qualified']:
                with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
                    y,p,sd=a['target'],a['prediction'],a['sd']
                    if y.shape!=(1,900,3) or p.shape!=y.shape or sd.shape!=(1,3):raise ValueError('Spatial retained array shape mismatch')
                    err=np.mean(((p[0,:-1]-y[0,:-1])/sd[0])**2,axis=0)
                    difference=max(abs(err[1:].mean()-row['full_hb_nmse']),abs(err[0]-row['eeg_nmse']))
                    if difference>1e-9:raise ValueError('Spatial score mismatch')
                    checked+=1;max_error=max(max_error,float(difference))
                    dynamic=float(np.sqrt(np.var(y[0,:-1,1:],axis=0).mean()));neural=float(np.std(y[0,:-1,0]))
                    detail.update(hb_relative_rmse=float(np.sqrt(np.mean((p[0,:-1,1:]-y[0,:-1,1:])**2))/dynamic) if dynamic>0 else np.nan,
                        hb_eeg_amplitude_ratio=dynamic/neural if neural>0 else np.nan)
            else:failures.append(dict(id=ref['id'],arm=arm['name'],status=row['fit_status'],source_task=str(path.relative_to(out))))
            detail['source_task']=str(path.relative_to(out))
            detail['boundary']=min(fit.get('log_parameter_boundary_distance',[]) or [np.inf])<=1e-6
            values=[s['parameter_values'] for s in fit.get('starts',[]) if s['converged']]
            if row['qualified'] and arm['fit'] and len(values)>1:
                spans.extend((100*np.ptp(np.asarray(values),axis=0)/np.asarray(fit['parameter_values'])).tolist())
            arms[arm['name']]=detail
        free=arms['tak_tau_beta'];fixed=arms['tak_fixed']
        rows.append(dict(id=ref['id'],dataset=ref['dataset'],subject=ref['subject'],record=ref['record'],site_id=ref['site_id'],
            map_repeat=ref['map_repeat'],x=ref['xy'][0] if ref['xy'] is not None else np.nan,y=ref['xy'][1] if ref['xy'] is not None else np.nan,
            qualified=free['qualified'],fixed_qualified=fixed['qualified'],fit_status=free['fit_status'],tau=free.get('tau',np.nan),beta=free.get('beta',np.nan),
            full_hb_nmse=free.get('full_hb_nmse',np.nan),fixed_full_hb_nmse=fixed.get('full_hb_nmse',np.nan),eeg_nmse=free.get('eeg_nmse',np.nan),
            hb_relative_rmse=free.get('hb_relative_rmse',np.nan),hb_eeg_amplitude_ratio=free.get('hb_eeg_amplitude_ratio',np.nan),
            boundary=free['boundary'],integration_max_training_sd=free.get('integration_max_training_sd',np.nan),source_task=free['source_task']))
    frame=pd.DataFrame(rows);locations=[]
    for (ds,subject,repeat),part in frame.groupby(['dataset','subject','map_repeat'],sort=True):
        grouped={}
        for row in part.to_dict('records'):
            key=(round(row['x'],6),round(row['y'],6)) if np.isfinite([row['x'],row['y']]).all() else ('missing',row['site_id'])
            grouped.setdefault(key,[]).append(row)
        for members in grouped.values():
            complete=all(r['qualified'] for r in members);first=members[0];site_names=sorted(r['site_id'] for r in members)
            values={p:float(np.exp(np.mean(np.log([r[p] for r in members])))) if complete else np.nan for p in ('tau','beta')}
            locations.append(dict(dataset=ds,subject=subject,map_repeat=repeat,location_id='|'.join(site_names),
                x=first['x'],y=first['y'],member_sites=json.dumps(site_names),member_count=len(members),complete=complete,
                qualified_channels=sum(r['qualified'] for r in members),boundary=any(r['boundary'] for r in members),
                hb_relative_rmse=float(np.mean([r['hb_relative_rmse'] for r in members])) if complete else np.nan,
                hb_eeg_amplitude_ratio=float(np.exp(np.mean(np.log([r['hb_eeg_amplitude_ratio'] for r in members])))) if complete else np.nan,**values))
    loc=pd.DataFrame(locations);stats=_tak_topography_map_statistics(loc)
    reconstruction=[]
    for ds,g in frame.groupby('dataset'):
        common=g[g.qualified&g.fixed_qualified];entry=dict(dataset=ds,planned_cells=len(g),qualified_free=int(g.qualified.sum()),qualified_fixed=int(g.fixed_qualified.sum()),paired_cells=len(common))
        for label,column in [('free','full_hb_nmse'),('fixed','fixed_full_hb_nmse')]:
            value=common.groupby(['subject','map_repeat'])[column].mean().groupby('subject').mean()
            entry[label+'_hb_nrmse']=float(np.sqrt(value.mean())) if len(value) else np.nan
        entry['fixed_minus_free']=entry['fixed_hb_nrmse']-entry['free_hb_nrmse'];reconstruction.append(entry)
    associations=[]
    for (ds,subject,repeat),g in loc[loc.complete].groupby(['dataset','subject','map_repeat']):
        z=g[np.isfinite(g.hb_eeg_amplitude_ratio)&g.hb_eeg_amplitude_ratio.gt(0)]
        associations.append(dict(dataset=ds,subject=subject,map_repeat=repeat,locations=len(z),
            beta_vs_Hb_EEG_amplitude_ratio_Spearman=float(spearmanr(z.beta,z.hb_eeg_amplitude_ratio).statistic) if len(z)>=3 else np.nan))
    synthetic=[]
    for spec in tak_topography_specs(core,'synthetic'):
        row=json.loads((out/'tasks'/(spec['key']+'.json')).read_text())['rows'][0];case=spec['group']['case']
        synthetic.append(dict(scenario=case['scenario'],subject=case['subject'],map_repeat=case['repeat'],node=case['spatial_node'],arm=spec['arm']['name'],qualified=row['qualified'],
            **{k:row.get(k,np.nan) for k in ('tau','beta','truth_tau','truth_beta','full_hb_nmse')}))
    sf=pd.DataFrame(synthetic);synthetic_summary={}
    for p in ('tau','beta'):
        null=sf[sf.arm.eq('tak_tau_beta')&sf.scenario.eq('uniform')&sf.qualified]
        structured=sf[sf.arm.eq('tak_tau_beta')&sf.scenario.eq('structured')&sf.qualified]
        synthetic_summary[p]=dict(uniform_max_apparent_spatial_range_pct=max(100*(g[p].max()/g[p].min()-1) for _,g in null.groupby(['subject','map_repeat'])),
            structured_truth_spearman=[float(spearmanr(g[p],g['truth_'+p]).statistic) for _,g in structured.groupby(['subject','map_repeat'])])
    ranking=[]
    for (ds,subject),g in stats['repeatability'].groupby(['dataset','subject']):
        good=frame[frame.dataset.eq(ds)&frame.subject.eq(subject)]
        ranking.append(dict(dataset=ds,subject=subject,minimum_parameter_repeat_spearman=float(g.spearman.min(skipna=False)),
            mean_spatial_range_pct=float(g.mean_map_spatial_range_pct.mean()),qualified_cells=int(good.qualified.sum()),planned_cells=len(good),
            median_hb_relative_rmse=float(good.loc[good.qualified,'hb_relative_rmse'].median())))
    ranks=pd.DataFrame(ranking).sort_values(['dataset','minimum_parameter_repeat_spearman','mean_spatial_range_pct'],ascending=[True,False,False])
    ranks['candidate_role']=np.where(ranks.dataset.eq(identity['dataset']),identity['interpretation'],'illustrative_parameter_map')
    target.mkdir();tables=dict(parameter_cells=frame,location_estimates=loc,reconstruction=pd.DataFrame(reconstruction),input_associations=pd.DataFrame(associations),
        synthetic_cells=sf,display_ranking=ranks,**stats)
    for name,table in tables.items():table.to_csv(target/(name+'.csv'),index=False,encoding='utf-8-sig')
    write_json(target/'data_identity_impact.json',identity)
    result=dict(schema='tak_topography_analysis_v1',status='completed',source_run=str(out),selected_subject_ids=plan['selected_subject_ids'],
        planned_cells=len(frame),qualified_free=int(frame.qualified.sum()),qualified_fixed=int(frame.fixed_qualified.sum()),failures=failures,
        checked_array_rows=checked,max_nmse_discrepancy=max_error,numerical=dict(maximum_start_span_pct=max(spans,default=np.nan),
        boundary_cells=int(frame.boundary.sum()),maximum_integration_difference=float(frame.loc[frame.qualified,'integration_max_training_sd'].max())),
        dataset_summary=stats['dataset_summary'].to_dict('records'),reconstruction=reconstruction,synthetic=synthetic_summary,
        data_identity=dict(dataset=identity['dataset'],interpretation=identity['interpretation'],
            source='data_identity_impact.json',owning_audit=str(audit_path),planned_cells=identity['planned_cells'],
            cells_with_directly_mismatched_local_channels=identity['cells_with_directly_mismatched_local_channels']),
        definitions=dict(locations='geometric mean of all channels at an identical rounded registered XY; incomplete location stays unavailable; channel memberships retained',
            repeat='Spearman across common complete locations for A/B; centered log RMS removes each map own mean on the common location set',
            between='compare subject geometric A/B mean maps on common locations; centered log RMS removes global parameter level; subject pairs are dependent',
            spatial_range='100*(exp(P90(log parameter)-P10(log parameter))-1) on each subject A/B mean map',
            relative_map='100*(parameter divided by that subject spatial geometric mean minus 1); absolute maps remain separate',
            reconstruction='paired successful native channels; time and Hb species NMSE then channels within map, repeats within subject, subjects equal, square root',
            hb_relative_rmse='model-coordinate pooled Hb residual RMS divided by pooled time-centered target Hb RMS; differs from training-SD NRMSE',
            inference='exploratory selected cases; channels are dependent measurements; no population significance or physiological identification'),
        protected_reads=0,raw_signal_reads=0,refits=0)
    write_json(target/'summary.json',result);shutil.copy2(Path(__file__),target/'analysis_source.py');return result


def tak_topography_main(args):
    root=args.project_root.resolve();cfg,core=tak_topography_config(args.config,root);out=args.run_dir.resolve()
    if not out.is_relative_to(root/cfg['output_root']) or out==root/cfg['output_root']:raise ValueError('Existing Tak run namespace required')
    out.mkdir(parents=True,exist_ok=True);lock=(out/'controller.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    for name,value in [('resolved_config.json',cfg),('resolved_model_config.json',core)]:
        path=out/name
        if path.exists() and json.loads(path.read_text())!=serial(value):raise ValueError('Immutable topography contract changed')
        if not path.exists():write_json(path,value)
    stage=args.topography_stage
    if stage in ('synthetic','screen','prepare','pilot','run'):
        if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable supervisor required')
        if not 1<=args.workers<=cfg['resources']['max_workers']:raise ValueError('Worker envelope exceeded')
    if stage=='analyze':
        result=tak_topography_analyze(out,(args.topography_analysis_output or out/'topography_analysis_v1').resolve())
    elif stage=='check':
        case=dict(subject=0,repeat=0,task='A',scenario='structured',spatial_node=0)
        y,op,sd,truth=tak_task_parameter_synthetic(core,case)
        if y.shape!=(900,3) or op.shape!=(2700,2700) or len(tak_topography_specs(core,'synthetic'))!=96:raise ValueError('Spatial tensor/spec mismatch')
        np.testing.assert_allclose(_tak_topography_xy(dict(x=.95,y=.309,z=-.03,coordinate_system='EEGLAB_CED_cartesian')),[-.309,.95])
        result=dict(status='passed',shape=list(y.shape),synthetic_tasks=96,geometry_axis_check='passed',measured_signal_reads=0,protected_reads=0)
        write_json(out/'software_checks.json',result)
    elif stage=='plan':
        result=tak_topography_plan(cfg,root);path=out/'plan.json'
        if path.exists() and json.loads(path.read_text())!=serial(result):raise ValueError('Immutable public inventory changed')
        if not path.exists():write_json(path,result)
    else:
        if json.loads((out/'software_checks.json').read_text())['status']!='passed':raise ValueError('Software checks required')
        plan=json.loads((out/'plan.json').read_text())
        if stage=='screen':result=tak_topography_screen(cfg,root,out,plan,args.workers)
        elif stage=='prepare':result=tak_topography_prepare(cfg,core,root,out,plan,args.workers)
        else:
            phase='synthetic' if stage=='synthetic' else 'measured'
            if phase=='synthetic':specs=tak_topography_specs(core,phase)
            else:
                if json.loads((out/'preparation.json').read_text())['status']!='completed':raise ValueError('Completed spatial preparation required')
                plan=json.loads((out/'measured_plan.json').read_text());specs=tak_specs(core,plan,phase)
            pilots=None
            if stage=='pilot':
                chosen={}
                for g in plan['groups']:
                    r=g['refs'][0]
                    if r['geometry_status']=='available':chosen.setdefault((r['dataset'],r['map_repeat']),g['id'])
                pilots=set(chosen.values())
            result=tak_run(core,out,plan,phase,args.workers,pilot=stage=='pilot',specs=specs,pilot_groups=pilots)
            if stage!='pilot':result=tak_summarize(core,out,plan,phase,specs=specs)
    brief={k:v for k,v in result.items() if k not in ('subjects','groups','records','feature_workers','terminal','paired_contrasts')}
    print(json.dumps(serial(brief)),flush=True)


def tak_main(args):
    cfg=tak_config(args.config);root=args.project_root.resolve();out=args.run_dir.resolve()
    if not out.is_relative_to(root/cfg['output_root']) or out==root/cfg['output_root']:
        raise ValueError('Tak output must be a fresh directory below the owning run root')
    if args.tak_stage=='morphology':
        if args.morphology_output is None:
            raise ValueError('morphology requires --morphology-output pointing to a fresh export')
        result=tak_morphology_export(cfg,out,args.morphology_output,args.morphology_settings)
        print(json.dumps(serial(result)),flush=True)
        return result
    out.mkdir(parents=True,exist_ok=True)
    lock=(out/'controller.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    p=out/'resolved_config.json'
    if p.exists() and json.loads(p.read_text())!=cfg:raise ValueError('Tak resolved contract is immutable')
    write_json(p,cfg)
    stage=args.tak_stage
    if stage=='check':
        from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
        dt=cfg['tensor']['dt_s']
        p0=volume_drive_parameters(cfg);r=.025*np.sin(np.arange(32)*.3);initial=np.r_[0.,np.ones(4)]
        a=nonlinear_driver_forward(r,initial,p0,dt,numerical_backend='numba',hemodynamics='tak',viscoelastic_s=0.)
        b=nonlinear_driver_forward(r,initial,p0,dt,numerical_backend='numba',
            hemodynamics='inlet_balance',viscoelastic_s=0.)
        error=float(np.max(abs(a['states']-b['states'])))
        if error>1e-12:raise ValueError('Tak zero-viscoelastic equivalence failed')
        y,op,sd,truth=tak_synthetic(cfg,0,'tak_nonrest')
        result=dict(status='passed',zero_viscoelastic_max_abs=error,synthetic_shape=list(y.shape),
            measured_arrays_read=0,sources=cfg['model']['sources'])
        if cfg['schema']=='shared_driver_tak_10hz_v2':
            from src.inference.observation_baselines import eeg_band_power
            clock=np.arange(6000)/200.
            volts=np.column_stack([np.sin(2*np.pi*f*clock) for f in (3.,6.,10.,15.,22.,36.)])
            power=eeg_band_power(volts,bands=cfg['tensor']['eeg_bands_hz'],sample_rate=200.)
            if power.shape!=(300,6,5) or not np.isfinite(power).all() or np.any(power<=0):
                raise ValueError('10 Hz native-voltage proxy check failed')
            result.update(dt_s=dt,eeg_proxy_rate_hz=10.,power_shape=list(power.shape),
                reference_seconds=cfg['tensor']['reference_steps']*dt,
                data_weight=dt/cfg['solver']['observation_reference_dt_s'])
        write_json(out/'software_checks.json',result)
    elif stage=='plan':
        result=tak_plan(cfg,root);write_json(out/'plan.json',result)
    else:
        plan=json.loads((out/'plan.json').read_text()) if (out/'plan.json').exists() else None
        if stage=='prepare':result=tak_prepare(cfg,root,out,plan)
        elif stage in ('synthetic','pilot','measured','sensitivity'):
            if not 1<=args.workers<=cfg['resources']['max_workers']:raise ValueError('workers outside Tak resource envelope')
            phase='measured' if stage=='pilot' else stage
            result=tak_run(cfg,out,plan,phase,args.workers,pilot=stage=='pilot')
            if stage!='pilot':result=tak_summarize(cfg,out,plan,phase)
        elif stage=='summarize':
            result={phase:tak_summarize(cfg,out,plan,phase) for phase in ('synthetic','measured','sensitivity')}
        elif stage=='audit':
            result=tak_verify_arrays(cfg,out,plan)
        elif stage=='verify':
            summaries={phase:tak_summarize(cfg,out,plan,phase) for phase in ('synthetic','measured','sensitivity')}
            problems=[]
            for phase,summary in summaries.items():
                if summary['status']!='completed' or summary['terminal_rows']!=summary['planned_rows']:problems.append(phase+'_incomplete')
                for spec in tak_specs(cfg,plan,phase):
                    meta=json.loads((out/'tasks'/(spec['key']+'.json')).read_text())
                    if meta['status']!='completed':continue
                    if meta['fit'].get('objective_components'):
                        if not np.isclose(meta['fit']['objective'],sum(meta['fit']['objective_components'].values()),rtol=1e-10):
                            problems.append(spec['key']+'_objective_mismatch')
                    for row in meta['rows']:
                        if row['qualified'] and (not row['converged'] or row['integration_max_training_sd']>.005):
                            problems.append(spec['key']+'_invalid_qualification')
                        if spec['arm']['hemodynamics']=='tak' and row.get('p_minus_v_max',0)!=0:
                            problems.append(spec['key']+'_p_v_mismatch')
            result=dict(status='passed' if not problems else 'failed',problems=problems,
                full_denominators={p:s['terminal_rows'] for p,s in summaries.items()})
            write_json(out/'verification.json',result)
            if problems:raise ValueError('Tak verification failed: '+str(problems[:10]))
    print(json.dumps(serial({k:v for k,v in result.items() if k not in
        ('groups','records','coordinates','jobs','terminal','paired_contrasts','missing','prepared_ids')})),flush=True)


def tak_cache_config(path=None):
    folder=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer'
    default=folder/'shared_driver_tak_subject_cache_v3.yaml'
    cfg=yaml.safe_load(Path(path or default).read_text())
    contracts={f'shared_driver_tak_subject_cache_v{v}':folder/f'shared_driver_tak_subject_cache_v{v}.yaml'
               for v in (1,2,3,4)}
    if cfg.get('schema') not in contracts or cfg!=yaml.safe_load(contracts[cfg['schema']].read_text()):
        raise ValueError('Use the reviewed subject-calibrated reconstruction cache contract')
    core=deepcopy(tak_config(CODE_ROOT/cfg['base_config']))
    core.update(schema=cfg['schema'],experiment_id=cfg['experiment_id'],seed=cfg['seed'])
    core['model']['primary']='tak_tau_beta'
    core['conditions']=['joint_full'];core['tensor']['lengths_s']=[90]
    core['fitting']['reference']['neurovascular_gain']=1.
    core['fitting']['bounds']['neurovascular_gain']=[.1,10.]
    core['arms']=[dict(name='tak_fixed',hemodynamics='tak',initial='volume_tied',tau_v=2.,fit=[]),
        dict(name='tak_tau_beta',hemodynamics='tak',initial='volume_tied',tau_v=2.,
             fit=cfg['model']['parameters'],log_sd=cfg['model']['log_prior_sd'],
             start_values=cfg['model']['starts'],warm='tak_fixed')]
    return cfg,core


def tak_cache_sample_join(sample, record):
    """Choose one containing fit; retain both clocks and fractional offsets."""
    duration=float(sample.get('supported_seconds',sample['duration_s']))
    candidates=[]
    for w in record['cache_windows']:
        if all(sample[k]>=w[k]-1e-8 and sample[k]+duration<=w[k]+w['duration_s']+1e-8
               for k in ('eeg_start_s','hb_start_s')):
            distance=sum(abs(sample[k]+duration/2-w[k]-w['duration_s']/2)
                         for k in ('eeg_start_s','hb_start_s'))
            candidates.append((distance,w['hb_start_s'],w))
    result=dict(sample_id=sample['id'],record_key=record['cache_key'],split=record['split'],
                supported_seconds=duration,downstream_duration_s=sample['duration_s'])
    if not candidates:
        return dict(result,status='unavailable',reason='no_complete_containing_admitted_fit_window')
    w=min(candidates,key=lambda v:v[:2])[2]
    return dict(result,status='available',window_key=w['key'],fit_duration_s=w['duration_s'],
        eeg_offset_s=sample['eeg_start_s']-w['eeg_start_s'],
        hb_offset_s=sample['hb_start_s']-w['hb_start_s'],
        interpretation='window_reference_retained; no_state_stitching_or_duplicate_independent_sample')


def tak_cache_plan(cfg,root):
    if cfg['schema']=='shared_driver_tak_subject_cache_v4':return tak_cache_v4_plan(cfg,root)
    from src.data.tak_mismatch import inventory_tak_mismatch,tak_reconstruction_windows
    data=cfg['data'];source=root/data['downstream_input']
    previous=json.loads((source/'input_plan.json').read_text())
    verified=json.loads((source/'verification.json').read_text())
    if (previous.get('schema')!='physiology_downstream_input_v1' or verified.get('status')!='passed'
            or Path(previous['source_cache']).resolve()!=(root/data['cache_root']).resolve()):
        raise ValueError('Verified matching public downstream input identities required')
    public=inventory_tak_mismatch(cfg,root)
    splits={(ds,s):split for ds,parts in previous['subject_partitions'].items()
            for split,subjects in parts.items() for s in subjects}
    if {r['join_key'] for r in public['records']}!={r['join_key'] for r in previous['records']}:
        raise ValueError('Central and downstream record inventories differ')
    records=[]
    for r in public['records']:
        if any(not re.fullmatch(r'[A-Za-z0-9_.-]+',r[k]) for k in ('dataset','subject','record')):
            raise ValueError('Unsafe cache record identity')
        r.pop('fold',None)
        r['split']=splits[(r['dataset'],r['subject'])]
        r['cache_key']='/'.join(r[k] for k in ('dataset','subject','record'))
        r['cache_windows'],r['cache_exclusions']=tak_reconstruction_windows(r)
        records.append(r)
    lookup={r['join_key']:r for r in records}
    joins=[tak_cache_sample_join(s,lookup[s['join_key']]) for s in previous['samples']]
    counts={}
    for ds in data['datasets']:
        rr=[r for r in records if r['dataset']==ds]
        counts[ds]=dict(subjects=len({r['subject'] for r in rr}),records=len(rr),
            windows=sum(len(r['cache_windows']) for r in rr),
            short_windows=sum(w['short_record'] for r in rr for w in r['cache_windows']),
            pair_windows=sum(len(r['cache_windows'])*len(r['pairs']) for r in rr),
            excluded_records=sum(not r['cache_windows'] for r in rr),
            metadata_exclusions=sum(len(r['cache_exclusions']) for r in rr))
    return dict(schema=cfg['schema'],records=records,subject_partitions=previous['subject_partitions'],
        downstream_input=str(source),downstream_joins=joins,counts=counts,
        planned_pair_windows=sum(v['pair_windows'] for v in counts.values()),
        measured_signal_reads=0,protected_reads=0,
        interpretation=('individual_unlabelled_PCA_and_scaling' if cfg['schema'] in ('shared_driver_tak_subject_cache_v2','shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4')
                        else 'individual_unlabelled_adaptation_with_training_only_shared_PCA'))


def _tak_cache_npz(path, **arrays):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    temporary=path.with_suffix('.partial.npz')
    np.savez_compressed(temporary,**arrays)
    temporary.replace(path)


@lru_cache(maxsize=1)
def _tak_cache_source_index(cache_root):
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    return CleanPhysiologyCacheIndex(Path(cache_root))


def _tak_cache_prepare_worker(payload):
    from src.data.tak_mismatch import iter_tak_reconstruction_record
    cfg,root_string,out_string,record,requested=payload
    root,out=Path(root_string),Path(out_string);started=time.monotonic()
    folder=out/'features'/record['cache_key'];folder.mkdir(parents=True,exist_ok=True)
    windows=[w for w in record['cache_windows'] if requested is None or w['key'] in requested]
    pending=[];statuses=[]
    for w in windows:
        meta=folder/(w['key']+'.json');array=meta.with_suffix('.npz')
        if meta.exists():
            old=json.loads(meta.read_text())
            if (old.get('schema')!=cfg['schema'] or old.get('window')!=w
                    or old.get('join_key')!=record['join_key']
                    or (old['status']=='completed' and not array.exists())):
                raise ValueError('Feature resume identity or array mismatch')
            statuses.append(old['status'])
        else:pending.append(w['key'])
    def save(item):
        w=item['window'];path=folder/(w['key']+'.npz')
        if item['status']=='completed':
            _tak_cache_npz(path,**{k:item[k] for k in
                ('eeg','hb','eeg_valid','hb_valid','eeg_reference','hb_reference')},
                time_s=np.arange(round(w['duration_s']*10))/10.)
        metadata={k:v for k,v in item.items() if k not in
                  ('eeg','hb','eeg_valid','hb_valid','eeg_reference','hb_reference')}
        metadata.update(schema=cfg['schema'],join_key=record['join_key'],split=record['split'])
        write_json(path.with_suffix('.json'),metadata);statuses.append(item['status'])
    if pending:
        try:
            d=cfg['data']
            for item in iter_tak_reconstruction_record(root,record,cache_root=d['cache_root'],
                    geometry_root=d['geometry_root'],refed_geometry_root=d['refed_geometry_root'],
                    seed=cfg['seed'],index=_tak_cache_source_index(str(root/d['cache_root'])),
                    pending_windows=pending,visual_eeg_channel_identity=d['visual_eeg_channel_identity']):
                save(item)
        except Exception:
            error=traceback.format_exc()
            for w in windows:
                if not (folder/(w['key']+'.json')).exists():
                    save(dict(window=w,status='failed',error=error))
    return dict(record_key=record['cache_key'],windows=len(windows),completed=statuses.count('completed'),
        failed=statuses.count('failed'),seconds=time.monotonic()-started,
        peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)


class _TakCacheGPUClient:
    def __init__(self,connection,device,storage,index):
        self.connection=connection;self.backend=f'torch_float64_shared_cuda:{device}'
        self.buffer=np.frombuffer(storage,dtype=np.float64)[index*_TAK_CACHE_GPU_SLOT:(index+1)*_TAK_CACHE_GPU_SLOT]
        self.requests=0;self.wait_seconds=0.

    def __call__(self,jacobian,residual,parameters,damping):
        from src.inference.shared_driver_reconstruction import LinearSolverUnavailable
        started=time.monotonic()
        m,n=jacobian.shape;k=parameters.shape[1]
        if (m>4500 or n>904 or k>2 or residual.shape!=(m,) or parameters.shape!=(m,k)
                or jacobian.dtype!=np.float64):
            raise ValueError('GPU staging requires the declared float64 Tak cache block')
        self.buffer[:m*n]=jacobian.ravel()
        right=self.buffer[m*n:m*n+m*(k+1)].reshape(m,k+1)
        right[:,0]=residual;right[:,1:]=parameters
        try:
            self.connection.send((m,n,k,float(damping)))
            if not self.connection.poll(120):
                raise LinearSolverUnavailable('GPU linear solver response timed out')
            response=self.connection.recv()
            if isinstance(response,dict) and response.get('error'):
                raise LinearSolverUnavailable(response['error'])
        except (EOFError,BrokenPipeError,OSError) as exc:
            raise LinearSolverUnavailable('GPU linear solver connection failed') from exc
        self.requests+=1;self.wait_seconds+=time.monotonic()-started
        return response


def _tak_cache_worker_initialize(structured,clients,counter,devices,storage):
    global _TAK_CACHE_STRUCTURED,_TAK_CACHE_GPU_CLIENT
    _TAK_CACHE_STRUCTURED=structured;_TAK_CACHE_GPU_CLIENT=None
    if clients:
        with counter.get_lock():
            index=counter.value;counter.value+=1
        for i,connection in enumerate(clients):
            if i!=index:connection.close()
        if index<len(clients):
            _TAK_CACHE_GPU_CLIENT=_TakCacheGPUClient(clients[index],devices[index%len(devices)],storage,index)


def _tak_cache_gpu_server(device,indexed_clients,control,ready,output,batch_size,storage):
    from multiprocessing.connection import wait as connection_wait
    from collections import defaultdict
    from src.inference.shared_driver_reconstruction import torch_normal_steps
    indices={connection:index for index,connection in indexed_clients}
    clients=list(indices);shared=np.frombuffer(storage,dtype=np.float64)
    stats=dict(device=device,status='initializing',requests=0,batches=0,seconds=0.,
               transport='shared_float64_buffers_and_small_pipe_headers',linear_compute_seconds=0.)
    started=time.monotonic();last_write=0.;cursor=0
    try:
        import torch
        torch.set_num_threads(1);torch.set_num_interop_threads(1)
        torch.cuda.set_device(device);torch.cuda.set_per_process_memory_fraction(.1,device)
        # Initialize CUDA before any CPU worker can block waiting for a response.
        torch.ones(1,dtype=torch.float64,device=f'cuda:{device}').sum().item()
        dampings=[.001*(i+1) for i in range(batch_size)]
        probes=torch_normal_steps([np.eye(8,4)]*batch_size,[np.arange(8,dtype=float)]*batch_size,
                                  [np.zeros((8,2))]*batch_size,dampings,device=f'cuda:{device}')
        for probe,damping in zip(probes,dampings):
            np.testing.assert_allclose(probe[3][:,0],np.arange(4)/(1+damping),rtol=1e-12,atol=1e-12)
        stats.update(status='running',torch=torch.__version__,GPU=torch.cuda.get_device_name(device))
        ready.send(dict(status='ready',device=device))
        while clients:
            ordered=clients[cursor:]+clients[:cursor]
            available=connection_wait([control]+ordered,timeout=5.)
            if control in available:
                control.recv();break
            selected=[c for c in ordered if c in available][:batch_size]
            requests=[]
            for connection in selected:
                try:m,n,k,damping=connection.recv()
                except EOFError:continue
                if not (0<m<=4500 and 0<n<=904 and 0<=k<=2):
                    raise ValueError('GPU request exceeds its shared buffer')
                offset=indices[connection]*_TAK_CACHE_GPU_SLOT
                j=shared[offset:offset+m*n].reshape(m,n)
                right=shared[offset+m*n:offset+m*n+m*(k+1)].reshape(m,k+1)
                request=(j,right[:,0],right[:,1:],damping)
                requests.append((connection,request))
                cursor=(clients.index(connection)+1)%len(clients)
            groups=defaultdict(list)
            for connection,request in requests:
                j,r,p,d=request
                groups[(j.shape,p.shape[1])].append((connection,request))
            for group in groups.values():
                values=[request for _,request in group]
                compute_started=time.monotonic()
                answers=torch_normal_steps([v[0] for v in values],[v[1] for v in values],
                    [v[2] for v in values],[v[3] for v in values],device=f'cuda:{device}')
                stats['linear_compute_seconds']+=time.monotonic()-compute_started
                for (connection,_),answer in zip(group,answers):
                    try:connection.send(answer)
                    except (EOFError,BrokenPipeError):pass
                stats['requests']+=len(group);stats['batches']+=1
            if time.monotonic()-last_write>=15:
                stats.update(seconds=time.monotonic()-started,
                    peak_allocated_MiB=torch.cuda.max_memory_allocated(device)/2**20)
                write_json(Path(output)/f'gpu{device}.json',stats);last_write=time.monotonic()
        stats.update(status='completed',seconds=time.monotonic()-started)
    except Exception:
        stats.update(status='failed',error=traceback.format_exc(),seconds=time.monotonic()-started)
        try:ready.send(dict(status='failed',error=stats['error']))
        except (EOFError,BrokenPipeError):pass
        for connection in clients:
            try:connection.send(dict(error=stats['error']))
            except (EOFError,BrokenPipeError):pass
        raise
    finally:
        write_json(Path(output)/f'gpu{device}.json',stats)
        for connection in clients:connection.close()
        control.close();ready.close()


def _tak_cache_pool(worker, payloads, *, out, phase, workers, total,
                    structured=False, gpu_devices=(), gpu_batch_size=4, gpu_workers=None):
    """Bound the two producer pools and retain progress through the supervisor."""
    import multiprocessing as mp
    iterator=iter(payloads);completed=0;started=time.monotonic();rows=[]
    clients=[];services=[];counter=None;storage=None
    if gpu_devices:
        gpu_workers=workers if gpu_workers is None else gpu_workers
        if not 1<=gpu_workers<=workers:
            raise ValueError('GPU worker count must fit inside the CPU worker pool')
        context=mp.get_context('spawn');counter=mp.Value('i',0)
        storage=context.RawArray('d',gpu_workers*_TAK_CACHE_GPU_SLOT)
        pairs=[context.Pipe() for _ in range(gpu_workers)]
        clients=[p[0] for p in pairs]
        try:
            for i,device in enumerate(gpu_devices):
                control,server_control=context.Pipe();ready,server_ready=context.Pipe()
                servers=[(k,p[1]) for k,p in enumerate(pairs) if k%len(gpu_devices)==i]
                process=context.Process(target=_tak_cache_gpu_server,
                    args=(device,servers,server_control,server_ready,str(out/'gpu_runtime'),gpu_batch_size,storage))
                process.start();server_control.close();server_ready.close()
                services.append((process,control,ready))
            for _,server in pairs:server.close()
            for process,control,ready in services:
                if not ready.poll(120):raise RuntimeError('GPU service initialization timed out')
                result=ready.recv()
                if result['status']!='ready':raise RuntimeError(result.get('error','GPU initialization failed'))
        except BaseException:
            for process,control,ready in services:
                try:control.send('stop')
                except (EOFError,BrokenPipeError):pass
                process.join(timeout=10)
                if process.is_alive():process.terminate();process.join()
            raise
    try:
        with ProcessPoolExecutor(max_workers=workers,initializer=_tak_cache_worker_initialize,
                initargs=(structured,clients,counter,gpu_devices,storage)) as pool:
            active={}
            def submit():
                try:payload=next(iterator)
                except StopIteration:return False
                active[pool.submit(worker,payload)]=None
                return True
            for _ in range(2*workers):
                if not submit():break
            while active:
                done,_=wait(active,timeout=15,return_when=FIRST_COMPLETED)
                for future in done:
                    active.pop(future);row=future.result();rows.append(row);completed+=1;submit()
                write_json(out/'progress.json',dict(schema='tak_reconstruction_cache_progress_v1',
                    phase=phase,planned=total,terminal=completed,in_flight=len(active),workers=workers,
                    observation_algebra='structured' if structured else 'dense',gpu_devices=list(gpu_devices),
                    gpu_workers=len(clients),cpu_only_workers=workers-len(clients),
                    elapsed_s=time.monotonic()-started,supervisor=os.environ.get('SSM_SYSTEMD_UNIT'),
                    updated_at=datetime.now(timezone.utc).isoformat()))
    finally:
        for process,control,ready in services:
            try:control.send('stop')
            except (EOFError,BrokenPipeError):pass
            process.join(timeout=20)
            if process.is_alive():process.terminate();process.join()
            control.close();ready.close()
        for connection in clients:connection.close()
    result=dict(status='completed',phase=phase,planned=total,terminal=completed,workers=workers,
                observation_algebra='structured' if structured else 'dense',gpu_devices=list(gpu_devices),
                gpu_workers=len(clients),cpu_only_workers=workers-len(clients),
                seconds=time.monotonic()-started,rows=rows)
    write_json(out/(phase+'_execution.json'),result)
    return result


def _tak_cache_chunks(out, records, *, counts=None):
    """Yield finite paired neighborhoods; support masks precede all moments."""
    for r in records:
        for w in r['cache_windows']:
            path=out/'features'/r['cache_key']/(w['key']+'.npz')
            meta=path.with_suffix('.json')
            if not meta.exists() or json.loads(meta.read_text())['status']!='completed':
                continue
            with np.load(path,allow_pickle=False) as a:
                eeg,hb,ev,hv=(a[k] for k in ('eeg','hb','eeg_valid','hb_valid'))
            used=0
            for pair in r['pairs']:
                if pair['status']!='available':continue
                indices=pair['channel_sets']['nearest6'];p=pair['native_index']
                if not hv[p] or not ev[indices].all():continue
                x=eeg[:,indices].reshape(len(eeg),30);y=hb[:,p]
                if not np.isfinite(x).all() or not np.isfinite(y).all():
                    raise ValueError('Finite flags disagree with feature arrays')
                used+=1
                yield x,y
            if counts is not None and used:
                counts.append(dict(record_key=r['cache_key'],window_key=w['key'],pairs=used,
                                   steps=len(eeg),subject=r['subject'],split=r['split']))


def tak_cache_calibrate(cfg,out,plan, *, records=None, destination=None):
    from src.data.ssm_prepared import fit_feature_coordinate
    records=plan['records'] if records is None else records
    destination=out/'coordinates.json' if destination is None else destination
    if destination.exists():
        value=json.loads(destination.read_text())
        if value['schema']!=cfg['schema'] or value['calibration']!=cfg['calibration']:
            raise ValueError('Frozen calibration contract changed')
        return value
    population={};individual={}
    individual_pca=cfg['schema'] in ('shared_driver_tak_subject_cache_v2','shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4')
    for ds in cfg['data']['datasets']:
        selected=[r for r in records if r['dataset']==ds and r['split']=='train']
        sources=[]
        co=fit_feature_coordinate(_tak_cache_chunks(out,selected,counts=sources))
        co.update(subjects=sorted({s['subject'] for s in sources}),sources=sources,scope='training_only')
        if individual_pca:co['purpose']='reference_scoring_SD_only_not_an_individual_projection'
        population[ds]=co
    identities=sorted({(r['dataset'],r['subject'],r['split']) for r in records})
    for ds,subject,split in identities:
        sources=[]
        try:
            co=fit_feature_coordinate(_tak_cache_chunks(out,[r for r in records
                if r['dataset']==ds and r['subject']==subject],counts=sources),
                fixed_pc=None if individual_pca else population[ds]['pc'])
            co.update(status='completed',dataset=ds,subject=subject,split=split,sources=sources,
                scope='own_unlabelled_observations_all_prepared_records_and_sites',
                PCA_source=ds+'__'+subject if individual_pca else ds,
                parameter_comparison=('effective_in_individual_PCA_and_scale_coordinates' if individual_pca
                                      else 'effective_in_individually_scaled_coordinates'))
            if individual_pca:
                co['common_scale_interpretation']='fixed_training_reference_SD_not_a_shared_EEG_target'
        except ValueError as exc:
            co=dict(status='unavailable',dataset=ds,subject=subject,split=split,error=str(exc),sources=sources)
        individual[ds+'__'+subject]=co
    result=dict(schema=cfg['schema'],calibration=cfg['calibration'],population=population,
                individual=individual,labels_used=False,heldout_subject_adaptation=True)
    write_json(destination,result)
    return result


@lru_cache(maxsize=2)
def _tak_cache_operator(steps):
    if not 50 < steps <= 900:
        raise ValueError('A complete fit must extend beyond its five-second reference')
    reference=np.eye(steps);reference[:,:50]-=1/50
    return np.kron(reference,np.eye(3))


def _tak_cache_errors(target,prediction,sd):
    error=(np.asarray(prediction)[:-1]-np.asarray(target)[:-1])/np.asarray(sd)
    value=np.mean(error**2,axis=0)
    return dict(eeg_nmse=float(value[0]),hbo_nmse=float(value[1]),hbr_nmse=float(value[2]),
                hb_nmse=float(value[1:].mean()))


def tak_cache_fit_arrays(core,target_unscaled,coordinate,common_sd, *, structured=False,linear_solver=None,
                         observation_weights=None, initial_solution=None):
    """The same two-parameter fit for 90 s and actual-duration REFED supports."""
    from src.inference.shared_driver_reconstruction import nonlinear_driver_forward
    target_unscaled=np.asarray(target_unscaled,float)
    scale=np.array([coordinate['eeg_factor'],coordinate['hb_factor'],coordinate['hb_factor']],float)
    sd=np.asarray(coordinate['sd'],float);n=len(target_unscaled)
    if (target_unscaled.shape!=(n,3) or not np.isfinite(target_unscaled).all()
            or not np.isfinite(scale).all() or np.any(scale<=0)
            or sd.shape!=(3,) or np.any(sd<=0) or not np.isfinite(sd).all()
            or np.shape(common_sd)!=(3,) or np.any(np.asarray(common_sd)<=0)):
        raise ValueError('Finite three-component target and fixed positive scales required')
    target=target_unscaled*scale
    weights=np.ones(3) if observation_weights is None else np.asarray(observation_weights,float)
    if weights.shape!=(3,) or not np.isfinite(weights).all() or np.any(weights<=0):
        raise ValueError('Three positive finite observation weights required')
    fit_sd=sd if observation_weights is None else sd/np.sqrt(weights)
    operator=None if structured else _tak_cache_operator(n)
    mask=np.ones((1,n,3),bool);mask[:,-1]=False
    arrays=dict(target=target_unscaled,scale=scale,sd_subject=sd/scale,
                sd_common=np.asarray(common_sd,float),time_s=np.arange(n)/10.,
                observation_valid=np.ones((n,3),bool),fit_mask=mask[0])
    results={};warm=None
    if initial_solution is not None:
        if list(next(a for a in core['arms'] if a['name']=='tak_tau_beta')['fit'])!=['tau','neurovascular_gain']:raise ValueError('Explicit warm start requires tau/beta ordering')
    for arm in core['arms']:
        if initial_solution is not None and not arm['fit']:continue
        started=time.monotonic()
        fit=tak_fit_group(core,arm,target[None],None if operator is None else operator[None],fit_sd[None],mask,warm,
            observation_reference_steps=50 if structured else None,linear_solver=linear_solver,
            starts_override=None if initial_solution is None else [initial_solution])
        details={k:v for k,v in fit.items() if k not in
                 ('driver','initial_state','prediction','canonical_prediction','states')}
        detail=dict(solver=details,qualified=False,seconds=time.monotonic()-started)
        if 'prediction' in fit:
            p=volume_drive_parameters(core,kappa=fit['kappa'],tau=fit['tau'],gamma=fit['gamma'],
                                      neurovascular_gain=fit['neurovascular_gain'])
            fine=nonlinear_driver_forward(fit['driver'][0],fit['initial_state'][0],p,.1,
                substeps=8,derivative=False,numerical_backend='numba',hemodynamics='tak',
                viscoelastic_s=fit['viscoelastic_s'])
            canonical=fine['canonical_prediction']
            refined=(canonical-canonical[:50].mean(0) if structured else
                     (operator@canonical.ravel()).reshape(n,3))
            integration=float(np.max(abs((refined-fit['prediction'][0])[:-1]/sd)))
            states=fit['states'][0]
            qualified=bool(fit['converged'] and integration<=core['solver']['maximum_integration_difference_training_sd']
                           and np.array_equal(states[:,3],states[:,4]))
            prediction=fit['prediction'][0]/scale
            detail.update(qualified=qualified,integration_max_subject_sd=integration,
                metrics_subject=_tak_cache_errors(target_unscaled,prediction,sd/scale),
                metrics_common=_tak_cache_errors(target_unscaled,prediction,common_sd),
                waveform=filter_retest_waveform_metrics(target_unscaled,prediction,sd/scale,dt=.1),
                tau=float(fit['tau']),beta=float(fit['neurovascular_gain']))
            prefix='fixed_' if not arm['fit'] else ''
            arrays[prefix+'prediction']=prediction
            if arm['fit']:
                arrays.update(residual=target_unscaled-prediction,driver=fit['driver'][0],
                    states=states,initial_state=fit['initial_state'][0],
                    prediction_valid=np.full((n,3),qualified,bool))
            if not arm['fit']:
                warm=dict(driver=fit['driver'],initial_state=fit['initial_state'])
        results[arm['name']]=detail
    free=results['tak_tau_beta']
    result=dict(status='completed' if free['qualified'] else 'failed_numerical',
        qualified=free['qualified'],fits=results,
        execution_backend=dict(observation_algebra='structured' if structured else 'dense',
            linear_solver=getattr(linear_solver,'backend','scipy_cpu_float64')),
        zero_baseline=_tak_cache_errors(target_unscaled,np.zeros_like(target_unscaled),common_sd),
        observation_weights=weights.tolist(),
        normalization=dict(subject='individual_calibration_SD',common=coordinate.get(
            'common_scale_interpretation','training_subjects_common_projection_SD')),
        duration_s=n/10.,scored_steps=n-1,reference_steps=50)
    if 'prediction' in arrays:
        result['nonpositive_correlation_components']=[w['component'] for w in free['waveform']
            if w['pearson_r'] is not None and w['pearson_r']<=0]
        result['Hb_not_better_than_zero']=free['metrics_common']['hb_nmse']>=result['zero_baseline']['hb_nmse']
        if not np.allclose(arrays['target'],arrays['prediction']+arrays['residual'],rtol=1e-12,atol=1e-12):
            raise ValueError('Stored prediction/residual decomposition does not close')
    return result,arrays


@lru_cache(maxsize=4)
def _tak_cache_coordinates(path):
    return json.loads(Path(path).read_text())


@lru_cache(maxsize=2)
def _tak_cache_feature_arrays(path):
    with np.load(path,allow_pickle=False) as a:
        return {k:a[k] for k in ('eeg','hb','eeg_valid','hb_valid','eeg_reference','hb_reference')}


def _tak_cache_fit_worker(payload):
    from src.inference.shared_driver_reconstruction import LinearSolverUnavailable
    cfg,core,out_string,coordinate_string,destination_string,spec=payload
    if cfg['schema'] in ('shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4'):return _tak_cache_v3_fit_worker(payload)
    out,destination=Path(out_string),Path(destination_string);started=time.monotonic()
    path=destination/'tasks'/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
    if path.exists():
        previous=json.loads(path.read_text())
        if (previous.get('schema')!=cfg['schema'] or previous.get('identity')!=spec
                or previous.get('coordinates')!=coordinate_string
                or (previous.get('qualified') and not path.with_suffix('.npz').exists())):
            raise ValueError('Terminal reconstruction cache identity or array changed')
        return dict(key=str(path.relative_to(destination)),status=previous['status'],
                    qualified=previous.get('qualified',False),seconds=0.,cached=True)
    row=dict(schema=cfg['schema'],identity=spec,coordinates=coordinate_string,
             status='unavailable',qualified=False)
    arrays={}
    try:
        coordinates=_tak_cache_coordinates(coordinate_string)
        co=coordinates['individual'][spec['dataset']+'__'+spec['subject']]
        population=coordinates['population'][spec['dataset']]
        pair=spec['pair'];feature=out/'features'/spec['record_key']/(spec['window']['key']+'.npz')
        if pair['status']!='available':
            raise ValueError('unavailable_geometry: '+str(pair.get('reason')))
        if co['status']!='completed':
            raise ValueError('unavailable_subject_calibration: '+str(co.get('error')))
        metadata=json.loads(feature.with_suffix('.json').read_text())
        if metadata['status']!='completed':
            raise ValueError('feature_preparation_failed: '+str(metadata.get('error')))
        a=_tak_cache_feature_arrays(str(feature));indices=pair['channel_sets']['nearest6'];p=pair.get('compact_index',pair['native_index'])
        if not a['hb_valid'][p] or not a['eeg_valid'][indices].all():
            raise ValueError('unsupported_Hb_pair_or_required_native_EEG_channel')
        n=len(a['eeg']);pc=np.asarray(co['pc'],float)
        target=np.column_stack((a['eeg'][:,indices].reshape(n,30)@pc,a['hb'][:,p]))
        common_sd=np.asarray(population['sd'])/np.array([population['eeg_factor'],population['hb_factor'],population['hb_factor']])
        before_requests=getattr(_TAK_CACHE_GPU_CLIENT,'requests',0)
        before_wait=getattr(_TAK_CACHE_GPU_CLIENT,'wait_seconds',0.)
        fitted,arrays=tak_cache_fit_arrays(core,target,co,common_sd,
            structured=_TAK_CACHE_STRUCTURED,linear_solver=_TAK_CACHE_GPU_CLIENT)
        fitted['gpu_linear_requests']=getattr(_TAK_CACHE_GPU_CLIENT,'requests',0)-before_requests
        fitted['gpu_linear_wait_seconds']=getattr(_TAK_CACHE_GPU_CLIENT,'wait_seconds',0.)-before_wait
        row.update(fitted,feature_source=str(feature.relative_to(out)),provenance=metadata['provenance'])
        arrays['reference_unscaled']=np.r_[a['eeg_reference'][indices].ravel()@pc,a['hb_reference'][p]]
    except LinearSolverUnavailable:
        raise
    except Exception:
        row.update(status='failed_preparation_or_fit',error=traceback.format_exc())
    row.update(seconds=time.monotonic()-started,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    if arrays:
        _tak_cache_npz(path.with_suffix('.npz'),**arrays)
    write_json(path,row)
    return dict(key=str(path.relative_to(destination)),status=row['status'],qualified=row['qualified'],
                seconds=row['seconds'],peak_rss_mib=row['peak_rss_mib'],cached=False)


def tak_cache_specs(records, *, pilot=False, individual_pca=False):
    for r in records:
        pairs=r['pairs']
        if pilot:
            available=[p for p in pairs if p['status']=='available']
            pairs=[available[i] for i in sorted({0,len(available)//2,len(available)-1})] if available else []
        for w in r['cache_windows'][:1] if pilot else r['cache_windows']:
            for pair in pairs:
                yield dict(record_key=r['cache_key'],dataset=r['dataset'],subject=r['subject'],split=r['split'],
                    join_key=r['join_key'],record=r['record'],window=w,pair={k:pair[k] for k in
                        ('native_index','compact_index','id','site_id','status','channel_sets','channel_set_names') if k in pair},
                    output_coordinates=('individual_PC1_logpower_and_referenced_cached_Hb' if individual_pca
                                        else 'training_PC1_logpower_and_referenced_cached_Hb'),
                    visibility='joint_full_declared_window',subject_adaptation=True)


def _tak_cache_synthetic_worker(payload):
    cfg,core,out_string,index,case,duration=payload
    out=Path(out_string);path=out/'synthetic'/f'case{index:02d}.json';started=time.monotonic()
    if path.exists():return json.loads(path.read_text())
    target,operator,sd,truth=tak_task_parameter_synthetic(core,case)
    n=round(duration*10)
    target=target[:n]
    result,arrays=tak_cache_fit_arrays(core,target,dict(eeg_factor=1.,hb_factor=1.,sd=sd),sd,
        observation_weights=cfg['model'].get('observation_weights'))
    result.update(case=case,truth_tau=truth['tau'],truth_beta=truth['beta'],
                  seconds=time.monotonic()-started,
                  peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    _tak_cache_npz(path.with_suffix('.npz'),**arrays,truth_clean=truth['clean'][:n])
    write_json(path,result)
    return result


def tak_cache_synthetic(cfg,core,out,workers):
    jobs=[(cfg,core,str(out),i,c,90.) for i,c in enumerate(cfg['synthetic']['cases'])]
    jobs.append((cfg,core,str(out),len(jobs),cfg['synthetic']['cases'][0],cfg['synthetic']['short_REFED_duration_s']))
    execution=_tak_cache_pool(_tak_cache_synthetic_worker,jobs,out=out,phase='synthetic',
                              workers=min(workers,len(jobs)),total=len(jobs))
    result=dict(status='completed',cases=len(jobs),qualified=sum(r['qualified'] for r in execution['rows']),
                numerical_checks_passed=all(r['qualified'] for r in execution['rows']),rows=execution['rows'],
                measured_signal_reads=0,protected_reads=0)
    write_json(out/'synthetic_summary.json',result)
    if not result['numerical_checks_passed']:
        raise ValueError('Synthetic numerical failures must be resolved before measured cache preparation')
    return result


def tak_cache_check(cfg,core,out):
    from src.data.ssm_prepared import fit_feature_coordinate
    rng=np.random.default_rng(20261104);x=rng.normal(size=(120,30));h=rng.normal(size=(120,2))
    population=fit_feature_coordinate([(x,h)])
    own=fit_feature_coordinate([(x*3,h*7)],fixed_pc=population['pc'])
    np.testing.assert_array_equal(own['pc'],population['pc'])
    np.testing.assert_allclose(own['eeg_factor'],population['eeg_factor']/3,rtol=1e-12)
    np.testing.assert_allclose(own['hb_factor'],population['hb_factor']/7,rtol=1e-12)
    individual_pca=cfg['schema'] in ('shared_driver_tak_subject_cache_v2','shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4')
    if individual_pca:
        changed=x.copy();changed[:,np.argmin(abs(population['pc']))]*=100
        individual=fit_feature_coordinate([(changed,h)])
        assert abs(individual['pc']@population['pc'])<.5
        np.testing.assert_allclose(np.std(changed@individual['pc'])*individual['eeg_factor'],.025,rtol=1e-12)
    for n in (900,450):
        y=rng.normal(size=(n,3))
        np.testing.assert_allclose((_tak_cache_operator(n)@y.ravel()).reshape(n,3),
                                   y-y[:50].mean(0),rtol=1e-12,atol=1e-12)
    if (core['arms'][1]['fit']!=['tau','neurovascular_gain']
            or core['arms'][1]['log_sd']!=[.125,.125] or core['tensor']['dt_s']!=.1):
        raise ValueError('Explicit tau/beta 10Hz prior contract required')
    result=dict(status='passed',checks=[('individual_PCA_and_scaling' if individual_pca else 'frozen_PCA_individual_scaling'),
        '90s_and_short_reference_operator',
        'explicit_tau_beta_prior_and_clock'],measured_signal_reads=0,protected_reads=0)
    write_json(out/'software_checks.json',result)
    return result


def tak_cache_pilot_records(plan):
    selected=[]
    for ds in plan['subject_partitions']:
        candidates=[r for r in plan['records'] if r['dataset']==ds and r['split']=='train'
            and r['cache_windows'] and r['cache_windows'][0]['duration_s']==90
            and any(p['status']=='available' for p in r['pairs'])]
        if not candidates:raise ValueError('No complete training pilot support for '+ds)
        selected.append(candidates[0])
    short=[r for r in plan['records'] if r['dataset']=='refed' and r['split']=='train'
           and r['cache_windows'] and r['cache_windows'][0]['short_record']
           and any(p['status']=='available' for p in r['pairs'])]
    if short:selected.append(short[0])
    return selected


def tak_cache_pilot(cfg,core,root,out,plan,workers):
    pilot=out/'pilot';pilot.mkdir(exist_ok=True)
    if (pilot/'summary.json').exists():
        return json.loads((pilot/'summary.json').read_text())
    records=tak_cache_pilot_records(plan)
    prepare=_tak_cache_pool(_tak_cache_prepare_worker,
        [(cfg,str(root),str(out),r,[r['cache_windows'][0]['key']]) for r in records],
        out=pilot,phase='prepare_pilot',workers=min(cfg['resources']['preparation_workers'],len(records)),
        total=len(records))
    coordinate_path=pilot/'coordinates.json'
    tak_cache_calibrate(cfg,out,plan,records=records,destination=coordinate_path)
    specs=list(tak_cache_specs(records,pilot=True,individual_pca=cfg['schema'] in ('shared_driver_tak_subject_cache_v2','shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4')))
    run=_tak_cache_pool(_tak_cache_fit_worker,
        ((cfg,core,str(out),str(coordinate_path),str(pilot),s) for s in specs),
        out=pilot,phase='pilot_fit',workers=min(workers,len(specs)),total=len(specs))
    rows=[json.loads((pilot/r['key']).read_text()) for r in run['rows']]
    successes={r['identity']['dataset'] for r in rows if r['qualified']}
    numerically_ready=successes==set(cfg['data']['datasets'])
    if any(s['window']['short_record'] for s in specs):
        numerically_ready &= any(r['qualified'] and r['identity']['window']['short_record'] for r in rows)
    times=[r['seconds'] for r in run['rows'] if not r.get('cached')]
    peak=max((r.get('peak_rss_mib',0.) for r in run['rows']),default=0.)
    verify_records=[]
    for r in records:
        item=deepcopy(r);item['cache_windows']=r['cache_windows'][:1]
        selected={s['pair']['native_index'] for s in specs if s['record_key']==r['cache_key']}
        item['pairs']=[p for p in r['pairs'] if p['native_index'] in selected]
        verify_records.append(item)
    verification=_tak_cache_pool(_tak_cache_verify_record,
        ((cfg,core,str(pilot),r) for r in verify_records),out=pilot,phase='pilot_verification',
        workers=min(len(records),cfg['resources']['preparation_workers']),total=len(records))
    issues=[i for r in verification['rows'] for i in r['issues']]
    numerically_ready &= not issues
    result=dict(status='completed',numerical_smoke_passed=bool(numerically_ready),
        planned=len(rows),qualified=sum(r['qualified'] for r in rows),
        selection='first_training_record_per_dataset_and_first_short_REFED_record; first_middle_last_sites',
        provisional_coordinates=True,production_reuse='unscaled_features_only_not_fits_or_calibration',
        fit_seconds_mean=float(np.mean(times)) if times else None,
        fit_seconds_median=float(np.median(times)) if times else None,
        fit_seconds_p90=float(np.quantile(times,.9)) if times else None,peak_fit_rss_mib=peak,
        peak_prepare_rss_mib=max(r['peak_rss_mib'] for r in prepare['rows']),
        independent_array_verification=dict(status='passed' if not issues else 'failed',issues=issues),
        rows=[dict(identity=r['identity'],qualified=r['qualified'],status=r['status'],
                   metrics=r.get('fits',{}),seconds=r['seconds']) for r in rows])
    write_json(pilot/'summary.json',result)
    if not numerically_ready:raise ValueError('Pilot cannot fit every dataset and short REFED; inspect retained failures')
    return result


def _tak_cache_verify_record(payload):
    """Independently check retained arrays; no source signals or refitting."""
    cfg,core,out_string,record=payload;out=Path(out_string)
    migration=cfg['schema']=='shared_driver_tak_subject_cache_v4'
    if migration and record['dataset']!=cfg['migration']['dataset']:
        cfg=dict(cfg,schema=cfg['source_cache']['schema'])
    counts=dict(planned=0,terminal=0,qualified=0,failed=0,paired=0,short=0,
                nonpositive_EEG_correlation=0,nonpositive_HbO_correlation=0,
                nonpositive_HbR_correlation=0,Hb_not_better_than_zero=0)
    sums={};maxima=dict(closure=0.,metric=0.,observation=0.);issues=[]
    if cfg['schema'] in ('shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4'):
        counts.update(cached_free_start=0,standard_after_unqualified_warm=0,standard_missing_seed=0,standard_subject_guard=0)
        maxima['weighted_data_cost']=0.
    for spec in tak_cache_specs([record],individual_pca=cfg['schema'] in ('shared_driver_tak_subject_cache_v2','shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4')):
        counts['planned']+=1
        path=out/'tasks'/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
        if not path.exists():
            issues.append(dict(key=str(path.relative_to(out)),reason='missing_terminal_record'));continue
        row=json.loads(path.read_text());counts['terminal']+=1
        if row.get('schema')!=cfg['schema'] or row.get('identity')!=spec:
            issues.append(dict(key=str(path.relative_to(out)),reason='identity_mismatch'));continue
        if cfg['schema'] in ('shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4'):
            route=row.get('initialization_route')
            if route in counts:counts[route]+=1
            if row.get('observation_weights')!=cfg['model']['observation_weights']:issues.append(dict(key=str(path),reason='observation_weight_mismatch'))
        if not row.get('qualified'):
            counts['failed']+=1;continue
        counts['qualified']+=1;counts['short']+=int(spec['window']['short_record'])
        for component in row.get('nonpositive_correlation_components',[]):
            counts['nonpositive_'+component+'_correlation']+=1
        counts['Hb_not_better_than_zero']+=int(row.get('Hb_not_better_than_zero',False))
        try:
            with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
                y,p,e=a['target'],a['prediction'],a['residual'];n=round(spec['window']['duration_s']*10)
                if (y.shape!=(n,3) or p.shape!=y.shape or e.shape!=y.shape
                        or y.dtype!=np.float64 or not all(np.isfinite(v).all() for v in (y,p,e))
                        or not a['prediction_valid'].all()
                        or not a['fit_mask'][:-1].all() or a['fit_mask'][-1].any()
                        or not a['observation_valid'].all()
                        or not np.array_equal(a['time_s'],np.arange(n)/10.)):
                    raise ValueError('shape, precision, mask or clock mismatch')
                if migration and record['dataset']==cfg['migration']['dataset']:
                    coordinate=_tak_cache_coordinates(str(out/'coordinates.json'))['individual'][spec['dataset']+'__'+spec['subject']]
                    feature=_tak_cache_feature_arrays(str(out/'features'/spec['record_key']/(spec['window']['key']+'.npz')))
                    pair=spec['pair'];indices=pair['channel_sets']['nearest6']
                    expected_target=np.column_stack((feature['eeg'][:,indices].reshape(n,30)@np.asarray(coordinate['pc']),feature['hb'][:,pair['compact_index']]))
                    np.testing.assert_array_equal(y,expected_target)
                    np.testing.assert_array_equal(a['scale'],[coordinate['eeg_factor'],coordinate['hb_factor'],coordinate['hb_factor']])
                    np.testing.assert_allclose(a['sd_subject']*a['scale'],coordinate['sd'],rtol=1e-14)
                closure=float(np.max(abs(y-p-e)));maxima['closure']=max(maxima['closure'],closure)
                if not np.allclose(y,p+e,rtol=1e-12,atol=1e-12):raise ValueError('residual closure')
                squared=np.sum((p[:-1]-y[:-1])**2,axis=0)/(n-1)
                for name in ('subject','common'):
                    values=squared/a['sd_'+name]**2
                    expected=dict(eeg_nmse=values[0],hbo_nmse=values[1],hbr_nmse=values[2],hb_nmse=values[1:].mean())
                    actual=row['fits']['tak_tau_beta']['metrics_'+name]
                    for key,value in expected.items():
                        maxima['metric']=max(maxima['metric'],abs(float(value)-actual[key]))
                        if not np.isclose(value,actual[key],rtol=1e-10,atol=1e-10):
                            raise ValueError('retained metric disagrees with arrays')
                        sums['free_'+name+'_'+key]=sums.get('free_'+name+'_'+key,0.)+float(value)
                if cfg['schema'] in ('shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4'):
                    cost=core['tensor']['dt_s']/core['solver'].get('observation_reference_dt_s',core['tensor']['dt_s'])*np.sum(np.asarray(cfg['model']['observation_weights'])*((p-y)[:-1]/a['sd_subject'])**2)
                    saved=row['fits']['tak_tau_beta']['solver']['objective_components']['data']
                    maxima['weighted_data_cost']=max(maxima['weighted_data_cost'],abs(float(cost)-saved))
                    if not np.isclose(cost,saved,rtol=1e-10,atol=1e-8):raise ValueError('New weighted objective disagrees with arrays')
                states=a['states'];parameters=volume_drive_parameters(core).fixed
                if (states.shape!=(n,6) or not np.isfinite(states).all()
                        or not np.array_equal(states[:,3],states[:,4])
                        or np.any(states[:,2:]<=0) or np.any(parameters.P0*states[:,4]<parameters.Q0*states[:,5])):
                    raise ValueError('invalid retained Tak state')
                canonical=np.column_stack((parameters.eeg_loading*a['driver']+parameters.eeg_offset,
                    parameters.P0*(states[:,4]-1)-parameters.Q0*(states[:,5]-1),
                    parameters.Q0*(states[:,5]-1)))
                expected=(canonical-canonical[:50].mean(0))/a['scale']
                maxima['observation']=max(maxima['observation'],float(np.max(abs(expected-p))))
                if not np.allclose(expected,p,rtol=1e-9,atol=1e-10):
                    raise ValueError('states do not reproduce stored observation')
                if row['fits'].get('tak_fixed',{}).get('qualified',False):
                    counts['paired']+=1
                    for arm,prediction in [('free',p),('fixed',a['fixed_prediction'])]:
                        nmse=np.mean((prediction[:-1]-y[:-1])**2,axis=0)/a['sd_common']**2
                        for key,value in zip(('eeg','hbo','hbr','hb'),[*nmse,nmse[1:].mean()]):
                            name='paired_'+arm+'_'+key
                            sums[name]=sums.get(name,0.)+float(value)
        except Exception as exc:
            issues.append(dict(key=str(path.relative_to(out)),reason=str(exc)))
    if migration and record['dataset']==cfg['migration']['dataset']:
        expected={w['key']+f"__p{p['native_index']:03d}.json" for w in record['cache_windows'] for p in record['pairs']}
        actual={p.name for p in (out/'tasks'/record['cache_key']).glob('*.json')}
        if actual!=expected:issues.append(dict(reason='unexpected_or_excluded_task_identity'))
    return dict(record_key=record['cache_key'],dataset=record['dataset'],subject=record['subject'],
                split=record['split'],durations_s=sorted({w['duration_s'] for w in record['cache_windows']}),
                counts=counts,sums=sums,maxima=maxima,issues=issues)


def tak_cache_verify(cfg,core,out,plan,workers):
    from collections import defaultdict
    records=[r for r in plan['records'] if r['cache_windows']]
    execution=_tak_cache_pool(_tak_cache_verify_record,
        ((cfg,core,str(out),r) for r in records),out=out,phase='verification',
        workers=min(workers,cfg['resources']['preparation_workers']),total=len(records))
    rows=execution['rows'];issues=[i for r in rows for i in r['issues']]
    counts={k:sum(r['counts'][k] for r in rows) for k in rows[0]['counts']}
    if counts['planned']!=plan['planned_pair_windows']:
        issues.append(dict(reason='planned_population_mismatch'))
    def aggregate(selected):
        subject_values=defaultdict(lambda:defaultdict(list));values=defaultdict(list)
        for r in selected:
            for key,value in r['sums'].items():
                denominator=r['counts']['paired' if key.startswith('paired_') else 'qualified']
                if denominator:subject_values[r['subject']][key].append(value/denominator)
        for metrics in subject_values.values():
            for key,v in metrics.items():values[key].append(float(np.mean(v)))
        return dict(counts={k:sum(r['counts'][k] for r in selected) for k in counts},
                    nrmse={key:float(np.sqrt(np.mean(v))) for key,v in values.items()},
                    contributing_subjects=len(subject_values))
    summaries={}
    for ds in cfg['data']['datasets']:
        rr=[r for r in rows if r['dataset']==ds]
        summaries[ds]=aggregate(rr)
        summaries[ds]['duration_strata']={
            '90s':aggregate([r for r in rr if r['durations_s']==[90.]]),
            'short_REFED':aggregate([r for r in rr if max(r['durations_s'])<90.])}
        summaries[ds]['aggregation']='time/component_NMSE_then_window_mean_within_record_then_record_mean_within_subject_then_subject_mean_then_sqrt'
    result=dict(schema=cfg['schema'],status='passed' if not issues else 'failed',counts=counts,
        datasets=summaries,issues=issues,
        maxima={k:max((r['maxima'][k] for r in rows),default=0.) for k in rows[0]['maxima']},
        source='frozen_plan_coordinates_and_every_terminal_task_array',raw_signal_reads=0,refits=0)
    if cfg['schema']=='shared_driver_tak_subject_cache_v4':
        result['migration']=dict(plan['migration'],excluded_tasks_present=any(i.get('reason')=='unexpected_or_excluded_task_identity' for i in issues))
    write_json(out/'verification.json',result)
    summary=dict(schema=cfg['schema'],experiment_id=cfg['experiment_id'],
        status='completed' if not issues else 'verification_failed',counts=counts,datasets=summaries,
        plan='plan.json',coordinates='coordinates.json',verification='verification.json',
        layout='tasks/<dataset>/<subject>/<record>/<window>__p<pair>.json_and_npz',
        claim_limits=cfg['claim_limits'],downstream_join='plan.json:downstream_joins',
        complete_population_includes_failures=True)
    if cfg['schema']=='shared_driver_tak_subject_cache_v4':summary['migration']=result['migration']
    write_json(out/'summary.json',summary)
    if issues:raise ValueError('Independent full-cache verification failed; evidence retained')
    return summary


def tak_cache_worker_capacity(*, cgroup_root=Path('/sys/fs/cgroup'), membership_path=Path('/proc/self/cgroup')):
    """Bound an execution-only worker change by affinity and inherited CPU quota."""
    capacity=len(os.sched_getaffinity(0))
    if not membership_path.exists():
        return capacity
    membership=next((line.split('::',1)[1] for line in membership_path.read_text().splitlines()
                     if line.startswith('0::')),None)
    if membership is None:
        return capacity
    root=cgroup_root.resolve();current=(root/membership.lstrip('/')).resolve()
    if not current.is_relative_to(root):
        raise ValueError('Invalid process cgroup path')
    while current.is_relative_to(root):
        path=current/'cpu.max'
        if path.exists():
            quota,period=path.read_text().split()
            if quota!='max':
                if int(quota)<=0 or int(period)<=0:raise ValueError('Invalid CPU quota')
                capacity=min(capacity,max(1,int(quota)//int(period)))
        if current==root:break
        current=current.parent
    return capacity


def _tak_cache_accelerator_worker(payload):
    from src.inference.shared_driver_reconstruction import LinearSolverUnavailable
    core,output,case,variant=payload;folder=Path(output)/variant;path=folder/(case['id']+'.json')
    if path.exists():
        row=json.loads(path.read_text())
        if row['case']!=case or row['variant']!=variant or not path.with_suffix('.npz').exists():
            raise ValueError('Accelerator comparison resume identity changed')
        return row
    source=Path(case['source'])
    with np.load(source.with_suffix('.npz'),allow_pickle=False) as a:
        target=a['target'];scale=a['scale'];sd=a['sd_subject']*scale;common=a['sd_common']
    coordinate=dict(eeg_factor=float(scale[0]),hb_factor=float(scale[1]),sd=sd)
    client=_TAK_CACHE_GPU_CLIENT if variant=='cuda_structured' else None
    if variant=='cuda_structured' and client is None:
        raise LinearSolverUnavailable('CUDA comparison has no GPU connection')
    before=getattr(client,'requests',0);before_wait=getattr(client,'wait_seconds',0.);started=time.monotonic()
    row,arrays=tak_cache_fit_arrays(core,target,coordinate,common,
        structured=variant!='cpu_dense',linear_solver=client)
    row.update(case=case,variant=variant,seconds=time.monotonic()-started,
        gpu_requests=getattr(client,'requests',0)-before,
        gpu_wait_seconds=getattr(client,'wait_seconds',0.)-before_wait,
        peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    _tak_cache_npz(path.with_suffix('.npz'),**arrays);write_json(path,row)
    return row


def tak_cache_accelerator_check(cfg,core,root,out,args,devices):
    """Read-only retained-case refits in a fresh validation child, not cache writes."""
    from collections import defaultdict
    if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):
        raise ValueError('Full-fit accelerator checks require the durable supervisor')
    if not 1<=args.workers<=min(4,tak_cache_worker_capacity()):
        raise ValueError('Bound accelerator validation to at most four CPU workers')
    target=(args.cache_validation_output or out/'accelerator_validation_v1').resolve()
    if target.parent!=out:raise ValueError('Use a fresh direct child for accelerator validation')
    if json.loads((out/'resolved_config.json').read_text())!=serial(cfg):
        raise ValueError('Exact parent public cache contract required')
    target.mkdir(exist_ok=True)
    lock=(target/'controller.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    cases=[]
    for i in range(4):
        source=out/'synthetic'/f'case{i:02d}.json'
        cases.append(dict(id=f'synthetic_{i}',source=str(source),kind='synthetic',timing_reference=i==0))
    pilot=json.loads((out/'pilot/summary.json').read_text())
    grouped=defaultdict(list)
    for row in pilot['rows']:
        spec=row['identity'];grouped[(spec['dataset'],spec['window']['duration_s'])].append(spec)
    for i,(key,specs) in enumerate(sorted(grouped.items())):
        spec=min(specs,key=lambda s:s['pair']['native_index'])
        source=out/'pilot/tasks'/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
        cases.append(dict(id=f'measured_{i}',source=str(source),kind='measured',
            dataset=spec['dataset'],duration_s=spec['window']['duration_s'],
            timing_reference=spec['dataset']=='eeg_fnirs_single_trial' or spec['window']['short_record']))
    checkpoint=json.loads((out/'resource_continuation_v2_cutover.json').read_text())
    slow=None;negative=None
    for item in sorted(checkpoint['retained_files'],key=lambda r:r['path']):
        if not item['path'].endswith('.json'):continue
        source=out/item['path'];row=json.loads(source.read_text())
        if slow is None and row.get('qualified') and row.get('seconds',0)>=150:
            slow=dict(id='slow_retained',source=str(source),kind='slow',timing_reference=False)
        if negative is None and row.get('status')=='failed_numerical' and source.with_suffix('.npz').exists():
            negative=dict(id='nonconverged_retained',source=str(source),kind='failed_numerical',timing_reference=False)
        if slow and negative:break
    cases += [v for v in (slow,negative) if v is not None]
    thresholds=dict(prediction_max_subject_sd=1e-4,state_max_absolute=1e-4,
        parameter_max_relative=1e-4,objective_max_relative=1e-6,metric_max_absolute=1e-6)
    protocol=dict(schema='tak_cache_accelerator_validation_v1',source_root=str(CODE_ROOT),
        parent=str(out),cases=cases,thresholds=thresholds,gpu_devices=devices,
        variants=['cpu_structured','cuda_structured'],timing_reference='same-session cpu_dense on marked cases',
        missing_or_failed='retain_every_case; failure_status_must_match; failed_trajectories_not_qualified_targets',
        modified_scientific_configuration=False,raw_reads=0,protected_reads=0)
    reference=None
    if args.cache_cpu_reference is not None:
        import ast
        reference=args.cache_cpu_reference.resolve()
        if reference.parent!=out or reference==target:
            raise ValueError('CPU comparison reuse requires a distinct validation child of this run')
        prior=json.loads((reference/'summary.json').read_text())
        prior_protocol=json.loads((reference/'protocol.json').read_text())
        if (prior['status']!='passed' or prior_protocol['cases']!=cases or prior_protocol['thresholds']!=thresholds):
            raise ValueError('Complete matching-case numerical validation required for CPU reuse')
        for relative,names in [
            ('src/inference/shared_driver_reconstruction.py',
             ['fit_nonlinear_shared_parameters','_nonlinear_trial_objective','nonlinear_driver_forward',
              '_volume_tied_initial_embedding','replay_nonlinear_driver','_information_svd']),
            ('experiments/scripts/evaluate_shared_driver_reconstruction.py',
             ['tak_cache_fit_arrays','tak_fit_group','_tak_cache_errors','filter_retest_waveform_metrics'])]:
            def definitions(path):
                return {n.name:ast.dump(n,include_attributes=False) for n in ast.parse(path.read_text()).body
                        if isinstance(n,ast.FunctionDef)}
            previous=definitions(Path(prior['source_root'])/relative);current=definitions(CODE_ROOT/relative)
            if any(previous[name]!=current[name] for name in names):
                raise ValueError('CPU numerical source changed; cannot reuse its comparisons')
        protocol.update(cpu_reference=str(reference),
                        timing_reference='retained_identical_CPU_algebra; CUDA_transport_remeasured')
    if (target/'protocol.json').exists():
        if json.loads((target/'protocol.json').read_text())!=protocol:
            raise ValueError('Immutable accelerator validation source/cases changed; use a fresh child')
    else:write_json(target/'protocol.json',protocol)
    if (target/'summary.json').exists():return json.loads((target/'summary.json').read_text())
    jobs=[]
    for case in cases:
        for variant in (['cpu_dense'] if case['timing_reference'] else [])+protocol['variants']:
            if reference is not None and variant.startswith('cpu_'):
                source=reference/variant/(case['id']+'.json');destination=target/variant/source.name
                if not destination.exists():
                    prior_row=json.loads(source.read_text());prior_row['reused_from']=str(source)
                    destination.parent.mkdir(parents=True,exist_ok=True)
                    os.link(source.with_suffix('.npz'),destination.with_suffix('.npz'))
                    write_json(destination,prior_row)
            else:
                jobs.append((core,str(target),case,variant))
    execution=_tak_cache_pool(_tak_cache_accelerator_worker,jobs,out=target,phase='paired_fits',
        workers=args.workers,total=len(jobs),structured=True,gpu_devices=devices,
        gpu_batch_size=args.cache_gpu_batch_size)
    comparisons=[];issues=[]
    for case in cases:
        baseline=json.loads(Path(case['source']).read_text())
        with np.load(Path(case['source']).with_suffix('.npz'),allow_pickle=False) as a:
            original={key:a[key] for key in ('target','prediction','states','sd_subject','scale') if key in a}
        for variant in (['cpu_dense'] if case['timing_reference'] else [])+protocol['variants']:
            row=json.loads((target/variant/(case['id']+'.json')).read_text())
            comparison=dict(case=case['id'],kind=case['kind'],variant=variant,
                qualified=row['qualified'],baseline_qualified=baseline['qualified'],seconds=row['seconds'],
                gpu_requests=row['gpu_requests'])
            comparison['gpu_wait_seconds']=row.get('gpu_wait_seconds',0.)
            if row.get('reused_from'):comparison['reused_from']=row['reused_from']
            if row['qualified']!=baseline['qualified']:
                issues.append(dict(case=case['id'],variant=variant,reason='qualification_changed'))
            with np.load(target/variant/(case['id']+'.npz'),allow_pickle=False) as a:
                if not np.array_equal(a['target'],original['target']):
                    issues.append(dict(case=case['id'],variant=variant,reason='input_changed'))
                if row['qualified'] and baseline['qualified']:
                    prediction=float(np.max(abs((a['prediction']-original['prediction'])/original['sd_subject'])))
                    state=float(np.max(abs(a['states']-original['states'])))
                    actual=row['fits']['tak_tau_beta'];reference_fit=baseline['fits']['tak_tau_beta']
                    parameter=max(abs(actual[k]/reference_fit[k]-1) for k in ('tau','beta'))
                    objective=abs(actual['solver']['objective']-reference_fit['solver']['objective'])/max(1.,abs(reference_fit['solver']['objective']))
                    metric=max(abs(actual['metrics_common'][k]-reference_fit['metrics_common'][k]) for k in actual['metrics_common'])
                    comparison.update(prediction_max_subject_sd=prediction,state_max_absolute=state,
                        parameter_max_relative=parameter,objective_max_relative=objective,metric_max_absolute=metric)
                    for name,limit in thresholds.items():
                        if comparison[name]>limit:issues.append(dict(case=case['id'],variant=variant,reason=name,value=comparison[name],limit=limit))
                    if not np.allclose(a['target'],a['prediction']+a['residual'],rtol=1e-12,atol=1e-12):
                        issues.append(dict(case=case['id'],variant=variant,reason='residual_closure'))
                    parameters=volume_drive_parameters(core).fixed;states=a['states']
                    canonical=np.column_stack((parameters.eeg_loading*a['driver']+parameters.eeg_offset,
                        parameters.P0*(states[:,4]-1)-parameters.Q0*(states[:,5]-1),parameters.Q0*(states[:,5]-1)))
                    reproduced=(canonical-canonical[:50].mean(0))/a['scale']
                    if not np.allclose(a['prediction'],reproduced,rtol=1e-9,atol=1e-10):
                        issues.append(dict(case=case['id'],variant=variant,reason='state_observation_replay'))
            comparisons.append(comparison)
    timing=[]
    for case in cases:
        if case['timing_reference']:
            found={r['variant']:r['seconds'] for r in comparisons if r['case']==case['id']}
            timing.append(dict(case=case['id'],**found,cpu_structured_speedup=found['cpu_dense']/found['cpu_structured'],
                cuda_structured_speedup=found['cpu_dense']/found['cuda_structured']))
    result=dict(schema=protocol['schema'],status='passed' if not issues else 'failed',
        source_root=str(CODE_ROOT),cases=len(cases),fits=len(comparisons),comparisons=comparisons,
        issues=issues,timing=timing,gpu_devices=devices,thresholds=thresholds,
        configuration_unchanged=True,coordinates_unchanged=True,production_writes=0,
        cpu_reference=str(reference) if reference is not None else None,
        planned_new_fits=len(jobs),reused_CPU_fits=len(comparisons)-len(jobs))
    write_json(target/'summary.json',result)
    if issues:raise ValueError('Accelerator equivalence checks failed; production remains on its existing backend')
    return result


def _tak_cache_v3_coordinates_worker(payload):
    from src.data.ssm_prepared import fit_feature_coordinate
    cfg,out_string,records=payload;out=Path(out_string);first=records[0];key=first['dataset']+'__'+first['subject'];path=out/'calibration'/(key+'.json')
    if any(r['dataset']!=first['dataset'] or r['subject']!=first['subject'] or r['split']!=first['split'] for r in records):raise ValueError('Subject calibration boundary mismatch')
    if first['split'] not in ('train','validation','test'):raise ValueError('Unregistered public split')
    if path.exists():return json.loads(path.read_text())
    began=time.monotonic();sources=[]
    try:
        co=fit_feature_coordinate(_tak_cache_chunks(out,records,counts=sources))
        co.update(status='completed',dataset=first['dataset'],subject=first['subject'],split=first['split'],sources=sources,
            scope='own_unlabelled_observations_all_prepared_records_and_sites',PCA_source=key,
            parameter_comparison='effective_in_individual_PCA_and_scale_coordinates',common_scale_interpretation='fixed_training_reference_SD_not_a_shared_EEG_target')
    except ValueError as exc:co=dict(status='unavailable',dataset=first['dataset'],subject=first['subject'],split=first['split'],sources=sources,error=str(exc))
    value=dict(key=key,coordinate=co,seconds=time.monotonic()-began,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    write_json(path,value);return value


def tak_cache_v3_prepare(cfg,root,out,plan):
    source=(root/cfg['source_cache']['run']).resolve();old=json.loads((source/'plan.json').read_text());verified=json.loads((source/'verification.json').read_text())
    if old['schema']!=cfg['source_cache']['schema'] or verified['status']!='passed':raise ValueError('Verified v1 parent required')
    for key in ('records','subject_partitions','downstream_joins','planned_pair_windows'):
        if plan[key]!=old[key]:raise ValueError('Parent source identities or time support changed: '+key)
    expected=dict(source=str(source),schema=old['schema'],plan=str(source/'plan.json'),verification=str(source/'verification.json'),read_boundary='same_registered_public_subjects_unlabelled_teacher_cache_no_protected_material',raw_reads=0)
    marker=out/'source_reuse.json'
    if marker.exists() and json.loads(marker.read_text())!=expected:raise ValueError('Frozen source reuse identity changed')
    write_json(marker,expected)
    features=out/'features'
    if features.exists():
        if not features.is_symlink() or features.resolve()!=source/'features':raise ValueError('v3 features must reference exact retained parent')
    else:features.symlink_to(source/'features',target_is_directory=True)
    destination=out/'coordinates.json'
    if destination.exists():
        value=json.loads(destination.read_text())
        if value['schema']!=cfg['schema'] or value['calibration']!=cfg['calibration']:raise ValueError('Frozen v3 calibration changed')
        return value
    parent=json.loads((source/'coordinates.json').read_text());groups={}
    for r in plan['records']:groups.setdefault((r['dataset'],r['subject']),[]).append(r)
    execution=_tak_cache_pool(_tak_cache_v3_coordinates_worker,[(cfg,str(out),records) for records in groups.values()],out=out,phase='individual_calibration',workers=cfg['resources']['calibration_workers'],total=len(groups))
    individual={r['key']:r['coordinate'] for r in execution['rows']};population=deepcopy(parent['population'])
    for ds,co in population.items():co['purpose']='reference_scoring_SD_only_not_an_individual_projection'
    for key,co in individual.items():
        if co['status']=='completed':co['parent_PC_signed_cosine']=float(np.asarray(co['pc'])@np.asarray(parent['individual'][key]['pc']))
    result=dict(schema=cfg['schema'],calibration=cfg['calibration'],population=population,individual=individual,labels_used=False,heldout_subject_adaptation=True)
    write_json(destination,result);return result


def tak_cache_v3_seed(source,spec,n):
    """Treat a retained solution solely as an initial value, with identity checks."""
    path=source/'tasks'/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
    if not path.exists():return None,dict(status='unavailable',reason='missing_parent_task',source=str(path))
    old=json.loads(path.read_text());identity=old.get('identity',{})
    for key in ('record_key','dataset','subject','split','window','pair'):
        if identity.get(key)!=spec.get(key):raise ValueError('Parent warm-start identity mismatch: '+key)
    if not old.get('qualified'):return None,dict(status='unavailable',reason='parent_unqualified',source=str(path))
    try:
        with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
            driver=a['driver'].copy();initial=a['initial_state'].copy();clock=a['time_s'].copy()
        fit=old['fits']['tak_tau_beta'];values=np.array([fit['tau'],fit['beta']],float)
        if (driver.shape!=(n,) or initial.shape!=(5,) or not np.isfinite(driver).all() or not np.isfinite(initial).all()
                or not np.isfinite(values).all() or not (.25<=values[0]<=12 and .1<=values[1]<=10)
                or np.any(initial[1:]<=0) or initial[2]!=initial[3] or not np.array_equal(clock,np.arange(n)/10.)):
            raise ValueError('Invalid retained initial state, parameters or clock')
        return dict(parameter_values=values,driver=driver[None],initial_state=initial[None]),dict(status='available',source=str(path),source_schema=old['schema'],parameter_values=values)
    except (OSError,KeyError,ValueError) as exc:return None,dict(status='unavailable',reason=str(exc),source=str(path))


def _tak_cache_v3_fit_worker(payload):
    from src.inference.shared_driver_reconstruction import LinearSolverUnavailable
    cfg,core,out_string,coordinate_string,destination_string,spec=payload[:6];mode=payload[6] if len(payload)>6 else 'auto'
    out=Path(out_string);destination=Path(destination_string);path=destination/'tasks'/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
    weights=np.array(cfg['model']['observation_weights']);started=time.monotonic()
    if path.exists():
        previous=json.loads(path.read_text())
        if (previous.get('schema')!=cfg['schema'] or previous.get('identity')!=spec or previous.get('coordinates')!=coordinate_string
                or previous.get('observation_weights')!=weights.tolist() or (previous.get('qualified') and not path.with_suffix('.npz').exists())):raise ValueError('Terminal v3 cache identity changed')
        return dict(key=str(path.relative_to(destination)),status=previous['status'],qualified=previous['qualified'],seconds=0.,cached=True,route=previous.get('initialization_route'))
    row=dict(schema=cfg['schema'],identity=spec,coordinates=coordinate_string,status='unavailable',qualified=False,observation_weights=weights.tolist());arrays={}
    try:
        if spec['split'] not in ('train','validation','test') or (mode!='auto' and spec['split']!='train'):raise ValueError('Registered public teacher split required; diagnostics training only')
        coordinates=_tak_cache_coordinates(coordinate_string);key=spec['dataset']+'__'+spec['subject'];co=coordinates['individual'][key];population=coordinates['population'][spec['dataset']]
        source=Path(_tak_cache_coordinates(str(out/'source_reuse.json'))['source']);pair=spec['pair'];feature=out/'features'/spec['record_key']/(spec['window']['key']+'.npz')
        if pair['status']!='available' or co['status']!='completed':raise ValueError('Unavailable geometry or subject calibration')
        metadata=json.loads(feature.with_suffix('.json').read_text())
        if metadata['status']!='completed' or metadata['split']!=spec['split']:raise ValueError('Prepared feature status or split mismatch')
        a=_tak_cache_feature_arrays(str(feature));indices=pair['channel_sets']['nearest6'];p=pair.get('compact_index',pair['native_index'])
        if not a['hb_valid'][p] or not a['eeg_valid'][indices].all():raise ValueError('Unsupported source samples')
        n=len(a['eeg']);pc=np.asarray(co['pc']);target=np.column_stack((a['eeg'][:,indices].reshape(n,30)@pc,a['hb'][:,p]))
        common_sd=np.asarray(population['sd'])/np.array([population['eeg_factor'],population['hb_factor'],population['hb_factor']])
        seed_spec=deepcopy(spec);seed_spec['pair'].pop('compact_index',None)
        seed,source_info=tak_cache_v3_seed(source,seed_spec,n);row['warm_source']=source_info
        policy=out/'pilot'/'summary.json';guarded=set(_tak_cache_coordinates(str(policy)).get('standard_subjects',[])) if mode=='auto' and policy.exists() else set()
        use_warm=mode!='standard' and seed is not None and (mode!='auto' or key not in guarded)
        if mode=='warm_only' and seed is None:raise ValueError('Pilot old seed unavailable')
        before_requests=getattr(_TAK_CACHE_GPU_CLIENT,'requests',0);before_wait=getattr(_TAK_CACHE_GPU_CLIENT,'wait_seconds',0.)
        if use_warm:
            try:
                fitted,arrays=tak_cache_fit_arrays(core,target,co,common_sd,structured=True,linear_solver=_TAK_CACHE_GPU_CLIENT,observation_weights=weights,initial_solution=seed)
            except LinearSolverUnavailable:raise
            except (ValueError,FloatingPointError,OverflowError) as exc:
                fitted=dict(status='failed_warm_initialization',qualified=False,error=repr(exc));arrays={}
            route='cached_free_start'
            if not fitted['qualified'] and mode=='auto':
                attempt=destination/'warm_attempts'/spec['record_key']/path.name
                if arrays:_tak_cache_npz(attempt.with_suffix('.npz'),**arrays)
                write_json(attempt,dict(fitted,identity=spec,warm_source=source_info,observation_weights=weights))
                fitted,arrays=tak_cache_fit_arrays(core,target,co,common_sd,structured=True,linear_solver=_TAK_CACHE_GPU_CLIENT,observation_weights=weights)
                route='standard_after_unqualified_warm';row['failed_warm_attempt']=str(attempt.relative_to(destination))
        else:
            fitted,arrays=tak_cache_fit_arrays(core,target,co,common_sd,structured=True,linear_solver=_TAK_CACHE_GPU_CLIENT,observation_weights=weights)
            route='standard_requested' if mode=='standard' else 'standard_subject_guard' if key in guarded else 'standard_missing_seed'
        row.update(fitted,initialization_route=route,feature_source=str(feature.relative_to(out)),provenance=metadata['provenance'],
            gpu_linear_requests=getattr(_TAK_CACHE_GPU_CLIENT,'requests',0)-before_requests,gpu_linear_wait_seconds=getattr(_TAK_CACHE_GPU_CLIENT,'wait_seconds',0.)-before_wait)
        arrays['reference_unscaled']=np.r_[a['eeg_reference'][indices].ravel()@pc,a['hb_reference'][p]]
        if 'prediction' in arrays:
            expected=core['tensor']['dt_s']/core['solver'].get('observation_reference_dt_s',core['tensor']['dt_s'])*np.sum(weights*((arrays['prediction']-arrays['target'])[:-1]/arrays['sd_subject'])**2)
            np.testing.assert_allclose(expected,row['fits']['tak_tau_beta']['solver']['objective_components']['data'],rtol=1e-10,atol=1e-8)
            row['verified_weighted_data_cost']=float(expected)
    except LinearSolverUnavailable:raise
    except Exception:row.update(status='failed_preparation_or_fit',qualified=False,error=traceback.format_exc())
    row.update(seconds=time.monotonic()-started,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    if arrays:_tak_cache_npz(path.with_suffix('.npz'),**arrays)
    write_json(path,row)
    return dict(key=str(path.relative_to(destination)),status=row['status'],qualified=row['qualified'],seconds=row['seconds'],peak_rss_mib=row['peak_rss_mib'],route=row.get('initialization_route'))


def tak_cache_v3_pilot(cfg,core,out,plan,devices):
    pilot=out/'pilot';pilot.mkdir(exist_ok=True);status=pilot/'summary.json'
    if status.exists():return json.loads(status.read_text())
    records=tak_cache_pilot_records(plan);coordinates=json.loads((out/'coordinates.json').read_text())
    for ds in cfg['data']['datasets']:
        candidates=[c for c in coordinates['individual'].values() if c['dataset']==ds and c['split']=='train' and c['status']=='completed']
        far=min(candidates,key=lambda c:c['parent_PC_signed_cosine']);record=next(r for r in plan['records'] if r['dataset']==ds and r['subject']==far['subject'] and r['cache_windows'] and r['cache_windows'][0]['duration_s']==90)
        if record['cache_key'] not in {r['cache_key'] for r in records}:records.append(record)
    specs=list(tak_cache_specs(records,pilot=True,individual_pca=True));write_json(pilot/'plan.json',dict(specs=specs,coordinate_source=str(out/'coordinates.json'),selection=cfg['pilot']['selection']))
    for mode,folder,gpus in [('standard','cpu_standard',()),('warm_only','cpu_warm',()),('warm_only','cuda_warm',tuple(devices))]:
        destination=pilot/folder
        _tak_cache_pool(_tak_cache_v3_fit_worker,[(cfg,core,str(out),str(out/'coordinates.json'),str(destination),s,mode) for s in specs],out=pilot,phase=folder,workers=8,total=len(specs),structured=True,gpu_devices=gpus,gpu_batch_size=4)
    comparisons=[];issues=[];guarded=set();cpu_qualified=0
    for spec in specs:
        relative=Path('tasks')/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
        standard=json.loads((pilot/'cpu_standard'/relative).read_text());cpu=json.loads((pilot/'cpu_warm'/relative).read_text());gpu=json.loads((pilot/'cuda_warm'/relative).read_text())
        key=spec['dataset']+'__'+spec['subject'];entry=dict(record_key=spec['record_key'],window=spec['window']['key'],pair=spec['pair']['id'],subject_key=key,standard_qualified=standard['qualified'],cpu_warm_qualified=cpu['qualified'],gpu_warm_qualified=gpu['qualified'],standard_seconds=standard['seconds'],cpu_warm_seconds=cpu['seconds'],gpu_warm_seconds=gpu['seconds'])
        if not cpu['qualified']:guarded.add(key)
        if cpu['qualified'] and standard['qualified']:
            a=standard['fits']['tak_tau_beta']['solver']['objective'];b=cpu['fits']['tak_tau_beta']['solver']['objective'];entry['warm_relative_objective_change']=(b-a)/max(abs(a),1e-12)
            if entry['warm_relative_objective_change']>cfg['warm_start']['objective_relative_tolerance']:guarded.add(key)
        if cpu['qualified']!=gpu['qualified']:issues.append(dict(identity=spec,reason='CPU_GPU_qualification_mismatch'))
        if cpu['qualified'] and gpu['qualified']:
            cpu_qualified+=1
            with np.load((pilot/'cpu_warm'/relative).with_suffix('.npz'),allow_pickle=False) as a,np.load((pilot/'cuda_warm'/relative).with_suffix('.npz'),allow_pickle=False) as b:
                np.testing.assert_array_equal(a['target'],b['target']);delta=float(np.max(abs(a['prediction']-b['prediction'])/a['sd_subject']));entry['CPU_GPU_prediction_max_SD']=delta
                parameter=max(abs(cpu['fits']['tak_tau_beta'][k]/gpu['fits']['tak_tau_beta'][k]-1) for k in ('tau','beta'));entry['CPU_GPU_parameter_relative']=parameter
                if delta>1e-4 or parameter>1e-4:issues.append(dict(identity=spec,reason='CPU_GPU_numerical_tolerance',prediction=delta,parameter=parameter))
        comparisons.append(entry)
    successful={e['subject_key'].split('__')[0] for e in comparisons if e['standard_qualified'] or e['cpu_warm_qualified']}
    if successful!=set(cfg['data']['datasets']):issues.append(dict(reason='no_qualified_fit_in_some_dataset'))
    result=dict(status='passed' if not issues else 'failed',planned=len(specs),CPU_GPU_qualified_pairs=cpu_qualified,standard_subjects=sorted(guarded),comparisons=comparisons,issues=issues,source_root=str(CODE_ROOT),devices=devices,full_subject_coordinates=True)
    write_json(status,result)
    if issues:raise ValueError('v3 pilot numerical checks failed; production not started')
    return result


def tak_cache_v3_execute(cfg,core,root,out,plan,args,devices):
    if serial(tak_cache_plan(cfg,root))!=plan:raise ValueError('Registered public inventory changed before reuse')
    if args.cache_stage=='produce' and (out/'summary.json').exists():raise ValueError('Completed cache is read-only')
    if args.cache_stage=='produce' and (args.cache_algebra!='structured' or args.cache_linear_backend!='cuda' or devices!=cfg['resources']['gpu_devices']):raise ValueError('v3 production uses validated structured hybrid CPU/CUDA backend')
    started=time.monotonic();execution=dict(schema=cfg['schema'],status='running',stage=args.cache_stage,supervisor=os.environ['SSM_SYSTEMD_UNIT'],command=sys.argv,working_directory=str(Path.cwd()),started_at=datetime.now(timezone.utc).isoformat(),workers=args.workers,gpu_workers=args.cache_gpu_workers,source_root=str(CODE_ROOT))
    write_json(out/'execution.json',execution)
    try:
        tak_cache_v3_prepare(cfg,root,out,plan);pilot=tak_cache_v3_pilot(cfg,core,out,plan,devices)
        if args.cache_stage=='pilot':return dict(status='passed',planned=pilot['planned'],standard_subjects=pilot['standard_subjects'])
        if pilot['status']!='passed' or pilot['source_root']!=str(CODE_ROOT) or pilot['devices']!=devices:raise ValueError('Matching v3 source pilot required')
        records=[r for r in plan['records'] if r['cache_windows']]
        _tak_cache_pool(_tak_cache_fit_worker,((cfg,core,str(out),str(out/'coordinates.json'),str(out),s) for s in tak_cache_specs(records,individual_pca=True)),out=out,phase='reconstruction',workers=args.workers,total=plan['planned_pair_windows'],structured=True,gpu_devices=devices,gpu_batch_size=args.cache_gpu_batch_size,gpu_workers=args.cache_gpu_workers)
        result=tak_cache_verify(cfg,core,out,plan,args.workers);execution.update(status='completed',seconds=time.monotonic()-started);write_json(out/'execution.json',execution);return result
    except Exception:
        execution.update(status='failed',error=traceback.format_exc(),seconds=time.monotonic()-started);write_json(out/'execution.json',execution);raise
    finally:
        if args.cache_stage=='pilot' and execution['status']=='running':execution.update(status='pilot_completed',seconds=time.monotonic()-started);write_json(out/'execution.json',execution)


def tak_cache_v4_plan(cfg,root):
    """Migrate verified metadata; excluded locations never become task specs."""
    from src.data.clean_physiology_cache import CleanPhysiologyCacheIndex
    source=root/cfg['source_cache']['run'];lower=root/cfg['data']['cache_root'];upper=root/cfg['data']['downstream_input']
    parent=json.loads((source/'plan.json').read_text())
    if parent['schema']!=cfg['source_cache']['schema'] or json.loads((source/'verification.json').read_text())['status']!='passed':
        raise ValueError('Verified v3 parent required')
    for cache in (lower,upper):
        if json.loads((cache/'verification.json').read_text())['status']!='passed':raise ValueError('Verified input migration required')
    inputs=json.loads((upper/'input_plan.json').read_text())
    if inputs['schema']!='physiology_downstream_input_v2' or Path(inputs['source_cache']).resolve()!=lower.resolve():raise ValueError('Mismatched v2 measurement source')
    if inputs['subject_partitions']!=parent['subject_partitions']:raise ValueError('Subject splits changed')
    index=CleanPhysiologyCacheIndex(lower);lookup={r.join_key:r for r in index.records}
    if set(lookup)!={r['join_key'] for r in parent['records']}:raise ValueError('Record identities changed')
    plan=deepcopy(parent);plan.update(schema=cfg['schema'],downstream_input=str(upper.resolve()))
    removed=[]
    for record in plan['records']:
        if record['dataset']!=cfg['migration']['dataset']:continue
        m=lookup[record['join_key']].manifest;selection=m['fnirs_selection'];kept=selection['retained_pair_indices']
        if selection['retained_names']!=m['measurement']['fnirs_channel_names']:raise ValueError('Channel names changed')
        original=record['pairs'];pairs=[]
        for i in kept:
            pair=deepcopy(original[i])
            if pair['native_index']!=i or pair['id'].split(':')[-1]!=f'CH{i+1}':raise ValueError('Native pair order changed')
            if pair['status']!='available' and record['cache_windows']:raise ValueError('Usable pair geometry unavailable')
            pair['compact_index']=len(pairs);pair['component_indices']=[2*len(pairs),2*len(pairs)+1];pairs.append(pair)
        removed.append(dict(record_key=record['cache_key'],excluded_pair_ids=[p['id'] for p in original if p['native_index'] not in kept],
            removed_pair_windows=len(record['cache_windows'])*(len(original)-len(pairs))))
        record.update(pairs=pairs,hb_channel_names=m['measurement']['fnirs_channel_names'],array_shapes=m['array_shapes'],
            measurement_record=str(lookup[record['join_key']].npz_path),fnirs_selection=selection)
        if 'geometry_identity' in record:
            record['geometry_identity']['fnirs']=[record['geometry_identity']['fnirs'][i] for i in selection['retained_columns']]
    lookup={r['join_key']:r for r in plan['records']}
    joins=[tak_cache_sample_join(s,lookup[s['join_key']]) for s in inputs['samples']]
    if joins!=parent['downstream_joins']:raise ValueError('Window-to-downstream joins changed')
    for ds,counts in plan['counts'].items():
        rr=[r for r in plan['records'] if r['dataset']==ds]
        counts['pair_windows']=sum(len(r['cache_windows'])*len(r['pairs']) for r in rr)
    plan['planned_pair_windows']=sum(v['pair_windows'] for v in plan['counts'].values())
    changed=cfg['migration']['dataset'];new_count=plan['counts'][changed]['pair_windows']
    plan['migration']=dict(source=str(source.resolve()),measurement=str(lower.resolve()),downstream=str(upper.resolve()),
        refit_dataset=changed,new_fits=new_count,reused_fits=plan['planned_pair_windows']-new_count,
        excluded_pair_windows=parent['counts'][changed]['pair_windows']-new_count,excluded_records=removed,
        EEG_coordinate='frozen_v3',Hb_coordinate='measurement_v6_normalization',other_datasets='immutable_v3_reuse')
    return plan


def _tak_cache_v4_prepare_worker(payload):
    """Copy EEG features; independently replay compact Hb from measurements."""
    cfg,root_string,out_string,record=payload;root=Path(root_string);out=Path(out_string)
    source=root/cfg['source_cache']['run'];directory=out/'features'/record['cache_key'];directory.mkdir(parents=True,exist_ok=True)
    lower=Path(record['measurement_record']);meta=json.loads((lower/'record.json').read_text())
    if meta['fnirs_selection']!=record['fnirs_selection']:raise ValueError('Compact selection changed')
    values=np.load(lower/meta['arrays']['fnirs'],mmap_mode='r').reshape(-1,len(record['pairs']),2)
    indices=[p['native_index'] for p in record['pairs']]
    for w in record['cache_windows']:
        old=source/'features'/record['cache_key']/(w['key']+'.npz');target=directory/old.name
        if target.exists() and target.with_suffix('.json').exists():continue
        metadata=json.loads(old.with_suffix('.json').read_text())
        if metadata['status']!='completed' or metadata['window']!=w or metadata['split']!=record['split']:raise ValueError('Prepared window changed')
        with np.load(old,allow_pickle=False) as a:arrays={k:a[k] for k in a.files}
        start=round(w['hb_start_s']*10);steps=round(w['duration_s']*10);raw=np.asarray(values[start:start+steps]);reference=raw[:50].mean(0);hb=raw-reference
        if len(raw)!=steps or not np.isfinite(raw).all():raise ValueError('Compact measurement support incomplete')
        np.testing.assert_allclose(hb,arrays['hb'][:,indices],rtol=0,atol=1e-12)
        np.testing.assert_allclose(reference,arrays['hb_reference'][indices],rtol=0,atol=1e-12)
        if not arrays['hb_valid'][indices].all():raise ValueError('Usable Hb lacks valid prepared support')
        arrays.update(hb=hb,hb_reference=reference,hb_valid=np.ones(len(indices),bool))
        metadata.update(schema=cfg['schema'],measurement_record=str(lower),source_prepared=str(old),
            fnirs_selection=record['fnirs_selection'],Hb_coordinates='unscaled_measurement_first_5s_referenced; frozen_factor_applied_once_in_solver')
        metadata['provenance']['hb']['cache_path']=str(lower)
        metadata['provenance']['hb']['channel_selection']='visual_device_exclusion_v1'
        _tak_cache_npz(target,**arrays);write_json(target.with_suffix('.json'),metadata)
    return dict(record_key=record['cache_key'],status='completed',windows=len(record['cache_windows']),retained_pairs=len(indices))


def tak_cache_v4_prepare(cfg,root,out,plan):
    source=root/cfg['source_cache']['run'];changed=cfg['migration']['dataset']
    for kind in ('features','tasks'):
        (out/kind).mkdir(exist_ok=True)
        for ds in cfg['data']['datasets']:
            if ds==changed:continue
            path=out/kind/ds;origin=source/kind/ds
            if path.exists():
                if not path.is_symlink() or path.resolve()!=origin.resolve():raise ValueError('Immutable dataset reuse changed')
            else:path.symlink_to(origin.resolve(),target_is_directory=True)
    write_json(out/'source_reuse.json',dict(source=str(source.resolve()),schema=cfg['source_cache']['schema'],
        read_boundary='same_registered_public_subjects_unlabelled_teacher_cache_no_protected_material',raw_reads=0,
        unchanged_datasets=[ds for ds in cfg['data']['datasets'] if ds!=changed]))
    records=[r for r in plan['records'] if r['dataset']==changed and r['cache_windows']]
    _tak_cache_pool(_tak_cache_v4_prepare_worker,[(cfg,str(root),str(out),r) for r in records],out=out,
        phase='preparation',workers=cfg['resources']['preparation_workers'],total=len(records))
    parent=json.loads((source/'coordinates.json').read_text());coordinates=deepcopy(parent)
    coordinates.update(schema=cfg['schema'],calibration=cfg['calibration'],source=str(source.resolve()))
    for key,co in coordinates['individual'].items():
        if co['dataset']!=changed:continue
        norm_path=root/cfg['data']['cache_root']/'normalization'/(co['subject']+'.json');norm=json.loads(norm_path.read_text())
        np.testing.assert_allclose(norm['moments']['old']['factor'],co['hb_factor'],rtol=1e-9)
        co.update(hb_factor=norm['factor'],sd=[co['sd'][0],*(np.array(norm['moments']['usable']['component_sd'])*norm['factor']).tolist()],
            normalization_source=str(norm_path.resolve()),EEG_coordinate_source=str(source/'coordinates.json'),
            Hb_training_samples=norm['moments']['usable']['samples'],sources_scope='retained_v3_EEG_sources; Hb_support_owned_by_normalization_source')
    target=out/'coordinates.json'
    if target.exists() and json.loads(target.read_text())!=coordinates:raise ValueError('Frozen v4 coordinate changed')
    write_json(target,coordinates)
    return records


def tak_cache_v4_pilot(cfg,core,out,records,devices):
    pilot=out/'pilot';pilot.mkdir(exist_ok=True)
    retained=(pilot/'summary.json').exists()
    path=pilot/('verification_v2.json' if retained else 'summary.json')
    if path.exists():return json.loads(path.read_text())
    selected={}
    for r in records:
        if r['split']=='train':selected.setdefault(r['subject'],r)
    specs=list(tak_cache_specs(list(selected.values()),pilot=True,individual_pca=True))
    pilot_plan=dict(specs=specs,selection=cfg['pilot']['selection'])
    if retained:
        if json.loads((pilot/'plan.json').read_text())!=pilot_plan:raise ValueError('Retained pilot identities changed')
    else:write_json(pilot/'plan.json',pilot_plan)
    executions={}
    for mode,folder,gpus in [('standard','cpu_standard',()),('warm_only','cpu_warm',()),('warm_only','cuda_warm',tuple(devices))]:
        if retained:
            executions[folder]=json.loads((pilot/(folder+'_execution.json')).read_text());continue
        executions[folder]=_tak_cache_pool(_tak_cache_v3_fit_worker,
            [(cfg,core,str(out),str(out/'coordinates.json'),str(pilot/folder),s,mode) for s in specs],
            out=pilot,phase=folder,workers=8,total=len(specs),structured=True,gpu_devices=gpus,gpu_batch_size=4)
    issues=[];guarded=set();comparisons=[]
    for spec in specs:
        relative=Path('tasks')/spec['record_key']/(spec['window']['key']+f"__p{spec['pair']['native_index']:03d}.json")
        standard,cpu,gpu=[json.loads((pilot/folder/relative).read_text()) for folder in ('cpu_standard','cpu_warm','cuda_warm')]
        key=spec['dataset']+'__'+spec['subject'];row=dict(subject_key=key,identity=spec,
            standard_qualified=standard['qualified'],warm_qualified=cpu['qualified'],gpu_qualified=gpu['qualified'],
            standard_seconds=standard['seconds'],warm_seconds=cpu['seconds'],gpu_seconds=gpu['seconds'])
        if not cpu['qualified']:guarded.add(key)
        if cpu['qualified'] and standard['qualified']:
            a=standard['fits']['tak_tau_beta']['solver']['objective'];b=cpu['fits']['tak_tau_beta']['solver']['objective']
            row['warm_relative_objective_change']=(b-a)/max(abs(a),1e-12)
            if row['warm_relative_objective_change']>cfg['warm_start']['objective_relative_tolerance']:guarded.add(key)
        if cpu['qualified']!=gpu['qualified']:issues.append(dict(identity=spec,reason='CPU_GPU_qualification_mismatch'))
        if cpu['qualified'] and gpu['qualified']:
            with np.load((pilot/'cpu_warm'/relative).with_suffix('.npz')) as a,np.load((pilot/'cuda_warm'/relative).with_suffix('.npz')) as b:
                np.testing.assert_array_equal(a['target'],b['target']);delta=float(np.max(abs(a['prediction']-b['prediction'])/a['sd_subject']))
            parameter=max(abs(cpu['fits']['tak_tau_beta'][k]/gpu['fits']['tak_tau_beta'][k]-1) for k in ('tau','beta'))
            row.update(CPU_GPU_prediction_max_SD=delta,CPU_GPU_parameter_relative=parameter)
            if delta>1e-4 or parameter>1e-4:issues.append(dict(identity=spec,reason='CPU_GPU_numerical_tolerance'))
        comparisons.append(row)
    if not any(r['standard_qualified'] or r['warm_qualified'] for r in comparisons):
        issues.append(dict(reason='no_qualified_Visual_pilot_fit'))
    result=dict(status='failed' if issues else 'passed',planned=len(specs),comparisons=comparisons,
        standard_subjects=sorted(guarded),issues=issues,source_root=str(CODE_ROOT),devices=devices,
        phase_seconds={k:v['seconds'] for k,v in executions.items()},
        retained_unqualified_examples=[r['identity'] for r in comparisons if not r['standard_qualified'] and not r['warm_qualified']],
        qualification_policy='backend_equivalence_and_Visual_successful_smoke; individual_failures_retained_without_relaxing_solver_qualification',
        prior_pilot_summary=str(pilot/'summary.json') if retained else None)
    write_json(path,result)
    if issues:raise ValueError('v4 pilot checks failed; inspect retained evidence')
    return result


def tak_cache_v4_execute(cfg,core,root,out,plan,args,devices):
    if serial(tak_cache_v4_plan(cfg,root))!=plan:raise ValueError('Frozen v4 input inventory changed')
    if args.cache_stage=='produce' and (out/'summary.json').exists():raise ValueError('Completed cache is read-only')
    if args.cache_algebra!='structured' or args.cache_linear_backend!='cuda' or devices!=cfg['resources']['gpu_devices']:
        raise ValueError('v4 uses validated structured hybrid CPU/CUDA execution')
    started=time.monotonic();execution=dict(schema=cfg['schema'],status='running',stage=args.cache_stage,
        supervisor=os.environ['SSM_SYSTEMD_UNIT'],command=sys.argv,working_directory=str(Path.cwd()),
        started_at=datetime.now(timezone.utc).isoformat(),workers=args.workers,gpu_workers=args.cache_gpu_workers,source_root=str(CODE_ROOT))
    write_json(out/'execution.json',execution)
    try:
        records=tak_cache_v4_prepare(cfg,root,out,plan);pilot=tak_cache_v4_pilot(cfg,core,out,records,devices)
        if pilot['status']!='passed' or pilot['source_root']!=str(CODE_ROOT) or pilot['devices']!=devices:raise ValueError('Matching-source v4 pilot required')
        if args.cache_stage=='pilot':
            execution.update(status='pilot_completed',seconds=time.monotonic()-started);write_json(out/'execution.json',execution);return pilot
        _tak_cache_pool(_tak_cache_fit_worker,
            ((cfg,core,str(out),str(out/'coordinates.json'),str(out),s) for s in tak_cache_specs(records,individual_pca=True)),
            out=out,phase='reconstruction',workers=args.workers,total=plan['migration']['new_fits'],structured=True,
            gpu_devices=devices,gpu_batch_size=args.cache_gpu_batch_size,gpu_workers=args.cache_gpu_workers)
        result=tak_cache_verify(cfg,core,out,plan,args.workers)
        execution.update(status='completed',seconds=time.monotonic()-started);write_json(out/'execution.json',execution);return result
    except Exception:
        execution.update(status='failed',error=traceback.format_exc(),seconds=time.monotonic()-started);write_json(out/'execution.json',execution);raise


def tak_cache_main(args):
    cfg,core=tak_cache_config(args.config);root=args.project_root.resolve();out=args.run_dir.resolve()
    if out.parent!=(root/cfg['output_root']).resolve():
        raise ValueError('Use one fresh direct child of the shared-driver run namespace')
    devices=[int(v) for v in args.cache_gpu_devices.split(',') if v.strip()]
    if (not devices or len(set(devices))!=len(devices) or min(devices)<0
            or not 1<=args.cache_gpu_batch_size<=8):
        raise ValueError('Unique GPU indices and a bounded batch size required')
    if args.cache_gpu_workers is not None and (args.cache_stage!='produce'
            or args.cache_linear_backend!='cuda' or not 1<=args.cache_gpu_workers<=args.workers):
        raise ValueError('Hybrid CUDA worker allocation applies only to production and must fit its worker pool')
    if args.cache_stage=='accelerator-check':
        return tak_cache_accelerator_check(cfg,core,root,out,args,devices)
    out.mkdir(parents=True,exist_ok=True)
    lock=(out/'controller.lock').open('a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    for name,value in [('resolved_config.json',cfg),('resolved_model_config.json',core)]:
        path=out/name
        if path.exists() and json.loads(path.read_text())!=serial(value):
            raise ValueError('Immutable reconstruction cache configuration changed')
        if not path.exists():write_json(path,value)
    stage=args.cache_stage
    if stage not in ('check','plan'):
        if not os.environ.get('INVOCATION_ID') or not os.environ.get('SSM_SYSTEMD_UNIT'):
            raise ValueError('Substantial cache work requires its durable supervisor')
        # The frozen resources section records the initial launch envelope.
        # Later measured resource-only continuations use the existing --workers
        # argument and retain their separate source/launch/resource evidence.
        if not 1<=args.workers<=tak_cache_worker_capacity():
            raise ValueError('Worker count exceeds process affinity or inherited CPU quota')
    if stage=='check':
        result=tak_cache_check(cfg,core,out)
    elif stage=='plan':
        result=tak_cache_plan(cfg,root);path=out/'plan.json'
        if path.exists() and json.loads(path.read_text())!=serial(result):
            raise ValueError('Frozen cache inventory changed')
        if not path.exists():write_json(path,result)
    elif stage=='synthetic':
        if json.loads((out/'software_checks.json').read_text())['status']!='passed':
            raise ValueError('Software checks required')
        result=tak_cache_synthetic(cfg,core,out,args.workers)
    else:
        if not json.loads((out/'synthetic_summary.json').read_text()).get('numerical_checks_passed'):
            raise ValueError('Synthetic numerical checks required before measured reads')
        plan=json.loads((out/'plan.json').read_text())
        if cfg['schema']=='shared_driver_tak_subject_cache_v4' and stage in ('pilot','produce'):
            result=tak_cache_v4_execute(cfg,core,root,out,plan,args,devices)
            print(json.dumps(serial(result)),flush=True);return result
        if cfg['schema']=='shared_driver_tak_subject_cache_v3' and stage in ('pilot','produce'):
            result=tak_cache_v3_execute(cfg,core,root,out,plan,args,devices)
            print(json.dumps(serial(result)),flush=True);return result
        if stage=='verify':
            result=tak_cache_verify(cfg,core,out,plan,args.workers)
        else:
            if serial(tak_cache_plan(cfg,root))!=plan:
                raise ValueError('Frozen public inputs or splits changed before preparation')
            if stage=='pilot':
                result=tak_cache_pilot(cfg,core,root,out,plan,args.workers)
            else:
                if (out/'summary.json').exists():
                    raise ValueError('Completed or verified cache is read-only; use its retained results')
                started=time.monotonic()
                structured=args.cache_algebra=='structured'
                gpu_devices=devices if args.cache_linear_backend=='cuda' else ()
                if structured or gpu_devices:
                    validation=(args.cache_validation_output or out/'accelerator_validation_v1').resolve()
                    if validation.parent!=out:raise ValueError('Validation must belong to this cache')
                    checked=json.loads((validation/'summary.json').read_text())
                    if (checked['status']!='passed' or checked['source_root']!=str(CODE_ROOT)
                            or (gpu_devices and checked['gpu_devices']!=devices)):
                        raise ValueError('Matching-source full-fit accelerator validation required')
                execution=dict(schema=cfg['schema'],status='running',supervisor=os.environ['SSM_SYSTEMD_UNIT'],
                    command=sys.argv,working_directory=str(Path.cwd()),started_at=datetime.now(timezone.utc).isoformat(),
                    observation_algebra=args.cache_algebra,linear_backend=args.cache_linear_backend,
                    gpu_devices=list(gpu_devices),
                    gpu_workers=(args.workers if args.cache_gpu_workers is None else args.cache_gpu_workers) if gpu_devices else 0)
                write_json(out/'execution.json',execution)
                try:
                    pilot=tak_cache_pilot(cfg,core,root,out,plan,args.workers)
                    if not pilot['numerical_smoke_passed']:raise ValueError('Pilot numerical smoke failed')
                    records=[r for r in plan['records'] if r['cache_windows']]
                    _tak_cache_pool(_tak_cache_prepare_worker,
                        ((cfg,str(root),str(out),r,None) for r in records),out=out,phase='preparation',
                        workers=min(args.workers,cfg['resources']['preparation_workers']),total=len(records))
                    tak_cache_calibrate(cfg,out,plan)
                    coordinate_path=out/'coordinates.json'
                    _tak_cache_pool(_tak_cache_fit_worker,
                        ((cfg,core,str(out),str(coordinate_path),str(out),s) for s in tak_cache_specs(
                            records,individual_pca=cfg['schema'] in ('shared_driver_tak_subject_cache_v2','shared_driver_tak_subject_cache_v3','shared_driver_tak_subject_cache_v4'))),
                        out=out,phase='reconstruction',workers=args.workers,total=plan['planned_pair_windows'],
                        structured=structured,gpu_devices=gpu_devices,gpu_batch_size=args.cache_gpu_batch_size,
                        gpu_workers=args.cache_gpu_workers)
                    result=tak_cache_verify(cfg,core,out,plan,args.workers)
                    execution.update(status='completed',seconds=time.monotonic()-started)
                except Exception:
                    execution.update(status='failed',error=traceback.format_exc(),seconds=time.monotonic()-started)
                    write_json(out/'execution.json',execution);raise
                write_json(out/'execution.json',execution)
    print(json.dumps(serial({k:v for k,v in result.items() if k not in
        ('records','downstream_joins','subject_partitions','rows')})),flush=True)
    return result


def normalization_comparison_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_normalization_comparison_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):
        raise ValueError('Use the reviewed three-subject normalization comparison contract')
    return serial(cfg)


def normalization_comparison_coordinates(original, individual, local_old, local_new):
    """Factorial gains/direction; objective denominators never change."""
    result={}
    for name,pc,scale in (
        ('cached_baseline',original['pc'],original),
        ('individual_pca',individual['pc'],original),
        ('local_scale',original['pc'],local_old),
        ('individual_pca_local_scale',individual['pc'],local_new)):
        result[name]=dict(pc=np.asarray(pc),eeg_factor=scale['eeg_factor'],hb_factor=scale['hb_factor'],
            sd=np.asarray(original['sd']),common_scale_interpretation='fixed_original_reference_denominator')
    return result


def normalization_comparison_metrics(target,prediction,coordinate):
    """Unscaled waveform metrics and model-space amplitudes, last bin excluded."""
    y=np.asarray(target,float)[:-1];p=np.asarray(prediction,float)[:-1]
    if y.shape!=p.shape or y.ndim!=2 or y.shape[1]!=3 or not np.isfinite(y).all() or not np.isfinite(p).all():
        raise ValueError('Finite matched target/prediction required')
    scale=np.array([coordinate['eeg_factor'],coordinate['hb_factor'],coordinate['hb_factor']])
    denominator=np.asarray(coordinate['sd'])
    sd=y.std(0);psd=p.std(0);rmse=np.sqrt(np.mean((p-y)**2,axis=0));model_sd=sd*scale
    errors=(p-y)*scale/denominator
    result=dict(input_hb_eeg_ratio=float(np.sqrt(np.mean(model_sd[1:]**2))/model_sd[0]),
        objective_sse=(errors**2).sum(0).tolist(),
        hb_rmse=float(np.sqrt(np.mean((p[:,1:]-y[:,1:])**2))))
    for j,name in enumerate(('eeg','hbo','hbr')):
        result.update({name+'_rmse':float(rmse[j]),name+'_local_nrmse':float(rmse[j]/sd[j]),
            name+'_reference_nrmse':float(rmse[j]*scale[j]/denominator[j]),
            name+'_amplitude_ratio':float(psd[j]/sd[j]),name+'_bias':float((p-y)[:,j].mean()),
            name+'_correlation':float(np.corrcoef(y[:,j],p[:,j])[0,1]) if psd[j]>0 else None,
            name+'_observed_sd':float(sd[j]),name+'_model_sd':float(model_sd[j])})
    return result


def normalization_comparison_select(rows,quantiles=(.1,.5,.9)):
    """Selection depends on observed amplitude only, never reconstruction errors."""
    grouped={}
    for row in rows:
        if row.get('available'):
            grouped.setdefault(row['subject'],[]).append(row)
    eligible={}
    for subject,items in grouped.items():
        chosen=[]
        for row in sorted(items,key=lambda r:(r['window']['hb_start_s'],r['window']['key'])):
            w=row['window']
            if all(w[k]>=c['window'][k]+c['window']['duration_s']-1e-8
                   for c in chosen for k in ('hb_start_s','eeg_start_s')):
                chosen.append(row)
        if len(chosen)>=len(quantiles):eligible[subject]=chosen
    if len(eligible)<3:raise ValueError('Need three subjects with nonoverlapping cached support')
    med={s:float(np.median([r['input_hb_eeg_ratio'] for r in rr])) for s,rr in eligible.items()}
    high=max(med,key=lambda s:(med[s],s));remaining=set(med)-{high}
    balanced=min(remaining,key=lambda s:(abs(np.log(med[s])),s));remaining.remove(balanced)
    low=min(remaining,key=lambda s:(med[s],s))
    panel=[]
    for role,subject in zip(('high','near_one','low'),(high,balanced,low)):
        ordered=sorted(eligible[subject],key=lambda r:(r['input_hb_eeg_ratio'],r['window']['key']))
        for q in quantiles:
            index=int(round(q*(len(ordered)-1)))
            panel.append(dict(ordered[index],selection_role=role,ratio_quantile=q))
    return dict(subject_median_ratio=med,nonoverlapping_counts={s:len(r) for s,r in eligible.items()},
        selected_subjects=[high,balanced,low],panel=panel)


def normalization_comparison_prepare(cfg,out):
    from src.data.ssm_prepared import fit_feature_coordinate
    source=(CODE_ROOT/cfg['source_run']).resolve()
    plan=json.loads((source/'plan.json').read_text());coordinates=json.loads((source/'coordinates.json').read_text())
    core=json.loads((source/'resolved_model_config.json').read_text())
    _,expected=tak_cache_config(CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_tak_subject_cache_v1.yaml')
    if (plan['schema']!=cfg['source_schema'] or coordinates['schema']!=cfg['source_schema'] or core!=serial(expected)):
        raise ValueError('Source plan/coordinate/model contract changed')
    records=[r for r in plan['records'] if r['dataset']==cfg['dataset'] and r['subject'] in cfg['candidate_subjects']]
    if any(r['split']!=cfg['split'] for r in records):raise ValueError('Reject test/protected/cross-split reads')
    if {r['subject'] for r in records}!=set(cfg['candidate_subjects']):raise ValueError('Missing candidate subject')
    census=[]
    for record in records:
        if record['record']!=cfg['record']:continue
        pair=next(p for p in record['pairs'] if p['id']==cfg['site'])
        if pair['status']!='available':raise ValueError('Requested site unavailable')
        co=coordinates['individual'][cfg['dataset']+'__'+record['subject']]
        for window in record['cache_windows']:
            feature=source/'features'/record['cache_key']/(window['key']+'.npz')
            task=source/'tasks'/record['cache_key']/(window['key']+f"__p{pair['native_index']:03d}.json")
            row=dict(subject=record['subject'],record_key=record['cache_key'],window=window,pair=pair,
                feature=str(feature),source_task=str(task),available=False)
            if not task.exists() or not task.with_suffix('.npz').exists() or not feature.with_suffix('.json').exists():
                row['reason']='missing_retained_task_or_feature';census.append(row);continue
            meta=json.loads(feature.with_suffix('.json').read_text());result=json.loads(task.read_text())
            if meta['split']!=cfg['split'] or meta['status']!='completed':
                row['reason']='feature_unavailable';census.append(row);continue
            if (result['identity']['split']!=cfg['split'] or result['identity']['window']!=window
                    or result['identity']['pair']['native_index']!=pair['native_index']):
                raise ValueError('Source task identity differs')
            with np.load(feature,allow_pickle=False) as a:
                indices=pair['channel_sets']['nearest6'];pi=pair['native_index']
                if not a['eeg_valid'][indices].all() or not a['hb_valid'][pi]:
                    row['reason']='invalid_measurement_support';census.append(row);continue
                x=a['eeg'][:,indices].reshape(900,30);h=a['hb'][:,pi]
                target=np.column_stack((x@co['pc'],h))
            with np.load(task.with_suffix('.npz'),allow_pickle=False) as a:
                if 'prediction' not in a:
                    row['reason']='no_cached_prediction';census.append(row);continue
                np.testing.assert_allclose(target,a['target'],rtol=1e-12,atol=1e-12)
                np.testing.assert_allclose(a['scale'],[co['eeg_factor'],co['hb_factor'],co['hb_factor']])
                metric=normalization_comparison_metrics(target,a['prediction'],co)
            row.update(available=True,qualified=result['qualified'],**metric);census.append(row)
    selected=normalization_comparison_select(census,cfg['selection']['quantiles'])
    selected.update(schema=cfg['schema'],selection=cfg['selection'],candidate_windows=len(census),
        unavailable=[r for r in census if not r['available']],scope=cfg['boundary'])
    write_json(out/'selection.json',selected)
    pd.DataFrame([{k:v for k,v in r.items() if k not in ('window','pair','objective_sse')}|{'window_key':r['window']['key']}
        for r in census]).to_csv(out/'baseline_census.csv',index=False)
    fitted={}
    for subject in selected['selected_subjects']:
        own_records=[r for r in records if r['subject']==subject]
        original=coordinates['individual'][cfg['dataset']+'__'+subject]
        counts=[];individual=fit_feature_coordinate(_tak_cache_chunks(source,own_records,counts=counts))
        if individual['training_samples']!=original['training_samples'] or counts!=original['sources']:
            raise ValueError('Individual PCA calibration support differs from retained individual calibration')
        local_records=[dict(r,pairs=[p for p in r['pairs'] if p['id']==cfg['site']]) for r in own_records]
        local_counts=[];local=list(_tak_cache_chunks(source,local_records,counts=local_counts))
        local_old=fit_feature_coordinate(local,fixed_pc=original['pc'])
        local_new=fit_feature_coordinate(local,fixed_pc=individual['pc'])
        arms=normalization_comparison_coordinates(original,individual,local_old,local_new)
        fitted[subject]=dict(arms=arms,original=original,individual=individual,local_old=local_old,local_new=local_new,
            all_site_sources=counts,local_sources=local_counts,
            pca_dot=float(np.asarray(original['pc'])@individual['pc']),
            pca_unsigned_angle_degrees=float(np.degrees(np.arccos(np.clip(abs(np.asarray(original['pc'])@individual['pc']),0,1)))))
    write_json(out/'coordinates.json',fitted);write_json(out/'resolved_model_config.json',core)
    for row in selected['panel']:
        key=row['subject']+'__'+row['window']['key'];co=fitted[row['subject']]['arms']['cached_baseline']
        with np.load(row['feature'],allow_pickle=False) as a:
            x=a['eeg'][:,row['pair']['channel_sets']['nearest6']].reshape(900,30);h=a['hb'][:,row['pair']['native_index']]
        _tak_cache_npz(out/'inputs'/(key+'.npz'),features=x,hb=h)
        task=Path(row['source_task']);baseline=json.loads(task.read_text())
        with np.load(task.with_suffix('.npz'),allow_pickle=False) as a:arrays={k:a[k] for k in a.files}
        baseline.update(arm='cached_baseline',case=key,subject=row['subject'],source_task=str(task),
            coordinate=co,metrics=normalization_comparison_metrics(arrays['target'],arrays['prediction'],co),
            target_correlation_with_original=1.)
        _tak_cache_npz(out/'tasks'/(key+'__cached_baseline.npz'),**arrays)
        write_json(out/'tasks'/(key+'__cached_baseline.json'),baseline)
    result=dict(status='completed',selected_subjects=selected['selected_subjects'],selected_windows=len(selected['panel']),
        baseline_available=sum(r['available'] for r in census),candidate_windows=len(census),
        raw_reads=0,test_reads=0,protected_reads=0,weights=[1,1,1],objective_SD='frozen_original_all_arms')
    write_json(out/'preparation.json',result)
    return result


def _normalization_comparison_worker(payload):
    out_string,core,row,arm,coordinate=payload;out=Path(out_string);started=time.monotonic()
    case=row['subject']+'__'+row['window']['key'];path=out/'tasks'/(case+'__'+arm+'.json')
    if path.exists():return dict(case=case,arm=arm,status=json.loads(path.read_text())['status'],cached=True)
    record=dict(case=case,subject=row['subject'],arm=arm,coordinate=coordinate,qualified=False)
    try:
        with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:
            x=a['features'];target=np.column_stack((x@coordinate['pc'],a['hb']))
        with np.load(out/'tasks'/(case+'__cached_baseline.npz'),allow_pickle=False) as a:
            old_target=a['target'];old_prediction=a['prediction'];old_sd=a['sd_subject']
        record['target_correlation_with_original']=float(np.corrcoef(target[:,0],old_target[:,0])[0,1])
        fit,arrays=tak_cache_fit_arrays(core,target,coordinate,old_sd,structured=True)
        record.update(fit)
        if 'prediction' in arrays:
            record['metrics']=normalization_comparison_metrics(target,arrays['prediction'],coordinate)
        if arm=='baseline_replay' and 'prediction' in arrays:
            baseline=json.loads((out/'tasks'/(case+'__cached_baseline.json')).read_text())
            objective=baseline['fits']['tak_tau_beta']['solver']['objective']
            record['replay']=dict(max_prediction_difference_original_SD=float(np.max(abs((arrays['prediction']-old_prediction)/old_sd))),
                relative_objective_difference=float(abs(fit['fits']['tak_tau_beta']['solver']['objective']-objective)/max(1,abs(objective))))
        _tak_cache_npz(path.with_suffix('.npz'),**arrays)
    except Exception:
        record.update(status='failed_exception',error=traceback.format_exc())
    record.update(seconds=time.monotonic()-started,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    write_json(path,record)
    return dict(case=case,arm=arm,status=record['status'],qualified=record.get('qualified'),seconds=record['seconds'])


def normalization_comparison_run(cfg,out,workers,*,pilot=False):
    selected=json.loads((out/'selection.json').read_text());co=json.loads((out/'coordinates.json').read_text())
    core=json.loads((out/'resolved_model_config.json').read_text());jobs=[]
    for row in selected['panel']:
        arms=(['baseline_replay','local_scale'] if row['ratio_quantile']==.5 else []) if pilot else cfg['arms'][1:]
        for arm in arms:
            coord=co[row['subject']]['arms']['cached_baseline' if arm=='baseline_replay' else arm]
            jobs.append((str(out),core,row,arm,coord))
    return _tak_cache_pool(_normalization_comparison_worker,jobs,out=out,
        phase='normalization_pilot' if pilot else 'normalization_fits',workers=workers,total=len(jobs),structured=True)


def normalization_comparison_check(cfg,out):
    from src.data.ssm_prepared import fit_feature_coordinate
    rng=np.random.default_rng(cfg['seed']);x=rng.normal(size=(900,30));x[:,0]*=5
    h=rng.normal(size=(900,2))*[3,1];old=fit_feature_coordinate([(x,h)])
    changed=x.copy();changed[:,1]*=30
    individual=fit_feature_coordinate([(changed,h)])
    local_old=fit_feature_coordinate([(changed,h*8)],fixed_pc=old['pc'])
    local_new=fit_feature_coordinate([(changed,h*8)],fixed_pc=individual['pc'])
    arms=normalization_comparison_coordinates(old,individual,local_old,local_new)
    for co in arms.values():np.testing.assert_array_equal(co['sd'],old['sd'])
    assert arms['individual_pca']['hb_factor']==old['hb_factor']
    np.testing.assert_array_equal(arms['local_scale']['pc'],old['pc'])
    assert arms['local_scale']['hb_factor']!=old['hb_factor']
    y=np.column_stack((x@old['pc'],h));m=normalization_comparison_metrics(y,y,old)
    assert m['hb_rmse']==0 and m['eeg_local_nrmse']==0
    result=dict(status='passed',measured_reads=0,checks=['four_arm_factorial','fixed_objective_SD','unchanged_component_weights','metric_roundtrip'])
    write_json(out/'software_checks.json',result);return result


def normalization_comparison_summarize(cfg,out):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from scipy.stats import spearmanr
    selected=json.loads((out/'selection.json').read_text());coordinates=json.loads((out/'coordinates.json').read_text())
    rows=[];replays=[];missing=[]
    for case in selected['panel']:
        key=case['subject']+'__'+case['window']['key']
        for arm in cfg['arms']:
            path=out/'tasks'/(key+'__'+arm+'.json')
            if not path.exists():missing.append(str(path));continue
            item=json.loads(path.read_text())
            rows.append(dict(case=key,subject=case['subject'],window=case['window']['key'],arm=arm,
                ratio_quantile=case['ratio_quantile'],status=item['status'],qualified=item['qualified'],
                target_correlation_with_original=item.get('target_correlation_with_original'),
                **item.get('metrics',{})))
        if case['ratio_quantile']==.5:
            path=out/'tasks'/(key+'__baseline_replay.json')
            if not path.exists():missing.append(str(path));continue
            item=json.loads(path.read_text());r=item.get('replay',{})
            passed=bool(item.get('qualified') and r.get('max_prediction_difference_original_SD',np.inf)<=cfg['replay']['maximum_prediction_difference_original_SD']
                and r.get('relative_objective_difference',np.inf)<=cfg['replay']['maximum_relative_objective_difference'])
            replays.append(dict(case=key,passed=passed,**r))
    if missing:raise ValueError('Incomplete comparison: '+str(missing[:5]))
    checks=dict(target_max_abs=0.,fixed_objective_sd_max_abs=0.,metric_max_abs=0.,
        objective_data_max_abs=0.,closure_max_abs=0.,Hb_between_arms_max_abs=0.)
    for row in rows:
        case,arm=row['case'],row['arm'];co=coordinates[row['subject']]['arms'][arm]
        with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as inp:
            expected_target=np.column_stack((inp['features']@co['pc'],inp['hb']))
        with np.load(out/'tasks'/(case+'__'+arm+'.npz'),allow_pickle=False) as a:
            y,p=a['target'],a['prediction'];gain=a['scale'];objective_sd=a['sd_subject']*gain
            e=(p-y)[:-1];sd=y[:-1].std(0);rmse=np.sqrt((e*e).mean(0))
            checks['target_max_abs']=max(checks['target_max_abs'],float(np.max(abs(y-expected_target))))
            checks['fixed_objective_sd_max_abs']=max(checks['fixed_objective_sd_max_abs'],float(np.max(abs(objective_sd-co['sd']))))
            checks['closure_max_abs']=max(checks['closure_max_abs'],float(np.max(abs(y-p-a['residual']))))
            for j,name in enumerate(('eeg','hbo','hbr')):
                checks['metric_max_abs']=max(checks['metric_max_abs'],abs(float(rmse[j]/sd[j])-row[name+'_local_nrmse']))
            data_cost=.4*float(np.sum((e*gain/objective_sd)**2))
            saved=json.loads((out/'tasks'/(case+'__'+arm+'.json')).read_text())
            checks['objective_data_max_abs']=max(checks['objective_data_max_abs'],abs(data_cost-saved['fits']['tak_tau_beta']['solver']['objective_components']['data']))
            with np.load(out/'tasks'/(case+'__cached_baseline.npz'),allow_pickle=False) as b:
                checks['Hb_between_arms_max_abs']=max(checks['Hb_between_arms_max_abs'],float(np.max(abs(y[:,1:]-b['target'][:,1:]))))
    passed=all(value<=1e-8 for value in checks.values()) and all(r['passed'] for r in replays)
    write_json(out/'verification.json',dict(status='passed' if passed else 'failed',checks=checks,
        baseline_replays=replays,explicit_weights=[1,1,1],fixed_original_objective_SD=True))
    if not passed:raise ValueError('Independent comparison verification failed')
    frame=pd.DataFrame(rows);frame.to_csv(out/'window_metrics.csv',index=False)
    metrics=['input_hb_eeg_ratio','eeg_local_nrmse','eeg_amplitude_ratio','eeg_correlation',
        'hb_rmse','hbo_local_nrmse','hbr_local_nrmse','hbo_correlation','hbr_correlation','target_correlation_with_original']
    subject=frame.groupby(['subject','arm'],sort=False)[metrics].median().reset_index()
    counts=frame.groupby(['subject','arm'],sort=False).agg(windows=('case','size'),qualified=('qualified','sum')).reset_index()
    subject=subject.merge(counts,on=['subject','arm']);subject.to_csv(out/'subject_metrics.csv',index=False)
    aggregate=subject.groupby('arm',sort=False)[metrics].mean().reset_index()
    aggregate.to_csv(out/'aggregate_metrics.csv',index=False)
    paired=[]
    for _,r in frame.iterrows():
        if r['arm']=='cached_baseline':continue
        b=frame[(frame.case==r['case']) & (frame.arm=='cached_baseline')].iloc[0]
        paired.append(dict(subject=r['subject'],case=r['case'],arm=r['arm'],
            **{k+'_delta':float(r[k]-b[k]) for k in metrics if k!='target_correlation_with_original'}))
    paired_frame=pd.DataFrame(paired);paired_frame.to_csv(out/'paired_differences.csv',index=False)
    contrasts=paired_frame.groupby(['subject','arm'],sort=False).median(numeric_only=True).reset_index()
    contrasts.to_csv(out/'subject_paired_differences.csv',index=False)
    census=pd.read_csv(out/'baseline_census.csv');available=census[census.available==True]
    correlations=[]
    for s,g in available.groupby('subject'):
        correlations.append(dict(subject=s,windows=len(g),qualified=int(g.qualified.sum()),
            input_ratio_median=float(g.input_hb_eeg_ratio.median()),
            input_ratio_p10=float(g.input_hb_eeg_ratio.quantile(.1)),input_ratio_p90=float(g.input_hb_eeg_ratio.quantile(.9)),
            eeg_nrmse_median=float(g.eeg_local_nrmse.median()),eeg_nrmse_max=float(g.eeg_local_nrmse.max()),
            amplitude_ratio_median=float(g.eeg_amplitude_ratio.median()),amplitude_ratio_max=float(g.eeg_amplitude_ratio.max()),
            error_above_one=int((g.eeg_local_nrmse>1).sum()),amplitude_above_two=int((g.eeg_amplitude_ratio>2).sum()),
            spearman_ratio_vs_eeg_error=float(spearmanr(g.input_hb_eeg_ratio,g.eeg_local_nrmse).statistic),
            spearman_ratio_vs_amplitude=float(spearmanr(g.input_hb_eeg_ratio,g.eeg_amplitude_ratio).statistic)))
    pd.DataFrame(correlations).to_csv(out/'baseline_severity.csv',index=False)
    labels={'cached_baseline':'Cached baseline','individual_pca':'Individual PCA',
        'local_scale':'Local scale','individual_pca_local_scale':'PCA + local scale'}
    colors=['#666666','#2266bb','#df8124','#27946d'];figures=[]
    fig,axes=plt.subplots(1,3,figsize=(15,4.6),constrained_layout=True)
    for i,(metric,title) in enumerate((('eeg_local_nrmse','EEG error / own target SD'),
            ('eeg_amplitude_ratio','Predicted / observed EEG SD'),('hb_rmse','Hb joint RMSE (uM)'))):
        for k,arm in enumerate(cfg['arms']):
            values=[float(subject[(subject.subject==s)&(subject.arm==arm)][metric].iloc[0]) for s in selected['selected_subjects']]
            axes[i].bar(np.arange(3)+(k-1.5)*.19,values,width=.18,color=colors[k],label=labels[arm])
        axes[i].set_xticks(np.arange(3),selected['selected_subjects']);axes[i].set_title(title);axes[i].grid(axis='y',alpha=.2)
        if i<2:axes[i].axhline(1,color='black',ls=':',lw=1)
    axes[0].legend(fontsize=8);fig.suptitle('Per-subject median of 3 fixed windows; all explicit weights = 1')
    fig.savefig(out/'comparison.png',dpi=220);plt.close(fig);figures.append('comparison.png')
    fig,axes=plt.subplots(1,2,figsize=(12,4.5),constrained_layout=True)
    for s,g in available.groupby('subject'):
        for ax,y in zip(axes,('eeg_local_nrmse','eeg_amplitude_ratio')):
            ax.scatter(g.input_hb_eeg_ratio,g[y],s=25,alpha=.7,label=s);ax.set_xscale('log');ax.grid(alpha=.2)
            ax.set_xlabel('Observed model-space combined Hb SD / EEG SD')
    axes[0].set_ylabel('EEG error / observed window SD');axes[1].set_ylabel('Predicted / observed EEG SD')
    axes[1].axhline(1,color='black',ls=':');axes[0].legend(fontsize=8)
    fig.suptitle('Existing equal-weight cache: 5 development subjects; overlapping windows are dependent')
    fig.savefig(out/'baseline_severity.png',dpi=220);plt.close(fig);figures.append('baseline_severity.png')
    fig,axes=plt.subplots(2,3,figsize=(14,7),constrained_layout=True)
    for k,s in enumerate(selected['selected_subjects']):
        g=frame[frame.subject==s].copy();g['hb_model_sd']=np.sqrt((g.hbo_model_sd**2+g.hbr_model_sd**2)/2)
        med=g.groupby('arm').median(numeric_only=True).reindex(cfg['arms'])
        axes[0,k].plot(range(4),med.eeg_model_sd,'o-',label='EEG observed SD')
        axes[0,k].plot(range(4),med.hb_model_sd,'s-',label='Combined Hb observed SD')
        axes[0,k].axhline(.025,color='gray',ls=':',label='Calibration target 0.025')
        axes[0,k].set_title(s);axes[0,k].set_ylabel('Model-coordinate SD');axes[0,k].legend(fontsize=8)
        axes[1,k].bar(range(4),med.input_hb_eeg_ratio,color=colors)
        axes[1,k].axhline(1,color='black',ls=':');axes[1,k].set_ylabel('Combined Hb SD / EEG SD')
        for ax in axes[:,k]:ax.set_xticks(range(4),['Baseline','PCA','Scale','PCA+Scale']);ax.grid(axis='y',alpha=.2)
    fig.suptitle('Observed amplitudes after calibration: per-subject median of the same 3 windows')
    fig.savefig(out/'input_scales.png',dpi=220);plt.close(fig);figures.append('input_scales.png')
    for case in selected['panel']:
        key=case['subject']+'__'+case['window']['key'];fig,axes=plt.subplots(3,4,figsize=(18,9),sharex=True,constrained_layout=True)
        ranges=[[],[],[]]
        for k,arm in enumerate(cfg['arms']):
            path=out/'tasks'/(key+'__'+arm+'.npz')
            if not path.exists():
                for ax in axes[:,k]:ax.text(.5,.5,'NO PREDICTION',ha='center',transform=ax.transAxes)
                continue
            with np.load(path,allow_pickle=False) as a:y=a['target'][:-1];p=a['prediction'][:-1];t=a['time_s'][:-1]
            r=frame[(frame.case==key)&(frame.arm==arm)].iloc[0]
            for j,name in enumerate(('eeg','hbo','hbr')):
                ax=axes[j,k];ax.plot(t,y[:,j],color='#6c7481',lw=1,label='Observed (this PCA) ' if j==0 else 'Observed')
                ax.plot(t,p[:,j],color=colors[k],lw=1.1,label='SSM reconstruction',ls='--' if k==0 else '-')
                ranges[j].extend([float(y[:,j].min()),float(y[:,j].max()),float(p[:,j].min()),float(p[:,j].max())])
                ax.set_title((labels[arm]+'\n' if j==0 else '')+
                    f"NRMSE={r[name+'_local_nrmse']:.3f}  SD ratio={r[name+'_amplitude_ratio']:.2f}",fontsize=10)
                ax.grid(alpha=.2)
                if j==2:ax.set_xlabel('Within-window time (s)')
                if k==0:ax.set_ylabel(('EEG PCA log-power','HbO (uM)','HbR (uM)')[j])
                if j==0:ax.legend(fontsize=7,loc='best')
        for j in range(3):
            if ranges[j]:
                lo,hi=min(ranges[j]),max(ranges[j]);pad=(hi-lo)*.06+1e-9
                for ax in axes[j]:ax.set_ylim(lo-pad,hi+pad)
        fig.suptitle(f"{case['subject']} | n-back | POOz | {case['window']['key']} | baseline input Hb/EEG ratio {case['input_hb_eeg_ratio']:.3f}\n"
            'Same window and row limits; EEG observations change with PCA; Hb observations are identical',fontsize=13)
        filename=key+'.png';fig.savefig(out/filename,dpi=220);plt.close(fig);figures.append(filename)
    completion=dict(schema=cfg['schema'],status='completed',subjects=selected['selected_subjects'],
        selected_windows=len(selected['panel']),planned_cells=len(selected['panel'])*4,terminal_cells=len(frame),
        qualified_cells=int(frame.qualified.sum()),failed_cells=frame.loc[~frame.qualified,['case','arm','status']].to_dict('records'),
        replay_verified=all(r['passed'] for r in replays),baseline_replays=replays,
        baseline_severity=correlations,subject_metrics=subject.to_dict('records'),aggregate=aggregate.to_dict('records'),
        contrasts=contrasts.to_dict('records'),figures=figures,
        controls=cfg['controls'],calibration_scope=cfg['calibration']['scope'],
        interpretation=cfg['endpoints'],raw_reads=0,protected_reads=0,test_reads=0)
    write_json(out/'summary.json',completion)
    tablecols=['subject','arm','input_hb_eeg_ratio','eeg_local_nrmse','eeg_amplitude_ratio','hb_rmse','qualified','windows']
    intro='''<h1>三被试 EEG–fNIRS 归一化控制实验</h1>
<p>目标：确认已有等权缓存的模态幅度失配程度，分离个体 PCA 与目标通道尺度校准的作用。
所有组固定 τ/β 模型、三个参数起点、先验、驱动/初态正则、收敛与积分阈值。
显式 EEG/HbO/HbR 权重均为 1；残差分母固定为原被试校准 SD。</p>
<p>个体 PCA 使用该被试原有全部有效缓存窗口和位置；局部尺度使用同一被试全部记录的 POOz。
尺度仍用原合并 SD 算法，未加入 MAD、Hb 观测增益、噪声白化或稳健损失。
校准包括评价支持，属于离线无标签个体适配，不是独立窗口预测。</p>
<p>候选为同一 Simultaneous 数据集的 5 名验证被试，固定 n-back 与 POOz。
先按时间去除重叠窗口，按每人 Hb/EEG 模型尺度比的中位数选最高、最接近 1、最低者，
各取幅度比分布 P10/P50/P90 附近的三个窗口。没有按拟合结果选样。</p>
<p>输入比 = sqrt((SD(HbO)^2+SD(HbR)^2)/2)/SD(EEG)，在缓存模型坐标中计算。
图中 NRMSE = RMSE/该窗口对应观测 SD；SD ratio = 预测 SD/观测 SD。
统计排除末个缓存时间点，与原拟合掩码一致；均值偏差保留在 RMSE 中。
表为被试内三个窗口的中位数，总汇总为三名被试等权平均。
PCA 改变 EEG 目标内容，其误差仅表示对该组代理的拟合，Hb µM 误差是共同测量比较。</p>
<p>Cached baseline=原缓存；Individual PCA=只换个体方向；Local scale=只换 POOz 尺度；
PCA + local scale=两者结合。改变缩放会改变模型观测坐标，不能称为仅更换单位；
未改显式权重和残差分母。质量失败完整保留，数值收敛不表示干净神经信号。</p>'''
    html='<html><head><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1500px;margin:30px auto;padding:0 20px;line-height:1.7}table{border-collapse:collapse;font-size:13px}td,th{border:1px solid #ccc;padding:5px}img{width:100%;height:auto}h2{margin-top:35px}</style></head><body>'+intro
    html+='<h2>原缓存幅度与重建严重程度</h2>'+pd.DataFrame(correlations).to_html(index=False,float_format=lambda x:f'{x:.4f}')
    html+='<img src="baseline_severity.png"><h2>三被试配对比较</h2>'+subject[tablecols].to_html(index=False,float_format=lambda x:f'{x:.4f}')
    html+='<img src="comparison.png"><h2>归一化后的实测输入幅度</h2><p>上排分别为 EEG 和合并 Hb 的模型坐标 SD，下排为两者比值；均是同一组三窗口的被试内中位数。0.025 是校准支持上的目标，不强制每个评价窗口达到该值。</p><img src="input_scales.png"><p>完整逐窗指标：<a href="window_metrics.csv">CSV</a>；配对差值：<a href="paired_differences.csv">CSV</a>；唯一数值汇总：<a href="summary.json">summary.json</a>。</p>'
    html+='<h2>基线复现</h2>'+pd.DataFrame(replays).to_html(index=False,float_format=lambda x:f'{x:.6g}')
    html+='<h2>PCA 方向与冻结尺度</h2>'+pd.DataFrame([dict(subject=s,arm=a,pca_dot=coordinates[s]['pca_dot'],
        eeg_gain=c['eeg_factor'],hb_gain=c['hb_factor'],objective_SD=str(c['sd']))
        for s in selected['selected_subjects'] for a,c in coordinates[s]['arms'].items()]).to_html(index=False,float_format=lambda x:f'{x:.5g}')
    for case in selected['panel']:
        key=case['subject']+'__'+case['window']['key']
        html+=f'<h2>{key}：原幅度比 {case["input_hb_eeg_ratio"]:.3f}，分位选择 {case["ratio_quantile"]}</h2><p>每列为一组，灰线为该组观测，彩色线为完整 SSM 重建。逐行统一纵轴；个体 PCA 列的 EEG 观测随投影改变。完整 90 秒联合可见，非未来预测；时间终点按原末点掩码显示至 89.8 秒。</p><img src="{key}.png">'
    html+=f'<p>计划 {len(frame)} 个比较单元，数值合格 {int(frame.qualified.sum())}，基线复现通过：{completion["replay_verified"]}。三名被试为针对性选择，不进行人群显著性检验；重叠缓存窗口不视为独立样本。未生成新的电压 S/O 标签。</p></body></html>'
    (out/'report.html').write_text(html)
    return {k:v for k,v in completion.items() if k not in ('subject_metrics','aggregate','contrasts','baseline_severity','figures')}


def normalization_comparison_main(args):
    cfg=normalization_comparison_config(args.config);out=args.run_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    resolved=out/'resolved_config.json'
    if resolved.exists() and json.loads(resolved.read_text())!=cfg:raise ValueError('Comparison resume contract changed')
    write_json(resolved,cfg)
    stage=args.normalization_stage
    if stage=='check':result=normalization_comparison_check(cfg,out)
    elif stage=='prepare':
        if json.loads((out/'software_checks.json').read_text())['status']!='passed':raise ValueError('Software check required')
        if (out/'preparation.json').exists():result=json.loads((out/'preparation.json').read_text())
        else:result=normalization_comparison_prepare(cfg,out)
    elif stage in ('pilot','run'):
        if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable supervised execution required')
        with (out/'controller.lock').open('w') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            result=normalization_comparison_run(cfg,out,args.workers,pilot=stage=='pilot')
    else:result=normalization_comparison_summarize(cfg,out)
    print(json.dumps(serial(result if stage in ('check','prepare') else {k:v for k,v in result.items() if k!='rows'})),flush=True)
    return result


def amplitude_frequency_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_amplitude_frequency_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):raise ValueError('Use reviewed amplitude frequency scope/thresholds')
    return cfg


def amplitude_frequency_flags(ratio,amplitude,error,thresholds):
    high=np.asarray(ratio)>=thresholds['input_Hb_over_EEG_SD']
    amplified=np.asarray(amplitude)>=thresholds['prediction_over_observed_EEG_SD']
    bad=np.asarray(error)>=thresholds['local_EEG_NRMSE']
    return dict(input_high=high,amplified=amplified,bad_error=bad,joint=high&amplified,
        high_and_bad=high&bad,attenuated=np.asarray(amplitude)<=thresholds['attenuation_SD_ratio'])


def amplitude_frequency_nonoverlap(windows):
    selected=[]
    for w in sorted(windows,key=lambda x:(x['hb_start_s'],x['key'])):
        if all(w[k]>=v[k]+v['duration_s']-1e-8 for v in selected for k in ('eeg_start_s','hb_start_s')):
            selected.append(w)
    return {w['key'] for w in selected}


def _amplitude_frequency_record(payload):
    cfg,source_string,out_string,record,coordinate,cutoff=payload
    if record['split'] not in cfg['splits'] or record['dataset'] not in cfg['datasets']:
        raise ValueError('Disallowed split/dataset before task reads')
    source,out=Path(source_string),Path(out_string);destination=out/'records'/record['cache_key']
    destination=destination.with_suffix('.csv');meta=destination.with_suffix('.json')
    if meta.exists():return json.loads(meta.read_text())
    began=time.monotonic();nonoverlap=amplitude_frequency_nonoverlap(record['cache_windows']);rows=[]
    for window in record['cache_windows']:
        for pair in record['pairs']:
            path=source/'tasks'/record['cache_key']/(window['key']+f"__p{pair['native_index']:03d}.json")
            base=dict(dataset=record['dataset'],subject=record['subject'],split=record['split'],record=record['record'],
                record_key=record['cache_key'],window=window['key'],site=pair['id'],pair=pair['native_index'],
                duration_s=window['duration_s'],nonoverlap=window['key'] in nonoverlap,source_task=str(path))
            item=None;reason='missing_at_cutoff'
            if path.exists() and path.stat().st_mtime<=cutoff:
                item=json.loads(path.read_text());identity=item['identity'];reason=item['status']
                if (item['schema']!=cfg['source_schema'] or identity['record_key']!=record['cache_key']
                        or identity['split']!=record['split'] or identity['window']!=window
                        or identity['pair']['native_index']!=pair['native_index']):
                    raise ValueError('Task identity mismatch: '+str(path))
            for arm in cfg['arms']:
                fit={} if item is None else item.get('fits',{}).get(arm,{})
                row=dict(base,arm=arm,terminal=item is not None,status=reason,finite=False,
                    qualified=bool(fit.get('qualified',False)),input_ratio=np.nan,amplitude=np.nan,error=np.nan,
                    correlation=np.nan,observed_eeg_sd=np.nan)
                wave=fit.get('waveform')
                if wave and [v['component'] for v in wave]==['EEG','HbO','HbR'] and coordinate.get('status')=='completed':
                    sd=np.array([v['target_centered_rms_in_cache_unit'] for v in wave],float)
                    amplitude=wave[0]['centered_amplitude_ratio'];error=wave[0]['local_centered_nrmse']
                    if np.isfinite(sd).all() and np.all(sd>1e-12) and amplitude is not None and error is not None:
                        scaled=sd*np.array([coordinate['eeg_factor'],coordinate['hb_factor'],coordinate['hb_factor']])
                        ratio=float(np.sqrt(np.mean(scaled[1:]**2))/scaled[0])
                        row.update(finite=bool(np.isfinite([ratio,amplitude,error]).all()),input_ratio=ratio,
                            amplitude=amplitude,error=error,correlation=wave[0]['pearson_r'],observed_eeg_sd=sd[0])
                rows.append(row)
    destination.parent.mkdir(parents=True,exist_ok=True)
    frame=pd.DataFrame(rows);temporary=destination.with_suffix('.tmp.csv');frame.to_csv(temporary,index=False);temporary.replace(destination)
    result=dict(record_key=record['cache_key'],rows=len(rows),terminal=sum(r['terminal'] for r in rows),
        finite=sum(r['finite'] for r in rows),qualified=sum(r['finite'] and r['qualified'] for r in rows),
        seconds=time.monotonic()-began,file=str(destination))
    write_json(meta,result);return result


def amplitude_frequency_check(cfg,out):
    th=cfg['thresholds'];r=amplitude_frequency_flags(np.array([1.49,1.5,2]),np.array([2,2,1.99]),np.ones(3),th)
    assert r['joint'].tolist()==[False,True,False]
    assert amplitude_frequency_nonoverlap([dict(key=str(i),eeg_start_s=i*60,hb_start_s=i*60+5,duration_s=90)
        for i in range(5)])=={'0','2','4'}
    result=dict(status='passed',measured_reads=0,checks=['inclusive_thresholds','both_clock_nonoverlap','explicit_train_validation_scope'])
    write_json(out/'software_checks.json',result);return result


def amplitude_frequency_scan(cfg,out,workers):
    if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable supervisor required')
    if json.loads((out/'software_checks.json').read_text())['status']!='passed':raise ValueError('Check first')
    source=(CODE_ROOT/cfg['source_run']).resolve();plan_path=out/'plan.json'
    if plan_path.exists():plan=json.loads(plan_path.read_text())
    else:
        original=json.loads((source/'plan.json').read_text());coords=json.loads((source/'coordinates.json').read_text())
        if original['schema']!=cfg['source_schema'] or coords['schema']!=cfg['source_schema']:raise ValueError('Source schema mismatch')
        records=[r for r in original['records'] if r['dataset'] in cfg['datasets'] and r['split'] in cfg['splits']]
        plan=dict(schema=cfg['schema'],source=str(source),cutoff_epoch=time.time(),
            cutoff_utc=datetime.now(timezone.utc).isoformat(),records=records,
            excluded_test_records=sum(r['split']=='test' for r in original['records']),
            coordinates={r['dataset']+'__'+r['subject']:coords['individual'].get(r['dataset']+'__'+r['subject'],{}) for r in records},
            source_progress=json.loads((source/'progress.json').read_text()))
        write_json(plan_path,plan)
    payloads=[(cfg,str(source),str(out),r,plan['coordinates'][r['dataset']+'__'+r['subject']],plan['cutoff_epoch']) for r in plan['records']]
    with (out/'controller.lock').open('w') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        return _tak_cache_pool(_amplitude_frequency_record,payloads,out=out,phase='frequency_scan',
            workers=workers,total=len(payloads),structured=False)


def amplitude_frequency_rates(group,thresholds):
    valid=group[group.finite & group.qualified];n=len(valid)
    result=dict(planned=len(group),terminal=int(group.terminal.sum()),finite=int(group.finite.sum()),qualified=n,
        missing=int((~group.terminal).sum()),unqualified_finite=int((group.finite & ~group.qualified).sum()),
        subjects=int(group.subject.nunique()),subjects_with_qualified=int(valid.subject.nunique()))
    flags=amplitude_frequency_flags(valid.input_ratio,valid.amplitude,valid.error,thresholds)
    for name,flag in flags.items():
        counts=valid.assign(event=flag).groupby('subject').event.agg(['sum','size'])
        result.update({name+'_count':int(flag.sum()),name+'_rate':float(flag.mean()) if n else None,
            name+'_equal_subject_rate':float((counts['sum']/counts['size']).mean()) if len(counts) else None,
            name+'_subjects':int((counts['sum']>0).sum())})
    high=flags['input_high'];bad=flags['bad_error'];amp=flags['amplified']
    result.update(error_given_high=float(bad[high].mean()) if high.any() else None,
        error_given_not_high=float(bad[~high].mean()) if (~high).any() else None,
        amplification_given_high=float(amp[high].mean()) if high.any() else None,
        amplification_given_not_high=float(amp[~high].mean()) if (~high).any() else None)
    return result


def amplitude_frequency_summarize(cfg,out):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plan=json.loads((out/'plan.json').read_text());frames=[]
    for r in plan['records']:
        path=(out/'records'/r['cache_key']).with_suffix('.csv')
        if not path.with_suffix('.json').exists():raise ValueError('Incomplete record: '+r['cache_key'])
        if json.loads(path.with_suffix('.json').read_text())['rows']:
            frames.append(pd.read_csv(path,dtype={k:str for k in ('subject','record','window','site','split','dataset')}))
    data=pd.concat(frames,ignore_index=True)
    if any(not data[c].isin(cfg[c+'s']).all() for c in ('dataset','split')):raise ValueError('Unexpected scope in summary')
    rates=[];subjects=[]
    for support,frame in [('nonoverlap',data[data.nonoverlap]),('all_windows',data)]:
        for (dataset,split,arm),g in frame.groupby(['dataset','split','arm']):
            rates.append(dict(support=support,dataset=dataset,split=split,arm=arm,**amplitude_frequency_rates(g,cfg['thresholds'])))
        for (dataset,arm),g in frame.groupby(['dataset','arm']):
            rates.append(dict(support=support,dataset=dataset,split='development',arm=arm,**amplitude_frequency_rates(g,cfg['thresholds'])))
        for (dataset,subject,arm),g in frame.groupby(['dataset','subject','arm']):
            subjects.append(dict(support=support,dataset=dataset,subject=subject,arm=arm,**amplitude_frequency_rates(g,cfg['thresholds'])))
    rates_frame=pd.DataFrame(rates);rates_frame.to_csv(out/'rates.csv',index=False)
    pd.DataFrame(subjects).to_csv(out/'subject_rates.csv',index=False)
    primary=data[data.nonoverlap & data.finite & data.qualified];sensitivity=[]
    for (dataset,arm),g in primary.groupby(['dataset','arm']):
        for rt in cfg['sensitivity']['input_ratio']:
            for at in cfg['sensitivity']['amplification']:
                count=int(((g.input_ratio>=rt)&(g.amplitude>=at)).sum())
                sensitivity.append(dict(dataset=dataset,arm=arm,input_threshold=rt,amplification_threshold=at,
                    count=count,denominator=len(g),rate=count/len(g)))
    pd.DataFrame(sensitivity).to_csv(out/'threshold_sensitivity.csv',index=False)
    # Failed numerical solutions remain a separate descriptive panel, not silently dropped.
    failure_rates=[]
    for (dataset,arm),g in data[data.nonoverlap & data.finite].groupby(['dataset','arm']):
        f=amplitude_frequency_flags(g.input_ratio,g.amplitude,g.error,cfg['thresholds'])
        failure_rates.append(dict(dataset=dataset,arm=arm,finite_including_unqualified=len(g),
            unqualified=int((~g.qualified).sum()),amplified=int(f['amplified'].sum()),joint=int(f['joint'].sum())))
    pd.DataFrame(failure_rates).to_csv(out/'all_finite_rates.csv',index=False)
    duration=[]
    for (dataset,arm,short),g in data[data.nonoverlap].assign(short=data[data.nonoverlap].duration_s<89.99).groupby(['dataset','arm','short']):
        duration.append(dict(dataset=dataset,arm=arm,short_support=bool(short),**amplitude_frequency_rates(g,cfg['thresholds'])))
    pd.DataFrame(duration).to_csv(out/'duration_rates.csv',index=False)
    windows=[]
    for (dataset,arm),g in primary.groupby(['dataset','arm']):
        flags=amplitude_frequency_flags(g.input_ratio,g.amplitude,g.error,cfg['thresholds'])
        w=g.assign(**flags).groupby(['subject','record','window'])[['input_high','amplified','joint','bad_error']].any()
        windows.append(dict(dataset=dataset,arm=arm,windows_with_any_qualified_site=len(w),
            **{k+'_any_site_count':int(w[k].sum()) for k in w}))
    pd.DataFrame(windows).to_csv(out/'window_any_site_rates.csv',index=False)
    examples=[];checks=[]
    for (dataset,arm),g in primary.groupby(['dataset','arm']):
        chosen=pd.concat([g.iloc[:1],g.nlargest(1,'amplitude')]).drop_duplicates('source_task')
        for _,r in chosen.iterrows():
            path=Path(r.source_task);co=plan['coordinates'][dataset+'__'+r.subject]
            with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
                y=a['target'][:-1];p=a['prediction' if arm=='tak_tau_beta' else 'fixed_prediction'][:-1]
                sd=y.std(0)*a['scale'];ratio=np.sqrt(np.mean(sd[1:]**2))/sd[0]
                amp=p[:,0].std()/y[:,0].std();err=np.sqrt(np.mean((p[:,0]-y[:,0])**2))/y[:,0].std()
                np.testing.assert_allclose([ratio,amp,err],[r.input_ratio,r.amplitude,r.error],rtol=cfg['verification']['rtol'],atol=1e-10)
                np.testing.assert_allclose(a['scale'],[co['eeg_factor'],co['hb_factor'],co['hb_factor']],rtol=1e-12)
            checks.append(dict(dataset=dataset,arm=arm,source_task=str(path),max_absolute_difference=float(np.max(abs(np.array([ratio,amp,err])-np.array([r.input_ratio,r.amplitude,r.error]))))))
        examples.extend(g.nlargest(5,'amplitude')[['dataset','subject','record','window','site','arm','input_ratio','amplitude','error','source_task']].to_dict('records'))
    write_json(out/'verification.json',dict(status='passed',array_checks=checks,raw_reads=0,test_reads=0,protected_reads=0))
    pd.DataFrame(examples).to_csv(out/'largest_amplification_examples.csv',index=False)
    historical=json.loads((CODE_ROOT/cfg['historical_panel']).read_text());history=[]
    for row in historical['records']:
        if row['split']!='validation' or row['variant']!='baseline':continue
        s=row['statistics'];pred=s['prediction'];ratio=s['hb_to_eeg_sd_ratio'];amp=pred['sd_ratio'][0]
        local_error=pred['nrmse'][0]/s['sd_over_training'][0]
        history.append(dict(label=row['label'],subject=row['subject'],region=row['region'],input_ratio=ratio,
            amplitude=amp,error=local_error,original_training_SD_NRMSE=pred['nrmse'][0],
            **amplitude_frequency_flags(ratio,amp,local_error,cfg['thresholds'])))
    write_json(out/'historical_panel.json',dict(scope=cfg['historical_scope'],rows=history))
    main=rates_frame[(rates_frame.support=='nonoverlap')&(rates_frame.split=='development')]
    labels=dict(eeg_fnirs_single_trial='Single-Trial',simultaneous_eeg_nirs='Simultaneous',refed='REFED',visual_cognitive_motivation='Visual')
    fig,axes=plt.subplots(1,3,figsize=(15,4.7),constrained_layout=True)
    for ax,key,title in zip(axes,['input_high_rate','amplified_rate','joint_rate'],['Input Hb/EEG SD >= 1.5','EEG prediction SD >= 2x observed','Both conditions']):
        for i,arm in enumerate(cfg['arms']):
            values=[float(main[(main.dataset==d)&(main.arm==arm)][key].iloc[0])*100 for d in cfg['datasets']]
            ax.bar(np.arange(4)+(i-.5)*.35,values,width=.34,label='Fitted tau/beta' if i==0 else 'Fixed parameters')
        ax.set_xticks(range(4),[labels[d] for d in cfg['datasets']],rotation=15);ax.set_title(title);ax.set_ylabel('Qualified site-windows (%)');ax.grid(axis='y',alpha=.2)
    axes[0].legend();fig.suptitle('Development cache: nonoverlapping windows, all sites; component weights = 1')
    fig.savefig(out/'frequency.png',dpi=220);plt.close(fig)
    summary=dict(schema=cfg['schema'],status='completed',cutoff_utc=plan['cutoff_utc'],thresholds=cfg['thresholds'],
        primary=main.to_dict('records'),all_rates=rates,all_finite=failure_rates,any_site_windows=windows,
        duration_rates=duration,examples=examples,threshold_sensitivity=sensitivity,
        interpretation=cfg['definitions'],historical_panel='historical_panel.json',array_checks=len(checks),
        scope=dict(splits=cfg['splits'],datasets=cfg['datasets'],excluded_test_records=plan['excluded_test_records'],
            subject_count=len({(r['dataset'],r['subject']) for r in plan['records']})),new_fits=0)
    write_json(out/'summary.json',summary)
    cols=['dataset','arm','planned','terminal','qualified','missing','unqualified_finite','input_high_count','amplified_count','joint_count','bad_error_count','joint_equal_subject_rate','joint_subjects','subjects_with_qualified']
    html='''<html><head><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1500px;margin:auto;padding:24px;line-height:1.7}table{border-collapse:collapse;font-size:12px}td,th{border:1px solid #ccc;padding:4px}img{width:100%}</style></head><body>
<h1>EEG–fNIRS 幅度失配与 EEG 重建严重放大的频次</h1>
<p>工程筛查：输入 R = 合并 Hb 模型坐标 SD / EEG 模型坐标 SD；R≥1.5 为 Hb 相对偏大。
输出 A = EEG 预测 SD / 观测 SD；A≥2 为严重放大。E = EEG RMSE / 观测 SD；E≥1 为较大误差。
主事件为 R≥1.5 与 A≥2 共现。E 单独报告；A≥2 本身蕴含 E≥1，并非两项独立证据。
阈值不是正常生理界限，共现不能证明因果。</p>
<p>主分母是训练/验证分区、按两个时钟预先去重叠的窗口×Hb通道（对应一个 EEG 代理），
且拟合数值合格、指标可计算。不同位置仍相关，不作独立样本显著性推断。
另给逐被试等权率、出现过事件的被试数、任一通道触发的时间窗数、全部重叠窗口及数值未合格结果。
REFED 短支持另表。测试/受保护分区未读，新模型拟合为零。</p>'''
    html+=f'<p>源缓存按 {plan["cutoff_utc"]} 截止，后来完成任务不自动混入本次分母。</p>'
    html+='<img src="frequency.png">'+main[cols].to_html(index=False,float_format=lambda x:f'{x:.6f}')
    html+='<h2>条件发生率</h2>'+main[['dataset','arm','error_given_high','error_given_not_high','amplification_given_high','amplification_given_not_high']].to_html(index=False,float_format=lambda x:f'{x:.6f}')
    html+='<h2>此前高 Hb 权重示例：单独列示</h2><p>这 7 个基线例子来自 5 名被试，是经过选择的说明性面板，不能用于估计数据集总体频次。原图 NRMSE 使用训练 SD；此处 error 列转换为窗口自身 SD 分母，以对应本次阈值。</p>'+pd.DataFrame(history).to_html(index=False,float_format=lambda x:f'{x:.4f}')
    html+='<p><a href="rates.csv">分数据集/分区/支持的频次</a> · <a href="subject_rates.csv">被试级统计</a> · <a href="threshold_sensitivity.csv">阈值敏感性</a> · <a href="all_finite_rates.csv">包含未合格结果</a> · <a href="duration_rates.csv">短窗统计</a> · <a href="largest_amplification_examples.csv">最严重样例</a> · <a href="summary.json">数值事实源</a></p></body></html>'
    (out/'report.html').write_text(html)
    return dict(status='completed',rows=len(data),array_checks=len(checks),primary=main.to_dict('records'))


def amplitude_frequency_main(args):
    cfg=amplitude_frequency_config(args.config);out=args.run_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    resolved=out/'resolved_config.json'
    if resolved.exists() and json.loads(resolved.read_text())!=cfg:raise ValueError('Frozen frequency contract changed')
    write_json(resolved,cfg)
    if args.frequency_stage=='check':result=amplitude_frequency_check(cfg,out)
    elif args.frequency_stage=='scan':result=amplitude_frequency_scan(cfg,out,args.workers)
    else:result=amplitude_frequency_summarize(cfg,out)
    print(json.dumps(serial({k:v for k,v in result.items() if k!='rows'})),flush=True);return result


def weight_so_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_weight_so_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):raise ValueError('Use reviewed weight/SO contract')
    return cfg


def weight_so_weights(ratios):
    ratios=np.asarray(ratios,float)
    if ratios.shape!=(3,) or not np.isfinite(ratios).all() or np.any(ratios<=0):
        raise ValueError('Three positive weight ratios required')
    return 3*ratios/ratios.sum()


def weight_so_plan(cfg,out):
    source=CODE_ROOT/cfg['source_run'];old=json.loads((source/'plan.json').read_text())
    coordinates=json.loads((source/'coordinates.json').read_text());cache=json.loads((source/'resolved_config.json').read_text())
    core=json.loads((source/'resolved_model_config.json').read_text())
    if old['schema']!=cfg['source_schema'] or coordinates['schema']!=cfg['source_schema']:raise ValueError('Wrong source cache')
    rows=[];datasets={}
    numeric=lambda s:(int(re.search(r'\d+',s).group()),s)
    for ds in cfg['datasets']:
        records=[r for r in old['records'] if r['dataset']==ds and r['split'] in cfg['boundary']['splits']
            and any(w['duration_s']==90 for w in r['cache_windows'])]
        training=sorted({r['subject'] for r in records if r['split']=='train'},key=numeric)[:3]
        validation=sorted({r['subject'] for r in records if r['split']=='validation'},key=numeric)
        if len(training)!=3 or len(validation)<2:raise ValueError('Insufficient metadata subject support')
        reference=min([r for r in records if r['subject']==training[0]],key=lambda r:r['record'])
        available=[p for p in reference['pairs'] if p['status']=='available']
        pairs=[available[i]['id'] for i in (0,len(available)//2,len(available)-1)]
        for split,subjects in [('train',training),('validation',[validation[0],validation[-1]])]:
            for subject in subjects:
                candidates=[r for r in records if r['subject']==subject and r['split']==split
                    and all(any(p['id']==name and p['status']=='available' for p in r['pairs']) for name in pairs)
                    and r['eeg_channel_names']==reference['eeg_channel_names']]
                if not candidates:raise ValueError('Matching training/evaluation geometry missing')
                record=min(candidates,key=lambda r:r['record']);windows=[w for w in record['cache_windows'] if w['duration_s']==90]
                window=windows[0 if split=='train' else len(windows)//2]
                selected=[next(p for p in record['pairs'] if p['id']==name) for name in pairs]
                co=coordinates['individual'][ds+'__'+subject]
                if co.get('status')!='completed':raise ValueError('Source individual coordinate unavailable')
                np.testing.assert_allclose(co['pc'],coordinates['population'][ds]['pc'],rtol=0,atol=1e-12)
                rows.append(dict(case=record['cache_key'].replace('/','__')+'__'+window['key'],dataset=ds,
                    subject=subject,split=split,record_plan=record,window=window,pairs=selected,
                    coordinate={k:co[k] for k in ('pc','eeg_factor','hb_factor','sd')},
                    feature=str(source/'features'/record['cache_key']/(window['key']+'.npz'))))
        datasets[ds]=dict(pairs=pairs,training_subjects=training,validation_subjects=[validation[0],validation[-1]])
    result=dict(schema=cfg['schema'],source=str(source),rows=rows,datasets=datasets,
        cache_data=cache['data'],weights={k:weight_so_weights(v).tolist() for k,v in cfg['weights'].items()},
        model_config=core,selection='metadata_only_no_fit_outcome_selection',raw_reads=0)
    write_json(out/'plan.json',result);return dict(status='completed',training_cases=12,validation_cases=8,datasets=datasets,weights=result['weights'])


@lru_cache(maxsize=2)
def _weight_so_plan(out_string):
    return json.loads((Path(out_string)/'plan.json').read_text())


def _weight_so_prepare_native(payload):
    from src.data.tak_mismatch import read_tak_weight_voltage_window,BANDS_HZ
    from src.inference.observation_baselines import eeg_band_power
    out_string,row=payload;out=Path(out_string);path=out/'inputs'/(row['case']+'.npz');meta=path.with_suffix('.json')
    if meta.exists():return json.loads(meta.read_text())
    started=time.monotonic();plan=_weight_so_plan(out_string);d=plan['cache_data']
    if row not in plan['rows'] or row['split'] not in ('train','validation'):raise ValueError('Undeclared voltage input')
    try:
        native=read_tak_weight_voltage_window(CODE_ROOT,row['record_plan'],row['window'],split=row['split'],
            cache_root=d['cache_root'],geometry_root=d['geometry_root'],refed_geometry_root=d['refed_geometry_root'],
            visual_eeg_channel_identity=d['visual_eeg_channel_identity'])
        indices=sorted({i for p in row['pairs'] for i in p['channel_sets']['nearest6']})
        roi=np.array([[indices.index(i) for i in p['channel_sets']['nearest6']] for p in row['pairs']])
        x=native.pop('x')[:,indices]
        if not np.isfinite(x).all():raise ValueError('Invalid selected native channels')
        with np.load(row['feature'],allow_pickle=False) as a:
            if not a['eeg_valid'][indices].all() or not a['hb_valid'][[p['native_index'] for p in row['pairs']]].all():
                raise ValueError('Cached support invalid')
            features=a['eeg'][:,indices];hb=a['hb'][:,[p['native_index'] for p in row['pairs']]]
        computed=np.log(eeg_band_power(x,bands=BANDS_HZ,sample_rate=native['rate'],target_rate=10));computed-=computed[:50].mean(0)
        np.testing.assert_allclose(computed,features,rtol=1e-9,atol=1e-9)
        a=np.zeros((3,len(indices)*5));pc=np.asarray(row['coordinate']['pc']).reshape(6,5)
        for r in range(3):
            for j,c in enumerate(roi[r]):a[r,c*5:c*5+5]=pc[j]
        if np.linalg.matrix_rank(a)!=3:raise ValueError('Rank-deficient proxy-to-power projection')
        _tak_cache_npz(path,x=x,features=features,hb=hb,roi_indices=roi,projection=a,rate=np.array(native['rate']),
            channels=np.array([native['channels'][i] for i in indices]),unit=np.array(str(native['unit'])))
        result=dict(status='completed',case=row['case'],dataset=row['dataset'],subject=row['subject'],split=row['split'],
            native=native,indices=indices,feature_replay_max_abs=float(np.max(abs(computed-features))),
            seconds=time.monotonic()-started,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    except Exception:result=dict(status='failed',case=row['case'],error=traceback.format_exc(),seconds=time.monotonic()-started)
    write_json(meta,result);return result


def weight_so_prepare(cfg,out,workers):
    from src.data.dual_component_tokenizer import fit_voltage_power_cap_reference,BANDS
    from src.inference.observation_baselines import eeg_band_power
    from scipy.signal import butter,sosfiltfilt,resample_poly
    plan=_weight_so_plan(str(out));rows=plan['rows']
    execution=_tak_cache_pool(_weight_so_prepare_native,[(str(out),r) for r in rows],out=out,
        phase='weight_so_native',workers=workers,total=len(rows))
    failures=[r for r in execution['rows'] if r['status']!='completed']
    if failures:
        write_json(out/'preparation_failures.json',failures);raise ValueError('Native preparation failures retained; no replacement')
    references={}
    for ds in cfg['datasets']:
        training=[];a=None;rate=None;channels=None
        for row in rows:
            if row['dataset']!=ds or row['split']!='train':continue
            with np.load(out/'inputs'/(row['case']+'.npz'),allow_pickle=False) as z:
                if a is not None:
                    np.testing.assert_array_equal(a,z['projection']);np.testing.assert_array_equal(channels,z['channels']);assert rate==int(z['rate'])
                a=z['projection'];rate=int(z['rate']);channels=z['channels'];training.append(dict(x=z['x'],split='train'))
        model=fit_voltage_power_cap_reference(training,a,sample_rate_hz=rate)
        model['voltage_rms']=np.sqrt(np.mean([np.mean(r['x']**2,axis=0) for r in training],axis=0))
        _tak_cache_npz(out/'references'/(ds+'.npz'),**model);references[ds]=model
    with np.load(CODE_ROOT/cfg['interventions']['ocular_source'],allow_pickle=False) as a:
        n=a['n_ocular'];donor=n[:,np.argmax(np.sum(n*n,axis=0))]
    tasks=[]
    for index,row in enumerate(r for r in rows if r['split']=='validation'):
        case=row['case'];model=references[row['dataset']]
        with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:base={k:a[k] for k in a.files}
        np.testing.assert_array_equal(base['projection'],model['projection'])
        x=base['x'];rate=int(base['rate']);t=np.arange(len(x))/rate;th=np.arange(900)/10
        use=(t>=30)&(t<50);huse=(th>=30)&(th<50);electrode=int(base['roi_indices'][0,0]);q=float(model['voltage_rms'][electrode])
        envelope=np.where(use,np.sin(np.pi*np.clip((t-30)/20,0,1))**2,0.)
        rng=np.random.default_rng(cfg['seed']+index);shapes={}
        shapes['ocular']=resample_poly(donor,rate,200)
        shapes['muscle']=sosfiltfilt(butter(4,[25,70],btype='bandpass',fs=rate,output='sos'),rng.normal(size=len(t)))*envelope
        for f in (10,35):shapes['neural'+str(f)]=np.sin(2*np.pi*f*t+rng.uniform(0,2*np.pi))*envelope
        arrays={};changed={}
        for variant in cfg['interventions']['variants']:
            de=np.zeros_like(x);dh=np.zeros_like(base['hb']);feature=base['features'].copy()
            if variant in shapes:
                n=shapes[variant];de[:,electrode]=n*(q/np.sqrt(np.mean(n[use]**2)))
                power=eeg_band_power(x[:,[electrode]]+de[:,[electrode]],bands=BANDS,sample_rate=rate,target_rate=10)
                log=np.log(power);log-=log[:50].mean(0);feature[:,electrode]=log[:,0]
            if variant in ('hbo_noise','hbr_noise'):
                j=0 if variant=='hbo_noise' else 1
                pulse=np.where(huse,np.sin(np.pi*np.clip((th-30)/20,0,1))**2,0.)
                co=row['coordinate'];amplitude=co['sd'][j+1]/co['hb_factor']
                dh[:,0,j]=pulse*amplitude/np.sqrt(np.mean(pulse[huse]**2))
            arrays['features_'+variant]=feature;arrays['hb_'+variant]=base['hb']+dh
            arrays['delta_eeg_'+variant]=de;arrays['delta_hb_'+variant]=dh
            affected=[r for r in range(3) if variant=='baseline' or not np.array_equal(feature[:,base['roi_indices'][r]],base['features'][:,base['roi_indices'][r]])
                or not np.array_equal(dh[:,r],np.zeros((900,2)))]
            changed[variant]=affected
            for weight in cfg['weights']:
                for roi in affected:tasks.append(dict(case=case,weight=weight,variant=variant,roi=roi))
        _tak_cache_npz(out/'variants'/(case+'.npz'),**arrays)
        write_json(out/'variants'/(case+'.json'),dict(case=case,changed_rois=changed,electrode=electrode,
            electrode_name=str(base['channels'][electrode]),injected_EEG_RMS=q,score_seconds=[30,50]))
    write_json(out/'fit_plan.json',dict(schema=cfg['schema'],tasks=tasks,planned=len(tasks),validation_cases=8,
        raw_access='exact_20_metadata_selected_development_windows',new_Hb_raw_reads=0))
    return dict(status='completed',input_cases=len(rows),planned_fits=len(tasks),datasets=cfg['datasets'])


def _weight_so_fit(payload):
    out_string,task=payload;out=Path(out_string);plan=_weight_so_plan(out_string)
    row=next(r for r in plan['rows'] if r['case']==task['case']);co=row['coordinate'];w=plan['weights'][task['weight']]
    key=f"{task['case']}__{task['weight']}__{task['variant']}__r{task['roi']}";path=out/'fits'/(key+'.json')
    if path.exists():return json.loads(path.read_text())
    began=time.monotonic();result=dict(task=task,key=key,qualified=False,observation_weights=w)
    try:
        with np.load(out/'inputs'/(row['case']+'.npz'),allow_pickle=False) as a:indices=a['roi_indices'][task['roi']]
        with np.load(out/'variants'/(row['case']+'.npz'),allow_pickle=False) as a:
            target=np.column_stack((a['features_'+task['variant']][:,indices].reshape(900,30)@co['pc'],a['hb_'+task['variant']][:,task['roi']]))
        gain=np.array([co['eeg_factor'],co['hb_factor'],co['hb_factor']]);sd=np.asarray(co['sd'])/gain
        fit,arrays=tak_cache_fit_arrays(plan['model_config'],target,co,sd,structured=True,observation_weights=w)
        result.update(fit);_tak_cache_npz(path.with_suffix('.npz'),**arrays)
        if task['weight']=='equal' and task['variant']=='baseline':
            source=Path(plan['source'])/'tasks'/row['record_plan']['cache_key']/(row['window']['key']+f"__p{row['pairs'][task['roi']]['native_index']:03d}.npz")
            if source.exists():
                with np.load(source,allow_pickle=False) as a:
                    np.testing.assert_allclose(target,a['target'],rtol=1e-9,atol=1e-9)
                    if 'prediction' in arrays and 'prediction' in a:result['baseline_replay_max_subject_SD']=float(np.max(abs(arrays['prediction']-a['prediction'])/sd))
    except Exception:result.update(status='failed_exception',error=traceback.format_exc())
    result.update(seconds=time.monotonic()-began,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    write_json(path,result);return {k:result[k] for k in ('key','status','qualified','seconds','peak_rss_mib')}


def weight_so_check(cfg,out):
    for name,ratio in cfg['weights'].items():
        weights=weight_so_weights(ratio);assert abs(weights.sum()-3)<1e-12
        np.testing.assert_allclose(weights/weights[0],np.asarray(ratio)/ratio[0])
    np.testing.assert_array_equal(weight_so_weights([1,1,1]),np.ones(3))
    write_json(out/'software_checks.json',dict(status='passed',checks=['positive_weights','constant_sum_three','equal_weight_identity'],measured_reads=0))
    return dict(status='passed')


def weight_so_delta_metrics(s0,s1,delta,*,kind):
    change=np.asarray(s1)-np.asarray(s0);delta=np.asarray(delta)
    norm=float(np.linalg.norm(delta))
    if norm<=0:raise ValueError('Nonzero known intervention required')
    error=change-delta if kind=='neural' else change
    return dict(normalized_error=float(np.linalg.norm(error)/norm),
        signed_projection=float(np.sum(change*delta)/(norm*norm)),
        changed_S_rms_over_injection=float(np.linalg.norm(change)/norm))


def weight_so_prediction(path,arm):
    """Read the selected numerical arm, including its own qualification flag."""
    if arm not in ('tak_fixed','tak_tau_beta'):raise ValueError('Unknown SSM arm')
    path=Path(path);fit=json.loads(path.read_text());record=fit['fits'][arm]
    if not record['qualified']:raise ValueError('Unqualified SSM: '+str(path)+' '+arm)
    with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
        prediction=a['fixed_prediction' if arm=='tak_fixed' else 'prediction'].copy()
    if prediction.shape!=(900,3) or not np.isfinite(prediction).all():raise ValueError('Invalid retained prediction')
    return prediction,dict(source=str(path),arm=arm,tau=record['tau'],beta=record['beta'])


def _weight_so_target(payload):
    from src.data.dual_component_tokenizer import voltage_power_cap_target,BANDS
    from src.inference.observation_baselines import eeg_band_power
    from scipy.signal import resample_poly
    out_string,case,weight=payload[:3];options=payload[3] if len(payload)>3 else {}
    out=Path(out_string);plan=_weight_so_plan(out_string)
    arm=options.get('arm','tak_tau_beta');freeze=options.get('freeze_baseline',False)
    row=next(r for r in plan['rows'] if r['case']==case);cfg=weight_so_config();start=time.monotonic()
    folder=Path(options.get('destination',out/'targets'))/case/weight;summary=folder/'summary.json'
    if summary.exists():return json.loads(summary.read_text())
    with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:base={k:a[k] for k in a.files}
    with np.load(out/'references'/(row['dataset']+'.npz'),allow_pickle=False) as a:model={k:a[k] for k in a.files}
    changed=json.loads((out/'variants'/(case+'.json')).read_text());rate=int(base['rate']);electrode=changed['electrode']
    use=slice(30*rate,50*rate);hs=slice(300,500);records=[];s0=None;h0=None
    with np.load(out/'variants'/(case+'.npz'),allow_pickle=False) as variants:
        for variant in options.get('variants',cfg['interventions']['variants']):
            result=dict(case=case,dataset=row['dataset'],subject=row['subject'],weight=weight,variant=variant,
                status='failed',qualified=False,unit=str(base['unit']),rate=rate,arm=arm,freeze_baseline=freeze)
            try:
                predictions=[];fit_status=[]
                for roi in range(3):
                    v=variant if not freeze and roi in changed['changed_rois'][variant] else 'baseline'
                    path=out/'fits'/f'{case}__{weight}__{v}__r{roi}.json'
                    prediction,record=weight_so_prediction(path,arm);predictions.append(prediction)
                    fit_status.append(dict(roi=roi,**record))
                pred=np.stack(predictions,axis=1);proxy=pred[:,:,0];hb_s=pred[:,:,1:]
                de=variants['delta_eeg_'+variant];dh=variants['delta_hb_'+variant]
                x=base['x']+de;hb=variants['hb_'+variant]
                voltage=voltage_power_cap_target(x,model,proxy,cap=1.,audit_final=True)
                s=voltage['s'];o=voltage['o'];q=model['voltage_rms']
                correlations=[];derivatives=[]
                for j in range(x.shape[1]):
                    correlations.append(float(np.corrcoef(x[use,j],s[use,j])[0,1]) if s[use,j].std()>1e-20 else 0.)
                    derivatives.append(float(np.corrcoef(np.diff(x[use,j]),np.diff(s[use,j]))[0,1]) if np.diff(s[use,j]).std()>1e-20 else 0.)
                co=row['coordinate'];hsd=np.asarray(co['sd'])[1:]/co['hb_factor']
                result.update(status='completed',qualified=True,noise_error=None,neural_error=None,
                    baseline_correlation=float(np.median(correlations)),derivative_correlation=float(np.median(derivatives)),
                    baseline_nrmse=float(np.sqrt(np.mean(((s[use]-x[use])/q)**2))),
                    retained_voltage_RMS=float(np.sqrt(np.mean((s[use]/q)**2))),
                    Hb_reference_nrmse=float(np.sqrt(np.mean(((hb_s[:-1]-hb[:-1])/hsd)**2))),
                    EEG_closure_max_abs=float(voltage['closure_max_abs']),
                    Hb_closure_max_abs=float(np.max(abs(hb_s+(hb-hb_s)-hb))),
                    final_bound_max=float(np.max(voltage['final_reanalysis_ratio'])),
                    final_bound_exceedance_fraction=float(np.mean(voltage['final_reanalysis_ratio']>1+1e-8)),fits=fit_status)
                raw_power=eeg_band_power(x,bands=BANDS,sample_rate=rate,target_rate=10)[300:500].mean(0)
                retained_power=eeg_band_power(s,bands=BANDS,sample_rate=rate,target_rate=10)[300:500].mean(0)
                for j,(low,high) in enumerate(BANDS):
                    result[f'band_power_ratio_{low:g}_{high:g}']=float(np.median(retained_power[:,j]/raw_power[:,j]))
                if variant=='baseline':s0=s.copy();h0=hb_s.copy()
                elif s0 is None:raise ValueError('No qualified same-weight baseline target')
                else:
                    if variant.startswith('neural'):
                        metric=weight_so_delta_metrics(s0[use],s[use],de[use],kind='neural');result['neural_error']=metric['normalized_error']
                    elif variant.startswith('ocular') or variant=='muscle':
                        metric=weight_so_delta_metrics(s0[use],s[use],de[use],kind='noise');result['noise_error']=metric['normalized_error']
                    else:
                        metric=weight_so_delta_metrics(h0[hs],hb_s[hs],dh[hs],kind='noise');result['noise_error']=metric['normalized_error']
                    result.update(signed_projection=metric['signed_projection'],
                        EEG_branch_change=float(np.sqrt(np.mean(((s[use]-s0[use])/q)**2))),
                        Hb_branch_change=float(np.sqrt(np.mean(((hb_s[hs]-h0[hs])/hsd)**2))))
                    if options.get('audit_interference'):
                        change=s[use]-s0[use];known=de[use];do=known-change
                        outside=np.r_[np.arange(5*rate,25*rate),np.arange(55*rate,85*rate)]
                        result.update(O_delta_correlation=float(np.corrcoef(do.ravel(),known.ravel())[0,1]),
                            O_signed_gain=1-metric['signed_projection'],
                            S_pair_correlation=float(np.median([np.corrcoef(s0[use,j],s[use,j])[0,1] for j in range(x.shape[1])])),
                            S_change_relative_baseline=float(np.linalg.norm(change)/np.linalg.norm(s0[use])),
                            outside_S_change_relative_baseline=float(np.linalg.norm(s[outside]-s0[outside])/np.linalg.norm(s0[outside])))
                display=lambda a:resample_poly(a,200,rate,axis=0)
                _tak_cache_npz(folder/(variant+'.npz'),s_display=display(s),hb_s=hb_s,hb_o=hb-hb_s,
                    delta_s_display=display(s-s0) if s0 is not None else np.zeros((18000,x.shape[1])),
                    delta_hb_s=hb_s-h0 if h0 is not None else np.zeros_like(hb_s),
                    display_rate=np.array(200),electrode=np.array(electrode))
            except Exception:result.update(status='failed',qualified=False,error=traceback.format_exc())
            write_json(folder/(variant+'.json'),result);records.append(result)
    result=dict(case=case,weight=weight,status='completed',planned=len(records),qualified=sum(r['qualified'] for r in records),
        rows=records,seconds=time.monotonic()-start,peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    write_json(summary,result)
    return {k:v for k,v in result.items() if k!='rows'}


def weight_so_targets(cfg,out,workers,*,pilot=False):
    if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable voltage target production required')
    plan=_weight_so_plan(str(out));rows=[r for r in plan['rows'] if r['split']=='validation']
    if pilot:rows=[next(r for r in rows if r['dataset']==d) for d in cfg['datasets']]
    jobs=[(str(out),r['case'],w) for r in rows for w in (['equal'] if pilot else cfg['weights'])]
    with (out/'target_controller.lock').open('w') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        return _tak_cache_pool(_weight_so_target,jobs,out=out,phase='weight_so_target_pilot' if pilot else 'weight_so_targets',
            workers=workers,total=len(jobs))


def weight_so_summarize(cfg,out):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from scipy.signal import resample_poly
    plan=_weight_so_plan(str(out));cases=[r for r in plan['rows'] if r['split']=='validation'];rows=[];fit_rows=[]
    fit_plan=json.loads((out/'fit_plan.json').read_text())['tasks'];checks=[]
    for task in fit_plan:
        key=f"{task['case']}__{task['weight']}__{task['variant']}__r{task['roi']}";path=out/'fits'/(key+'.json')
        if not path.exists():raise ValueError('Missing fit: '+key)
        r=json.loads(path.read_text());fit_rows.append(dict(**task,status=r['status'],qualified=r['qualified'],seconds=r['seconds']))
        if r['qualified']:
            with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
                w=np.asarray(plan['weights'][task['weight']]);e=(a['prediction']-a['target'])[:-1]/a['sd_subject']
                cost=.4*np.sum(e*e*w)
                expected=r['fits']['tak_tau_beta']['solver']['objective_components']['data']
                np.testing.assert_allclose(cost,expected,rtol=1e-9,atol=1e-8)
                checks.append(abs(float(cost-expected)))
    for case in cases:
        for weight in cfg['weights']:
            path=out/'targets'/case['case']/weight/'summary.json'
            if not path.exists():raise ValueError('Missing target group: '+str(path))
            rows.extend(json.loads(path.read_text())['rows'])
    scalar=[{k:v for k,v in r.items() if k not in ('fits','error')} for r in rows]
    frame=pd.DataFrame(scalar);input_scales=[]
    for case in cases:
        with np.load(out/'inputs'/(case['case']+'.npz'),allow_pickle=False) as a,np.load(out/'references'/(case['dataset']+'.npz'),allow_pickle=False) as b:
            rate=int(a['rate']);x=a['x'][30*rate:50*rate];q=b['voltage_rms'];electrode=int(a['roi_indices'][0,0])
            normalized_rms=float(np.sqrt(np.mean((x/q)**2)))
            input_scales.append(dict(case=case['case'],dataset=case['dataset'],subject=case['subject'],
                input_training_normalized_rms=normalized_rms,
                injection_to_current_electrode_rms=float(q[electrode]/np.sqrt(np.mean(x[:,electrode]**2)))))
            mask=(frame.case==case['case'])&(frame.variant=='baseline')
            frame.loc[mask,'baseline_S_input_RMS_ratio']=frame.loc[mask,'retained_voltage_RMS']/normalized_rms
            frame.loc[mask,'baseline_input_relative_distortion']=frame.loc[mask,'baseline_nrmse']/normalized_rms
    pd.DataFrame(input_scales).to_csv(out/'input_morphology_scales.csv',index=False)
    frame.to_csv(out/'target_metrics.csv',index=False);pd.DataFrame(fit_rows).to_csv(out/'fit_status.csv',index=False)
    case_metrics=[]
    for (ds,subject,case,weight),g in frame.groupby(['dataset','subject','case','weight'],sort=False):
        baseline=g[g.variant=='baseline'].iloc[0];noise=g[g.variant.isin(['ocular','muscle','hbo_noise','hbr_noise'])]
        neural=g[g.variant.isin(['neural10','neural35'])]
        case_metrics.append(dict(dataset=ds,subject=subject,case=case,weight=weight,targets=len(g),qualified=int(g.qualified.sum()),
            noise_error=float(noise.noise_error.mean()),neural_error=float(neural.neural_error.mean()),
            baseline_correlation=baseline.get('baseline_correlation'),baseline_nrmse=baseline.get('baseline_nrmse'),
            derivative_correlation=baseline.get('derivative_correlation'),Hb_reference_nrmse=baseline.get('Hb_reference_nrmse'),
            baseline_S_input_RMS_ratio=baseline.get('baseline_S_input_RMS_ratio'),
            baseline_input_relative_distortion=baseline.get('baseline_input_relative_distortion')))
    case_frame=pd.DataFrame(case_metrics);case_frame.to_csv(out/'case_metrics.csv',index=False)
    m=['noise_error','neural_error','baseline_correlation','baseline_nrmse','derivative_correlation','Hb_reference_nrmse',
       'baseline_S_input_RMS_ratio','baseline_input_relative_distortion']
    ds_frame=case_frame.groupby(['dataset','weight'],sort=False)[m].mean().reset_index()
    counts=frame.groupby(['dataset','weight'],sort=False).agg(qualified_targets=('qualified','sum'),planned_targets=('qualified','size')).reset_index()
    ds_frame=ds_frame.merge(counts,on=['dataset','weight'])
    ds_frame.to_csv(out/'dataset_metrics.csv',index=False);aggregate=ds_frame.groupby('weight',sort=False)[m].mean().reindex(cfg['weights']).reset_index()
    aggregate=aggregate.merge(counts.groupby('weight')[['qualified_targets','planned_targets']].sum().reset_index(),on='weight')
    failures=pd.DataFrame(fit_rows).assign(failed=lambda a:~a.qualified).groupby('weight').failed.sum()
    aggregate['failed_fits']=aggregate.weight.map(failures)
    aggregate.to_csv(out/'aggregate_metrics.csv',index=False)
    variant=frame.groupby(['dataset','weight','variant'],sort=False)[['noise_error','neural_error','EEG_branch_change','Hb_branch_change']].mean().reset_index()
    variant.to_csv(out/'variant_metrics.csv',index=False)
    decisions=[];criteria=cfg['decision']
    for weight in cfg['weights']:
        if weight=='equal':continue
        reasons=[];dataset_checks=[]
        for ds in cfg['datasets']:
            b=ds_frame[(ds_frame.dataset==ds)&(ds_frame.weight=='equal')].iloc[0]
            c=ds_frame[(ds_frame.dataset==ds)&(ds_frame.weight==weight)].iloc[0]
            complete=bool((case_frame[(case_frame.dataset==ds)&(case_frame.weight.isin(['equal',weight]))].qualified==7).all())
            check=dict(dataset=ds,complete_paired_support=complete,
                noise_gain=float(1-c.noise_error/b.noise_error),neural_error_increase=float(c.neural_error-b.neural_error),
                correlation_change=float(c.baseline_correlation-b.baseline_correlation),nrmse_increase=float(c.baseline_nrmse-b.baseline_nrmse))
            passed=(complete and check['noise_gain']>=criteria['candidate_noise_reduction_fraction']
                and check['neural_error_increase']<=criteria['maximum_neural_error_increase']
                and check['correlation_change']>=-criteria['maximum_baseline_correlation_decrease']
                and check['nrmse_increase']<=criteria['maximum_baseline_NRMSE_increase'])
            check['passed']=bool(passed);dataset_checks.append(check)
            if not passed:reasons.append(ds)
        decisions.append(dict(weight=weight,eligible=not reasons,dataset_checks=dataset_checks,failed_datasets=reasons))
    aliases=dict(equal='1:1:1',eeg4='4:1:1',hb2='1:2:2',hb4='1:4:4',hbo4='1:4:1',hbr4='1:1:4',hb100='1:100:100')
    colors=plt.cm.tab10(np.arange(7));fig,axes=plt.subplots(1,3,figsize=(16,5),constrained_layout=True)
    for i,key in enumerate(('noise_error','neural_error','baseline_correlation')):
        axes[i].bar(range(7),aggregate[key],color=colors);axes[i].set_xticks(range(7),[aliases[w] for w in cfg['weights']],rotation=30)
        axes[i].set_title(['Known-noise leakage into S (lower better)','Neural-like change preservation error (lower better)','Baseline S/input correlation (higher better)'][i],fontsize=10)
        axes[i].set_xlabel('EEG:HbO:HbR ratio (sum normalized to 3)');axes[i].grid(axis='y',alpha=.2)
        if i<2:axes[i].axhline(1,color='gray',ls=':')
    fig.suptitle('Equal subject means within dataset, then equal means across four datasets; inspect failures separately')
    fig.savefig(out/'weight_summary.png',dpi=220);plt.close(fig)
    fig,axes=plt.subplots(2,2,figsize=(12,9),constrained_layout=True)
    for ax,(ds,g) in zip(axes.flat,ds_frame.groupby('dataset',sort=False)):
        for i,w in enumerate(cfg['weights']):
            r=g[g.weight==w].iloc[0];ax.scatter(r.neural_error,r.noise_error,color=colors[i],s=65,label=aliases[w])
            ax.annotate(w,(r.neural_error,r.noise_error),xytext=(3,4),textcoords='offset points',fontsize=8)
        ax.set_title(ds,fontsize=10);ax.set_xlabel('Neural-like change error');ax.set_ylabel('Noise leakage');ax.grid(alpha=.2)
    fig.suptitle('Noise rejection / morphology trade-off: lower-left preferred; axes independent by dataset')
    fig.savefig(out/'weight_tradeoff.png',dpi=220);plt.close(fig)
    figures=[]
    for case in cases:
        cid=case['case']
        with np.load(out/'inputs'/(cid+'.npz'),allow_pickle=False) as a:
            x=a['x'];rate=int(a['rate']);channels=a['channels'];hb=a['hb'];unit=str(a['unit'])
        xdisplay=resample_poly(x,200,rate,axis=0);tv=np.arange(18000)/200;th=np.arange(900)/10
        info=json.loads((out/'variants'/(cid+'.json')).read_text());electrode=info['electrode']
        for kind in ('baseline','ocular','neural10','hbo_noise','hbr_noise'):
            fig,axes=plt.subplots(3,7,figsize=(24,9),constrained_layout=True)
            with np.load(out/'variants'/(cid+'.npz'),allow_pickle=False) as a:
                de=resample_poly(a['delta_eeg_'+kind],200,rate,axis=0);dh=a['delta_hb_'+kind]
            eeg_kind=kind in ('baseline','ocular','neural10')
            if eeg_kind:
                center=40. if kind=='baseline' else float(tv[np.argmax(abs(de[:,electrode]))]);zoom=(tv>=center-2)&(tv<=center+2)
            else:zoom=(th>=25)&(th<=55)
            ylims=[[],[],[]]
            for j,w in enumerate(cfg['weights']):
                folder=out/'targets'/cid/w;path=folder/(kind+'.npz');meta=json.loads((folder/(kind+'.json')).read_text())
                if not meta['qualified'] or not path.exists():
                    for ax in axes[:,j]:ax.text(.5,.5,'FAILED / NO TARGET',ha='center',transform=ax.transAxes,fontsize=9)
                    continue
                with np.load(path,allow_pickle=False) as a:s=a['s_display'];hs=a['hb_s'];ds=a['delta_s_display'];dhs=a['delta_hb_s']
                if kind=='baseline':
                    pairs=[(tv[zoom],xdisplay[zoom,electrode],s[zoom,electrode]),(th[:-1],hb[:-1,0,0],hs[:-1,0,0]),(th[:-1],hb[:-1,0,1],hs[:-1,0,1])]
                    yl=[f'EEG ({unit})','HbO (cached units)','HbR (cached units)'];leg=[('Input','S'),('Observed','S'),('Observed','S')]
                elif eeg_kind:
                    pairs=[(tv[zoom],(xdisplay+de)[zoom,electrode],s[zoom,electrode]),
                        (tv[zoom],de[zoom,electrode],ds[zoom,electrode]),(tv[zoom],de[zoom,electrode],(de-ds)[zoom,electrode])]
                    yl=[f'EEG ({unit})','Known addition / delta S','Known addition / delta O'];leg=[('Perturbed input','S'),('Added change','delta S'),('Added change','delta O')]
                else:
                    component=0 if kind=='hbo_noise' else 1
                    pairs=[(th[zoom],(hb+dh)[zoom,0,component],hs[zoom,0,component]),
                        (th[zoom],dh[zoom,0,component],dhs[zoom,0,component]),(th[zoom],dh[zoom,0,component],(dh-dhs)[zoom,0,component])]
                    yl=['Hb (cached units)','Known addition / delta S','Known addition / delta O'];leg=[('Perturbed input','S'),('Added change','delta S'),('Added change','delta O')]
                for k,(tt,obs,estimate) in enumerate(pairs):
                    ax=axes[k,j];ax.plot(tt,obs,color='#777777',lw=.9,label=leg[k][0]);ax.plot(tt,estimate,color=colors[j],lw=1,label=leg[k][1]);ax.grid(alpha=.2)
                    ylims[k].extend([float(obs.min()),float(obs.max()),float(estimate.min()),float(estimate.max())])
                    if k==0 or kind=='baseline':
                        other=obs-estimate;ax.plot(tt,other,color='#b44b4b',ls=':',lw=.85,label='O = input - S')
                        ylims[k].extend([float(other.min()),float(other.max())])
                    if j==0:ax.set_ylabel(yl[k],fontsize=9)
                    ax.legend(fontsize=8.5,loc='best')
                    if k==2:ax.set_xlabel('Window time (s)')
                metric=meta.get('neural_error') if kind.startswith('neural') else meta.get('noise_error')
                axes[0,j].set_title(aliases[w]+(f'\nerror={metric:.3f}' if metric is not None else f"\nmedian corr={meta['baseline_correlation']:.3f}"),fontsize=10)
            for k in range(3):
                if ylims[k]:
                    lo,hi=min(ylims[k]),max(ylims[k]);margin=(hi-lo)*.05+1e-12
                    for ax in axes[k]:ax.set_ylim(lo-margin,hi+margin)
            expectation='Noise: delta S should be zero; delta O should match addition' if kind in ('ocular','hbo_noise','hbr_noise') else 'Neural-like probe: delta S should match addition; delta O should be zero'
            if kind=='baseline':expectation='Original window is not clean ground truth; shape/distortion diagnostic only'
            fig.suptitle(f"{case['dataset']} | {case['subject']} | {kind} | electrode {channels[electrode]} / Hb site {case['pairs'][0]['id']}\n{expectation}\nZoom is display-only; scalar errors use all channels on [30,50) s; row axes shared",fontsize=12)
            filename=cid+'__'+kind+'.png';fig.savefig(out/filename,dpi=200);plt.close(fig);figures.append(dict(case=cid,variant=kind,file=filename))
    summary=dict(schema=cfg['schema'],status='completed',planned_fits=len(fit_rows),qualified_fits=sum(r['qualified'] for r in fit_rows),
        planned_targets=len(rows),qualified_targets=sum(r['qualified'] for r in rows),datasets=cfg['datasets'],subjects=8,
        weights=plan['weights'],aggregate=aggregate.to_dict('records'),dataset_metrics=ds_frame.to_dict('records'),
        decisions=decisions,eligible_weights=[r['weight'] for r in decisions if r['eligible']],
        recommendation='retain_equal_weight_cache' if not any(r['eligible'] for r in decisions) else 'candidate_weights_require_review_before_full_cache_regeneration',
        failed_fits=[r for r in fit_rows if not r['qualified']],failed_targets=[{k:r.get(k) for k in ('case','weight','variant','error')} for r in rows if not r['qualified']],
        verification=dict(weighted_objective_max_abs=max(checks,default=0),qualified_costs_checked=len(checks),
            EEG_closure_max_abs=float(frame.EEG_closure_max_abs.max()),Hb_closure_max_abs=float(frame.Hb_closure_max_abs.max())),
        figures=figures,input_morphology_scales=input_scales,scope=cfg['boundary'],claim_limits=cfg['endpoints'])
    write_json(out/'summary.json',summary)
    html='''<html><head><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1600px;margin:25px auto;line-height:1.7;padding:0 20px}img{width:100%}.waveform{overflow-x:auto}.waveform img{width:2400px;max-width:none}table{border-collapse:collapse;font-size:13px}td,th{border:1px solid #ccc;padding:5px}</style></head><body>
<h1>四数据集 τ/β 权重与 S/O 抗噪、形态保留实验</h1>
<p>权重顺序为 EEG:HbO:HbR，显示比例均归一化到总和3；固定现有PCA、个体尺度、τ/β先验、求解器和S/O功率上限算法。
四数据集各两名验证被试，按元数据选窗；各三名训练被试提供电压功率参考。没有按结果替换样本。
原生EEG以200/500/1000Hz读取和计算，绘图重采样到200Hz；未知单位保留原相对单位。
SSM可见完整90秒EEG与Hb；人工变化只用于评价目标的响应，不是盲预测。</p>
<p>抗噪误差 = ||S(扰动后)-S(原始)|| / ||已知噪声||，理想为0；神经样保留误差 = ||S(扰动后)-S(原始)-已知变化|| / ||已知变化||，理想为0。
二者在[30,50)秒、对应模态全部所选通道上计算。S+O严格互补，delta O与delta S的成功不是两项独立证据。
神经样探针为10/35Hz电压变化且Hb保持不变；它不是已知神经血管耦合真值。
原始窗口并非干净信号，因此S与原输入的相关/差异是形态诊断，不能单独证明去噪正确。</p>
<p>噪声均值先平均眼电、肌电、HbO/HbR扰动，神经均值先平均10/35Hz，再被试内汇总、数据集内等权、四数据集等权。
基线NRMSE使用训练电压RMS；导数相关反映快速形态。频带功率比、跨模态泄漏和最终功率越界在CSV保留。
未合格拟合不生成替代目标；有失败时数值均值为可用子集，配置推荐另要求完整配对支持。
拟合误差小不等于成分归属正确。全量缓存尚未重生成。</p>'''
    html+=f'<p>拟合合格 {summary["qualified_fits"]}/{summary["planned_fits"]}；S/O目标合格 {summary["qualified_targets"]}/{summary["planned_targets"]}。满足预设推荐条件的权重：{summary["eligible_weights"]}。</p>'
    html+='<h2>汇总</h2>'+aggregate.to_html(index=False,float_format=lambda x:f'{x:.4f}')+'<img src="weight_summary.png"><img src="weight_tradeoff.png">'
    html+='<h2>各数据集</h2>'+ds_frame.to_html(index=False,float_format=lambda x:f'{x:.4f}')
    html+='<p>推荐条件：每个数据集噪声误差至少下降20%，神经样误差增量不超过0.05、基线相关下降不超过0.02、基线NRMSE增量不超过0.05，并保留完整配对支持。这是工程选择规则，不是人群显著性检验。</p>'
    html+='<h2>扰动强度与幅度保留的分母</h2><p>EEG扰动RMS固定为对应训练参考电极RMS，未按当前窗口重定标；下表给出它相对当前电极输入的倍数。这是工程压力探针，不代表自然神经事件幅度。S/input RMS比与输入相对失真均先按固定训练通道尺度处理，再对同一窗口比较；它们区别于仅反映形态相似度的相关系数。原生频率上计算，图像降采样不进入评分。</p>'+pd.DataFrame(input_scales).to_html(index=False,float_format=lambda x:f'{x:.4f}')
    html+='<p><a href="summary.json">唯一数值汇总</a> · <a href="target_metrics.csv">逐目标指标与频带功率</a> · <a href="fit_status.csv">完整拟合状态</a> · <a href="variant_metrics.csv">按扰动类型统计</a></p>'
    for fig in figures:
        html+=f'<h2>{fig["case"]} / {fig["variant"]}</h2><p>灰线为观测或已知添加量；彩色线为S或相对同权重原始窗口的变化；红色点线为完整O。眼电/Hb噪声应进入O，神经样变化应进入S。各列是不同权重；图内每行统一刻度，不同窗口图独立刻度。七列图可横向滚动，点击查看原图。</p><div class="waveform"><a href="{fig["file"]}"><img src="{fig["file"]}"></a></div>'
    html+='</body></html>';(out/'report.html').write_text(html)
    return {k:summary[k] for k in ('status','planned_fits','qualified_fits','planned_targets','qualified_targets','eligible_weights','recommendation','verification')}


def weight_so_compact_example(out):
    """Display-only comparison from retained targets; first Visual case, no refits."""
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from scipy.signal import resample_poly
    plan=_weight_so_plan(str(out));r=next(r for r in plan['rows'] if r['dataset']=='visual_cognitive_motivation' and r['split']=='validation')
    case=r['case'];info=json.loads((out/'variants'/(case+'.json')).read_text());electrode=info['electrode']
    with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:rate=int(a['rate']);unit=str(a['unit'])
    t=np.arange(18000)/200;fig,axes=plt.subplots(2,3,figsize=(13,7),constrained_layout=True)
    for i,kind in enumerate(('ocular','neural10')):
        with np.load(out/'variants'/(case+'.npz'),allow_pickle=False) as a:
            added=resample_poly(a['delta_eeg_'+kind][:,electrode],200,rate)
        center=float(t[np.argmax(abs(added))]);width=2 if kind=='ocular' else .5
        mask=(t>=center-width)&(t<=center+width)
        for j,(weight,label) in enumerate((('equal','1:1:1'),('eeg4','4:1:1'),('hb4','1:4:4'))):
            folder=out/'targets'/case/weight
            with np.load(folder/(kind+'.npz'),allow_pickle=False) as a:delta=a['delta_s_display'][:,electrode]
            meta=json.loads((folder/(kind+'.json')).read_text());error=meta['noise_error' if kind=='ocular' else 'neural_error']
            ax=axes[i,j];ax.plot(t[mask],added[mask],color='black',ls='--',lw=1.2,label='Known added change')
            ax.plot(t[mask],delta[mask],color='#2475b5',lw=1.2,label='delta S')
            ax.plot(t[mask],(added-delta)[mask],color='#d65f29',lw=1.1,label='delta O')
            ax.set_title(f'EEG:HbO:HbR {label} | error={error:.3f}',fontsize=11);ax.set_xlabel('Within-window time (s)');ax.grid(alpha=.2)
            ax.legend(fontsize=9)
            if j==0:ax.set_ylabel(('Ocular addition' if i==0 else '10 Hz neural-like addition')+' ('+unit+')')
        lo=min(ax.get_ylim()[0] for ax in axes[i]);hi=max(ax.get_ylim()[1] for ax in axes[i])
        for ax in axes[i]:ax.set_ylim(lo,hi)
    fig.suptitle(f"Visual {r['subject']} | {info['electrode_name']} | same data and perturbations across weights\nNoise should enter O; neural-like change should enter S. Errors use all selected channels on [30,50) s.",fontsize=12)
    fig.savefig(out/'compact_SO_example.png',dpi=220);plt.close(fig)
    return dict(file='compact_SO_example.png',case=case,selection='first_metadata_selected_Visual_case',new_fits=0)


def weight_so_review(out):
    """Versioned presentation of the completed matrix; never changes fitted evidence."""
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    summary=json.loads((out/'summary.json').read_text());plan=_weight_so_plan(str(out));rows=[]
    for r in plan['rows']:
        if r['split']!='validation':continue
        with np.load(out/'inputs'/(r['case']+'.npz'),allow_pickle=False) as a:target=a['hb'][:-1]
        for weight in plan['weights']:
            folder=out/'targets'/r['case']/weight;meta=json.loads((folder/'baseline.json').read_text())
            if not meta['qualified']:continue
            with np.load(folder/'baseline.npz',allow_pickle=False) as a:pred=a['hb_s'][:-1]
            for j,component in enumerate(('HbO','HbR')):
                sd=target[:,:,j].std(0)
                rows.append(dict(dataset=r['dataset'],subject=r['subject'],weight=weight,component=component,
                    correlation=float(np.mean([np.corrcoef(target[:,k,j],pred[:,k,j])[0,1] for k in range(3)])),
                    local_nrmse=float(np.mean(np.sqrt(np.mean((pred[:,:,j]-target[:,:,j])**2,0))/sd)),
                    amplitude_ratio=float(np.mean(pred[:,:,j].std(0)/sd))))
    morphology=pd.DataFrame(rows);by_hb=morphology.groupby(['dataset','weight','component']).mean(numeric_only=True).groupby(['weight','component']).mean()
    for frame,name in [(morphology,'Hb_morphology_by_subject.csv'),(by_hb.reset_index(),'Hb_morphology_summary.csv')]:
        path=out/name
        if path.exists():
            old=pd.read_csv(path);numeric=[k for k in ('correlation','local_nrmse','amplitude_ratio') if k in frame]
            np.testing.assert_allclose(old[numeric],frame[numeric],rtol=1e-12,atol=1e-12)
        else:frame.to_csv(path,index=False)
    targets=pd.read_csv(out/'target_metrics.csv');neural=targets[targets.variant.isin(['neural10','neural35']) & targets.qualified].copy()
    neural['change_norm_ratio']=np.sqrt(np.maximum(neural.neural_error**2-1+2*neural.signed_projection,0))
    projections=neural.groupby(['dataset','weight','variant'])[['signed_projection','change_norm_ratio']].mean().groupby(['weight','variant']).mean()
    if not (out/'neural_change_projection.csv').exists():projections.to_csv(out/'neural_change_projection.csv')
    aggregate=pd.DataFrame(summary['aggregate']).set_index('weight');weights=list(plan['weights'])
    aliases=['1:1:1','4:1:1','1:2:2','1:4:4','1:4:1','1:1:4','1:100:100'];colors=plt.cm.tab10(np.arange(7))
    fig,axes=plt.subplots(2,2,figsize=(14,9),constrained_layout=True)
    metrics=['noise_error','neural_error','Hb_reference_nrmse','baseline_S_input_RMS_ratio']
    titles=['Known-noise error in S (lower better)','Neural-like preservation error (lower better)',
        'Original Hb reconstruction NRMSE (fixed subject SD)','Baseline S/input RMS ratio (fixed channel scales)']
    for ax,metric,title in zip(axes.flat,metrics,titles):
        bars=ax.bar(range(7),aggregate.loc[weights,metric],color=colors);bars[-1].set_hatch('///')
        ax.set_xticks(range(7),aliases,rotation=20);ax.set_title(title,fontsize=11);ax.grid(axis='y',alpha=.2)
        ax.set_xlabel('EEG:HbO:HbR ratio, normalized sum = 3')
        if metric in ('neural_error','baseline_S_input_RMS_ratio'):ax.axhline(1,color='gray',ls=':')
    fig.suptitle('Four-dataset equal means | 56/56 targets per setting; hatched Hb100 uses only 48/56',fontsize=13)
    fig.savefig(out/'weight_summary_v2.png',dpi=220);plt.close(fig)
    ds=pd.DataFrame(summary['dataset_metrics']);fig,axes=plt.subplots(2,2,figsize=(12,9),constrained_layout=True)
    markers=['o','s','^','v','D','P','X']
    for ax,(dataset,g) in zip(axes.flat,ds.groupby('dataset',sort=False)):
        for i,w in enumerate(weights):
            r=g[g.weight==w].iloc[0];ax.scatter(r.neural_error,r.noise_error,color=colors[i],marker=markers[i],s=65,label=aliases[i])
        ax.scatter([0],[0],marker='+',s=90,color='black');ax.axvline(1,color='gray',ls=':',lw=1)
        ax.set_xlim(-.02,1.1);ax.set_ylim(-.02,1.1);ax.grid(alpha=.2);ax.set_title(dataset,fontsize=10)
        ax.set_xlabel('Neural-like preservation error');ax.set_ylabel('Noise error in S')
    axes[0,0].legend(fontsize=9,loc='upper left');fig.suptitle('Same axes: lower-left preferred; unchanged S under neural addition gives error 1')
    fig.savefig(out/'weight_tradeoff_v2.png',dpi=220);plt.close(fig)
    narrative='''<h2>结论：抗噪候选与生产缓存建议分开</h2>
<p><strong>4:1:1通过预设的相对抗噪/EEG形态筛查，但暂不建议据此重生成全量缓存。</strong>
其综合噪声误差从0.4593降至0.3129，下降31.9%；四数据集分别下降约48.0%、28.8%、23.3%、28.0%。
改善主要来自HbO/HbR噪声，眼电和肌电指标基本不变。该筛查只约束相对等权的神经样/EEG形态退化，
没有要求绝对神经样保留达标，也没有把Hb原始波形保真设成硬门槛。</p>
<p>Hb重建的固定尺度NRMSE从0.3610升至0.4652（约28.9%）；HbO/HbR原始波形平均相关
分别从0.527/0.407降至0.323/0.273。因此不能把抗噪总分改善解释为双模态保真同时改善。
Hb优先通常改善Hb观测重建，但也更容易把Hb扰动分配给S；极端配置两次拟合失败导致8组目标不可用。</p>
<p>所有权重的神经样保留误差都约0.994。等权10Hz/35Hz新增变化在delta S中的有符号投影系数
约0.0226/-0.0069，delta S的范数仅约添加量的0.057/0.045，说明该档新增变化主要进入O。
这是投影幅度与范数比，不是来源能量百分比。S+O仍闭合；O不能据此命名为纯噪声。</p>
<p>神经样探针保持Hb不变，强度按训练电极RMS确定，相对当前窗口为1.08–18.79倍；
其中Single-Trial两例为14–19倍，是强压力测试，不能外推为自然神经事件的恢复率。
原始窗口S/input RMS约0.40、形态相关约0.87也提示：相关较高不等于幅度完整保留。
就本轮调权因素而言，生产缓存暂保留1:1:1，4:1:1作为抗噪候选保留；先改进或明确S/O目标
对电压变化的保留要求，再决定缓存替换。若最终更改权重，需重新求解驱动、初态和τ/β，不能事后乘系数替代。</p>'''
    html=(out/'report.html').read_text().replace('<h2>汇总</h2>',narrative+'<h2>汇总</h2>')
    html=html.replace('weight_summary.png','weight_summary_v2.png').replace('weight_tradeoff.png','weight_tradeoff_v2.png')
    table='<h2>Hb原始波形形态：先平均三位置，再等权汇总被试与数据集</h2>'+by_hb.reset_index().to_html(index=False,float_format=lambda x:f'{x:.4f}')
    table+='<p>local_nrmse使用每个窗口/位置观测SD，与主表的冻结被试尺度NRMSE分母不同；低波动位置也保留在分母中。Hb100为可用子集，不与完整组直接判优。</p>'
    html=html.replace('<h2>各数据集</h2>',table+'<h2>各数据集</h2>');(out/'report_v2.html').write_text(html)
    result=dict(status='completed',report='report_v2.html',source_summary='summary.json',
        new_fits=0,production_weight_recommendation='retain_equal_for_now',relative_screen_candidate='eeg4',
        additional_evidence=['Hb_morphology_summary.csv','Hb_morphology_by_subject.csv','neural_change_projection.csv'],
        original_report_retained='report.html',reason='Hb fidelity tradeoff and poor absolute neural-like preservation despite relative screen pass')
    write_json(out/'review.json',result);return result


def weight_so_main(args):
    cfg=weight_so_config(args.config);out=args.run_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    resolved=out/'resolved_config.json'
    if resolved.exists() and json.loads(resolved.read_text())!=cfg:raise ValueError('Weight study contract changed')
    write_json(resolved,cfg);stage=args.weight_so_stage
    if stage=='check':result=weight_so_check(cfg,out)
    elif stage=='plan':result=weight_so_plan(cfg,out)
    elif stage=='prepare':
        if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable preparation required')
        if json.loads((out/'software_checks.json').read_text())['status']!='passed':raise ValueError('Check first')
        result=weight_so_prepare(cfg,out,args.workers)
    elif stage in ('pilot','fit'):
        if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable fit required')
        tasks=json.loads((out/'fit_plan.json').read_text())['tasks'];plan=_weight_so_plan(str(out))
        if stage=='pilot':
            cases=[next(r['case'] for r in plan['rows'] if r['split']=='validation' and r['dataset']==ds) for ds in cfg['datasets']]
            tasks=[t for t in tasks if t['case'] in cases and t['weight']=='equal' and t['variant']=='baseline' and t['roi']==0]
        with (out/'controller.lock').open('w') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            result=_tak_cache_pool(_weight_so_fit,[(str(out),t) for t in tasks],out=out,phase='weight_so_'+stage,workers=args.workers,total=len(tasks),structured=True)
    elif stage=='targets':result=weight_so_targets(cfg,out,args.workers,pilot=args.pilot)
    elif stage=='review':result=weight_so_review(out)
    else:result=weight_so_summarize(cfg,out)
    print(json.dumps(serial({k:v for k,v in result.items() if k!='rows'})),flush=True);return result


def tau_beta_so_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_tau_beta_so_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):raise ValueError('Use reviewed tau/beta SO contract')
    return cfg


def tau_beta_so_validate_plan(plan,cfg):
    if plan['schema']!=cfg['source_schema']:raise ValueError('Wrong source schema')
    if any(r['split'] not in cfg['boundary']['splits'] for r in plan['rows']):
        raise ValueError('Disallowed split before signal reads')
    rows=[r for r in plan['rows'] if r['split']=='validation']
    if len(rows)!=8 or len({(r['dataset'],r['subject']) for r in rows})!=8:
        raise ValueError('Expected eight distinct source validation subjects')
    if len({r['dataset'] for r in rows})!=4:raise ValueError('Expected four datasets')
    return rows


def tau_beta_so_prepare(cfg,out):
    source=CODE_ROOT/cfg['source_run'];plan=_weight_so_plan(str(source))
    rows=tau_beta_so_validate_plan(plan,cfg);checks=[]
    for task in json.loads((source/'fit_plan.json').read_text())['tasks']:
        if task['weight'] not in cfg['weights']:continue
        case=task['case']
        if case not in {r['case'] for r in rows}:raise ValueError('Unplanned source case')
        key=f"{case}__{task['weight']}__{task['variant']}__r{task['roi']}"
        for arm in cfg['arms']:
            prediction,record=weight_so_prediction(source/'fits'/(key+'.json'),arm)
            checks.append(dict(key=key,qualified=True,**record))
    if len(checks)!=288:raise ValueError('Incomplete paired fit inventory')
    for row in rows:
        for weight in cfg['weights']:
            for variant in cfg['variants']:
                target=json.loads((source/'targets'/row['case']/weight/(variant+'.json')).read_text())
                if not target['qualified']:raise ValueError('Missing source free-arm target')
    result=dict(schema=cfg['schema'],source=str(source),cases=rows,retained_fit_arms=checks,
        paired_fit_tasks=len(checks)//2,new_nonlinear_fits=0,new_raw_reads=0,
        fixed_targets=112,reused_free_targets=112,frozen_control_targets=64)
    write_json(out/'plan.json',result);return dict(status='completed',paired_fit_tasks=len(checks)//2,cases=len(rows))


def tau_beta_so_targets(cfg,out,workers,pilot=False):
    if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable target production required')
    if workers<1 or workers>cfg['resources']['target_workers']:raise ValueError('Worker resource bound')
    saved=json.loads((out/'plan.json').read_text());source=Path(saved['source'])
    rows=tau_beta_so_validate_plan(_weight_so_plan(str(source)),cfg)
    if pilot:rows=[next(r for r in rows if r['dataset']==ds) for ds in dict.fromkeys(r['dataset'] for r in rows)]
    jobs=[]
    for row in rows:
        for weight in (['equal'] if pilot else cfg['weights']):
            for name,arm,freeze in [('fixed','tak_fixed',False),('frozen_fixed','tak_fixed',True),('frozen_free','tak_tau_beta',True)]:
                if pilot and name!='fixed':continue
                jobs.append((str(source),row['case'],weight,dict(arm=arm,freeze_baseline=freeze,
                    destination=str(out/name),variants=['baseline','ocular'] if freeze else cfg['variants'])))
    with (out/'controller.lock').open('w') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        return _tak_cache_pool(_weight_so_target,jobs,out=out,phase='tau_beta_so_pilot' if pilot else 'tau_beta_so_targets',
            workers=workers,total=len(jobs))


def tau_beta_so_summarize(cfg,out):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from scipy.signal import resample_poly
    saved=json.loads((out/'plan.json').read_text());source=Path(saved['source'])
    cases=tau_beta_so_validate_plan(_weight_so_plan(str(source)),cfg)
    destinations=dict(fixed=out/'fixed',free=source/'targets',frozen_fixed=out/'frozen_fixed',frozen_free=out/'frozen_free')
    rows=[];mechanism=[];proxy_rows=[];parameters=[];figures=[];baseline_replay=[]
    for case in cases:
        key=case['case'];dataset=case['dataset'];subject=case['subject']
        with np.load(source/'inputs'/(key+'.npz'),allow_pickle=False) as a:
            rate=int(a['rate']);unit=str(a['unit']);channel_names=a['channels'].astype(str)
        with np.load(source/'variants'/(key+'.npz'),allow_pickle=False) as a:
            delta={v:resample_poly(a['delta_eeg_'+v],200,rate,axis=0) for v in ('ocular','neural10')}
        electrode=json.loads((source/'variants'/(key+'.json')).read_text())['electrode']
        displays={};proxies={}
        for weight in cfg['weights']:
            for label,destination in destinations.items():
                variants=['baseline','ocular'] if label.startswith('frozen') else cfg['variants']
                for variant in variants:
                    path=destination/key/weight/(variant+'.json');record=json.loads(path.read_text())
                    row={k:v for k,v in record.items() if k!='fits'};row['condition']=label;rows.append(row)
                    if record['qualified'] and variant in ('baseline','ocular','neural10'):
                        with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:
                            displays[weight,label,variant]={k:a[k].copy() for k in ('s_display','delta_s_display')}
            for arm,label in [('tak_fixed','fixed'),('tak_tau_beta','free')]:
                frozen='frozen_'+label
                b=displays[weight,label,'baseline']['s_display'];fb=displays[weight,frozen,'baseline']['s_display']
                baseline_replay.append(dict(case=key,weight=weight,arm=arm,max_abs=float(np.max(abs(b-fb)))))
                np.testing.assert_allclose(b,fb,rtol=0,atol=1e-10)
                ds=displays[weight,label,'ocular']['delta_s_display'][6000:10000]
                df=displays[weight,frozen,'ocular']['delta_s_display'][6000:10000]
                n=delta['ocular'][6000:10000];den=np.linalg.norm(n)
                update=ds-df
                mechanism.append(dict(case=key,dataset=dataset,subject=subject,weight=weight,arm=label,
                    display_rate=200,full_change=float(np.linalg.norm(ds)/den),
                    frozen_reference_change=float(np.linalg.norm(df)/den),
                    reference_update_change=float(np.linalg.norm(update)/den),
                    reference_update_signed_gain=float(np.sum(update*n)/den**2),
                    decomposition_max_abs=float(np.max(abs(df+update-ds)))))
                for roi in range(3):
                    original=source/'fits'/f'{key}__{weight}__baseline__r{roi}.npz'
                    perturbed=source/'fits'/f'{key}__{weight}__ocular__r{roi}.npz'
                    if not perturbed.exists():perturbed=original
                    predkey='fixed_prediction' if label=='fixed' else 'prediction'
                    with np.load(original,allow_pickle=False) as a:
                        p0=a[predkey].copy();y0=a['target'].copy();sd=a['sd_subject'].copy()
                    with np.load(perturbed,allow_pickle=False) as a:p1=a[predkey].copy();y1=a['target'].copy()
                    rec0=json.loads(original.with_suffix('.json').read_text())['fits'][arm]
                    rec1=json.loads(perturbed.with_suffix('.json').read_text())['fits'][arm]
                    parameters.append(dict(case=key,dataset=dataset,subject=subject,weight=weight,arm=label,roi=roi,
                        tau_baseline=rec0['tau'],tau_ocular=rec1['tau'],beta_baseline=rec0['beta'],beta_ocular=rec1['beta']))
                    proxy_rows.append(dict(case=key,dataset=dataset,subject=subject,weight=weight,arm=label,roi=roi,
                        EEG_baseline_NRMSE=float(np.sqrt(np.mean(((p0[:-1,0]-y0[:-1,0])/sd[0])**2))),
                        Hb_baseline_NRMSE=float(np.sqrt(np.mean(((p0[:-1,1:]-y0[:-1,1:])/sd[1:])**2))),
                        ocular_prediction_change_over_observed_change=(float(np.linalg.norm((p1-p0)[300:500,0])/np.linalg.norm((y1-y0)[300:500,0])) if roi==0 else None)))
                    if roi==0:proxies[weight,label]=(y1-y0,p1-p0,sd)
        # All eight cases are exported: no outcome-dependent example selection.
        for variant in ('ocular','neural10'):
            fig,axes=plt.subplots(3,2,figsize=(13,10),sharex='col',sharey='row',layout='constrained')
            t=np.arange(4000)/200+30;n=delta[variant][6000:10000,electrode]
            rms=float(np.sqrt(np.mean(n*n)))
            for col,weight in enumerate(cfg['weights']):
                ax=axes[0,col]
                if variant=='ocular':
                    y,_,sd=proxies[weight,'fixed'];ax.plot(np.arange(200)/10+30,y[300:500,0]/sd[0],'k--',lw=1,label='Observed proxy change')
                    for label,color in [('fixed','#1764ab'),('free','#dc6b21')]:
                        _,p,_=proxies[weight,label];ax.plot(np.arange(200)/10+30,p[300:500,0]/sd[0],color=color,label=label+' SSM change')
                    ax.set_ylabel('Proxy change / frozen subject SD')
                else:
                    ax.plot(t,n/rms,'k--',lw=.8,label='Known 10 Hz addition')
                    for label,color in [('fixed','#1764ab'),('free','#dc6b21')]:
                        base=displays[weight,label,'baseline']['s_display'][6000:10000,electrode]
                        ax.plot(t,base/rms,color=color,lw=.7,label=label+' baseline S')
                    ax.set_ylabel('Voltage / injection RMS')
                ax.set_title('EEG:HbO:HbR = '+('1:1:1' if weight=='equal' else '4:1:1'));ax.legend(fontsize=8)
                for row in (1,2):
                    ax=axes[row,col];ax.plot(t,n/rms,'k--',lw=1,label='Known addition')
                    for label,color in [('fixed','#1764ab'),('free','#dc6b21')]:
                        ds=displays[weight,label,variant]['delta_s_display'][6000:10000,electrode]
                        ax.plot(t,(ds if row==1 else n-ds)/rms,color=color,lw=.9,label=label+(' delta S' if row==1 else ' delta O'))
                        if row==1 and variant=='ocular':
                            frozen=displays[weight,'frozen_'+label,variant]['delta_s_display'][6000:10000,electrode]
                            ax.plot(t,frozen/rms,color=color,lw=.8,ls=':',label=label+' frozen prediction')
                    ax.set_ylabel(('S' if row==1 else 'O')+' change / injection RMS');ax.legend(fontsize=8,ncol=2)
                axes[2,col].set_xlabel('Time in 90 s window / s')
            for ax in axes.flat:ax.grid(alpha=.2);ax.set_xlim(30,50)
            for row in range(3):
                low,high=axes[row,0].get_ylim();axes[row,0].set_ylim(low,high+.3*(high-low))
            fig.suptitle(f'{dataset} | {subject} | {channel_names[electrode]} | {variant}\nKnown added change; each model uses the full 90 s window. Display 200 Hz; metrics native rate.',fontsize=12)
            filename=f'{key}_{variant}.png';fig.savefig(out/filename,dpi=180);plt.close(fig);figures.append(filename)
    frame=pd.DataFrame(rows);frame.to_csv(out/'target_metrics.csv',index=False)
    if not frame.qualified.all():raise ValueError('Incomplete targets: inspect retained target_metrics.csv')
    if len(frame)!=288:raise ValueError('Expected 224 main and 64 frozen targets')
    frame['O_signed_projection']=1-frame.signed_projection
    frame.to_csv(out/'target_metrics.csv',index=False)
    numeric=['noise_error','neural_error','signed_projection','O_signed_projection','baseline_correlation',
        'baseline_nrmse','Hb_reference_nrmse','EEG_branch_change','Hb_branch_change']
    byds=frame.groupby(['dataset','weight','condition','variant'],sort=False)[numeric].mean().reset_index()
    aggregate=byds.groupby(['weight','condition','variant'],sort=False)[numeric].mean().reset_index()
    byds.to_csv(out/'dataset_metrics.csv',index=False);aggregate.to_csv(out/'aggregate_metrics.csv',index=False)
    ocular=frame[(frame.variant=='ocular')&frame.condition.isin(['fixed','free'])]
    paired=ocular.pivot(index=['dataset','subject','case','weight'],columns='condition',values='noise_error').reset_index()
    paired['free_minus_fixed']=paired.free-paired.fixed;paired.to_csv(out/'ocular_paired.csv',index=False)
    neural=frame[frame.variant.isin(['neural10','neural35'])&frame.condition.isin(['fixed','free'])]
    nsummary=neural.groupby(['dataset','subject','weight','condition'])[['neural_error','signed_projection']].mean().groupby(['dataset','weight','condition']).mean().groupby(['weight','condition']).mean().reset_index()
    nsummary.to_csv(out/'neural_summary.csv',index=False)
    pd.DataFrame(proxy_rows).to_csv(out/'proxy_metrics.csv',index=False)
    proxy_summary=pd.DataFrame(proxy_rows).groupby(['dataset','subject','weight','arm']).mean(numeric_only=True).groupby(['dataset','weight','arm']).mean().groupby(['weight','arm']).mean().reset_index()
    proxy_summary.to_csv(out/'proxy_summary.csv',index=False)
    pd.DataFrame(parameters).to_csv(out/'parameters.csv',index=False)
    mf=pd.DataFrame(mechanism);mf.to_csv(out/'mechanism_metrics.csv',index=False)
    ms=mf.groupby(['dataset','weight','arm']).mean(numeric_only=True).groupby(['weight','arm']).mean().reset_index();ms.to_csv(out/'mechanism_summary.csv',index=False)
    fig,axes=plt.subplots(1,2,figsize=(12,4.5),sharey=True,layout='constrained')
    for ax,weight in zip(axes,cfg['weights']):
        subset=paired[paired.weight==weight]
        for index,(_,row) in enumerate(subset.iterrows()):
            ax.plot([0,1],[row.fixed,row.free],marker='o',lw=1,label=row.dataset+' '+str(row.subject))
        means=subset[['fixed','free']].mean();ax.plot([0,1],means,'k--s',lw=2,label='Equal-dataset mean')
        ax.set_xticks([0,1],['Fixed tau/beta','Variable tau/beta']);ax.set_title('1:1:1' if weight=='equal' else '4:1:1')
        ax.set_ylabel('Ocular S leakage: norm(delta S) / norm(noise)');ax.grid(alpha=.2)
    axes[1].legend(fontsize=7,loc='upper left',bbox_to_anchor=(1.01,1))
    fig.savefig(out/'ocular_paired.png',dpi=200);plt.close(fig)
    result=dict(schema=cfg['schema'],status='completed',cases=8,datasets=4,main_targets=224,frozen_targets=64,
        qualified_targets=int(frame.qualified.sum()),paired_fit_tasks=saved['paired_fit_tasks'],new_nonlinear_fits=0,
        primary=aggregate[aggregate.variant=='ocular'].to_dict('records'),neural=nsummary.to_dict('records'),
        proxy=proxy_summary.to_dict('records'),mechanism=ms.to_dict('records'),
        improved_subjects={w:int(((paired.weight==w)&(paired.free_minus_fixed<0)).sum()) for w in cfg['weights']},
        baseline_replay_max_abs=max(x['max_abs'] for x in baseline_replay),
        decomposition_max_abs=max(x['decomposition_max_abs'] for x in mechanism),figures=figures,
        interpretation='Paired parameter intervention; O=X-S so complementary branch increments are not independent endpoints.')
    write_json(out/'summary.json',result)
    from html import escape
    body='<html><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1400px;margin:auto;padding:28px;line-height:1.65}img{width:100%}table{border-collapse:collapse;font-size:13px}td,th{border:1px solid #bbb;padding:5px}</style><h1>τ/β 固定与可调：S/O 配对实验</h1>'
    body+='<p>同一批四库八名验证被试，三位置，90 秒完整窗口条件拟合。固定分支 τ=2 秒、β=1；可调分支沿用原缓存先验与起点，log 参数先验标准差 0.125。每个输入条件重新拟合驱动和初态。144 组固定/可调拟合直接取自已保留结果；没有新增原始数据读取。两权重按 EEG/HbO/HbR 顺序，并把总和固定为 3。PCA、尺度、训练参考与功率约束完全相同。</p>'
    body+='<p>眼电主指标为 [30,50) 秒所有电极的 ||S污染−S原始|| / ||已知眼电||，越小越好，使用原生采样率。O 有符号投影 = 1−S 有符号投影；它是方向上的增益，不是独立成功率或能量比例。先被试内，再数据集内等权，最后四库等权。每个点代表一名被试的一段窗口。</p><img src="ocular_paired.png">'
    body+='<h2>眼电配对统计</h2>'+aggregate[(aggregate.variant=='ocular')&aggregate.condition.isin(['fixed','free'])][['weight','condition','noise_error','signed_projection','O_signed_projection']].to_html(index=False,float_format=lambda v:f'{v:.6f}')
    body+='<p>本组结果支持两权重下 O 能接收已知眼电。可调参数相对固定参数并未降低平均 S 泄漏；固定参数也已具有这一能力。结合冻结预测对照，主要抗扰动效果在既定预测参考下的电压功率约束中已经存在。τ/β 可调改善基线 SSM 拟合，与 O 接收眼电的机制应分别解释。</p>'
    body+='<h2>各被试配对差（可调减固定，负值为改善）</h2>'+paired.to_html(index=False,float_format=lambda v:f'{v:.6f}')
    body+='<h2>冻结基线预测的机制对照</h2><p>冻结时，输入仍增加同一眼电，只有提供功率参考的 SSM 预测保持基线值。完整变化 = 冻结参考下的变化 + 更新预测造成的变化。下表范数都除以已知眼电范数，使用统一 200 Hz 显示数组；两项范数不直接相加。冻结基线与各自完整基线逐点复现。</p>'+ms.to_html(index=False,float_format=lambda v:f'{v:.6f}')
    body+='<h2>SSM 代理和基线拟合</h2><p>代理误差以冻结原被试 SD 为分母；三个 ROI 先平均，再被试和数据集平均。眼电预测变化/观测变化仅针对第一处受扰动 ROI。</p>'+proxy_summary.to_html(index=False,float_format=lambda v:f'{v:.6f}')
    body+='<h2>神经样变化保留</h2><p>10/35 Hz 探针的指标为 ||ΔS−已知添加|| / ||已知添加||，越小越好；误差接近 1 且有符号投影接近 0 表示新增波形大部分进入 O。两频率先在被试内平均。此探针保持 Hb 不变，幅度采用训练参考电极 RMS，不等同于真实耦合神经事件；原始电压也不是干净真值。</p>'+nsummary.to_html(index=False,float_format=lambda v:f'{v:.6f}')
    body+='<h2>理论解释</h2><p>项目神经血管动力学中，血管舒张信号 a 的变化满足 da/dt = βr − κa − γ(f−1)，血流变化 df/dt = a。r 是共同驱动，β 是驱动到血管的增益；τ 是血液平均通过时间，控制血容量及脱氧变化的时间尺度。小扰动近似下 Hb ≈ βHτ[r]，Hτ 为血流动力学时间算子。固定错误的增益或时间尺度时，联合拟合可能通过修改 r 兼顾 Hb 和 EEG；放开参数可吸收这种失配。参数自由度也可吸收污染，所以改善基线拟合不自动等同于眼电剔除。log 先验标准差 0.125 是软惩罚，不是参数只能上下浮动 12.5% 的硬区间；实际值见 parameters.csv。</p>'
    body+='<p>电压目标不是把预测代理直接当成电压。当前算法用训练统计把三条代理提升为通道频带功率参考，再对输入电压实施局部二阶矩约束，得到 S，最后定义 O=X−S。记整条映射为 F(X,p)，则扰动响应可精确写成：ΔS=[F(X+n,p₀)−F(X,p₀)]+[F(X+n,p₁)−F(X+n,p₀)]。X 为原始窗口，n 为已知眼电，p₀/p₁ 为基线/污染条件的预测代理。第一项反映既定参考下电压约束的响应；第二项反映重新拟合后参考更新的作用。表中的冻结对照分别评估它们。</p>'
    body+='<h2>早期结果的方法差异</h2><p>早期同一 VP002 n-back 窗口的 current_target 是当时的空间目标；其 S 眼电误差为 0.83749、O 有符号增益为 0.17040。改用等权、固定 τ/β 的功率参考目标，误差已降到 0.50470、O 增益升至 0.58250。因此早期方法与当前方法的变化包含电压目标算法，而非只切换 τ/β。当前八被试的训练参考、窗口及扰动尺度也不同；跨代差异不能直接当作参数因果效应。历史提取表见 historical_audit.csv，其 source 字段指向原始 owning summary。</p>'
    body+='<h2>全体样例波形</h2><p>每个样例两个权重并排，同行共用纵轴。眼电图第一行为观测代理变化与 SSM 预测变化；第二行为 ΔS，点线为冻结基线预测对照；第三行为 ΔO。黑虚线为已知添加。电压除以注入 RMS，代理除以冻结被试 SD。神经样图第一行为原始 S 与添加波形，后两行为分支增量。时间均为窗口内 [30,50) 秒；完整评分与所有次要干预见 CSV。</p>'
    for filename in figures:body+='<p>'+escape(filename)+'</p><img src="'+escape(filename)+'">'
    body+='<p>证据：summary.json、target_metrics.csv、ocular_paired.csv、parameters.csv、mechanism_metrics.csv 和 resolved_config.json。神经血管模型参考 <a href="https://www.fil.ion.ucl.ac.uk/~wpenny/publications/tak-penny15.pdf">Tak 等（2015）</a>；训练参考统计约束的相关背景见 <a href="https://sccn.ucsd.edu/~scott/pdf/Mullen_IEEE15.pdf">Mullen 等（2015）</a>。项目实现采用自己的局部功率上限，并非原论文 ASR 的等同实现。</p></html>'
    (out/'report.html').write_text(body)
    return {k:v for k,v in result.items() if k not in ('figures',)}


def tau_beta_so_main(args):
    cfg=tau_beta_so_config(args.config);out=args.run_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    resolved=out/'resolved_config.json'
    if resolved.exists() and json.loads(resolved.read_text())!=cfg:raise ValueError('Frozen tau/beta comparison contract changed')
    write_json(resolved,cfg)
    if args.tau_beta_so_stage=='prepare':result=tau_beta_so_prepare(cfg,out)
    elif args.tau_beta_so_stage=='targets':result=tau_beta_so_targets(cfg,out,args.workers,args.pilot)
    else:result=tau_beta_so_summarize(cfg,out)
    print(json.dumps(serial(result)),flush=True);return result


def cache_ocular_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_cache_ocular_confirmation_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):raise ValueError('Use reviewed cache ocular contract')
    return cfg


def cache_ocular_select(source_plan,reference_plan,cfg):
    """Metadata-only selection. Never read a fit result to choose a case."""
    rows=[];counts={}
    for ds,setting in reference_plan['datasets'].items():
        template=next(r for r in reference_plan['rows'] if r['dataset']==ds and r['split']=='train')
        records=[r for r in source_plan['records'] if r['dataset']==ds and r['split']=='validation'
            and r['subject'] not in setting['validation_subjects']
            and r['eeg_channel_names']==template['record_plan']['eeg_channel_names']
            and any(w['duration_s']==90 for w in r['cache_windows'])
            and all(any(p['id']==name and p['status']=='available' for p in r['pairs']) for name in setting['pairs'])]
        subjects=sorted({r['subject'] for r in records},key=lambda s:(int(re.search(r'\d+',s).group()),s))
        counts[ds]=len(subjects)
        for subject in subjects:
            available=sorted([r for r in records if r['subject']==subject],key=lambda r:r['record'])
            if len(available)<2:raise ValueError('Two distinct records required')
            for record in (available[0],available[-1]):
                windows=[w for w in record['cache_windows'] if w['duration_s']==90];window=windows[len(windows)//2]
                rows.append(dict(case=record['cache_key'].replace('/','__')+'__'+window['key'],dataset=ds,subject=subject,
                    split='validation',record_plan=record,window=window,
                    pairs=[next(p for p in record['pairs'] if p['id']==name) for name in setting['pairs']]))
    if len(rows)!=cfg['selection']['expected_windows'] or sum(counts.values())!=cfg['selection']['expected_subjects']:
        raise ValueError('Unexpected metadata-selected population: '+str(counts))
    return rows,counts


def cache_ocular_plan(cfg,out):
    source=CODE_ROOT/cfg['source_run'];reference=CODE_ROOT/cfg['reference_run']
    source_plan=json.loads((source/'plan.json').read_text());reference_plan=_weight_so_plan(str(reference))
    rows,counts=cache_ocular_select(source_plan,reference_plan,cfg)
    coordinates=json.loads((source/'coordinates.json').read_text());source_cfg=json.loads((source/'resolved_config.json').read_text())
    source_summary=json.loads((source/'summary.json').read_text());verification=json.loads((source/'verification.json').read_text())
    if source_summary['status']!='completed' or verification['status']!='passed':raise ValueError('Completed verified source required')
    for row in rows:
        co=coordinates['individual'][row['dataset']+'__'+row['subject']]
        if co['status']!='completed':raise ValueError('Missing source calibration')
        template=next(r for r in reference_plan['rows'] if r['dataset']==row['dataset'])
        np.testing.assert_array_equal(co['pc'],template['coordinate']['pc'])
        row['coordinate']={k:co[k] for k in ('pc','eeg_factor','hb_factor','sd')}
        row['feature']=str(source/'features'/row['record_plan']['cache_key']/(row['window']['key']+'.npz'))
    plan=dict(schema=cfg['schema'],source=str(source),reference_source=str(reference),rows=rows,subject_counts=counts,
        cache_data=source_cfg['data'],weights={'equal':[1.,1.,1.]},model_config=json.loads((source/'resolved_model_config.json').read_text()),
        source_completion=source_summary,source_verification=verification,selection='metadata_only_no_fit_outcome_selection')
    write_json(out/'plan.json',plan)
    tasks=[dict(case=r['case'],weight='equal',variant=v,roi=i) for r in rows for v in cfg['interventions']['variants'] for i in range(3)]
    write_json(out/'fit_plan.json',dict(schema=cfg['schema'],tasks=tasks,planned=len(tasks)))
    return dict(status='planned',subjects=counts,windows=len(rows),fits=len(tasks),measured_signal_reads=0)


def cache_ocular_injection(x,rate,channels,donor,amplitude):
    """Fixed anterior mixing, exact native-voltage RMS, compact known support."""
    from scipy.signal import resample_poly
    x=np.asarray(x,float);donor=np.asarray(donor,float)
    if x.shape!=(90*rate,len(channels)) or donor.shape!=(18000,) or amplitude<=0:
        raise ValueError('Complete native window and positive intervention required')
    def strength(name):
        name=str(name).upper()
        if name.startswith(('FP','AFP')):return 1.
        if name.startswith('AF'):return .65
        if name.startswith('FC'):return .22
        if name.startswith('F'):return .4
        return .08
    topology=np.array([strength(c) for c in channels]);t=np.arange(len(x))/rate
    taper=np.where((t>=30)&(t<50),np.sin(.5*np.pi*np.clip(np.minimum(t-30,50-t),0,1))**2,0.)
    carrier=resample_poly(donor,rate,200)*taper
    added=carrier[:,None]*topology;use=slice(30*rate,50*rate)
    reference=float(np.sqrt(np.mean(x[use]**2)));scale=float(np.sqrt(np.mean(added[use]**2)))
    if min(reference,scale)<=0 or not np.isfinite([reference,scale]).all():raise ValueError('Nonzero finite reference and carrier required')
    added*=amplitude*reference/scale
    return added,dict(topology=topology.tolist(),reference_RMS=reference,amplitude_ratio=amplitude,
        injected_RMS=float(np.sqrt(np.mean(added[use]**2))),electrode=int(np.argmax(topology)))


def cache_ocular_prepare(cfg,out,rows):
    from src.inference.observation_baselines import eeg_band_power
    from src.data.dual_component_tokenizer import BANDS
    plan=_weight_so_plan(str(out));reference=Path(plan['reference_source'])
    execution=_tak_cache_pool(_weight_so_prepare_native,[(str(out),r) for r in rows],out=out,
        phase='cache_ocular_native_'+str(len(rows)),workers=cfg['resources']['preparation_workers'],total=len(rows))
    if any(r['status']!='completed' for r in execution['rows']):raise ValueError('Native preparation failed; no replacement')
    with np.load(CODE_ROOT/cfg['interventions']['source'],allow_pickle=False) as a:
        known=a['n_ocular'];donor=known[:,np.argmax(np.sum(known**2,axis=0))]
    for ds in {r['dataset'] for r in rows}:
        dest=out/'references'/(ds+'.npz');dest.parent.mkdir(parents=True,exist_ok=True)
        if not dest.exists():shutil.copy2(reference/'references'/(ds+'.npz'),dest)
    for row in rows:
        path=out/'variants'/(row['case']+'.npz');meta=path.with_suffix('.json')
        if meta.exists():continue
        with np.load(out/'inputs'/(row['case']+'.npz'),allow_pickle=False) as a:base={k:a[k] for k in a.files}
        with np.load(out/'references'/(row['dataset']+'.npz'),allow_pickle=False) as a:
            np.testing.assert_array_equal(a['projection'],base['projection']);assert int(a['sample_rate_hz'])==int(base['rate'])
        arrays={};metadata={};changed={};rate=int(base['rate'])
        for variant in cfg['interventions']['variants']:
            de=np.zeros_like(base['x']);features=base['features'].copy()
            if variant!='baseline':
                de,metadata[variant]=cache_ocular_injection(base['x'],rate,base['channels'],donor,cfg['interventions']['amplitudes'][variant])
                features=np.log(eeg_band_power(base['x']+de,bands=BANDS,sample_rate=rate,target_rate=10));features-=features[:50].mean(0)
            arrays.update({f'features_{variant}':features,f'hb_{variant}':base['hb'],
                f'delta_eeg_{variant}':de,f'delta_hb_{variant}':np.zeros_like(base['hb'])});changed[variant]=[0,1,2]
        _tak_cache_npz(path,**arrays);electrode=metadata['ocular1']['electrode']
        write_json(meta,dict(case=row['case'],changed_rois=changed,electrode=electrode,electrode_name=str(base['channels'][electrode]),
            interventions=metadata,score_seconds=[30,50],Hb_unchanged=True))
    return execution


def cache_ocular_summarize(cfg,out,export=None):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from scipy.signal import resample_poly
    from html import escape
    figure_out=Path(export).resolve() if export is not None else out
    if export is not None:
        if figure_out.parent!=out or figure_out.exists():raise ValueError('Fresh direct child report export required')
        figure_out.mkdir()
    plan=_weight_so_plan(str(out));records=[];fits=[];figures=[];checks=[]
    variants=cfg['interventions']['variants'];limits=cfg['endpoints']['engineering_checks']
    for row in plan['rows']:
        case=row['case'];folder=out/'targets'/case/'equal';metadata=json.loads((out/'variants'/(case+'.json')).read_text())
        with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:base={k:a[k] for k in a.files}
        rate=int(base['rate']);channel=metadata['electrode'];roi=next(i for i in range(3) if channel in base['roi_indices'][i])
        xd=resample_poly(base['x'][:,channel],200,rate);time=np.arange(len(xd))/200;ht=np.arange(900)/10
        data={};deltas={};proxies={};case_rows={}
        with np.load(out/'variants'/(case+'.npz'),allow_pickle=False) as a:
            for variant in variants:
                np.testing.assert_array_equal(a['hb_'+variant],base['hb'])
                delta=a['delta_eeg_'+variant];deltas[variant]=resample_poly(delta[:,channel],200,rate)
                assert not delta[:30*rate].any() and not delta[50*rate:].any()
                if variant!='baseline':
                    expected=cfg['interventions']['amplitudes'][variant]
                    measured=float(np.linalg.norm(delta[30*rate:50*rate])/np.linalg.norm(base['x'][30*rate:50*rate]))
                    np.testing.assert_allclose(measured,expected,rtol=1e-12,atol=1e-12)
                    checks.append(dict(case=case,variant=variant,amplitude_ratio=measured,Hb_unchanged=True,outside_injection_zero=True))
                path=folder/(variant+'.json');rec=json.loads(path.read_text()) if path.exists() else dict(qualified=False,status='missing')
                record=dict(case=case,dataset=row['dataset'],subject=row['subject'],record=row['record_plan']['record'],variant=variant,
                    **{k:v for k,v in rec.items() if k not in ('fits','case','dataset','subject','variant')})
                record['amplitude']=cfg['interventions']['amplitudes'].get(variant,0.)
                record['engineering_pass']=bool(rec['qualified'] and variant!='baseline'
                    and rec['noise_error']<=limits['maximum_S_leakage'] and rec['O_delta_correlation']>=limits['minimum_O_delta_correlation'])
                records.append(record);case_rows[variant]=record
                if rec['qualified']:
                    with np.load(path.with_suffix('.npz'),allow_pickle=False) as z:data[variant]={k:z[k].copy() for k in z.files}
                for i in range(3):
                    fitpath=out/'fits'/f'{case}__equal__{variant}__r{i}.json';fit=json.loads(fitpath.read_text())
                    fits.append(dict(case=case,dataset=row['dataset'],subject=row['subject'],variant=variant,roi=i,
                        qualified=fit['qualified'],status=fit['status'],seconds=fit['seconds'],
                        baseline_replay_max_subject_SD=fit.get('baseline_replay_max_subject_SD'),
                        tau=fit.get('fits',{}).get('tak_tau_beta',{}).get('tau'),beta=fit.get('fits',{}).get('tak_tau_beta',{}).get('beta')))
                    if i==roi and fitpath.with_suffix('.npz').exists():
                        with np.load(fitpath.with_suffix('.npz'),allow_pickle=False) as z:
                            if 'prediction' in z:proxies[variant]=(z['target'][:,0].copy(),z['prediction'][:,0].copy(),float(z['sd_subject'][0]))
        fig,axes=plt.subplots(7,3,figsize=(16,20),sharex='col',sharey='row',layout='constrained')
        for col,variant in enumerate(variants[1:]):
            axes[0,col].set_title(f"Added EOG RMS = {case_rows[variant]['amplitude']:g} x original RMS")
            for ax in axes[:,col]:ax.axvspan(30,50,color='#efcf91',alpha=.2);ax.grid(alpha=.2)
            axes[0,col].plot(time,xd,color='#59636b',lw=.7,label='Before');axes[0,col].plot(time,xd+deltas[variant],color='#d34d32',lw=.7,label='After')
            if 'baseline' not in data or variant not in data:
                for ax in axes[1:,col]:ax.text(.5,.5,'Unqualified target — retained failure',ha='center',transform=ax.transAxes)
                continue
            b=data['baseline'];v=data[variant]
            for row_index,before,after in [(1,b['s_display'][:,channel],v['s_display'][:,channel]),
                (2,xd-b['s_display'][:,channel],xd+deltas[variant]-v['s_display'][:,channel])]:
                axes[row_index,col].plot(time,before,color='#59636b',lw=.7,label='Before');axes[row_index,col].plot(time,after,color='#d34d32',lw=.7,label='After')
            for j in range(2):
                ax=axes[3+2*j,col];ax.plot(ht,base['hb'][:,roi,j],'k--',lw=.8,label='Measured Hb (same input)')
                ax.plot(ht,b['hb_s'][:,roi,j],color='#59636b',lw=.9,label='S before');ax.plot(ht,v['hb_s'][:,roi,j],color='#d34d32',lw=.9,label='S after')
                ax=axes[4+2*j,col];ax.axhline(0,color='k',ls=':',lw=.7,label='Zero residual')
                ax.plot(ht,b['hb_o'][:,roi,j],color='#59636b',lw=.9,label='O before')
                ax.plot(ht,v['hb_o'][:,roi,j],color='#d34d32',lw=.9,label='O after')
            np.testing.assert_allclose(v['hb_o']-b['hb_o'],-(v['hb_s']-b['hb_s']),rtol=0,atol=1e-12)
            rec=case_rows[variant];axes[1,col].text(.02,.96,f"S leakage={rec['noise_error']:.3f}; paired r={rec['S_pair_correlation']:.3f}",transform=axes[1,col].transAxes,va='top',fontsize=9)
            axes[2,col].text(.02,.96,f"O change r={rec['O_delta_correlation']:.3f}; gain={rec['O_signed_gain']:.3f}",transform=axes[2,col].transAxes,va='top',fontsize=9)
        lo=min(axes[j,0].get_ylim()[0] for j in range(3));hi=max(axes[j,0].get_ylim()[1] for j in range(3))
        for j in range(3):axes[j,0].set_ylim(lo,hi+.3*(hi-lo))
        for j in range(3,7):
            low,high=axes[j,0].get_ylim();axes[j,0].set_ylim(low,high+.3*(high-low))
        for j,label in enumerate(['Input EEG','EEG S','EEG O','HbO S','HbO O','HbR S','HbR O']):
            axes[j,0].set_ylabel(label+' / '+(str(base['unit']) if j<3 else 'cached native unit'))
            for ax in axes[j]:
                ax.set_xlim(0,90)
                if ax.get_legend_handles_labels()[0]:ax.legend(loc='upper right',fontsize=8,ncol=2)
        for ax in axes[-1]:ax.set_xlabel('Time in window / s')
        fig.suptitle(f"{row['dataset']} | {row['subject']} | {row['record_plan']['record']} | {row['window']['key']}\nEEG {str(base['channels'][channel])}; Hb {row['pairs'][roi]['id']}. Same voltage axes for input/S/O; shaded injection support.",fontsize=12)
        name=case+'_before_after.png';fig.savefig(figure_out/name,dpi=180);plt.close(fig);figures.append(name)
        fig,axes=plt.subplots(5,3,figsize=(16,15),sharex='col',sharey='row',layout='constrained')
        use=slice(6000,10000)
        for col,variant in enumerate(variants[1:]):
            axes[0,col].set_title(f"EOG strength {case_rows[variant]['amplitude']:g} x")
            if 'baseline' not in data or variant not in data:
                for ax in axes[:,col]:ax.text(.5,.5,'Unqualified target',ha='center',transform=ax.transAxes)
                continue
            n=deltas[variant][use];ds=data[variant]['delta_s_display'][use,channel];q=float(np.sqrt(np.mean(n*n)))
            for j,change,label in [(0,ds,'S after - S before'),(1,n-ds,'O after - O before')]:
                ax=axes[j,col];ax.plot(time[use],n/q,'k--',lw=.9,label='Known added EOG');ax.plot(time[use],change/q,color='#1764ab' if j==0 else '#d34d32',lw=1,label=label)
                ax.set_ylabel(('Delta S' if j==0 else 'Delta O')+' / local injection RMS')
            if variant in proxies and 'baseline' in proxies:
                y,p,sd=proxies[variant];y0,p0,_=proxies['baseline'];ax=axes[2,col]
                ax.plot(ht[300:500],(y-y0)[300:500]/sd,'k--',lw=.9,label='Observed proxy change')
                ax.plot(ht[300:500],(p-p0)[300:500]/sd,color='#1764ab',lw=1,label='SSM proxy change');ax.set_ylabel('Proxy change / frozen subject SD')
            for j,name in enumerate(('HbO','HbR')):
                ax=axes[3+j,col];change=data[variant]['hb_o'][300:500,roi,j]-data['baseline']['hb_o'][300:500,roi,j]
                ax.axhline(0,color='k',ls='--',lw=.8,label='Measured Hb change = 0')
                ax.plot(ht[300:500],change,color='#d34d32',lw=1,label='O after - O before')
                ax.set_ylabel('Delta '+name+' O / cached native unit')
        lo=min(axes[j,0].get_ylim()[0] for j in (0,1));hi=max(axes[j,0].get_ylim()[1] for j in (0,1))
        for j in (0,1):axes[j,0].set_ylim(lo,hi+.25*(hi-lo))
        for j in (2,3,4):
            low,high=axes[j,0].get_ylim();axes[j,0].set_ylim(low,high+.25*(high-low))
        for ax in axes.flat:
            ax.grid(alpha=.2);ax.set_xlim(30,50)
            if ax.get_legend_handles_labels()[0]:ax.legend(loc='upper right',fontsize=8)
        for ax in axes[-1]:ax.set_xlabel('Time in window / s')
        fig.suptitle(f"{row['dataset']} | {row['subject']} | {row['record_plan']['record']}\nKnown added change and branch responses; full 90 s refit; display 200 Hz, metrics native rate.",fontsize=12)
        name=case+'_changes.png';fig.savefig(figure_out/name,dpi=180);plt.close(fig);figures.append(name)
    frame=pd.DataFrame(records);ff=pd.DataFrame(fits)
    def save_table(value,name):
        if export is None:value.to_csv(out/name,index=False)
    save_table(frame,'target_metrics.csv');save_table(ff,'fit_status.csv')
    changed=frame[frame.variant!='baseline'].copy();numeric=['noise_error','O_delta_correlation','O_signed_gain','S_pair_correlation','S_change_relative_baseline','Hb_branch_change','outside_S_change_relative_baseline']
    subject=changed.groupby(['dataset','subject','amplitude'])[numeric].mean().reset_index();save_table(subject,'subject_metrics.csv')
    dataset=subject.groupby(['dataset','amplitude'])[numeric].mean().reset_index();save_table(dataset,'dataset_metrics.csv')
    aggregate=dataset.groupby('amplitude')[numeric].mean().reset_index()
    counts=changed.groupby('amplitude').agg(planned=('qualified','size'),qualified=('qualified','sum'),passed=('engineering_pass','sum')).reset_index()
    aggregate=aggregate.merge(counts,on='amplitude');aggregate['pass_fraction_all_planned']=aggregate.passed/aggregate.planned
    save_table(aggregate,'aggregate_metrics.csv')
    perds=changed.groupby(['dataset','amplitude']).agg(planned=('qualified','size'),qualified=('qualified','sum'),passed=('engineering_pass','sum')).reset_index()
    perds=dataset.merge(perds,on=['dataset','amplitude']);save_table(perds,'dataset_metrics.csv')
    names=dict(eeg_fnirs_single_trial='Single-Trial',simultaneous_eeg_nirs='Simultaneous',refed='REFED',visual_cognitive_motivation='Visual')
    fig,axes=plt.subplots(1,3,figsize=(14,4.5),layout='constrained')
    for ax,metric,title,limit in zip(axes,['noise_error','O_delta_correlation','S_pair_correlation'],['S leakage (lower better)','O change correlation (higher better)','S before/after correlation (higher better)'],[.3,.9,None]):
        for ds in plan['subject_counts']:
            f=dataset[dataset.dataset==ds];ax.plot(f.amplitude,f[metric],marker='o',label=names[ds])
        if limit is not None:ax.axhline(limit,color='k',ls='--',lw=1,label='Engineering check')
        ax.set_title(title);ax.set_xlabel('Added EOG RMS / original EEG RMS');ax.set_xticks([.5,1,2]);ax.grid(alpha=.2)
    axes[2].legend(fontsize=8,loc='lower left');fig.savefig(figure_out/'summary.png',dpi=200);plt.close(fig)
    replay=ff[ff.variant=='baseline'].baseline_replay_max_subject_SD
    verification=dict(status='passed',native_inputs=len(plan['rows']),interventions=len(checks),Hb_identical=True,
        injection_outside_support_zero=True,amplitude_checks=checks,
        baseline_replay_available=int(replay.notna().sum()),baseline_replay_max_subject_SD=float(replay.max()),
        EEG_closure_max_abs=float(frame.EEG_closure_max_abs.max()),Hb_closure_max_abs=float(frame.Hb_closure_max_abs.max()))
    if replay.notna().sum()!=72 or replay.max()>1e-6:verification['status']='failed_baseline_replay'
    if export is None:write_json(out/'verification.json',verification)
    result=dict(schema=cfg['schema'],status='completed' if verification['status']=='passed' else 'completed_with_verification_failure',
        subjects=plan['subject_counts'],windows=len(plan['rows']),planned_fits=len(ff),qualified_fits=int(ff.qualified.sum()),
        planned_targets=len(frame),qualified_targets=int(frame.qualified.sum()),aggregate=aggregate.to_dict('records'),
        numerical_failures=ff[~ff.qualified].to_dict('records'),figures=figures,
        decision='strength_specific_engineering_evidence_no_universal_robustness_claim',
        original_cache_unchanged=True,source_cache_counts=plan['source_completion']['counts'])
    if export is None:write_json(out/'summary.json',result)
    elif serial(result)!=json.loads((out/'summary.json').read_text()):raise ValueError('Report export changed scientific summary')
    html='<html><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1600px;margin:auto;padding:24px;line-height:1.65}img{width:100%}table{border-collapse:collapse}td,th{border:1px solid #aaa;padding:5px;font-size:13px}</style><h1>已完成缓存：实际眼电注入、状态空间重拟合与 S/O 前后对照</h1>'
    html+='<p>四库12名验证被试、每人两段90秒窗口。名单在读取信号前固定，排除前两轮权重/参数实验的8名被试，按元数据选窗。Visual仅余1名被试，结果按该实际人数解释。基线与眼电条件都实际重新拟合；权重1:1:1，τ/β原先验可调，PCA、个体尺度和训练参考冻结。未注入预测与现有缓存逐点核对。原始背景不是无眼电真值，只有新增扰动已知。</p>'
    html+='<p>在原生电压上加入保留实测VEOG派生波形，采用预设额前较强空间混合，整体RMS为原窗口所选电极[30,50)秒RMS的0.5/1/2倍。空间混合不是测得的个体传播矩阵。扰动两端一秒平滑到零，支持外严格为零；Hb逐点不变。重新计算全部频带功率及PCA代理，再运行状态空间优化与原功率上限S/O构建。原生200/500/1000Hz评分，200Hz仅用于显示。</p>'
    html+='<p>S泄漏=||S后−S前||/||已知眼电||；O相关为O增量与已知眼电的相关；O增益为其有符号投影/眼电能量。S前后相关取各通道中位数，相对变化用||ΔS||/||S前||；Hb变化除以冻结原被试SD。主支持[30,50)秒，支持外检查[5,25)与[55,85)秒。先两窗口在被试内平均，再被试等权、四库等权。工程核对线为S泄漏≤0.30且O相关≥0.90，未把它称为生理标准；通过数的分母包含失败。</p>'
    html+='<h2>三档强度统计</h2>'+aggregate.to_html(index=False,float_format=lambda v:f'{v:.4f}')+'<img src="summary.png">'
    html+='<p>本批O增量与眼电的平均相关为0.963–0.988，说明能接收主要眼电形态；S仍会改变。0.5/1/2倍强度分别9/24、12/24、19/24窗口通过两条工程线。较强眼电的相对泄漏下降，同时S前后相关从0.959降至0.826，S变化相对其基线幅度从0.453升至1.137。因此结果支持部分抗眼电能力，尚不支持S在这些扰动下近似不变。Hb输入虽不变，预测也会受EEG污染影响。</p>'
    html+='<p>每档有23个有效配对；VP005 n-back一处基线未收敛，与原缓存失败和预测一致，导致该窗口四个S/O条件不合格。数值均值基于有效配对，先按被试再数据集汇总；通过数始终以全部24个计划窗口为分母。失败窗口保留在完整图谱中。</p>'
    html+='<h2>各数据集</h2>'+perds.to_html(index=False,float_format=lambda v:f'{v:.4f}')
    html+='<h2>为什么观测不变，O仍然变化</h2><p>原图的Observation (unchanged)仅指HbO/HbR实测输入：眼电加在EEG电压上，Hb测量没有被修改。它不表示预测或O不变。本版改标Measured Hb (same input)，分别显示EEG、HbO、HbR的O前后曲线及增量。O=观测−S，所以EEG的ΔO=新增眼电−ΔS；Hb输入不变，因此Hb的ΔO=−ΔS。后者是EEG污染影响联合拟合后，Hb在S/O之间的重新分配，不是额外眼电被直接加入了光学测量。全部有效配对核验了这一恒等式。</p>'
    html+='<h2>完整前后波形</h2><p>每组第一幅图依次为输入EEG、EEG-S、EEG-O、HbO-S、HbO-O、HbR-S、HbR-O。灰为注入前、红为注入后；Hb的S面板黑虚线为同一实测输入，O面板黑点线为零残差。前三行使用相同电压坐标；各行跨强度共用坐标。第二幅图依次显示EEG的ΔS、ΔO、代理变化，以及HbO-O、HbR-O的变化，Hb变化图的黑虚线为零实测变化。单电极波形用于读图，表中主指标使用所有选定电极。所有窗口都展示，不按效果筛选。</p>'
    for name in figures:html+='<p>'+escape(name)+'</p><img src="'+escape(name)+'">'
    html+='<p>完整数值：summary.json、target_metrics.csv、subject_metrics.csv、dataset_metrics.csv、fit_status.csv；模型和选择合同：resolved_config.json、plan.json；闭合与缓存复现：verification.json。数值失败保留原记录，图中明确标注。</p></html>'
    labels=dict(amplitude='眼电RMS倍数',noise_error='S泄漏',O_delta_correlation='O增量相关',O_signed_gain='O有符号增益',
        S_pair_correlation='S前后相关',S_change_relative_baseline='S变化/基线S',Hb_branch_change='Hb变化/冻结SD',
        outside_S_change_relative_baseline='支持外S变化/基线S',planned='计划窗口',qualified='有效配对',passed='通过窗口',
        pass_fraction_all_planned='全部窗口通过率',dataset='数据集')
    for key,label in {**labels,**names}.items():html=html.replace('>'+key+'<','>'+label+'<')
    if export is not None:
        html=html.replace('完整数值：','本目录为版本化可视化导出，数值事实源在上一级运行目录。完整数值：')
        write_json(figure_out/'export.json',dict(status='completed',source_summary=str(out/'summary.json'),
            scientific_summary_identical=True,new_fits=0,figures=len(figures)+1,
            revision='Explicit unchanged-Hb-input legend; EEG/HbO/HbR O before/after and changes; original exports retained',
            Hb_delta_O_equals_negative_delta_S_checked=True))
    (figure_out/'report.html').write_text(html)
    return {k:v for k,v in result.items() if k!='figures'}


def cache_ocular_main(args):
    cfg=cache_ocular_config(args.config);out=args.run_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    path=out/'resolved_config.json'
    if path.exists() and json.loads(path.read_text())!=cfg:raise ValueError('Frozen ocular confirmation contract changed')
    write_json(path,cfg);stage=args.cache_ocular_stage
    if stage=='plan':result=cache_ocular_plan(cfg,out)
    elif stage=='summarize':result=cache_ocular_summarize(cfg,out,args.cache_ocular_export)
    else:
        if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable ocular experiment required')
        plan=_weight_so_plan(str(out));rows=plan['rows'];pilot=stage=='pilot'
        if pilot:rows=[next(r for r in rows if r['dataset']==ds) for ds in plan['subject_counts']]
        with (out/'controller.lock').open('w') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            cache_ocular_prepare(cfg,out,rows)
            tasks=json.loads((out/'fit_plan.json').read_text())['tasks']
            if pilot:tasks=[t for t in tasks if t['case'] in {r['case'] for r in rows} and t['variant'] in ('baseline','ocular1') and t['roi']==0]
            result=_tak_cache_pool(_weight_so_fit,[(str(out),t) for t in tasks],out=out,
                phase='cache_ocular_pilot_fit' if pilot else 'cache_ocular_fit',
                workers=cfg['resources']['pilot_fit_workers' if pilot else 'fit_workers'],total=len(tasks),structured=True)
            if not pilot:
                jobs=[(str(out),r['case'],'equal',dict(variants=cfg['interventions']['variants'],audit_interference=True)) for r in rows]
                result=_tak_cache_pool(_weight_so_target,jobs,out=out,phase='cache_ocular_targets',
                    workers=cfg['resources']['target_workers'],total=len(jobs))
                result=cache_ocular_summarize(cfg,out)
    print(json.dumps(serial(result)),flush=True);return result


def modality_weight_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_ocular_modality_weight_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):raise ValueError('Use reviewed modality-weight contract')
    return cfg


def modality_weight_plan(cfg,out):
    parent=CODE_ROOT/cfg['source_run'];old=_weight_so_plan(str(parent));rows=[]
    if old['schema']!=cfg['source_schema'] or json.loads((parent/'resolved_config.json').read_text())!=cache_ocular_config():
        raise ValueError('Reviewed source ocular contract required')
    for ds,subjects in cfg['subjects'].items():
        for subject in subjects:
            selected=sorted([r for r in old['rows'] if r['dataset']==ds and r['subject']==subject],key=lambda r:r['record_plan']['record'])
            if len(selected)!=2 or any(r['split']!='validation' for r in selected):raise ValueError('Exact paired development records required before arrays')
            rows.extend([dict(r,panel=label) for r,label in zip(selected,('screen','review'))])
    if len(rows)!=12:raise ValueError('Twelve prespecified records required')
    plan=dict(schema=cfg['schema'],parent=str(parent),source=old['source'],rows=rows,cache_data=old['cache_data'],
        model_config=old['model_config'],weights={k:weight_so_weights(v).tolist() for k,v in cfg['weights'].items()})
    write_json(out/'plan.json',plan)
    tasks=[dict(case=r['case'],weight=w,variant=v,roi=i) for r in rows if r['panel']=='screen'
        for w in cfg['weights'] for v in cfg['screen']['variants'] for i in range(3)]
    write_json(out/'fit_plan.json',dict(tasks=tasks,planned=len(tasks),new_fits=sum(t['weight']!='equal' for t in tasks)))
    return dict(status='planned',screen_cases=6,review_cases=6,planned_ROI_conditions=len(tasks),new_ROI_conditions=108,signal_reads=0)


def _modality_weight_dry(payload):
    out_string,weight=payload;out=Path(out_string);plan=_weight_so_plan(out_string);path=out/'dry_run'/(weight+'.json')
    if path.exists():return json.loads(path.read_text())
    core=deepcopy(plan['model_config']);core['synthetic']['noise_sd']=[0.,0.,0.]
    target,_,sd,truth=tak_task_parameter_synthetic(core,dict(subject=1,repeat=0,task='A',scenario='unchanged_parameters'))
    fit,arrays=tak_cache_fit_arrays(core,target,dict(eeg_factor=1.,hb_factor=1.,sd=sd),sd,
        structured=True,observation_weights=plan['weights'][weight])
    result=dict(weight=weight,qualified=fit['qualified'],fits=fit['fits'],shape=list(arrays['prediction'].shape),measured_reads=0)
    _tak_cache_npz(path.with_suffix('.npz'),**arrays,truth_clean=truth['clean']);write_json(path,result);return result


def modality_weight_prepare(cfg,out):
    plan=_weight_so_plan(str(out));parent=Path(plan['parent'])
    if not all(json.loads((out/'dry_run'/(w+'.json')).read_text())['qualified'] for w in cfg['weights']):raise ValueError('Weighted synthetic check first')
    checks=[]
    for row in plan['rows']:
        if row['split']!='validation':raise ValueError('Development boundary before retained arrays')
        case=row['case']
        for category in ('inputs','variants'):
            for suffix in ('.json','.npz'):
                source=parent/category/(case+suffix);dest=out/category/(case+suffix)
                dest.parent.mkdir(parents=True,exist_ok=True)
                if not dest.exists():shutil.copy2(source,dest)
        dest=out/'references'/(row['dataset']+'.npz');dest.parent.mkdir(parents=True,exist_ok=True)
        if not dest.exists():shutil.copy2(parent/'references'/dest.name,dest)
        with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:roi_indices=a['roi_indices'].copy()
        with np.load(out/'variants'/(case+'.npz'),allow_pickle=False) as a:
            for variant in ('baseline','ocular05','ocular1','ocular2'):
                for roi in range(3):
                    key=f'{case}__equal__{variant}__r{roi}';source=parent/'fits'/(key+'.json')
                    fit=json.loads(source.read_text());np.testing.assert_array_equal(fit['observation_weights'],[1,1,1])
                    if not fit['qualified']:raise ValueError('Prespecified eligible source fit unavailable')
                    target=np.column_stack((a['features_'+variant][:,roi_indices[roi]].reshape(900,30)@row['coordinate']['pc'],a['hb_'+variant][:,roi]))
                    with np.load(source.with_suffix('.npz'),allow_pickle=False) as z:
                        np.testing.assert_allclose(target,z['target'],rtol=0,atol=1e-12)
                        np.testing.assert_allclose(z['sd_subject']*z['scale'],row['coordinate']['sd'],rtol=1e-12,atol=1e-12)
                    for suffix in ('.json','.npz'):
                        dest=out/'fits'/(key+suffix);dest.parent.mkdir(parents=True,exist_ok=True)
                        if not dest.exists():shutil.copy2(source.with_suffix(suffix),dest)
                    checks.append(dict(case=case,variant=variant,roi=roi,source=str(source),matched=True))
        dest=out/'targets'/case/'equal'
        if not dest.exists():shutil.copytree(parent/'targets'/case/'equal',dest)
    result=dict(status='passed',retained_fit_checks=len(checks),checks=checks,source=str(parent),new_raw_reads=0)
    write_json(out/'reuse_verification.json',result);return result


def modality_weight_delta_metrics(y0,p0,y1,p1,sd,cfg):
    arrays=[np.asarray(v,float) for v in (y0,p0,y1,p1)]
    if any(a.shape!=(900,3) or not np.isfinite(a).all() for a in arrays):raise ValueError('Finite 900x3 source and prediction arrays required')
    sd=np.asarray(sd,float)
    if sd.shape!=(3,) or np.any(sd<=0):raise ValueError('Frozen positive three-component SD required')
    delta=(arrays[3]-arrays[1])/sd;observed=(arrays[2]-arrays[0])/sd;result={}
    support=lambda name:slice(*(round(t*10) for t in cfg['screen'][name+'_support_s']))
    for j,name in enumerate(('EEG','HbO','HbR')):
        result[name+'_change']=float(np.sqrt(np.mean(delta[support('primary'),j]**2)))
        result[name+'_baseline_NRMSE']=float(np.sqrt(np.mean(((p0[:-1,j]-y0[:-1,j])/sd[j])**2)))
        for period in ('early','late','outside'):
            d=delta[support(period),j];result[name+'_'+period+'_mean']=float(d.mean())
            result[name+'_'+period+'_RMS']=float(np.sqrt(np.mean(d*d)))
        d=delta[support('primary'),j];result[name+'_positive_peak']=float(max(0,d.max()));result[name+'_negative_peak']=float(min(0,d.min()))
    numerator=np.linalg.norm(delta[support('primary'),0]);den=np.linalg.norm(observed[support('primary'),0])
    result['proxy_transfer_ratio']=float(numerator/den) if np.sqrt(np.mean(observed[support('primary'),0]**2))>cfg['screen']['proxy_transfer_denominator_min_SD'] else None
    return result


def modality_weight_select(aggregate,datasets,counts,cfg,paired_baselines=None):
    rule=cfg['selection_rule'];base=aggregate.set_index('weight').loc['equal'];dsbase=datasets[datasets.weight=='equal'].set_index('dataset')
    rows=[]
    for weight in rule['candidate_order_nearest_equal']:
        value=aggregate.set_index('weight').loc[weight];each=datasets[datasets.weight==weight].set_index('dataset')
        matched=(paired_baselines or {}).get(weight,{});change_base=matched.get('aggregate',base);change_ds=matched.get('datasets',dsbase)
        gates=dict(HbO_reduction=value.HbO_change<=change_base.HbO_change*(1-rule['minimum_HbO_change_reduction']),
            HbR_nonincrease=value.HbR_change<=change_base.HbR_change+1e-12,
            proxy_nonincrease=value.EEG_change<=change_base.EEG_change+1e-12,
            baseline_fidelity=all(value[c+'_baseline_NRMSE']<=base[c+'_baseline_NRMSE']+rule['maximum_baseline_NRMSE_increase_each_component'] for c in ('EEG','HbO','HbR')),
            voltage_fidelity=value.EEG_S_correlation>=base.EEG_S_correlation-rule['maximum_EEG_S_baseline_correlation_decrease'],
            complete=counts[weight]['qualified_fits']==36 and counts[weight]['qualified_targets']==12,
            each_dataset_HbO=bool((each.HbO_change<change_ds.HbO_change).all()))
        rows.append(dict(weight=weight,passes=all(gates.values()),checks={k:bool(v) for k,v in gates.items()},
            HbO_reduction=float(1-value.HbO_change/change_base.HbO_change),proxy_reduction=float(1-value.EEG_change/change_base.EEG_change),
            paired_qualified_ROIs=matched.get('ROIs',18),
            matched_baseline_changes={c:float(change_base[c+'_change']) for c in ('EEG','HbO','HbR')},
            baseline_NRMSE_deltas={c:float(value[c+'_baseline_NRMSE']-base[c+'_baseline_NRMSE']) for c in ('EEG','HbO','HbR')}))
    candidate=next((r['weight'] for r in rows if r['passes']),None)
    return dict(candidate=candidate,candidates=rows,status='candidate_selected' if candidate else 'stop_no_candidate',
        continuation_required=candidate is not None,rule=rule)


def modality_weight_analyze(cfg,out):
    plan=_weight_so_plan(str(out));rows=[r for r in plan['rows'] if r['panel']=='screen'];metrics=[];fits=[];target_rows=[];mechanism=[]
    counts={w:dict(qualified_fits=0,qualified_targets=0) for w in cfg['weights']}
    for row in rows:
        case=row['case']
        for weight in cfg['weights']:
            records=[];arrays=[]
            for variant in cfg['screen']['variants']:
                for roi in range(3):
                    key=f'{case}__{weight}__{variant}__r{roi}';record=json.loads((out/'fits'/(key+'.json')).read_text())
                    fits.append(dict(case=case,dataset=row['dataset'],subject=row['subject'],weight=weight,variant=variant,roi=roi,qualified=record['qualified'],status=record['status']))
                    counts[weight]['qualified_fits']+=int(record['qualified'])
                target=json.loads((out/'targets'/case/weight/(variant+'.json')).read_text())
                counts[weight]['qualified_targets']+=int(target['qualified']);target_rows.append({k:v for k,v in dict(target,condition='full').items() if k!='fits'})
                frozen=json.loads((out/'targets_frozen'/case/weight/(variant+'.json')).read_text());target_rows.append({k:v for k,v in dict(frozen,condition='frozen').items() if k!='fits'})
            for roi in range(3):
                pair=[]
                for variant in cfg['screen']['variants']:
                    path=out/'fits'/f'{case}__{weight}__{variant}__r{roi}.json';record=json.loads(path.read_text())
                    with np.load(path.with_suffix('.npz'),allow_pickle=False) as a:pair.append((record,{k:a[k].copy() for k in a.files}))
                result=dict(case=case,dataset=row['dataset'],subject=row['subject'],weight=weight,roi=roi,qualified=all(r['qualified'] for r,a in pair))
                f0,a0=pair[0]
                if f0['qualified']:
                    for j,name in enumerate(('EEG','HbO','HbR')):
                        result[name+'_baseline_NRMSE']=float(np.sqrt(np.mean(((a0['prediction'][:-1,j]-a0['target'][:-1,j])/a0['sd_subject'][j])**2)))
                if result['qualified']:
                    (f0,a0),(f1,a1)=pair;np.testing.assert_array_equal(a0['target'][:,1:],a1['target'][:,1:]);np.testing.assert_array_equal(a0['sd_subject'],a1['sd_subject'])
                    result.update(modality_weight_delta_metrics(a0['target'],a0['prediction'],a1['target'],a1['prediction'],a0['sd_subject'],cfg))
                    for param in ('tau','beta'):
                        result[param+'_before']=f0['fits']['tak_tau_beta'][param];result[param+'_after']=f1['fits']['tak_tau_beta'][param]
                    d=result['beta_after']*a1['driver']-result['beta_before']*a0['driver']
                    result['vascular_drive_change']=float(np.sqrt(np.mean(d[300:850]**2))/row['coordinate']['sd'][0])
                metrics.append(result)
            full=out/'targets'/case/weight;frozen=out/'targets_frozen'/case/weight
            if all(json.loads((d/(v+'.json')).read_text())['qualified'] for d in (full,frozen) for v in cfg['screen']['variants']):
                with np.load(full/'baseline.npz') as a:s0=a['s_display'].copy()
                with np.load(frozen/'baseline.npz') as a:np.testing.assert_allclose(s0,a['s_display'],rtol=0,atol=1e-10)
                with np.load(full/'ocular1.npz') as a:ds=a['delta_s_display'][6000:10000].copy()
                with np.load(frozen/'ocular1.npz') as a:df=a['delta_s_display'][6000:10000].copy()
                from scipy.signal import resample_poly
                with np.load(out/'inputs'/(case+'.npz')) as a:rate=int(a['rate'])
                with np.load(out/'variants'/(case+'.npz')) as a:n=resample_poly(a['delta_eeg_ocular1'],200,rate,axis=0)[6000:10000]
                mechanism.append(dict(case=case,dataset=row['dataset'],subject=row['subject'],weight=weight,display_rate=200,
                    full_change=float(np.linalg.norm(ds)/np.linalg.norm(n)),frozen_change=float(np.linalg.norm(df)/np.linalg.norm(n)),
                    reference_update=float(np.linalg.norm(ds-df)/np.linalg.norm(n))))
    frame=pd.DataFrame(metrics);frame.to_csv(out/'ssm_metrics.csv',index=False);pd.DataFrame(fits).to_csv(out/'fit_status.csv',index=False)
    targets=pd.DataFrame(target_rows);targets.to_csv(out/'target_metrics.csv',index=False);pd.DataFrame(mechanism).to_csv(out/'mechanism_metrics.csv',index=False)
    numeric=[c for c in frame.select_dtypes('number').columns if c!='roi']
    subjects=frame.groupby(['dataset','subject','case','weight'])[numeric].mean().reset_index()
    baseline=targets[(targets.condition=='full')&(targets.variant=='baseline')][['case','weight','baseline_correlation']].rename(columns={'baseline_correlation':'EEG_S_correlation'})
    subjects=subjects.merge(baseline,on=['case','weight'],how='left');subjects.to_csv(out/'subject_metrics.csv',index=False)
    datasets=subjects.groupby(['dataset','weight']).mean(numeric_only=True).reset_index();datasets.to_csv(out/'dataset_metrics.csv',index=False)
    aggregate=datasets.groupby('weight').mean(numeric_only=True).reset_index();aggregate.to_csv(out/'aggregate_metrics.csv',index=False)
    paired_baselines={};paired_rows=[]
    for weight in cfg['weights']:
        keys=frame[(frame.weight==weight)&frame.qualified][['case','roi']]
        common=frame[(frame.weight=='equal')&frame.qualified].merge(keys,on=['case','roi'])
        by_subject=common.groupby(['dataset','subject']).mean(numeric_only=True).reset_index()
        by_dataset=by_subject.groupby('dataset').mean(numeric_only=True);mean=by_dataset.mean()
        paired_baselines[weight]=dict(aggregate=mean,datasets=by_dataset,ROIs=len(common))
        value=aggregate.set_index('weight').loc[weight]
        for c in ('EEG','HbO','HbR'):
            paired_rows.append(dict(weight=weight,component=c,paired_ROIs=len(common),subjects=common.subject.nunique(),
                candidate_change=value[c+'_change'],matched_equal_change=mean[c+'_change'],relative_reduction=1-value[c+'_change']/mean[c+'_change']))
    pd.DataFrame(paired_rows).to_csv(out/'paired_weight_effects.csv',index=False)
    selection=modality_weight_select(aggregate,datasets,counts,cfg,paired_baselines);write_json(out/'selection.json',selection)
    result=dict(schema=cfg['schema'],status='completed' if selection['candidate'] is None else 'screen_completed',subjects=6,records=6,weights=list(cfg['weights']),
        planned_ROI_conditions=144,new_ROI_conditions=108,qualified_ROI_conditions=sum(v['qualified_fits'] for v in counts.values()),
        counts=counts,aggregate=aggregate.to_dict('records'),selection=selection,mechanism_rate_hz=200,
        continuation='pending_candidate_review' if selection['candidate'] else 'not_triggered_by_prespecified_stopping_rule',
        new_raw_reads=0,production_cache_changed=False,
        support_policy='Changes use qualified pairs; comparisons match equal-weight ROI support per candidate. Baseline fidelity uses all qualified baseline fits independently of perturbed convergence. Failures always disqualify a candidate.')
    write_json(out/'summary.json',result);return result


def modality_weight_verify(cfg,out):
    plan=_weight_so_plan(str(out));tasks=json.loads((out/'fit_plan.json').read_text())['tasks'];objective_errors=[];target_errors=[];scale_errors=[]
    for row in [r for r in plan['rows'] if r['panel']=='screen']:
        with np.load(out/'inputs'/(row['case']+'.npz'),allow_pickle=False) as a:indices=a['roi_indices'].copy()
        with np.load(out/'variants'/(row['case']+'.npz'),allow_pickle=False) as a:
            targets={}
            for variant in cfg['screen']['variants']:
                np.testing.assert_array_equal(a['hb_'+variant],a['hb_baseline'])
                for roi in range(3):targets[variant,roi]=np.column_stack((a['features_'+variant][:,indices[roi]].reshape(900,30)@row['coordinate']['pc'],a['hb_'+variant][:,roi]))
        for task in [t for t in tasks if t['case']==row['case']]:
            key=f"{task['case']}__{task['weight']}__{task['variant']}__r{task['roi']}";rec=json.loads((out/'fits'/(key+'.json')).read_text())
            weights=np.array(plan['weights'][task['weight']]);np.testing.assert_array_equal(rec['observation_weights'],weights)
            with np.load(out/'fits'/(key+'.npz'),allow_pickle=False) as a:
                target_errors.append(float(np.max(abs(a['target']-targets[task['variant'],task['roi']]))))
                scale_errors.append(float(np.max(abs(a['sd_subject']*a['scale']-row['coordinate']['sd']))))
                for arm,field in [('tak_fixed','fixed_prediction'),('tak_tau_beta','prediction')]:
                    if field not in a:continue
                    solver=rec['fits'][arm]['solver'];value=solver['data_weight']*float(np.sum(weights*((a[field][:-1]-a['target'][:-1])/a['sd_subject'])**2))
                    objective_errors.append(abs(value-solver['objective_components']['data']))
    targets=pd.read_csv(out/'target_metrics.csv');qualified=targets[targets.qualified]
    result=dict(status='passed',fit_input_checks=len(tasks),objective_arm_checks=len(objective_errors),
        observation_max_abs=max(target_errors),scale_max_abs=max(scale_errors),weighted_data_objective_max_abs=max(objective_errors),
        EEG_closure_max_abs=float(qualified.EEG_closure_max_abs.max()),Hb_closure_max_abs=float(qualified.Hb_closure_max_abs.max()),
        Hb_observations_identical=True,source_equal_fits_reused=True,new_raw_reads=0)
    if max(target_errors)>1e-10 or max(scale_errors)>1e-10 or max(objective_errors)>1e-7:raise ValueError('Weighted fit readout verification failed: '+str(result))
    write_json(out/'verification.json',result);return result


def modality_weight_report(cfg,out):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    from scipy.signal import resample_poly
    from html import escape
    plan=_weight_so_plan(str(out));summary=json.loads((out/'summary.json').read_text())
    folder=out/'report';folder.mkdir(exist_ok=True);subjects=pd.read_csv(out/'subject_metrics.csv')
    datasets=pd.read_csv(out/'dataset_metrics.csv');aggregate=pd.read_csv(out/'aggregate_metrics.csv');metrics=pd.read_csv(out/'ssm_metrics.csv')
    labels={w:':'.join(map(str,cfg['weights'][w])) for w in cfg['weights']};weights=list(cfg['weights']);figures=[];case_tables=[]
    names=dict(eeg_fnirs_single_trial='Single-Trial',simultaneous_eeg_nirs='Simultaneous',refed='REFED',visual_cognitive_motivation='Visual')
    for row in [r for r in plan['rows'] if r['panel']=='screen']:
        case=row['case'];meta=json.loads((out/'variants'/(case+'.json')).read_text());electrode=meta['electrode']
        with np.load(out/'inputs'/(case+'.npz'),allow_pickle=False) as a:base={k:a[k].copy() for k in a.files}
        rate=int(base['rate']);roi=next(i for i in range(3) if electrode in base['roi_indices'][i]);sd=np.asarray(row['coordinate']['sd'])/np.array([row['coordinate']['eeg_factor'],row['coordinate']['hb_factor'],row['coordinate']['hb_factor']])
        with np.load(out/'variants'/(case+'.npz'),allow_pickle=False) as a:n=resample_poly(a['delta_eeg_ocular1'][:,electrode],200,rate)
        x=resample_poly(base['x'][:,electrode],200,rate);time=np.arange(len(x))/200;ht=np.arange(900)/10;outputs={};ssm={}
        for weight in weights:
            for variant in ('baseline','ocular1'):
                key=f'{case}__{weight}__{variant}__r{roi}';rec=json.loads((out/'fits'/(key+'.json')).read_text())
                if rec['qualified']:
                    with np.load(out/'fits'/(key+'.npz'),allow_pickle=False) as a:ssm[weight,variant]={k:a[k].copy() for k in ('target','prediction')}
                for condition,root in [('full','targets'),('frozen','targets_frozen')]:
                    dest=out/root/case/weight;rec=json.loads((dest/(variant+'.json')).read_text())
                    if rec['qualified']:
                        with np.load(dest/(variant+'.npz'),allow_pickle=False) as a:outputs[weight,variant,condition]={k:a[k].copy() for k in ('s_display','delta_s_display')}
        fig,axes=plt.subplots(6,4,figsize=(19,18),sharex='col',sharey='row',layout='constrained')
        for col,weight in enumerate(weights):
            axes[0,col].set_title('EEG:HbO:HbR = '+labels[weight],fontsize=12)
            ax=axes[0,col];ax.plot(time,x,color='#1764ab',lw=.65,label='Original EEG');ax.plot(time,x+n,color='#d54b22',lw=.65,label='EEG + added EOG')
            for j in range(3):
                ax=axes[j+1,col]
                if (weight,'baseline') not in ssm or (weight,'ocular1') not in ssm:
                    ax.text(.5,.5,'Unqualified SSM',ha='center',transform=ax.transAxes);continue
                a,b=ssm[weight,'baseline'],ssm[weight,'ocular1']
                ax.plot(ht,a['target'][:,j],color='#727b83',ls=':',lw=.85,label='Observed before' if j==0 else 'Measured Hb (same input)')
                if j==0:ax.plot(ht,b['target'][:,j],'k--',lw=.8,label='Observed after')
                ax.plot(ht,a['prediction'][:,j],color='#1764ab',lw=.95,label='SSM before')
                ax.plot(ht,b['prediction'][:,j],color='#d54b22',lw=.95,label='SSM after')
            if all((weight,v,'full') in outputs for v in ('baseline','ocular1')):
                a=outputs[weight,'baseline','full']['s_display'][:,electrode];b=outputs[weight,'ocular1','full']['s_display'][:,electrode]
                for j,v0,v1 in [(4,a,b),(5,x-a,x+n-b)]:
                    axes[j,col].plot(time,v0,color='#1764ab',lw=.75,label='Before injection');axes[j,col].plot(time,v1,color='#d54b22',lw=.75,label='After injection')
            else:
                for j in (4,5):axes[j,col].text(.5,.5,'Unqualified voltage target',ha='center',transform=axes[j,col].transAxes)
        for j,label in enumerate(['Input EEG / '+str(base['unit']),'SSM EEG proxy / log-power PC','SSM HbO / cached native unit','SSM HbR / cached native unit','EEG-S / '+str(base['unit']),'EEG-O / '+str(base['unit'])]):
            axes[j,0].set_ylabel(label)
            lo,hi=axes[j,0].get_ylim();axes[j,0].set_ylim(lo,hi+.3*(hi-lo))
            for ax in axes[j]:
                ax.axvspan(30,50,color='#efcf91',alpha=.18);ax.grid(alpha=.2);ax.set_xlim(0,90)
                if ax.get_legend_handles_labels()[0]:ax.legend(fontsize=7.5,loc='upper right',ncol=2)
        for ax in axes[-1]:ax.set_xlabel('Time in 90 s window / s')
        fig.suptitle(f"{names[row['dataset']]} | {row['subject']} | {row['record_plan']['record']} | {row['window']['key']}\nEEG {base['channels'][electrode]}, Hb {row['pairs'][roi]['id']}; identical 1 x EOG input across weights; full-window refit. Shared axes across columns, independent axes across rows.",fontsize=12)
        name=case+'_waveforms.png';fig.savefig(folder/name,dpi=180);plt.close(fig);figures.append(name)
        fig,axes=plt.subplots(5,4,figsize=(19,14),sharex='col',sharey='row',layout='constrained')
        sl=slice(6000,17000);hs=slice(300,850);q=float(np.sqrt(np.mean(n[6000:10000]**2)))
        for col,weight in enumerate(weights):
            axes[0,col].set_title(labels[weight])
            if (weight,'baseline') in ssm and (weight,'ocular1') in ssm:
                a,b=ssm[weight,'baseline'],ssm[weight,'ocular1'];delta=(b['prediction']-a['prediction'])/sd
                axes[0,col].plot(ht[hs],((b['target']-a['target'])/sd)[hs,0],'k--',lw=.8,label='Observed proxy change')
                for j in range(3):
                    if j:axes[j,col].axhline(0,color='k',ls='--',lw=.8,label='Measured Hb change = 0')
                    axes[j,col].plot(ht[hs],delta[hs,j],color='#d54b22',lw=1,label='SSM prediction change')
            else:
                for j in range(3):axes[j,col].text(.5,.5,'Unqualified SSM',ha='center',transform=axes[j,col].transAxes)
            if all((weight,'ocular1',c) in outputs for c in ('full','frozen')):
                ds=outputs[weight,'ocular1','full']['delta_s_display'][sl,electrode]
                df=outputs[weight,'ocular1','frozen']['delta_s_display'][sl,electrode]
                axes[3,col].plot(time[sl],n[sl]/q,'k--',lw=.8,label='Known EOG addition')
                axes[3,col].plot(time[sl],ds/q,color='#d54b22',lw=1,label='Full pipeline delta S')
                axes[3,col].plot(time[sl],df/q,color='#7952a8',ls=':',lw=1,label='Frozen reference delta S')
                axes[4,col].plot(time[sl],n[sl]/q,'k--',lw=.8,label='Known EOG addition')
                axes[4,col].plot(time[sl],(n[sl]-ds)/q,color='#d54b22',lw=1,label='EEG delta O')
        for j,label in enumerate(['SSM proxy change / frozen SD','HbO-S change / frozen SD','HbR-S change / frozen SD','EEG-S change / local EOG RMS','EEG-O change / local EOG RMS']):
            axes[j,0].set_ylabel(label);lo,hi=axes[j,0].get_ylim();axes[j,0].set_ylim(lo,hi+.3*(hi-lo))
            for ax in axes[j]:
                ax.axvspan(30,50,color='#efcf91',alpha=.18);ax.grid(alpha=.2);ax.set_xlim(30,85)
                if ax.get_legend_handles_labels()[0]:ax.legend(fontsize=7.5,loc='upper right')
        for ax in axes[-1]:ax.set_xlabel('Time in window / s')
        fig.suptitle(f"{names[row['dataset']]} | {row['subject']} — model response versus voltage construction\nShaded: EOG input [30,50) s. Score model change over [30,85) s; Hb observations unchanged.",fontsize=12)
        name=case+'_changes.png';fig.savefig(folder/name,dpi=180);plt.close(fig);figures.append(name)
        case_tables.append((row,subjects[subjects.case==case],metrics[(metrics.case==case)&(metrics.roi==roi)]))
    common_keys=metrics.groupby(['case','roi']).qualified.all();common_keys=common_keys[common_keys].reset_index()[['case','roi']]
    common=metrics.merge(common_keys,on=['case','roi'])
    change_cols=[c+'_change' for c in ('EEG','HbO','HbR')]
    common_datasets=common.groupby(['dataset','subject','weight'])[change_cols].mean().groupby(['dataset','weight']).mean().reset_index()
    common_aggregate=common_datasets.groupby('weight')[change_cols].mean().reset_index()
    common_datasets.to_csv(out/'common_support_change_metrics.csv',index=False)
    for filename,suffix,title in [('summary_ssm.png','_change','SSM change / frozen subject SD'),('summary_fidelity.png','_baseline_NRMSE','Baseline NRMSE / frozen subject SD')]:
        plot_datasets=common_datasets if suffix=='_change' else datasets
        plot_aggregate=common_aggregate if suffix=='_change' else aggregate
        fig,axes=plt.subplots(1,3,figsize=(14,4.5),layout='constrained')
        for ax,component in zip(axes,('EEG','HbO','HbR')):
            for ds in cfg['subjects']:
                values=plot_datasets[plot_datasets.dataset==ds].set_index('weight').loc[weights,component+suffix]
                ax.plot(np.arange(4),values,marker='o',lw=1,label=names[ds])
            ax.plot(np.arange(4),plot_aggregate.set_index('weight').loc[weights,component+suffix],'k--s',lw=2,label='Equal-dataset mean')
            ax.set_xticks(np.arange(4),[labels[w] for w in weights]);ax.set_xlabel('EEG:HbO:HbR weights');ax.set_title(component);ax.set_ylabel(title);ax.grid(alpha=.2)
        axes[-1].legend(fontsize=8)
        if suffix=='_change':fig.suptitle(f'Common support across all weights: {len(common_keys)} ROI pairs, 6 subjects. The missing Hb2 fit remains a failure.',fontsize=10)
        else:fig.suptitle('Baseline fidelity: all 18 qualified baseline ROIs per weight, 6 subjects.',fontsize=10)
        fig.savefig(folder/filename,dpi=200);plt.close(fig)
    mechanism=pd.read_csv(out/'mechanism_metrics.csv');m=mechanism.groupby(['dataset','weight']).mean(numeric_only=True).groupby('weight').mean().reset_index()
    m.to_csv(out/'mechanism_summary.csv',index=False)
    native=pd.read_csv(out/'target_metrics.csv');native=native[native.variant=='ocular1']
    valid_keys=native[native.qualified].groupby(['case','weight']).condition.nunique()
    valid_keys=valid_keys[valid_keys==2].reset_index()[['case','weight']];native=native.merge(valid_keys,on=['case','weight'])
    native_summary=native.groupby(['dataset','weight','condition'])[['noise_error','O_delta_correlation','O_signed_gain','S_pair_correlation','S_change_relative_baseline']].mean().groupby(['weight','condition']).mean().reset_index()
    native_summary.to_csv(out/'voltage_summary.csv',index=False)
    display_cols=['weight','EEG_change','HbO_change','HbR_change','EEG_baseline_NRMSE','HbO_baseline_NRMSE','HbR_baseline_NRMSE','EEG_S_correlation']
    html='<html><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1800px;margin:auto;padding:24px;line-height:1.65}img{width:100%}table{border-collapse:collapse}td,th{border:1px solid #aaa;padding:6px}p{max-width:1500px}</style><h1>τ/β 可调：EEG 与 fNIRS 优化权重对照</h1>'
    html+='<p>六名被试、四库、每人第一记录的一段90秒窗口、三个ROI。相同实测VEOG派生眼电按额前较强模板加入原生EEG，强度为原窗口RMS的1倍；Hb输入逐点相同。权重顺序为EEG/HbO/HbR，总和归一为3。PCA、尺度、原SD、先验、起点及功率上限均冻结；每权重/每条件独立拟合驱动、初态、τ、β。等权同源结果核验后复用，新增108个ROI条件。所有数据均来自已保留的公开开发样本，不是未见被试确认。</p>'
    html+='<p>主终点为SSM预测的注入后减注入前之RMS/冻结被试SD，使用[30,85)秒，分开看EEG代理、HbO、HbR。基线NRMSE使用相同冻结SD；越低表示与未注入观测越接近，不是干净神经真值。先三个ROI在被试内平均，再各库被试等权、最后四库等权。Visual及REFED本面板各一名被试。EEG-S电压层另外评分，避免把后处理稳定性等同于SSM稳定性。</p>'
    html+='<p>本轮支持的方向是：提高fNIRS相对权重能减少眼电传向HbO/HbR-S，但会增加未注入EEG代理的观测重建误差。偏重EEG具有相反取舍。较小的眼电响应与较好的原始观测拟合应分别判断；当前没有一组候选满足全部预设护栏。</p>'
    html+='<h2>SSM 主结果与基线保真</h2><p>1:2:2 的VP017第三ROI污染拟合未收敛，其变化统计只有17个合格ROI配对；其他权重各18个。基线保真独立使用各权重全部18个合格基线，不因污染拟合失败而删除基线。下表绝对变化均值须结合该支持差异阅读；相对改善使用与每个候选相同ROI集合的等权基线，见配对效应表。失败使1:2:2不具备通过筛查的资格，成功子集不能覆盖失败。</p>'+aggregate[display_cols].to_html(index=False,float_format=lambda x:f'{x:.5f}')
    html+='<h3>相同ROI支持下的配对效应</h3>'+pd.read_csv(out/'paired_weight_effects.csv').to_html(index=False,float_format=lambda x:f'{x:.5f}')+'<p>以下变化概览图统一使用四组都合格的17个ROI配对，使各条权重曲线逐点可比；不把该共同成功子集当作完整合格证据。基线保真图使用每组全部18个合格基线ROI。</p><img src="summary_ssm.png"><img src="summary_fidelity.png">'
    selection=summary['selection'];gate_rows=[]
    for rec in selection['candidates']:gate_rows.append(dict(weight=rec['weight'],passes=rec['passes'],HbO_reduction_fraction=rec['HbO_reduction'],**rec['checks']))
    html+='<h2>预设筛查与后续序列</h2>'+pd.DataFrame(gate_rows).to_html(index=False,float_format=lambda x:f'{x:.4f}')
    html+='<p>'+('候选为 '+str(selection['candidate'])+'；后续复核状态以主运行summary为准。' if selection['candidate'] else '没有权重同时满足预设约束，按计划停止候选扩展；第二记录、其他强度、反向Hb扰动及候选合成阳性复核未触发。保留全部负结果，不调整阈值或扩大权重网格。')+'</p>'
    html+='<h2>电压目标与冻结参考机制对照</h2>'+native_summary.to_html(index=False,float_format=lambda x:f'{x:.5f}')
    html+='<p>上表是原生采样率[30,50)秒的指标。full用污染后SSM代理提供参考；frozen用同权重注入前代理提供参考，输入仍包含同一眼电。两条路径使用同一批合格窗口：1:2:2为5窗，其余各6窗，不能将未配对失败排除后宣称整批合格。下面参考更新量以200Hz显示数组计算，为||ΔS_full−ΔS_frozen||/||眼电||，不与原生评分混用。O=X−S，O增量不是第二份独立成功证据。</p>'+m[['weight','full_change','frozen_change','reference_update']].to_html(index=False,float_format=lambda x:f'{x:.5f}')
    for row,table,params in case_tables:
        html+='<h2>'+escape(names[row['dataset']]+' / '+row['subject']+' / '+row['record_plan']['record'])+'</h2>'
        html+='<p>主图六行依次为原始/注入后EEG、SSM EEG代理、SSM HbO、SSM HbR、EEG-S、EEG-O。蓝为注入前，橙为注入后；SSM面板灰/黑虚线为观测。Hb只画一条相同的实测输入。每列一个权重，同一行跨权重共用坐标；不同行独立纵轴，单位写在左侧。波形展示最前部选定电极及包含该电极的ROI，下面数值表为三个ROI平均。</p>'
        html+=table[display_cols].to_html(index=False,float_format=lambda x:f'{x:.5f}')
        local=table.set_index('weight')
        html+=f"<p>该被试三个ROI平均：HbO预测变化从等权的 {local.loc['equal','HbO_change']:.4f} 降至1:4:4的 {local.loc['hb4','HbO_change']:.4f} 个SD；与此同时，基线EEG代理NRMSE从 {local.loc['equal','EEG_baseline_NRMSE']:.4f} 升至 {local.loc['hb4','EEG_baseline_NRMSE']:.4f}。下图用于查看这种稳定性与观测拟合的取舍。</p>"
        if row['subject']=='VP017':html+='<p>本被试1:2:2的第三ROI污染拟合未收敛；图中前部ROI的合格SSM输出仍展示，完整EEG-S/O目标因依赖三个ROI而留空。1:2:2的变化均值仅含两个合格ROI，不能掩盖失败。</p>'
        html+='<img src="'+row['case']+'_waveforms.png"><p>下图分开显示SSM响应与电压构建响应；紫点线是冻结代理参考的EEG-S变化，黑虚线是已知注入或不变Hb。眼电区间结束后的变化也保留。</p><img src="'+row['case']+'_changes.png">'
        html+='<p>本图ROI的τ/β注入前后值（每个90秒窗口为常数）：</p>'+params[['weight','tau_before','tau_after','beta_before','beta_after']].to_html(index=False,float_format=lambda x:f'{x:.5f}')
    html+='<p>事实源位于上一级：summary.json、selection.json、ssm_metrics.csv、subject_metrics.csv、dataset_metrics.csv、aggregate_metrics.csv、target_metrics.csv、mechanism_metrics.csv、fit_status.csv、reuse_verification.json。原始缓存和已保留报告未修改。</p></html>'
    for code,label in labels.items():html=html.replace('>'+code+'<','>'+label+'<')
    (folder/'report.html').write_text(html)
    result=dict(status='completed',subjects=6,subject_waveform_figures=6,subject_change_figures=6,overview_figures=2,figures=figures,
        source_summary=str(out/'summary.json'),new_fits=0,SSM_score_support_s=[30,85],voltage_score_support_s=[30,50])
    write_json(folder/'export.json',result);return result


def modality_weight_parameter_review(cfg,out):
    """Paired sensitivity of retained parameter estimates; no new fitting."""
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plan=_weight_so_plan(str(out));folder=out/'parameter_review_v1'
    if folder.exists():raise ValueError('Retain the existing parameter export; use a versioned export for revisions')
    folder.mkdir();records=[];weights=list(cfg['weights']);labels={w:':'.join(map(str,cfg['weights'][w])) for w in weights}
    for row in [r for r in plan['rows'] if r['panel']=='screen']:
        for roi in range(3):
            for weight in weights:
                pair=[json.loads((out/'fits'/f"{row['case']}__{weight}__{v}__r{roi}.json").read_text()) for v in ('baseline','ocular1')]
                rec=dict(case=row['case'],dataset=row['dataset'],subject=row['subject'],roi=roi,site=row['pairs'][roi]['id'],weight=weight,
                    qualified=all(f['fits']['tak_tau_beta']['qualified'] for f in pair))
                for param in ('tau','beta'):
                    before=pair[0]['fits']['tak_tau_beta'];after=pair[1]['fits']['tak_tau_beta']
                    rec[param+'_before']=before[param] if before['qualified'] else np.nan
                    rec[param+'_after']=after[param] if after['qualified'] else np.nan
                    rec[param+'_delta']=rec[param+'_after']-rec[param+'_before']
                    rec[param+'_abs_delta']=abs(rec[param+'_delta'])
                    rec[param+'_relative_pct']=100*rec[param+'_delta']/rec[param+'_before']
                    rec[param+'_abs_relative_pct']=abs(rec[param+'_relative_pct'])
                records.append(rec)
    frame=pd.DataFrame(records);common=frame.groupby(['case','roi']).qualified.all();keys=common[common].reset_index()[['case','roi']]
    paired=frame.merge(keys,on=['case','roi']);cols=[p+s for p in ('tau','beta') for s in ('_before','_after','_delta','_abs_delta','_relative_pct','_abs_relative_pct')]
    subject=paired.groupby(['dataset','subject','weight'])[cols].mean().reset_index()
    dataset=subject.groupby(['dataset','weight'])[cols].mean().reset_index()
    aggregate=dataset.groupby('weight')[cols].mean().reindex(weights).reset_index()
    count=[]
    for weight in weights:
        values=paired[paired.weight==weight];row=dict(weight=weight,paired_ROIs=len(values))
        for param in ('tau','beta'):
            row[param+'_increase_count']=int((values[param+'_delta']>0).sum());row[param+'_decrease_count']=int((values[param+'_delta']<0).sum())
            row[param+'_max_abs_relative_pct']=float(values[param+'_abs_relative_pct'].max())
        count.append(row)
    aggregate=aggregate.merge(pd.DataFrame(count),on='weight');hb4=frame[(frame.weight=='hb4')&frame.qualified]
    hb4subjects=hb4.groupby(['dataset','subject'])[cols].mean().reset_index()
    frame.to_csv(folder/'parameters_by_ROI.csv',index=False);aggregate.to_csv(folder/'common17_summary.csv',index=False)
    subject.to_csv(folder/'common17_subjects.csv',index=False);hb4subjects.to_csv(folder/'hb4_all18_subjects.csv',index=False)
    fig,axes=plt.subplots(1,2,figsize=(11,4.5),layout='constrained')
    for ax,param,title in zip(axes,('tau','beta'),('Transit time tau','Neurovascular gain beta')):
        ax.bar(np.arange(4),aggregate[param+'_abs_relative_pct'],color=['#d77b36','#6d7680','#528fc1','#27664f'],width=.65)
        for i,value in enumerate(aggregate[param+'_abs_relative_pct']):ax.text(i,value,f'{value:.2f}%',ha='center',va='bottom')
        ax.set_xticks(np.arange(4),[labels[w] for w in weights]);ax.set_xlabel('EEG:HbO:HbR weights');ax.set_ylabel('Mean absolute paired change / %');ax.set_title(title)
        ax.set_ylim(0,float(aggregate[param+'_abs_relative_pct'].max())*1.2);ax.grid(axis='y',alpha=.2)
    fig.suptitle('Same 17 qualified ROI pairs; ROI means within subject, subjects within dataset, then equal four datasets.',fontsize=10)
    fig.savefig(folder/'parameter_sensitivity.png',dpi=220);plt.close(fig)
    order=list(dict.fromkeys((r['case'],r['roi']) for r in records));row_labels=[]
    names=dict(eeg_fnirs_single_trial='Single',simultaneous_eeg_nirs='Sim',refed='REFED',visual_cognitive_motivation='Visual')
    for case,roi in order:
        rec=frame[(frame.case==case)&(frame.roi==roi)].iloc[0];row_labels.append(f"{names[rec.dataset]} {rec.subject} / {rec.site}")
    fig,axes=plt.subplots(1,2,figsize=(14,11),sharey=True,layout='constrained')
    for ax,param in zip(axes,('tau','beta')):
        matrix=frame.pivot(index=['case','roi'],columns='weight',values=param+'_relative_pct').reindex(pd.MultiIndex.from_tuples(order)).reindex(columns=weights).to_numpy()
        maximum=float(np.nanmax(abs(matrix)));palette=plt.get_cmap('RdBu_r').copy();palette.set_bad('#c7c7c7')
        im=ax.imshow(np.ma.masked_invalid(matrix),aspect='auto',cmap=palette,vmin=-maximum,vmax=maximum)
        for i in range(len(order)):
            for j in range(4):
                value=matrix[i,j];ax.text(j,i,'FAIL' if not np.isfinite(value) else f'{value:+.1f}',ha='center',va='center',fontsize=8,
                    color='white' if np.isfinite(value) and abs(value)>.6*maximum else 'black')
        ax.set_xticks(np.arange(4),[labels[w] for w in weights]);ax.set_yticks(np.arange(len(order)),row_labels,fontsize=8)
        ax.set_title(param+' : 100 x (after / before - 1)');fig.colorbar(im,ax=ax,label='Paired parameter change / %',shrink=.8)
    fig.suptitle('All 18 planned ROI locations. Grey = unqualified fit; summary uses common 17. Separate color scales for tau and beta.',fontsize=10)
    fig.savefig(folder/'parameter_changes_by_ROI.png',dpi=220);plt.close(fig)
    result=dict(status='completed',source_fits=str(out/'fits'),new_fits=0,planned_ROI_pairs_each_weight=18,common_qualified_ROI_pairs=17,
        subjects=6,aggregation='Mean absolute/relative changes per ROI, then subject, then dataset, then equal four datasets',
        relative_change_definition='100*(after-before)/before within the same weight and ROI',
        mean_absolute_relative_change_definition='Average abs(relative_change); not abs(average signed change)',
        summary=aggregate.to_dict('records'),hb4_subjects_full_18_ROIs=hb4subjects.to_dict('records'),
        failed_pair=frame[~frame.qualified][['case','weight','roi','site']].to_dict('records'))
    write_json(folder/'summary.json',result)
    html='<html><meta charset="utf-8"><style>body{font-family:sans-serif;max-width:1400px;margin:auto;padding:24px;line-height:1.65}img{width:100%}table{border-collapse:collapse}td,th{border:1px solid #aaa;padding:6px}</style><h1>眼电注入对τ、β拟合的影响</h1>'
    html+='<p>直接读取上一轮保留拟合，不重新求解。比较同一权重、同一ROI的注入前后参数。τ以秒为单位，β为本项目模型坐标中的神经血管增益。四配置比较使用共同17个合格ROI配对；1:2:2在VP017/POOz未收敛，不能把该结果当作有效参数。每个参数在一个90秒窗口内为常数，前后差是两次独立条件拟合之差。</p>'
    display=['weight','tau_before','tau_after','tau_abs_delta','tau_abs_relative_pct','beta_before','beta_after','beta_relative_pct','beta_abs_relative_pct']
    html+=aggregate[display].to_html(index=False,float_format=lambda x:f'{x:.5f}')
    html+='<p>相对变化=100×(注入后−注入前)/注入前。绝对变化先在每个ROI取绝对值，再按被试、数据集平均；有符号均值会抵消不同位置的升降。参数均值之比不等于各ROI相对变化的均值。下面热图保留全部位置，包括其他权重下仍合格的VP017/POOz；灰格表示失败。</p><img src="parameter_sensitivity.png"><img src="parameter_changes_by_ROI.png">'
    html+='<h2>1:4:4：全部18个ROI的被试汇总</h2>'+hb4subjects[['dataset','subject','tau_before','tau_after','beta_before','beta_after','tau_abs_relative_pct','beta_abs_relative_pct']].to_html(index=False,float_format=lambda x:f'{x:.5f}')
    html+='<p>本轮β的变化通常大于τ；偏向Hb后，两者的扰动幅度总体减小。1:4:4仍有局部变化：S08的Probe1:CH13 β从0.92557降到0.65877（−28.82%）；最大τ相对变化在subject_14的AF7Fp1，为2.33230→2.41567秒（+3.57%）。变化并非统一向下，REFED及部分Single-Trial位置β会上升。</p>'
    html+='<p>Hb实测未改变，这些前后参数差描述估计对人工EEG污染的敏感性，不是实际生理参数改变。β下降可缓冲更大的估计驱动对血管的作用，但优化也会同时改变驱动、初态和τ，不能把全部抗眼电收益归因于β单独补偿。原参数先验与全部拟合结果保持原样。</p></html>'
    for key,label in labels.items():html=html.replace('>'+key+'<','>'+label+'<')
    (folder/'report.html').write_text(html);return dict(status='completed',export=str(folder),new_fits=0,common_ROI_pairs=17)


def modality_weight_main(args):
    cfg=modality_weight_config(args.config);out=args.run_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    path=out/'resolved_config.json'
    if path.exists() and json.loads(path.read_text())!=cfg:raise ValueError('Frozen modality-weight contract changed')
    write_json(path,cfg);stage=args.modality_weight_stage
    if stage=='plan':result=modality_weight_plan(cfg,out)
    elif stage=='analyze':result=modality_weight_analyze(cfg,out)
    elif stage=='verify':result=modality_weight_verify(cfg,out)
    elif stage=='report':result=modality_weight_report(cfg,out)
    elif stage=='parameters':result=modality_weight_parameter_review(cfg,out)
    else:
        if not os.environ.get('SSM_SYSTEMD_UNIT'):raise ValueError('Durable modality-weight execution required')
        with (out/'controller.lock').open('w') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            if stage=='pilot':
                _tak_cache_pool(_modality_weight_dry,[(str(out),w) for w in cfg['weights']],out=out,phase='modality_weight_dry',workers=4,total=4,structured=True)
            modality_weight_prepare(cfg,out);plan=_weight_so_plan(str(out));tasks=json.loads((out/'fit_plan.json').read_text())['tasks']
            tasks=[t for t in tasks if t['weight']!='equal']
            if stage=='pilot':
                cases={next(r['case'] for r in plan['rows'] if r['panel']=='screen' and r['dataset']==ds) for ds in cfg['subjects']}
                tasks=[t for t in tasks if t['case'] in cases and t['weight']=='hb2' and t['roi']==0]
            result=_tak_cache_pool(_weight_so_fit,[(str(out),t) for t in tasks],out=out,
                phase='modality_weight_pilot' if stage=='pilot' else 'modality_weight_screen_fit',
                workers=cfg['resources']['pilot_workers' if stage=='pilot' else 'fit_workers'],total=len(tasks),structured=True)
            if stage=='screen':
                jobs=[]
                for row in [r for r in plan['rows'] if r['panel']=='screen']:
                    for w in cfg['weights']:
                        if w!='equal':jobs.append((str(out),row['case'],w,dict(variants=cfg['screen']['variants'],audit_interference=True)))
                        jobs.append((str(out),row['case'],w,dict(variants=cfg['screen']['variants'],audit_interference=True,
                            freeze_baseline=True,destination=str(out/'targets_frozen'))))
                _tak_cache_pool(_weight_so_target,jobs,out=out,phase='modality_weight_screen_targets',workers=cfg['resources']['target_workers'],total=len(jobs))
                result=modality_weight_analyze(cfg,out)
    print(json.dumps(serial(result)),flush=True);return result


def so_features_config(path=None):
    owner=CODE_ROOT/'experiments/configs/physiology_semantic_tokenizer/shared_driver_so_physiology_features_v1.yaml'
    cfg=yaml.safe_load(Path(path or owner).read_text())
    if cfg!=yaml.safe_load(owner.read_text()):raise ValueError('Use reviewed S/O physiology feature contract')
    return cfg


def so_features_plan(cfg,out):
    recent=CODE_ROOT/cfg['sources']['recent'];earlier=CODE_ROOT/cfg['sources']['earlier']
    a=_weight_so_plan(str(recent));b=_weight_so_plan(str(earlier))
    if a['model_config']!=b['model_config'] or a['weights']['hb4']!=b['weights']['hb4']:raise ValueError('Model/weight mismatch across retained sources')
    rows=[]
    for source,items in [(recent,[r for r in a['rows'] if r['panel']=='screen']),
                         (earlier,[r for r in b['rows'] if r['split']=='validation']),
                         (earlier,[r for r in b['rows'] if r['split']=='train'])]:
        for row in items:
            if row['split'] not in cfg['boundary']['splits']:raise ValueError('Disallowed split before arrays')
            role='training' if row['split']=='train' else 'evaluation'
            variants=['baseline','ocular1'] if source==recent else ['baseline']
            rows.append(dict(row,artifact_root=str(source),role=role,variants=variants))
    evaluation=[r for r in rows if r['role']=='evaluation'];training=[r for r in rows if r['role']=='training']
    if len(evaluation)!=14 or len(training)!=12 or len({(r['dataset'],r['subject']) for r in evaluation})!=14:
        raise ValueError('Expected independent fourteen-subject retained panel and twelve training references')
    if len({r['case'] for r in rows})!=len(rows):raise ValueError('Duplicate retained case')
    result=dict(schema=cfg['schema'],rows=rows,training_source=str(earlier),recent_source=str(recent),
        model_config=a['model_config'],weights=a['weights']['hb4'],new_raw_reads=0,new_fits=0)
    write_json(out/'plan.json',result);return dict(status='planned',baseline_subjects=14,ocular_subjects=6,training_records=12)


def so_features_reference(cfg,out):
    plan=json.loads((out/'plan.json').read_text());result={}
    for ds in dict.fromkeys(r['dataset'] for r in plan['rows']):
        training=[r for r in plan['rows'] if r['dataset']==ds and r['role']=='training']
        if len(training)!=3 or any(r['split']!='train' for r in training):raise ValueError('Training references only')
        powers=[]
        for row in training:
            with np.load(Path(row['artifact_root'])/'inputs'/(row['case']+'.npz'),allow_pickle=False) as a:powers.append(np.mean(a['hb'][50:850]**2,axis=0))
        with np.load(Path(plan['training_source'])/'references'/(ds+'.npz'),allow_pickle=False) as a:
            eeg=a['voltage_rms'].copy()
            with np.load(Path(plan['recent_source'])/'references'/(ds+'.npz'),allow_pickle=False) as b:
                for key in a.files:np.testing.assert_array_equal(a[key],b[key])
        hb=np.sqrt(np.mean(powers,axis=0))
        if np.any(hb<=0):raise ValueError('Nonpositive training Hb scale')
        result[ds]=dict(eeg_rms=eeg,hb_rms=hb,training_cases=[r['case'] for r in training])
    write_json(out/'analysis_scales.json',result);return result


def _so_features_worker(payload):
    from src.analysis.physiological_patch_features import supervision_signal_features,supervision_spectral_triplet
    from src.data.dual_component_tokenizer import voltage_power_cap_target
    from scipy.signal import resample_poly,butter,sosfiltfilt
    from scipy.stats import kurtosis
    out_string,row=payload;out=Path(out_string);folder=out/'cases'/row['case'];status=folder/'status.json'
    if status.exists():return json.loads(status.read_text())
    if row['split'] not in ('train','validation') or (row['role']=='training' and row['split']!='train'):raise ValueError('Retained development boundary before arrays')
    source=Path(row['artifact_root']);scales=json.loads((out/'analysis_scales.json').read_text())[row['dataset']]
    qe=np.array(scales['eeg_rms']);qh=np.array(scales['hb_rms']);started=time.monotonic();feature_rows=[];spectra={};relations=[];replays=[];identities=[]
    with np.load(source/'inputs'/(row['case']+'.npz'),allow_pickle=False) as a:base={k:a[k].copy() for k in a.files}
    rate=int(base['rate']);channels=base['channels'].astype(str);electrode=0
    if row['role']=='evaluation':
        with np.load(source/'references'/(row['dataset']+'.npz'),allow_pickle=False) as a:model={k:a[k].copy() for k in a.files}
        electrode=json.loads((source/'variants'/(row['case']+'.json')).read_text())['electrode']
    for variant in row['variants']:
        x=base['x'].copy();hb=base['hb'];de=np.zeros_like(x)
        if variant!='baseline':
            with np.load(source/'variants'/(row['case']+'.npz'),allow_pickle=False) as a:
                de=a['delta_eeg_'+variant].copy();np.testing.assert_array_equal(a['hb_'+variant],hb)
            x+=de
        signals={'X':x};hsignals={'X':hb}
        if row['role']=='evaluation':
            predictions=[]
            for roi in range(3):
                pred,_=weight_so_prediction(source/'fits'/f"{row['case']}__hb4__{variant}__r{roi}.json",'tak_tau_beta');predictions.append(pred)
            pred=np.stack(predictions,axis=1)
            voltage=voltage_power_cap_target(x,model,pred[:,:,0],cap=1.,audit_final=True)
            signals.update(S=voltage['s'],O=voltage['o']);hsignals.update(S=pred[:,:,1:],O=hb-pred[:,:,1:])
            with np.load(source/'targets'/row['case']/'hb4'/(variant+'.npz'),allow_pickle=False) as a:
                error=float(np.max(abs(resample_poly(voltage['s'],200,rate,axis=0)-a['s_display'])/qe))
                np.testing.assert_allclose(pred[:,:,1:],a['hb_s'],rtol=0,atol=1e-12)
                np.testing.assert_allclose(hsignals['O'],a['hb_o'],rtol=0,atol=1e-12)
            if error>1e-10:raise ValueError('Native target replay failed')
            replays.append(dict(variant=variant,display_replay_max_training_RMS=error,
                native_closure_max_training_RMS=float(np.max(abs(signals['S']+signals['O']-x)/qe))))
        analyzed={branch:sosfiltfilt(butter(4,[1,45],fs=200,btype='bandpass',output='sos'),resample_poly(value,200,rate,axis=0),axis=0) for branch,value in signals.items()}
        metadata=dict(case=row['case'],dataset=row['dataset'],subject=row['subject'],role=row['role'],split=row['split'],condition=variant,
            source=str(source),native_EEG_rate=rate,EEG_unit=str(base['unit']))
        core_p=[];native_p=[];native_cross=[];core_cross=[]
        for segment,(start,end) in enumerate(((15,35),(35,55),(55,75))):
            sl=slice(start*200,end*200);ns=slice(start*rate,end*rate);blocks={b:v[sl] for b,v in analyzed.items()}
            native_blocks={b:v[ns] for b,v in signals.items()}
            extracted={}
            for branch,value in blocks.items():
                feats,f,p=supervision_signal_features(value,200,'EEG',qe);extracted[branch]=feats
                native=native_blocks[branch];native_mean=native.mean(0);native_sd=native.std(0)
                native_k=kurtosis(native/qe,axis=0,fisher=True,bias=False)
                for c in range(len(channels)):
                    rec=dict(metadata,modality='EEG',branch=branch,channel=str(channels[c]),channel_index=c,segment=segment,start_s=start,end_s=end,
                        point_key=row['case']+f'|EEG|{c}|{segment}',anchor=c==electrode,
                        native_rms=float(np.sqrt(np.mean(native[:,c]**2))),native_std=float(native_sd[c]),native_mean=float(native_mean[c]),native_excess_kurtosis=float(native_k[c]))
                    rec.update({k:float(v[c]) for k,v in feats.items() if k!='valid_shape'});rec['valid_shape']=bool(feats['valid_shape'][c])
                    if row['role']=='evaluation':rec['correlation_to_X']=float(np.corrcoef(blocks['X'][:,c],value[:,c])[0,1]) if value[:,c].std()>1e-20 else np.nan
                    feature_rows.append(rec)
            if row['role']=='evaluation':
                f,p,cross,error=supervision_spectral_triplet(blocks['X'],blocks['S'],blocks['O'],200,'EEG',qe);core_p.append(p);core_cross.append(cross);identities.append(error)
                nf,npower,ncross,error=supervision_spectral_triplet(native_blocks['X'],native_blocks['S'],native_blocks['O'],rate,'EEG',qe)
                native_p.append(npower);native_cross.append(ncross);identities.append(error)
        if row['role']=='evaluation':
            spectra[variant+'_EEG_f']=f;spectra[variant+'_EEG_psd']=np.mean(core_p,axis=0);spectra[variant+'_EEG_cross']=np.mean(core_cross,axis=0)
            spectra[variant+'_EEG_native_f']=nf;spectra[variant+'_EEG_native_psd']=np.mean(native_p,axis=0);spectra[variant+'_EEG_native_cross']=np.mean(native_cross,axis=0)
        for component,modality in enumerate(('HbO','HbR')):
            blocks={b:v[50:850,:,component] for b,v in hsignals.items()}
            for branch,value in blocks.items():
                feats,f,p=supervision_signal_features(value,10,modality,qh[:,component])
                for c in range(3):
                    rec=dict(metadata,modality=modality,branch=branch,channel=row['pairs'][c]['id'],channel_index=c,segment=0,start_s=5,end_s=85,
                        point_key=row['case']+f'|{modality}|{c}',anchor=c==0)
                    rec.update({k:float(v[c]) for k,v in feats.items() if k!='valid_shape'});rec['valid_shape']=bool(feats['valid_shape'][c])
                    if row['role']=='evaluation':rec['correlation_to_X']=float(np.corrcoef(blocks['X'][:,c],value[:,c])[0,1]) if value[:,c].std()>1e-20 else np.nan
                    feature_rows.append(rec)
            if row['role']=='evaluation':
                f,p,cross,error=supervision_spectral_triplet(blocks['X'],blocks['S'],blocks['O'],10,modality,qh[:,component]);identities.append(error)
                spectra[variant+'_'+modality+'_f']=f;spectra[variant+'_'+modality+'_psd']=p;spectra[variant+'_'+modality+'_cross']=cross
        for branch,value in hsignals.items():
            for c in range(3):relations.append(dict(metadata,branch=branch,roi=c,HbO_HbR_correlation=float(np.corrcoef(value[50:850,c,0],value[50:850,c,1])[0,1])))
    folder.mkdir(parents=True,exist_ok=True);pd.DataFrame(feature_rows).to_csv(folder/'features.csv',index=False);pd.DataFrame(relations).to_csv(folder/'Hb_relation.csv',index=False)
    if spectra:_tak_cache_npz(folder/'spectra.npz',**spectra)
    result=dict(status='completed',case=row['case'],role=row['role'],feature_rows=len(feature_rows),replays=replays,
        spectral_identity_max_relative_error=max(identities,default=0.),seconds=time.monotonic()-started,
        peak_rss_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024)
    if result['spectral_identity_max_relative_error']>1e-10:raise ValueError('Spectral additive identity failed')
    write_json(status,result);return result


def so_features_prepare_embeddings(cfg,out):
    """Retained-only feature pairing and training-original standardization."""
    from src.analysis.physiological_patch_features import supervision_embedding_features
    plan=json.loads((out/'plan.json').read_text());frames=[];relations=[]
    for row in plan['rows']:
        folder=out/'cases'/row['case'];status=json.loads((folder/'status.json').read_text())
        if status['status']!='completed':raise ValueError('Incomplete feature extraction')
        frames.append(pd.read_csv(folder/'features.csv',dtype={'subject':str}));relations.append(pd.read_csv(folder/'Hb_relation.csv',dtype={'subject':str}))
    df=pd.concat(frames,ignore_index=True);hb=df.modality!='EEG'
    for key in ('rms','std','mean','excess_kurtosis'):df.loc[hb,'native_'+key]=df.loc[hb,key]
    df['point_id']=df.point_key+'|'+df.condition+'|'+df.branch
    if df.point_id.duplicated().any():raise ValueError('Duplicate feature identity')
    df.to_csv(out/'features.csv',index=False);pd.concat(relations,ignore_index=True).to_csv(out/'Hb_relations.csv',index=False)
    evaluation=df[df.role=='evaluation'];original=evaluation[evaluation.branch=='X'].set_index(['point_key','condition']);paired=[]
    ratio_fields=['rms','std','native_rms','native_std','core_power_ref','hjorth_mobility','hjorth_complexity']+[c for c in df if c.startswith('power_') and c.endswith('_ref')]
    diff_fields=['excess_kurtosis','native_excess_kurtosis','skewness','spectral_entropy','spectral_centroid','spectral_edge95','outband_fraction']+[c for c in df if c.startswith('relative_')]
    for _,row in evaluation[evaluation.branch!='X'].iterrows():
        x=original.loc[(row.point_key,row.condition)];rec={k:row[k] for k in ('point_id','point_key','case','dataset','subject','condition','modality','branch','channel','segment','anchor','correlation_to_X')}
        for key in ratio_fields:rec[key+'_ratio']=float(row[key]/x[key]) if np.isfinite(x[key]) and x[key]>0 else np.nan
        for key in diff_fields:rec[key+'_change']=float(row[key]-x[key])
        paired.append(rec)
    pairs=pd.DataFrame(paired)
    cancellation=[]
    for (key,condition),g in evaluation.groupby(['point_key','condition'],sort=False):
        a=g.set_index('branch');x=a.loc['X'];s=a.loc['S'];o=a.loc['O']
        rec={k:x[k] for k in ('point_key','case','dataset','subject','condition','modality')}
        total=(s.core_power_ref+o.core_power_ref)/x.core_power_ref if x.core_power_ref>0 else np.nan
        corr=(x['std']**2-s['std']**2-o['std']**2)/(2*s['std']*o['std']) if s['std']*o['std']>0 else np.nan
        if np.isfinite(corr) and abs(corr)>1+1e-8:raise ValueError('Invalid S/O covariance identity')
        rec.update(power_sum_ratio=total,cross_to_X=1-total,cancellation_fraction=max(0.,1-1/total) if total>0 else np.nan,correlation_SO=np.clip(corr,-1,1))
        cancellation.append(rec)
    pd.DataFrame(cancellation).to_csv(out/'spectral_cancellation.csv',index=False)
    tasks=[];scalers={};distances=[];inputs=out/'embedding_inputs';inputs.mkdir(exist_ok=True)
    for modality in cfg['embedding']['modalities']:
        for view in cfg['embedding']['feature_views']:
            names=supervision_embedding_features(modality,view);train=df[(df.role=='training')&(df.modality==modality)&(df.branch=='X')]
            valid=np.isfinite(train[names].to_numpy()).all(1);t=train.loc[valid];v=t[names].to_numpy()
            if not len(t):raise ValueError('No valid training features')
            counts=t.groupby(['dataset','subject']).size();ns=t.groupby('dataset').subject.nunique();nd=t.dataset.nunique()
            w=np.array([1/(nd*ns[r.dataset]*counts[(r.dataset,r.subject)]) for r in t.itertuples()]);w/=w.sum()
            mean=np.average(v,axis=0,weights=w);sd=np.sqrt(np.average((v-mean)**2,axis=0,weights=w));keep=sd>=1e-8
            used=np.array(names)[keep].tolist();ztrain=(v[:,keep]-mean[keep])/sd[keep]
            _,singular,vt=np.linalg.svd(ztrain*np.sqrt(w[:,None]),full_matrices=False);components=vt[:2]
            scaler=dict(features=used,dropped=list(np.array(names)[~keep]),mean=mean[keep],std=sd[keep],training_rows=len(t),invalid_training_rows=int((~valid).sum()),PCA_variance_fraction=singular[:2]**2/np.sum(singular**2))
            scalers[modality+'_'+view]=scaler
            for population in ('baseline','ocular'):
                pop=evaluation[evaluation.modality==modality].copy()
                if population=='baseline':pop=pop[pop.condition=='baseline']
                else:
                    recent=[r['case'] for r in plan['rows'] if r['role']=='evaluation' and len(r['variants'])==2];pop=pop[pop.case.isin(recent)]
                    if modality!='EEG':pop=pop[~((pop.branch=='X')&(pop.condition=='ocular1'))]
                valid=np.isfinite(pop[used].to_numpy()).all(1);excluded=pop.loc[~valid,['point_id']];pop=pop.loc[valid].copy().reset_index(drop=True)
                z=(pop[used].to_numpy()-mean[keep])/sd[keep];name=f'{population}_{modality}_{view}'
                pop.to_csv(inputs/(name+'.csv'),index=False);excluded.to_csv(inputs/(name+'_excluded.csv'),index=False)
                _tak_cache_npz(inputs/(name+'.npz'),z=z,pca=z@components.T,feature_names=np.array(used))
                if population=='baseline':
                    loc={r.point_id:i for i,r in enumerate(pop.itertuples())}
                    for i,r in enumerate(pop.itertuples()):
                        if r.branch=='X':continue
                        j=loc.get(r.point_key+'|baseline|X')
                        if j is not None:distances.append(dict(point_id=r.point_id,view=view,feature_distance=float(np.sqrt(np.mean((z[i]-z[j])**2)))))
                for perplexity in cfg['embedding']['perplexities'][modality] if population=='baseline' else cfg['embedding']['perplexities'][modality][:1]:
                    for seed in cfg['embedding']['seeds'] if population=='baseline' else cfg['embedding']['seeds'][:1]:
                        tasks.append(dict(input=name,population=population,modality=modality,view=view,perplexity=perplexity,seed=seed,iterations=cfg['embedding']['iterations'],id=f'{name}_p{perplexity}_s{seed}'))
    for view in cfg['embedding']['feature_views']:
        dist=pd.DataFrame(distances);d=dist[dist.view==view].set_index('point_id').feature_distance
        pairs['feature_distance_'+view]=pairs.point_id.map(d)
    pairs.to_csv(out/'paired_features.csv',index=False)
    write_json(out/'feature_scalers.json',scalers);write_json(out/'embedding_plan.json',dict(tasks=tasks))
    keys=['condition','modality','branch','dataset','subject'];numeric=[c for c in pairs if c.endswith(('_ratio','_change')) or c.startswith('feature_distance_') or c=='correlation_to_X']
    subject=pairs.groupby(keys,sort=False)[numeric].median().reset_index();subject.to_csv(out/'subject_features.csv',index=False)
    dataset=subject.groupby(keys[:-1],sort=False)[numeric].mean().reset_index();dataset.to_csv(out/'dataset_features.csv',index=False)
    summary=dataset.groupby(keys[:3],sort=False)[numeric].mean().reset_index();summary.to_csv(out/'summary_features.csv',index=False)
    write_json(out/'feature_inventory.json',dict(rows=len(df),training_subjects=12,baseline_subjects=14,ocular_subjects=6,embedding_tasks=len(tasks),
        aggregation='median channels/segments within subject; mean subjects within dataset; equal mean across four datasets',
        row_counts=df.groupby(['role','condition','modality','branch']).size().rename('rows').reset_index().to_dict('records'),
        invalid_shape_rows=int((~df.valid_shape).sum())))


def _so_tsne_worker(payload):
    from sklearn.manifold import TSNE,trustworthiness
    out_string,task=payload;out=Path(out_string);folder=out/'embeddings';folder.mkdir(exist_ok=True);status=folder/(task['id']+'.json')
    if status.exists():return json.loads(status.read_text())
    start=time.monotonic()
    with np.load(out/'embedding_inputs'/(task['input']+'.npz'),allow_pickle=False) as a:z=a['z']
    model=TSNE(n_components=2,perplexity=task['perplexity'],random_state=task['seed'],max_iter=task['iterations'],learning_rate='auto',init='pca',n_jobs=1)
    xy=model.fit_transform(z);meta=pd.read_csv(out/'embedding_inputs'/(task['input']+'.csv'),dtype={'subject':str})
    meta['tsne1']=xy[:,0];meta['tsne2']=xy[:,1];meta.to_csv(folder/(task['id']+'.csv'),index=False)
    result=dict(task,status='completed',rows=len(z),KL=float(model.kl_divergence_),trustworthiness_k5=float(trustworthiness(z,xy,n_neighbors=5)),seconds=time.monotonic()-start)
    write_json(status,result);return result


def so_features_report(cfg,out,export_dir=None):
    """Descriptive report: subject-based summaries and exploratory embeddings."""
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import html
    colors={'X':'#687586','S':'#1769aa','O':'#d45d27'};markers={'X':'o','S':'^','O':'x'}
    dslabels={'eeg_fnirs_single_trial':'Single','simultaneous_eeg_nirs':'Sim','refed':'REFED','visual_cognitive_motivation':'Visual'}
    figdir=Path(export_dir) if export_dir is not None else out/'report'
    if figdir.exists():raise FileExistsError('Use a fresh feature report export to preserve dated figures')
    figdir.mkdir(parents=True);figures=[]
    def save(fig,name,caption):
        fig.savefig(figdir/(name+'.png'),dpi=220,bbox_inches='tight');plt.close(fig);figures.append((name,caption))
    df=pd.read_csv(out/'features.csv',dtype={'subject':str});sub=pd.read_csv(out/'subject_features.csv',dtype={'subject':str});summary=pd.read_csv(out/'summary_features.csv');plan=json.loads((out/'plan.json').read_text())
    baseline=sub[sub.condition=='baseline'];tasks=json.loads((out/'embedding_plan.json').read_text())['tasks']
    status=[json.loads((out/'embeddings'/(t['id']+'.json')).read_text()) for t in tasks];pd.DataFrame(status).to_csv(out/'embedding_diagnostics.csv',index=False)
    inventory=json.loads((out/'feature_inventory.json').read_text())
    # Per-dataset spectra preserve modality-specific units through fixed training RMS normalization.
    fig,axes=plt.subplots(3,4,figsize=(18,11))
    for c,ds in enumerate(dslabels):
        cases=[r for r in plan['rows'] if r['role']=='evaluation' and r['dataset']==ds]
        for r,modality in enumerate(('EEG','HbO','HbR')):
            powers=[]
            for case in cases:
                with np.load(out/'cases'/case['case']/'spectra.npz',allow_pickle=False) as a:
                    f=a['baseline_'+modality+'_f'];powers.append(np.median(a['baseline_'+modality+'_psd'],axis=2))
            power=np.mean(powers,axis=0);ax=axes[r,c]
            for b,branch in enumerate(('X','S','O')):ax.semilogy(f,np.maximum(power[b],1e-18),color=colors[branch],label=branch)
            limits=(1,45) if modality=='EEG' else (0,.5);ax.set_xlim(limits)
            visible=power[:,(f>=limits[0])&(f<=limits[1])];positive=visible[visible>0]
            ax.set_ylim(positive.min()*.7,positive.max()*1.4)
            ax.set_title(f'{dslabels[ds]} | {modality} | n={len(cases)} subjects')
            if modality!='EEG':ax.axvspan(0,.0375,color='gray',alpha=.16);ax.axvline(.2,color='gray',ls=':')
            ax.set_xlabel('Frequency (Hz)');ax.set_ylabel('PSD / training RMS squared (1/Hz)');ax.grid(alpha=.2);ax.legend()
    fig.suptitle('Baseline X / S / O spectra | median channels per subject, then mean subjects',fontsize=15);fig.tight_layout(rect=(0,0,1,.96))
    save(fig,'01_spectra','每列一个数据集；X 原始实测、S 监督目标、O=X−S。频谱除以固定训练 RMS²；先被试内通道/ROI 中位数，再平均被试。EEG 为统一 1–45 Hz 分析视图；Hb 未额外滤波。灰区频率在 80 秒内不足三个周期；0.2 Hz 虚线用于查看额外快变成分。不同面板纵轴独立。')
    fig,axes=plt.subplots(3,4,figsize=(18,11))
    metrics=[('rms_ratio','RMS / X',1),('excess_kurtosis_change','Excess kurtosis minus X',0),('hjorth_mobility_ratio','Hjorth mobility / X',1),('correlation_to_X','Waveform correlation with X',1)]
    for i,m in enumerate(('EEG','HbO','HbR')):
        for j,(metric,label,ref) in enumerate(metrics):
            ax=axes[i,j];g=baseline[baseline.modality==m]
            for k,b in enumerate(('S','O')):
                h=g[g.branch==b];values=h[metric].to_numpy();ax.boxplot([values[np.isfinite(values)]],positions=[k],widths=.45,showfliers=False)
                for n,(_,r) in enumerate(h.iterrows()):ax.scatter(k+((n%7)-3)*.035,r[metric],color=colors[b],marker=['o','s','^','D'][list(dslabels).index(r.dataset)],s=30,alpha=.8)
            ax.axhline(ref,ls=':',color='gray');ax.set_xticks([0,1],['S','O']);ax.set_ylabel(label);ax.set_title(m);ax.grid(axis='y',alpha=.2)
    fig.suptitle('Paired feature changes | one point = one subject median | EEG common 1-45 Hz',fontsize=15);fig.tight_layout(rect=(0,0,1,.96))
    save(fig,'02_features','每点为一名被试在通道/片段上的配对指标中位数，箱线表示 14 名被试分布。形状对应 Single 圆、Sim 方、REFED 三角、Visual 菱形。RMS 与活动快慢用比值，峰度用绝对差，相关系数反映带符号波形相似性。横虚线为与 X 一致的位置。')
    # Power changes: paired ratios, not energy fractions.
    fig,axes=plt.subplots(1,3,figsize=(17,5))
    for ax,m in zip(axes,('EEG','HbO','HbR')):
        bands=['delta','theta','alpha','beta','gamma'] if m=='EEG' else ['slow','fast']
        for b,off in [('S',-.13),('O',.13)]:
            g=baseline[(baseline.modality==m)&(baseline.branch==b)]
            for j,band in enumerate(bands):
                vals=g['power_'+band+'_ref_ratio'];ax.scatter(np.full(len(vals),j+off),vals,color=colors[b],alpha=.55,s=20,label=b if j==0 else None)
                ax.plot([j+off-.07,j+off+.07],[vals.median()]*2,color=colors[b],lw=3)
        ax.set_yscale('log');ax.axhline(1,color='gray',ls=':');ax.set_xticks(range(len(bands)),bands);ax.set_title(m);ax.set_ylabel('Band power / original band power');ax.legend();ax.grid(alpha=.2)
    fig.tight_layout();save(fig,'03_band_power','频带功率相对同点原始信号的比值；每点一名被试，短线为被试中位数。EEG δ/θ/α/β/γ 分别 1–4/4–8/8–13/13–30/30–45 Hz；Hb slow=0.0375–0.1、fast=0.1–0.2 Hz。纵轴对数；这些比值并非相加为 1 的成分占比。')
    cancellation=pd.read_csv(out/'spectral_cancellation.csv',dtype={'subject':str});cs=cancellation[cancellation.condition=='baseline'].groupby(['modality','dataset','subject']).median(numeric_only=True).reset_index();cs.to_csv(out/'subject_cancellation.csv',index=False)
    fig,axes=plt.subplots(1,3,figsize=(16,5))
